-- L0001 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-activity-config.xml:57 | query_act_comment_list | fnd_act_hi_comment, fnd_basic_data, fnd_user_info
<![CDATA[
			SELECT t1.* ,t2.`basicDataName` AS resultName , CONCAT(t3.`username`,'-' , t3.`realName`) AS assigneeName,
			t4.`quesnaireId`
			FROM fnd_act_hi_comment t1 
			LEFT JOIN fnd_basic_data t2 ON t1.`result` = t2.`basicDataId` AND t2.`dataTypeCode` = 26
			LEFT JOIN fnd_user_info t3 ON t1.`assignee` = t3.`username` 
			LEFT JOIN pm_presales_project_callback t4 ON t1.`objId` = t4.`presalesId` AND t1.`taskId` = t4.`taskId`
			where objId = #objId# and procdefKey = #procdefKey#
			order by t1.assigneeTime asc
		]]>
;

