-- L0040 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-admin-config.xml:947 | query_basic_data_for_map_with_sub | fnd_basic_data
SELECT 
		    b1.basicDataId AS category, b1.basicDataName AS categoryName, b1.basicDataAttri1 AS categoryAttr, b2.basicDataId AS subCategory, b2.basicDataName AS subCategoryName 
		FROM
		    fnd_basic_data b1 
		    LEFT JOIN fnd_basic_data b2 
		        ON b2.`dataTypeCode` = #subDataTypeCode#
		        AND b1.`basicDataId` = b2.`basicDataAttri1` 
		        AND b2.`effectiveTo` IS NULL 
		WHERE b1.dataTypeCode = #dataTypeCode#
		    <isNotEmpty prepend="AND" property="dataAttr">
		      FIND_IN_SET(#dataAttr#, b1.basicDataAttri1)
		    </isNotEmpty>
		    AND b1.effectiveTo IS NULL 
	    ORDER BY b1.`sortId`, b2.`sortId`
;

-- L0041 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-callback-config.xml:35 | query_callback_byId | pm_cl_callback, pm_cl_callback_quesnaire
<![CDATA[
			SELECT t1.id , t1.projectId,t1.instId ,t1.remark,t1.applyState , MAX(t2.id) AS quesnaireId ,t1.applyBy ,t1.applyTime,
			MAX( CONVERT(t2.taskId , SIGNED)) AS taskId  FROM pm_cl_callback t1
			LEFT JOIN  pm_cl_callback_quesnaire t2  ON t1.`id` = t2.`callBackId`
			WHERE t1.id = #callBackId#
		]]>
;

