        LEFT JOIN pm_basic_deliver_detail pd
            ON pd.projectId = m.id AND pd.projectType = m.projectType + 1
        <![CDATA[ AND now() < IFNULL(pd.effectiveTo, "9999-12-30") ]]>
    </isEqual>
    <isNotEqual property="hideWarranty" compareValue="true">
        LEFT JOIN temp_project_warranty_state wcs
            ON wcs.projectId = m.projectId
