                CONCAT(pd.`deliverablePath`, "$$", pd.`deliverableName`) SEPARATOR "||"
            ) AS deliverFiles,
            GROUP_CONCAT(pd.`deliverableType` SEPARATOR " | ") AS deliverTypes -->
            pd.deliverFiles, pd.deliverTypes
	    </isNotEqual>
	    <isNotEqual property="hideWarranty" compareValue="true" prepend=",">
             <!-- CASE WHEN IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) = - 1 THEN '维保内' 
                ELSE 
                CASE WHEN IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) = 0 THEN '部分保外' 
                    ELSE 
                    CASE WHEN IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) = 1 THEN '维保外' 
                    ELSE NULL 
                    END 
                END 
            END AS warrantyStatusName -->
	        IFNULL(wcs.warrantyStatus, m.warrantyStatus) as warrantyStatus <!-- `warrantyState.warrantyStatus` -->, 
	        CASE WHEN IFNULL(SUM(DISTINCT wcs.warrantyStatus), m.warrantyStatus) = - 1 THEN '维保内' 
                ELSE 
                CASE WHEN IFNULL(SUM(DISTINCT wcs.warrantyStatus), m.warrantyStatus) = 0 THEN '部分保外' 
                    ELSE 
                    CASE WHEN IFNULL(SUM(DISTINCT wcs.warrantyStatus), m.warrantyStatus) = 1 THEN '维保外' 
                    ELSE NULL 
                    END 
                END 
            END AS warrantyStatusName <!-- as `warrantyState.warrantyStatusName` -->
	        , wcs.warrantyGrade <!-- as `warrantyState.warrantyGrade` -->, 
	        wcs.warrantyGradeName <!-- as `warrantyState.warrantyGradeName` -->
	        , wcs.wafService <!-- as `warrantyState.wafService` -->, 
	        wcs.wafServiceName <!-- as `warrantyState.wafServiceName` -->
        </isNotEqual>
	FROM
	    pm_project_maintenance m 
	    LEFT JOIN pm_project_header ph 
	        ON m.`projectId` = ph.`projectId` 
	        AND m.`projectType` = "10" 
	    LEFT JOIN pm_presales_project_header prh 
	        ON m.`projectId` = prh.`presalesId` 
	        AND m.`projectType` = "20" 
	    LEFT JOIN pm_project_member sm 
            ON m.`projectId` = sm.`projectId` 
            AND m.`projectType` = sm.`projectType` 
            AND sm.`memberRole` = '20' 
            AND sm.`effectiveTo` IS NULL 
            AND sm.`fromFlag` = 1 
	    LEFT JOIN pm_project_member pm 
	        ON m.`projectId` = pm.`projectId` 
	        AND m.`projectType` = pm.`projectType` 
	        AND pm.`memberRole` = '30' 
	        AND pm.`effectiveTo` IS NULL 
	        AND pm.`fromFlag` = 1 
	    LEFT JOIN pm_project_member pm2 
	        ON m.`projectId` = pm2.`projectId` 
	        AND m.`projectType` = pm2.`projectType` 
	        AND pm2.`memberRole` = '30' 
	        AND pm2.`effectiveTo` IS NULL 
	        AND pm2.`fromFlag` = 2 
	    LEFT JOIN `pm_project_member` s 
	        ON s.`projectId` = m.`projectId` 
	        AND s.`projectType` = m.`projectType` 
	        AND m.`projectType` = "10" 
	        AND s.`memberRole` = "10" 
	        AND s.`effectiveTo` IS NULL 
	<isNotEqual property="projectMaintenance.hideQuesnaire" compareValue="true">
	    LEFT JOIN projectMaintenance_tempQuesnaireResultTable qrt 
	        ON qrt.quesnaireResultHeaderId = m.`quesnaireId` 
    </isNotEqual>
    <isNotEqual property="hideFiles" compareValue="true">
	    <!-- LEFT JOIN `fnd_files` ff
            ON FIND_IN_SET(ff.id, m.`deliverFileIds`) -->
        <!-- LEFT JOIN pm_basic_deliver_detail pd
            ON pd.projectId = m.id AND pd.projectType = m.projectType + 1
        <![CDATA[ AND now() < IFNULL(pd.effectiveTo, "9999-12-30") ]]>  -->
        LEFT JOIN 
            (select 
                projectId, projectType, 
                GROUP_CONCAT(
	                CONCAT(pd.`deliverablePath`, "$$", pd.`deliverableName`) SEPARATOR "||"
	            ) AS deliverFiles,
	            GROUP_CONCAT(pd.`deliverableType` SEPARATOR " | ") AS deliverTypes
            from
                pm_basic_deliver_detail pd 
            where <![CDATA[ now() < IFNULL(pd.effectiveTo, "9999-12-30") ]]>
            group by projectId, projectType) pd 
            ON pd.projectId = m.id 
            AND pd.projectType = m.projectType + 1 
    </isNotEqual>
    <isNotEqual property="hideWarranty" compareValue="true">
        <!-- LEFT JOIN temp_maintenance_contractNo mc 
            ON mc.id = m.id 
        LEFT JOIN temp_warranty_state ws 
            ON mc.`contractNo` = ws.contractNo  -->
        LEFT JOIN temp_project_warranty_state wcs 
            ON m.`projectId` = wcs.projectId 
            AND m.projectType = 10
    </isNotEqual>
	    LEFT JOIN `fnd_user_info` ui 
	        ON ui.`username` = m.`createBy` 
	    LEFT JOIN `fnd_basic_data` bd 
	        ON bd.`basicDataId` = m.`type` 
	        AND bd.`dataTypeCode` = 'maintenanceType' 
	    LEFT JOIN `fnd_basic_data` bd1 
            ON bd1.`basicDataId` = m.`category` 
            AND bd1.`dataTypeCode` = 'maintenanceCategory' 
        LEFT JOIN `fnd_basic_data` bd2 
            ON bd2.`basicDataId` = m.`subCategory` 
            AND bd2.`dataTypeCode` = 'maintenanceSubCategory' 
        LEFT JOIN `fnd_basic_data` bd3 
            ON bd3.`basicDataId` = m.`projectExecutionState` 
            AND bd3.`dataTypeCode` = 'projectExecutionState' 
	    LEFT JOIN fnd_department d 
	        ON d.`departmentNum` = m.`officeCode`
	    LEFT JOIN fnd_department d2 
            ON d2.`departmentNum` = m.`userOffice`
    <dynamic prepend="where">
        <isNotEmpty prepend="AND" property="projectMaintenance.id"> m.id = #projectMaintenance.id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.projectId"> m.projectId = #projectMaintenance.projectId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.projectCode"> m.projectCode like concat("%", #projectMaintenance.projectCode#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.projectName"> m.projectName like concat("%", #projectMaintenance.projectName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.projectType"> m.projectType = #projectMaintenance.projectType# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.projectExecutionState"> m.projectExecutionState = #projectMaintenance.projectExecutionState# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.contractNo"> m.contractNo = #projectMaintenance.contractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.officeCode"> m.officeCode = #projectMaintenance.officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.type"> m.type = #projectMaintenance.type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.category"> m.category = #projectMaintenance.category# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.subCategory"> m.subCategory = #projectMaintenance.subCategory# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.processTime"> m.processTime = #projectMaintenance.processTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.processDesc"> m.processDesc = #projectMaintenance.processDesc# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.processStep"> m.processStep = #projectMaintenance.processStep# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.remainProblem"> m.remainProblem = #projectMaintenance.remainProblem# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.transitHour"> m.transitHour = #projectMaintenance.transitHour# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.processHour"> m.processHour = #projectMaintenance.processHour# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.itemModel"> m.itemModel = #projectMaintenance.itemModel# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.softVersion"> m.softVersion = #projectMaintenance.softVersion# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.enabledFeatures"> m.enabledFeatures = #projectMaintenance.enabledFeatures# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.hasReport"> m.hasReport = #projectMaintenance.hasReport# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.quesnaireId"> m.quesnaireId = #projectMaintenance.quesnaireId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.deliverFileIds"> m.deliverFileIds = #projectMaintenance.deliverFileIds# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.remark"> m.remark = #projectMaintenance.remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.createTime"> m.createTime = #projectMaintenance.createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.createBy"> m.createBy = #projectMaintenance.createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.updateTime"> m.updateTime = #projectMaintenance.updateTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.updateBy"> m.updateBy = #projectMaintenance.updateBy# </isNotEmpty>
        
        <isNotEmpty prepend="AND" property="projectMaintenance.serviceManager"> sm.memberCode = #projectMaintenance.serviceManager# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.programManager"> (pm.memberCode = #projectMaintenance.programManager# or pm2.memberCode = #projectMaintenance.programManager#) </isNotEmpty>
        
        <isNotEmpty prepend="AND" property="projectMaintenance.userPower" open="(" close=")">
            (m.createBy = #projectMaintenance.userPower#
                or sm.memberCode = #projectMaintenance.userPower# 
                or pm.memberCode = #projectMaintenance.userPower# 
                or pm2.memberCode = #projectMaintenance.userPower#
                <isEqual prepend="or" property="projectMaintenance.checkServicePower" compareValue="true">
                    exists (
					   select 
			                1 
			            from
			                serviceManagerPower_$projectMaintenance.userPower$ ep 
			            where ep.serviceCode = #projectMaintenance.userPower#
			                AND ep.programCode = m.`createBy`
					)
                </isEqual>
            )
            <isNotEmpty prepend="OR" property="projectMaintenance.areaPower"> FIND_IN_SET(m.officeCode, #projectMaintenance.areaPower#)</isNotEmpty>
        </isNotEmpty>
        <isEmpty property="projectMaintenance.userPower">
            <isNotEmpty prepend="AND" property="projectMaintenance.areaPower"> FIND_IN_SET(m.officeCode, #projectMaintenance.areaPower#)</isNotEmpty>
        </isEmpty>
        
        <isNotEmpty prepend="AND" property="projectMaintenance.processStartTime"> <![CDATA[ m.processTime >= #projectMaintenance.processStartTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.processEndTime"> <![CDATA[ m.processTime <= #projectMaintenance.processEndTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.createStartTime"> <![CDATA[ m.createTime >= #projectMaintenance.createStartTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.createEndTime"> <![CDATA[ m.createTime <= #projectMaintenance.createEndTime# ]]> </isNotEmpty>
    
        <isNotEmpty prepend="AND" property="projectMaintenance.warrantyStatus"> m.warrantyStatus = #projectMaintenance.warrantyStatus# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.industryName"> m.industryName = #projectMaintenance.industryName# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.userOffice"> m.userOffice = #projectMaintenance.userOffice# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.year"> m.year = #projectMaintenance.year# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.quarter"> m.quarter = #projectMaintenance.quarter# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.month"> m.month = #projectMaintenance.month# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.wsCount"> m.wsCount = #projectMaintenance.wsCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.wafCount"> m.wafCount = #projectMaintenance.wafCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.wsYearCount"> m.wsYearCount = #projectMaintenance.wsYearCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.wafYearCount"> m.wafYearCount = #projectMaintenance.wafYearCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.warrantyInfo"> m.warrantyInfo = #projectMaintenance.warrantyInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectMaintenance.serviceInfo"> m.serviceInfo = #projectMaintenance.serviceInfo# </isNotEmpty>
        
        <isNotEqual property="hideFiles" compareValue="true">
            <isNotEmpty prepend="AND" property="projectMaintenance.deliverFiles">
                (
                <!-- ff.fileType like concat("%", #projectMaintenance.deliverFiles#, "%")
                or
                ff.fileName like concat("%", #projectMaintenance.deliverFiles#, "%") -->
                
                <!-- pd.deliverableType like concat("%", #projectMaintenance.deliverFiles#, "%")
                or
                pd.deliverableName like concat("%", #projectMaintenance.deliverFiles#, "%") -->
                
                pd.deliverFiles like concat("%", #projectMaintenance.deliverFiles#, "%")
                or
                pd.deliverTypes like concat("%", #projectMaintenance.deliverFiles#, "%")
                )
            </isNotEmpty>
        </isNotEqual>
        
        <isNotEqual property="hideWarranty" compareValue="true">
	        <isNotEmpty prepend="AND" property="projectMaintenance.queryWarrantyStatus"> wcs.warrantyStatus = #projectMaintenance.queryWarrantyStatus# </isNotEmpty>
	        <isNotEmpty prepend="AND" property="projectMaintenance.queryWarrantyGrade"> wcs.warrantyGrade = #projectMaintenance.queryWarrantyGrade# </isNotEmpty>
	        <isNotEmpty prepend="AND" property="projectMaintenance.queryWafService"> wcs.wafService = #projectMaintenance.queryWafService# </isNotEmpty>
        </isNotEqual>
    </dynamic>
    GROUP BY m.id
    ORDER BY m.id desc
    <isNotEmpty property="displayParam.offset">
        limit #displayParam.offset#, #displayParam.pagesize# 
    </isNotEmpty>
;

-- L0054 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1048 | selectDailyMaintenanceMapList | fnd_basic_data, pm_project_header, pm_project_maintenance, pm_project_member, fnd_department, fnd_user_info
SELECT
	    m.*, IFNULL(
	        CONCAT(m.createBy, "-", ui.realName), m.createBy
	    ) AS createUser, bd.`basicDataName` AS typeName, bd3.`basicDataName` AS projectExecutionStateName, 
	    CONCAT(IF(m.projectType = 40, '自定义', ''), bd1.`basicDataName`) AS categoryName, bd2.`basicDataName` AS subCategoryName, 
	    IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) AS diff, 
	    CASE WHEN IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) = -1 THEN '维保内'
	    ELSE CASE WHEN IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) = 0 THEN '部分保外'
	         ELSE CASE WHEN IFNULL(SUM(DISTINCT ws.diff), m.warrantyStatus) = 1 THEN '维保外' ELSE NULL END
	         END
	    END AS diffName,
	    CASE
	        WHEN m.projectType = 10 
	        THEN CONCAT(
	            s.`memberCode`, "-", REPLACE(
	                s.`memberName`, CONCAT(s.`memberCode`, "-"), ""
	            )
	        ) 
	        ELSE prh.salesman 
	    END AS salerName, 
	    IFNULL(ph.column004, prh.`marketName`) AS marketName, IFNULL(ph.column005, prh.`systemName`) AS systemName, 
	    IFNULL(ph.column006, prh.`expendName`) AS expendName, IFNULL(m.industryName, IFNULL(ph.column007, prh.`industryName`)) AS industryName,
	    ph.column013 AS finalCustomName
	FROM
	    pm_project_maintenance m 
	    LEFT JOIN pm_project_header ph 
            ON m.`projectId` = ph.`projectId` 
            AND m.`projectType` = "10" 
	    LEFT JOIN temp_maintenance_contractNo mc 
	        ON mc.id = m.id 
	    LEFT JOIN temp_warranty_state ws 
	        ON mc.`contractNo` = ws.contractNo 
	    LEFT JOIN `pm_project_member` s 
	        ON s.`projectId` = m.`projectId` 
	        AND s.`projectType` = m.`projectType` 
	        AND m.`projectType` = 10 
	        AND s.`memberRole` = 10 
	        AND s.`effectiveTo` IS NULL 
	    LEFT JOIN `pm_presales_project_header` prh 
	        ON prh.`presalesId` = m.`projectId` 
	        AND m.`projectType` = 20 
	        AND prh.`effectiveTo` IS NULL 
	    LEFT JOIN `fnd_user_info` ui 
	        ON ui.`username` = m.`createBy` 
	    LEFT JOIN `fnd_basic_data` bd 
	        ON bd.`basicDataId` = m.`type` 
	        AND bd.`dataTypeCode` = 'maintenanceType' 
	    LEFT JOIN `fnd_basic_data` bd1 
	        ON bd1.`basicDataId` = m.`category` 
	        AND bd1.`dataTypeCode` = 'maintenanceCategory' 
	    LEFT JOIN `fnd_basic_data` bd2 
	        ON bd2.`basicDataId` = m.`subCategory` 
	        AND bd2.`dataTypeCode` = 'maintenanceSubCategory' 
	    LEFT JOIN `fnd_basic_data` bd3 
            ON bd3.`basicDataId` = m.`projectExecutionState` 
            AND bd3.`dataTypeCode` = 'projectExecutionState' 
	    LEFT JOIN fnd_department d 
	        ON d.`departmentNum` = m.`officeCode` 
	<dynamic prepend="where">
        <isNotEmpty prepend="AND" property="id"> m.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectId"> m.projectId = #projectId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectCode"> m.projectCode like concat("%", #projectCode#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectName"> m.projectName like concat("%", #projectName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectType"> m.projectType = #projectType# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectExecutionState"> m.projectExecutionState = #projectExecutionState# </isNotEmpty>
        <isNotEmpty prepend="AND" property="contractNo"> m.contractNo = #contractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="officeCode"> m.officeCode = #officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> m.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="category"> m.category = #category# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subCategory"> m.subCategory = #subCategory# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processTime"> m.processTime = #processTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processDesc"> m.processDesc = #processDesc# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processStep"> m.processStep = #processStep# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remainProblem"> m.remainProblem = #remainProblem# </isNotEmpty>
        <isNotEmpty prepend="AND" property="transitHour"> m.transitHour = #transitHour# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processHour"> m.processHour = #processHour# </isNotEmpty>
        <isNotEmpty prepend="AND" property="itemModel"> m.itemModel = #itemModel# </isNotEmpty>
        <isNotEmpty prepend="AND" property="softVersion"> m.softVersion = #softVersion# </isNotEmpty>
        <isNotEmpty prepend="AND" property="enabledFeatures"> m.enabledFeatures = #enabledFeatures# </isNotEmpty>
        <isNotEmpty prepend="AND" property="hasReport"> m.hasReport = #hasReport# </isNotEmpty>
        <isNotEmpty prepend="AND" property="quesnaireId"> m.quesnaireId = #quesnaireId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="deliverFileIds"> m.deliverFileIds = #deliverFileIds# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remark"> m.remark = #remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createTime"> m.createTime = #createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createBy"> m.createBy = #createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateTime"> m.updateTime = #updateTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateBy"> m.updateBy = #updateBy# </isNotEmpty>
        
        <isEmpty property="userPower">
            <isNotEmpty prepend="AND" property="areaPower"> FIND_IN_SET(m.officeCode, #areaPower#)</isNotEmpty>
        </isEmpty>
        
        <isNotEmpty prepend="AND" property="processStartTime"> <![CDATA[ m.processTime >= #processStartTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="processEndTime"> <![CDATA[ m.processTime <= #processEndTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="createStartTime"> <![CDATA[ m.createTime >= #createStartTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="createEndTime"> <![CDATA[ m.createTime <= #createEndTime# ]]> </isNotEmpty>
        
        <isNotEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(m.createTime, #currentDate#) ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(m.createTime, now()) ]]> </isEmpty>
        <!-- <isNotEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(IFNULL(m.updateTime, m.createTime), #currentDate#) ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(IFNULL(m.updateTime, m.createTime), now()) ]]> </isEmpty> -->
        <!-- <isNotEmpty prepend="AND" property="currentTime"> <![CDATA[ TIMESTAMPDIFF(HOUR, m.createTime, #currentTime#) BETWEEN 0 AND 23 ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentTime"> <![CDATA[ TIMESTAMPDIFF(HOUR, m.createTime, now()) BETWEEN 0 AND 23 ]]> </isEmpty> -->
    
        <isNotEmpty prepend="AND" property="warrantyStatus"> m.warrantyStatus = #warrantyStatus# </isNotEmpty>
        <isNotEmpty prepend="AND" property="industryName"> m.industryName = #industryName# </isNotEmpty>
        <isNotEmpty prepend="AND" property="userOffice"> m.userOffice = #userOffice# </isNotEmpty>
        <isNotEmpty prepend="AND" property="year"> m.year = #year# </isNotEmpty>
        <isNotEmpty prepend="AND" property="quarter"> m.quarter = #quarter# </isNotEmpty>
        <isNotEmpty prepend="AND" property="month"> m.month = #month# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wsCount"> m.wsCount = #wsCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wafCount"> m.wafCount = #wafCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wsYearCount"> m.wsYearCount = #wsYearCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wafYearCount"> m.wafYearCount = #wafYearCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="warrantyInfo"> m.warrantyInfo = #warrantyInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="serviceInfo"> m.serviceInfo = #serviceInfo# </isNotEmpty>
    </dynamic>
	GROUP BY m.id
;

-- L0055 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1232 | selectDailyMaintenanceUsers | pm_project_maintenance
