        <isNotEmpty prepend="AND" property="hasReport"> m.hasReport = #hasReport# </isNotEmpty>
        <isNotEmpty prepend="AND" property="quesnaireId"> m.quesnaireId = #quesnaireId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="deliverFileIds"> m.deliverFileIds = #deliverFileIds# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remark"> m.remark = #remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createTime"> m.createTime = #createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createBy"> m.createBy = #createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateTime"> m.updateTime = #updateTime# </isNotEmpty>
