-- L0057 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1510 | queryProjectMaintenanceServiceDeliveriedByProjectDeliver | fnd_basic_data, pm_project_maintenance
SELECT 
		    COUNT(distinct deliverId) = LENGTH(std.basicDataAttri1) - LENGTH(replace(std.basicDataAttri1, ",", "")) + 1 AS hasQuarterDeliveried
		FROM
		    `pm_project_maintenance` m 
		    LEFT JOIN `pm_basic_deliver_detail` pd 
		        ON m.`id` = pd.projectId 
		        AND pd.`projectType` = m.`projectType` + 1 
		    INNER JOIN `fnd_basic_data` std
		        ON std.dataTypeCode = 'projectServiceDeliveryType' 
		        AND FIND_IN_SET(pd.deliverId, std.basicDataAttri1)
		WHERE m.projectId = #projectId#
		    AND std.basicDataId = #eventKey#
           <isNotEmpty prepend="AND" property="uploadTime">
               year(m.`processTime`) = year(IFNULL(#uploadTime#, now())) 
               AND quarter(m.`processTime`) = quarter(IFNULL(#uploadTime#, now()))
           </isNotEmpty>
           <!-- <isNotEmpty property="startDate">
	           <isNotEmpty property="endDate">
	              AND m.processTime between #startDate# and #endDate#
	           </isNotEmpty>
	        </isNotEmpty> -->
		GROUP BY m.`projectId`, m.projectType, dataTypeCode
;

-- L0058 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1535 | queryProjectMaintenanceServiceDeliveriedByMap | fnd_basic_data, pm_project_maintenance
SELECT 
            COUNT(distinct deliverId) = LENGTH(std.basicDataAttri1) - LENGTH(replace(std.basicDataAttri1, ",", "")) + 1 AS hasQuarterDeliveried
        FROM
            `pm_project_maintenance` m 
            LEFT JOIN `pm_basic_deliver_detail` pd 
                ON m.`id` = pd.projectId 
                AND pd.`projectType` = m.`projectType` + 1 
            INNER JOIN `fnd_basic_data` std
                ON std.dataTypeCode = 'projectServiceDeliveryType' 
                AND FIND_IN_SET(pd.deliverId, std.basicDataAttri1)
        WHERE m.projectId = #projectId#
            AND std.basicDataId = #serviceType#
           <isNotEmpty prepend="AND" property="maintenanceId"> m.id = #maintenanceId# </isNotEmpty>
           <isNotEmpty prepend="AND" property="serviceDate">
               year(m.`processTime`) = year(IFNULL(#serviceDate#, now())) 
               AND quarter(m.`processTime`) = quarter(IFNULL(#serviceDate#, now()))
           </isNotEmpty>
           <isNotEmpty property="startDate">
               <isNotEmpty property="endDate">
                  AND m.processTime between #startDate# and #endDate#
               </isNotEmpty>
           </isNotEmpty>
        GROUP BY m.`projectId`, m.projectType, dataTypeCode
;

-- L0059 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1561 | queryProjectMaintenanceDeliverCount | fnd_basic_data, pm_project_maintenance
select 
        <!-- 单季度多次上传算一次 -->
        <!-- <isEqual property="mergeQuarterCount" compareValue="true">
		    count(*) as `count` 
        </isEqual>
        <isNotEqual property="mergeQuarterCount" compareValue="true">
            sum(quarterCount) quarterCount
        </isNotEqual> -->
        count(deliverId) as `count`, IFNULL(sum(quarterCount), 0) totalCount,
        IFNULL(sum(if(year = year(IFNULL(#serviceDate#, now())) and quarter = quarter(IFNULL(#serviceDate#, now())), quarterCount, 0)), 0) as quarterCount
	from
	    (select 
	        m.`id`, m.projectId, pd.deliverId, deliverableType, year(m.`processTime`) as year, quarter(processTime) as quarter, count(deliverId) as quarterCount 
	    from
	        `pm_project_maintenance` m 
	        left join `fnd_basic_data` std
                on std.dataTypeCode = 'projectServiceDeliveryType' 
	        inner join `pm_basic_deliver_detail` pd 
	            on m.`id` = pd.projectId 
	            and pd.`projectType` = m.`projectType` + 1 
	            and pd.deliverId = #deliverId# 
	    where m.projectId = #projectId# 
	    <isNotEmpty property="startDate">
	       <isNotEmpty property="endDate">
		      AND m.processTime between #startDate# and #endDate#
	       </isNotEmpty>
	    </isNotEmpty>
	    group by m.`projectId`, m.projectType, year, quarter) t
;

-- L0060 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1639 | queryProjectMaintenanceServiceDeliveriedCount | pm_project_maintenance
select 
	    count(serviceType) as `count`, 
	    IFNULL(sum(quarterCount), 0) totalCount, 
	    IFNULL(sum(if(year = year(#serviceDate#) and quarter = quarter(#serviceDate#), quarterCount, 0)), 0) as quarterCount
	from
	    (select 
	        m.`id`, m.projectId, serviceType, 
	        year(IFNULL(pm.processTime, m.processTime)) as year, 
	        quarter(IFNULL(pm.processTime, m.processTime)) as quarter, 
	        sum(deliveried) as quarterCount 
	    from
	        `pm_project_maintenance_service_delivery` m 
	        Left join pm_project_maintenance pm
	           on pm.id = m.maintenanceId
	    where m.projectId = #projectId# 
	       and m.`deliveried` = 1
	    <isNotEmpty prepend="AND" property="serviceType"> m.`serviceType` = #serviceType# </isNotEmpty>
	    <isNotEmpty property="startDate">
           <isNotEmpty property="endDate">
              AND IFNULL(pm.processTime, m.processTime) between #startDate# and #endDate#
           </isNotEmpty>
        </isNotEmpty>
	group by m.`projectId`, m.projectType, serviceType, year, quarter) t
;

-- L0061 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-maintenance-config.xml:1850 | countProjectMaintenanceServiceDeliveryMapList | fnd_basic_data, pm_project_maintenance, pm_project_member
select count(*) from temp_project_warranty_state wcs
    <include refid="sqlProjectMaintenanceServiceDeliveryWhere"/>
