-- L0067 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-presales-config.xml:392 | query_presales_en_task | fnd_basic_data, pm_project_task
<![CDATA[
			SELECT t2.`basicDataName` AS taskName ,CASE WHEN t1.eventActualFinishDate IS NULL THEN 0 ELSE 1 END taskState ,
			CASE WHEN t1.eventActualFinishDate IS NULL THEN '未完成' ELSE '已完成' END taskStateName   , t1.*   
			FROM pm_project_task t1
			LEFT JOIN fnd_basic_data t2 ON t1.`taskTypeCode` = t2.`dataTypeCode` AND t1.`taskTypeId` = t2.`basicDataId`
			AND t2.`effectiveTo` IS NULL
			WHERE t1.`projectId` = #projectId#  AND t1.`projectType` = #projectType# AND t1.`effectiveTo` IS NULL;
		]]>
;

-- L0068 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-presales-config.xml:469 | query_presale_shipmentInfo | fb_contract, fb_items, fb_shipment, fb_shipment_barcode, fnd_basic_data
SELECT 
		    `c`.`contract_code` AS `contractNo`, `sb`.`item` AS `itemCode`, `fi`.`describe_` AS `itemName`, `sb`.`barcode` AS `barCode`, s.`packdate` AS packdate, s.`receiveName`, fd.`basicDataName` AS emsCompany, s.`emsNum`, NULL as rmaNo
		FROM
		    `fb_contract` `c` 
		    LEFT JOIN `fb_shipment` `s` 
		        ON `c`.`contract_id` = `s`.`con_id` 
		    LEFT JOIN `fb_shipment_barcode` `sb` 
		        ON `s`.`packlist_id` = `sb`.`pack_id` 
		    LEFT JOIN `fb_items` `fi` 
		        ON `sb`.`item` = `fi`.`item` 
		    LEFT JOIN `fnd_basic_data` `fd` 
		        ON `s`.`emsCompany` = `fd`.`basicDataId` 
		        AND `fd`.`dataTypeCode` = '01' 
		WHERE `sb`.`barcode` IS NOT NULL 
		    AND (
                ISNULL(`sb`.`rma_no`) 
                OR (`sb`.`rma_no` = '') 
                OR (`sb`.`rma_no` = 'null')
            ) 
		    AND contract_code = #projectCode#
	   <isEqual property="containRma" compareValue="true">
	    UNION ALL 
		SELECT 
		    `c`.`contract_code` AS `contractNo`, `sb`.`item` AS `itemCode`, `fi`.`describe_` AS `itemName`, `sb`.`barcode` AS `barCode`, s.`packdate` AS packdate, s.`receiveName`, fd.`basicDataName` AS emsCompany, s.`emsNum`, sb.`rma_no` AS rmaNo 
		FROM
		    `fb_contract` `c` 
		    LEFT JOIN `fb_shipment` `s` 
		        ON `c`.`contract_id` = `s`.`con_id` 
		    LEFT JOIN `fb_shipment_barcode` `sb` 
		        ON `s`.`packlist_id` = `sb`.`pack_id` 
		    LEFT JOIN `fb_items` `fi` 
		        ON `sb`.`item` = `fi`.`item` 
		    LEFT JOIN `fnd_basic_data` `fd` 
		        ON `s`.`emsCompany` = `fd`.`basicDataId` 
		        AND `fd`.`dataTypeCode` = '01' 
		WHERE `sb`.`barcode` IS NOT NULL 
		    AND FALSE = (
		        ISNULL(`sb`.`rma_no`) 
		        OR (`sb`.`rma_no` = '') 
		        OR (`sb`.`rma_no` = 'null')
		    ) 
		    AND c.`contract_code` = #projectCode#
       </isEqual>
;

-- L0069 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-presales-config.xml:541 | queryPresalesExportData | fnd_basic_data, pm_project_member, pm_project_task, fnd_department, fnd_user_info
SELECT 
	    <isEqual property="searchTimeType" compareValue="testCompleteTime">
	        <isNotEqual property="exportDetail" compareValue="2">DISTINCT</isNotEqual>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            <isNotEqual property="exportDetail" compareValue="2">DISTINCT</isNotEqual>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            <isNotEqual property="exportDetail" compareValue="2">DISTINCT</isNotEqual>
        </isEqual>
		    t1.presalesId, t1.instId, IFNULL(t1.applyState, - 1) AS applyState, t1.applyTime, t1.endTime, t1.projectState, 
		    t1.projectCode, t1.projectName, t1.projectType, t1.marketName, t1.systemName, t1.expendName, t1.industryName, 
		    t1.officeCode, t1.salesman, t1.productManager, t1.closeRemark,
		    IF(
		        t1.confirmFileIds IS NULL 
		        AND pd.deliverableType IS NULL, '否', '是'
		    ) AS isUpload, t1.hasTransfer AS hasTransfer, t1.hasRma AS hasRma,  IFNULL(
		        pd.deliverableType, IF(
		            t1.confirmFileIds IS NOT NULL, '历史附件', ''
		        )
		    ) AS deliverableType, IFNULL(pt.taskTypeName, IF(t1.projectState = 10, "待开始", "已完成")) AS taskTypeName, 
		    CASE
		        WHEN t1.presalesCode IS NULL 
		        THEN t1.projectCode 
		        ELSE t1.presalesCode 
		    END AS presalesCode, t5.`departmentName` AS officeName, t3.`memberCode` AS serviceManager, t3.`memberName` AS serviceManagerName, t4.`memberCode` AS projectManager, t4.`memberName` AS projectManagerName, t2.`ID_` AS taskId, t2.`ASSIGNEE_` AS taskAssignee, t2.`NAME_` AS taskName, t2.TASK_DEF_KEY_ AS taskDefKey, CONCAT(t6.`username`, '-', t6.`realName`) AS taskAssigneeName, t7.`basicDataName` AS projectStateName, t8.basicDataName AS projectTypeName 
		<!-- exportDetail: 0-基于项目， 1-基于设备， 2-基于回访  -->
		<isNotEqual prepend="," property="exportDetail" compareValue="1">
		    pppd.applyDuration, pppd.totalDuration, pppd.serviceDuration, pppd.programDuration, pppd.testDuration, pppd.callbackDuration 
		</isNotEqual>
		<isEqual prepend="," property="exportDetail" compareValue="1">
            IFNULL(tl1.`itemCode`, rma.itemcode) AS itemCode, 
            IFNULL(tl1.`itemModel`, rma.itemModel) AS itemModel, 
            tl1.`productFirstName`, tl1.`productTypeName`, tl1.`productNum`, 
            rma.orderQty, rma.dlvQty, rma.rmaQty, rma.deliveryDate, rma.rmaDate
        </isEqual>
		<isEqual prepend="," property="exportDetail" compareValue="2">
            cbt.START_TIME_ AS callbackStartTime, pcb.createTime as callbackQuesnarieTime, cbt.END_TIME_ AS callbackEndTime, pcb.taskId as callbackTaskId, IFNULL(pcb.quesnaireId, 0) AS quesnaireId, pqsl.*
        </isEqual>
		FROM
		    pm_presales_project_header t1 
		    LEFT JOIN act_ru_task t2 
		        ON t1.`instId` = t2.`PROC_INST_ID_` 
		    LEFT JOIN pm_project_member t3 
		        ON t1.`presalesId` = t3.`projectId` 
		        AND t3.`memberRole` = '20' 
		        AND t3.`effectiveTo` IS NULL 
		    LEFT JOIN pm_project_member t4 
		        ON t1.`presalesId` = t4.`projectId` 
		        AND t4.`memberRole` = '30' 
		        AND t4.`effectiveTo` IS NULL 
		    LEFT JOIN 
		        (SELECT 
		            ptt.projectId, SUBSTRING_INDEX(
		                GROUP_CONCAT(
		                    bd.basicDataName 
		                    ORDER BY bd.`sortId` ASC
		                ), ",", 1
		            ) AS taskTypeName 
		        FROM
		            `pm_project_task` ptt 
		            LEFT JOIN `fnd_basic_data` bd 
		                ON ptt.`taskTypeCode` = bd.`dataTypeCode` 
		                AND ptt.`taskTypeId` = bd.`basicDataId` 
		        WHERE projectType = '20' 
		            AND eventActualFinishDate IS NULL 
		        GROUP BY projectId) pt 
		        ON pt.projectId = t1.presalesId 
		    LEFT JOIN 
		        (SELECT 
		            projectId, GROUP_CONCAT(DISTINCT deliverableType) AS deliverableType 
		        FROM
		            `pm_basic_deliver_detail` pd 
		        WHERE projectType = 20 
		        GROUP BY projectId, projectType) pd 
		        ON pd.projectId = t1.presalesId 
		<isNotEqual property="exportDetail" compareValue="1">    
		    LEFT JOIN `view_presales_project_duration_temp` pppd 
		        ON pppd.presalesId = t1.presalesId 
        </isNotEqual>
	    <isEqual property="exportDetail" compareValue="1">    
            LEFT JOIN 
                pm_presales_project_rma_info rma 
                ON t1.projectCode = rma.contract
            LEFT JOIN 
                temp_presales_product_line tl1 
                ON t1.presalesId = tl1.presalesId 
                AND rma.itemcode = tl1.itemCode 
        </isEqual>
        <isNotEqual property="exportDetail" compareValue="2">
          <isEqual property="searchTimeType" compareValue="testCompleteTime">
            LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
          </isEqual>
          <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            LEFT JOIN `pm_presales_project_callback` pcb ON pcb.presalesId = t1.presalesId AND pcb.quesnaireState = 1
          </isEqual>
          <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
          </isEqual>
        </isNotEqual>
        <isEqual property="exportDetail" compareValue="2">
            LEFT JOIN `act_hi_taskinst` cbt 
                ON cbt.PROC_INST_ID_ = t1.instId 
                AND cbt.TASK_DEF_KEY_ = 'usertask4' 
            LEFT JOIN `pm_presales_project_callback` pcb 
                ON pcb.presalesId = t1.presalesId 
                AND pcb.taskId = cbt.ID_ 
                AND pcb.quesnaireState = 1
            LEFT JOIN presales_tempQuesnaireResultTable pqsl 
                ON pqsl.quesnaireResultHeaderId = pcb.`quesnaireId`
        </isEqual>
		    LEFT JOIN fnd_department t5 
		        ON t1.`officeCode` = t5.`departmentNum` 
		        AND t5.`status` = 1 
		    LEFT JOIN fnd_user_info t6 
		        ON t2.`ASSIGNEE_` = t6.`username` 
		    LEFT JOIN fnd_basic_data t7 
		        ON t7.`basicDataId` = t1.`projectState` 
		        AND t7.`dataTypeCode` = 27 
		        AND t7.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t8 
		        ON t8.`basicDataId` = t1.`projectType` 
		        AND t8.`dataTypeCode` = "presalesType" 
		        AND t8.`effectiveTo` IS NULL 
		WHERE 1 = 1
		<isNotEmpty prepend="and" property="serviceManager">
            <![CDATA[ (t3.`memberCode` = #serviceManager#  or t4.`memberCode` = #serviceManager# ) ]]> 
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectManager">
            <![CDATA[ t4.`memberCode` = #projectManager#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="presalesCode">
            <![CDATA[ (t1.projectCode = #presalesCode# or t1.presalesCode = #presalesCode# )]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectName">
            <![CDATA[ t1.projectName like '%$projectName$%']]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="officeCode">
            <![CDATA[ t1.officeCode = #officeCode#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectType">
            <![CDATA[ t1.projectType = #projectType#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectState">
            <![CDATA[ t1.projectState = #projectState#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectStates">
            <![CDATA[ FIND_IN_SET(t1.projectState, #projectStates#) ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="hasTransfer">
            <![CDATA[ t1.hasTransfer = #hasTransfer#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="hasRma">
            <![CDATA[ t1.hasRma = #hasRma#]]>
        </isNotEmpty>
        <isEqual property="searchTimeType" compareValue="applyTime">
            <isNotNull prepend="AND" property="searchStartTime"> t1.applyTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ t1.applyTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="endTime">
            <isNotNull prepend="AND" property="searchStartTime"> t1.endTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ t1.endTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="testCompleteTime">
            <isNotNull prepend="AND" property="searchStartTime"> cbt.START_TIME_ >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ cbt.START_TIME_ <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            <isNotNull prepend="AND" property="searchStartTime"> pcb.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ pcb.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            <isNotNull prepend="AND" property="searchStartTime"> cbt.END_TIME_ >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ cbt.END_TIME_ <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
         ORDER BY t1.`applyTime` DESC
;

-- L0070 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:27 | query_prob_count | fnd_basic_data
<![CDATA[
			SELECT count(*)
			FROM prob_main t1 
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			AND t2.`effectiveTo` IS NULL
		]]>	
		<isNotEmpty prepend=" " property="affectedVersion"> left join (
		SELECT 
		  probId, GROUP_CONCAT(
		      DISTINCT CONCAT(
		            "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, ""), " manual:", IFNULL(manualEntry, "")
		        ) SEPARATOR ";"
		    ) AS affectedVersion
		FROM
		    prob_softwares 
		where datastate = 1    
		GROUP BY probId) a 
		on a.probId = t1.id
		</isNotEmpty>
			where t1.effectiveTo is null
		<isNotEmpty prepend="and" property="probNum"><![CDATA[ t1.probNum like '%$probNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="watch"><![CDATA[ t1.watch = #watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="theme"><![CDATA[ t1.theme like '%$theme$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="status"><![CDATA[ t1.`status` = #status#]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="productType"><![CDATA[ t1.productType like concat("%", #productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="desc"><![CDATA[ t1.desc like concat("%", #desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="affectedVersion"><![CDATA[ a.affectedVersion like concat("%", #affectedVersion#, "%")]]></isNotEmpty>
		
		<isNotEmpty property="visibleRange">
            <isNotEqual prepend="and" property="visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #visibleRange#
                <isNotEmpty prepend="or" property="trackingUser"> t1.trackingUser = #trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
;

-- L0071 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:76 | query_prob_list | fnd_basic_data, fnd_user_info
<![CDATA[
			SELECT t1.id as probId, t1.probNum, t1.theme,  t1.watch, t4.basicDataName as watchName, t2.`basicDataName` AS priority, t1.status, t3.basicDataName AS statusName, t1.trackingUser, CONCAT(t1.trackingUser,"-",ui.realName) AS trackingUsername,  t1.createTime, t1.updateTime 
			FROM prob_main t1 
			LEFT JOIN fnd_user_info ui ON ui.username = t1.trackingUser
			LEFT JOIN fnd_basic_data t4 ON t1.`watch` = t4.`basicDataId` AND t4.`dataTypeCode` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			LEFT JOIN fnd_basic_data t3 ON t1.`status` = t3.basicDataId AND t3.dataTypeCode = '31'
			AND t2.`effectiveTo` IS NULL
		]]>
			<isNotEmpty prepend=" " property="prob.affectedVersion"> left join (
		        SELECT 
		          probId,  GROUP_CONCAT(
		              DISTINCT CONCAT(
		                    "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, ""), " manual:", IFNULL(manualEntry, "")
		                ) SEPARATOR ";"
		            ) AS affectedVersion
		        FROM
		            prob_softwares 
		        where datastate = 1
		        GROUP BY probId) a 
		        on a.probId = t1.id
	        </isNotEmpty>
		WHERE t1.effectiveTo IS NULL
		<isNotEmpty prepend="and" property="prob.probNum"><![CDATA[ t1.probNum like '%$prob.probNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.watch"><![CDATA[ t1.watch = #prob.watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.theme"><![CDATA[ t1.theme like '%$prob.theme$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.status"><![CDATA[ t1.`status` = #prob.status#]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="prob.productType"><![CDATA[ t1.productType like concat("%", #prob.productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.desc"><![CDATA[ t1.desc like concat("%", #prob.desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedVersion"><![CDATA[ a.affectedVersion like concat("%", #prob.affectedVersion#, "%")]]></isNotEmpty>
        
        <isNotEmpty property="prob.visibleRange">
            <isNotEqual prepend="and" property="prob.visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #prob.visibleRange# 
                <isNotEmpty prepend="or" property="prob.trackingUser"> t1.trackingUser = #prob.trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
        
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isEmpty prepend=" order by " property="displayParam.sort">
            t1.createTime desc
        </isEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset#,  #displayParam.pagesize#
		</isNotEmpty>
;

-- L0072 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:156 | query_prob_one | fnd_basic_data, fnd_user_info
SELECT t1.* , t3.`basicDataName` AS watchName,  t4.`basicDataName` AS statusName,  t5.`basicDataName` AS priorityName  
			, concat(t6.username, '-', t6.realName) as trackingUsername
		    <isNotEmpty prepend="," property="reader"> IFNULL(rl.status, 0) as readStatus </isNotEmpty>
		    <isEmpty prepend="," property="reader"> 0 as readStatus </isEmpty>
		FROM prob_main t1 
        <isNotEmpty property="reader">
		   left join (select * from prob_read_log where probId = #probId# and reader = #reader# and status = 1 limit 1) rl
              on t1.id = rl.probId and rl.status = 1
        </isNotEmpty>
        
		LEFT JOIN fnd_basic_data t3 ON t1.`watch` = t3.`basicDataId` AND t3.`dataTypeCode` = '30' AND t3.`effectiveTo` IS NULL
		LEFT JOIN fnd_basic_data t4 ON t1.`status` = t4.`basicDataId` AND t4.`dataTypeCode` = '31' AND t4.`effectiveTo` IS NULL
		LEFT JOIN fnd_basic_data t5 ON t1.`priority` = t5.`basicDataId` AND t5.`dataTypeCode` = '32' AND t5.`effectiveTo` IS NULL
		left join fnd_user_info t6 on t1.trackingUser = t6.username
		
		WHERE t1.id = #probId#
;

-- L0073 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:228 | check_soft_version_list | fb_soft_version, pm_project_soft_version
SELECT  DISTINCT 
		<isNotEmpty property="conp">
			conp 
		</isNotEmpty>
		<isEmpty property="conp">
			null as conp
		</isEmpty>
		<isNotEmpty property="cpld">
			,cpld 
		</isNotEmpty>
		<isEmpty property="cpld">
			,null as cpld 
		</isEmpty>
		<isNotEmpty property="boot">
			,boot 
		</isNotEmpty>
		<isEmpty property="boot">
			,null as boot
		</isEmpty>
		<isNotEmpty property="pcb">
			,pcb
		</isNotEmpty>
		<isEmpty property="pcb">
			,null as pcb
		</isEmpty>
		FROM 
			(SELECT conp, cpld, boot, pcb  FROM fb_soft_version 
		    UNION
		    SELECT conp, cpld, boot, pcb FROM `pm_project_soft_version` 
		    UNION
            SELECT conp, cpld, boot, pcb FROM prob_soft_version) t
		WHERE 1 = 1		
		<isEqual property="conpCondition" compareValue="between">
			<isNotEmpty prepend="and" property="conp"><![CDATA[ conp $conpCondition$ #conp1# and #conp2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="conpCondition" compareValue="between">
		    <isEqual property="conpCondition" compareValue="regexp">
	            <isNotEmpty prepend="and" property="conp"><![CDATA[ conp $conpCondition$ #conp#]]> </isNotEmpty>
	        </isEqual>
	        <isNotEqual property="conpCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="conp"><![CDATA[ conp $conpCondition$ '%$conp$%']]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		<isEqual property="cpldCondition" compareValue="between">
		    <isNotEmpty prepend="and" property="cpld"><![CDATA[ cpld $cpldCondition$ #cpld1# and #cpld2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="cpldCondition" compareValue="between">
		    <isEqual property="cpldCondition" compareValue="regexp">
                <isNotEmpty prepend="and" property="cpld"><![CDATA[ cpld $cpldCondition$ #cpld#]]> </isNotEmpty>
            </isEqual>
            <isNotEqual property="cpldCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="cpld"><![CDATA[ cpld $cpldCondition$ '%$cpld$%']]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		<isEqual property="bootCondition" compareValue="between">
			<isNotEmpty prepend="and" property="boot"><![CDATA[ boot $bootCondition$ #boot1# and #boot2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="bootCondition" compareValue="between">
		    <isEqual property="bootCondition" compareValue="regexp">
                <isNotEmpty prepend="and" property="boot"><![CDATA[ boot $bootCondition$ #boot#]]> </isNotEmpty>
            </isEqual>
            <isNotEqual property="bootCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="boot"><![CDATA[ boot $bootCondition$ '%$boot$%']]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		<isEqual property="pcbCondition" compareValue="between">
			<isNotEmpty prepend="and" property="pcb"><![CDATA[ pcb $pcbCondition$ #pcb1# and #pcb2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="pcbCondition" compareValue="between">
		    <isEqual property="pcbCondition" compareValue="regexp">
                <isNotEmpty prepend="and" property="pcb"><![CDATA[ pcb $pcbCondition$ #pcb#]]> </isNotEmpty>
            </isEqual>
            <isNotEqual property="pcbCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="pcb"><![CDATA[ pcb $pcbCondition$ '%$pcb$%']]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		order by 1
		<isNotEmpty prepend="," property="conp">
			 conp 
		</isNotEmpty>
		<isNotEmpty prepend="," property="cpld">
			cpld 
		</isNotEmpty>
		<isNotEmpty prepend="," property="boot">
			boot 
		</isNotEmpty>
		<isNotEmpty prepend="," property="pcb">
			pcb
		</isNotEmpty>
;

-- L0074 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:358 | query_prob_restore_list | fb_contract, fb_items, fb_shipment, fb_shipment_barcode, fb_soft_version, fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_soft_version, view_shipment_info_4_pm, fnd_department
<!-- <![CDATA[
			SELECT t1.* , b1.`itemname` as itemModel ,t6.`projectName` , t6.`column001`  AS officeCode , t9.`departmentName` AS officeName ,
			t4.`contractNo` , t2.`probId` , t6.`projectId` FROM 
			(SELECT a1.serial_number,CASE WHEN a2.conp IS NULL THEN a1.conp ELSE a2.conp END AS conp ,
				CASE WHEN a2.boot IS NULL THEN a1.boot ELSE a2.boot END AS boot,
				CASE WHEN a2.cpld IS NULL THEN a1.cpld ELSE a2.cpld END AS cpld,
				CASE WHEN a2.pcb IS NULL THEN a1.pcb ELSE a2.pcb END AS pcb
			 FROM fb_soft_version a1 
			LEFT JOIN pm_project_soft_version a2 ON a1.`serial_number` = a2.`barcode` AND a2.`datastate` = 1 ) t1 
			
			LEFT JOIN prob_softwares t2 ON CASE WHEN t2.`conp` IS NOT NULL THEN t1.`conp` = t2.`conp` ELSE 1=1 END 
			AND CASE WHEN t2.`boot` IS NOT NULL THEN t1.`boot` = t2.`boot` ELSE 1=1 END
			AND CASE WHEN t2.`cpld` IS NOT NULL THEN t1.`cpld` = t2.`cpld` ELSE 1=1 END
			AND CASE WHEN t2.`pcb` IS NOT NULL THEN t1.`pcb` = t2.`pcb` ELSE 1 =1 END
			LEFT JOIN view_shipment_info_4_pm t3 ON t1.`serial_number` = t3.`barcode`
			LEFT JOIN fb_items b1 ON t3.`itemCode` = b1.`item`
			LEFT JOIN pm_project_contract t4 ON t3.`contract_code` = t4.`contractNo`
			LEFT JOIN pm_project_group_relationship t5 ON t4.`projectGroupCode` = t5.`projectGroupCode`
			LEFT JOIN pm_project_header t6 ON t5.`projectCode` = t6.`projectCode`
			LEFT JOIN pm_project_member t7 ON t6.`projectId` = t7.`projectId` AND t7.`memberRole` = '30' AND t7.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t8 ON t6.`projectId` = t8.`projectId` AND t8.`memberRole` = '20' AND t8.`effectiveTo` IS NULL 
			LEFT JOIN fnd_department t9 ON t6.`column001` = t9.`departmentNum` 
			LEFT JOIN fnd_basic_data t10 ON t6.`projectState` = t10.`basicDataId` AND t10.`dataTypeCode` = '02' AND t10.`effectiveTo` IS NULL
			WHERE t2.`datastate` = 1 AND t2.`probId` =  #probRestore.probId# AND t4.`contractNo` IS NOT NULL
			AND t5.`projectCode` NOT LIKE '%his'
			AND NOT EXISTS(SELECT * FROM prob_restore WHERE serialNum = t1.serial_number)  
		]]> -->
		<![CDATA[
			SELECT t1.*, fi.`itemname` as itemModel, t6.`projectName`, t6.`column001` AS officeCode, t9.`departmentName` AS officeName, t4.`contractNo`,
			t2.`probId`, MAX(t6.`projectId`) AS projectId  
			FROM
			    (SELECT * FROM prob_softwares WHERE datastate = 1 AND manualEntry is null AND probId = #probRestore.probId#) t2 
			    LEFT JOIN 
			        (SELECT  a1.serial_number, 
			            CASE WHEN a2.conp IS NULL THEN a1.conp ELSE a2.conp END AS conp, 
			            CASE WHEN a2.boot IS NULL THEN a1.boot ELSE a2.boot END AS boot, 
			            CASE WHEN a2.cpld IS NULL THEN a1.cpld ELSE a2.cpld END AS cpld, 
			            CASE WHEN a2.pcb IS NULL THEN a1.pcb ELSE a2.pcb END AS pcb 
			        FROM fb_soft_version a1 
			            LEFT JOIN pm_project_soft_version a2 
			                ON a1.`serial_number` = a2.`barcode` 
			                AND a2.`datastate` = 1) t1  
				ON  CASE WHEN t2.`conp` IS NOT NULL THEN t1.`conp` = t2.`conp` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`boot` IS NOT NULL THEN t1.`boot` = t2.`boot` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`cpld` IS NOT NULL THEN t1.`cpld` = t2.`cpld` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`pcb` IS NOT NULL THEN t1.`pcb` = t2.`pcb` ELSE 1 = 1 END 
			    INNER JOIN fb_shipment_barcode fsb 
			        ON fsb.`barcode` = t1.serial_number 
			        AND (
			            ISNULL(`fsb`.`rma_no`) 
			            OR (`fsb`.`rma_no` = '') 
			            OR (`fsb`.`rma_no` = 'null')
			        ) 
			    INNER JOIN fb_shipment fs ON fs.`packlist_id` = fsb.`pack_id` 
			    INNER JOIN fb_contract fc ON fc.`contract_id` = fs.`con_id`
			    INNER JOIN fb_items fi ON fi.`item` = fsb.`item`
			    INNER JOIN pm_project_contract t4 ON fc.`contract_code` = t4.`contractNo` 
			    INNER JOIN pm_project_group_relationship t5 ON t4.`projectGroupCode` = t5.`projectGroupCode` 
			    INNER JOIN pm_project_header t6 ON t5.`projectCode` = t6.`projectCode`
			    	AND (
			            (
			                column012 IS NOT NULL 
			                AND column012 <> 3
			            ) 
			            OR (
			                column012 IS NULL 
			                AND `columno12_readonly` <> 3
			            )
			        )  
			    LEFT JOIN fnd_department t9 ON t6.`column001` = t9.`departmentNum` 
			    LEFT JOIN fnd_basic_data t10 ON t6.`projectState` = t10.`basicDataId` AND t10.`dataTypeCode` = '02' AND t10.`effectiveTo` IS NULL 
			WHERE t4.`contractNo` IS NOT NULL 
			    AND t5.`projectCode` NOT LIKE '%his' 
			    AND NOT EXISTS 
			    (SELECT * FROM prob_restore WHERE serialNum = t1.serial_number AND probId = #probRestore.probId#) 
		]]>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ t1.serial_number like '$probRestore.serialNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ fi.itemname like '$probRestore.itemModel$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ t6.projectName like '%$probRestore.projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ t4.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ t6.column001 = #probRestore.officeCode#]]></isNotEmpty>
		<![CDATA[
			GROUP BY t1.serial_number
		]]>
;

-- L0075 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:561 | query_list_probRestore_task | fnd_basic_data, pm_project_soft_version, fnd_department, fnd_user_info
<![CDATA[
			SELECT a1.* , a2.`basicDataName` AS restoreStatusName ,a3.`departmentName` AS officeName,
				a4.restoreRemark ,a4.restoreStatus ,a5.`conp` , a5.`boot` ,a5.`cpld` ,a5.`pcb` ,a5.`executeTime` ,
				CASE WHEN a6.realName IS NOT NULL THEN a6.realName ELSE '服务经理' END AS assigneeName
			  FROM prob_restore a1
			LEFT JOIN prob_restore_process a4 ON a1.processId = a4.id
			LEFT JOIN fnd_basic_data a2 ON a4.`restoreStatus` = a2.`basicDataId` AND a2.`dataTypeCode` = '33'
			LEFT JOIN fnd_department a3 ON a1.`officeCode` = a3.`departmentNum`
			LEFT JOIN pm_project_soft_version a5 ON a1.`serialNum` = a5.`barcode` AND a5.`datastate` = 1 
			LEFT JOIN fnd_user_info a6 ON a1.`assignee` = a6.`username` 
			WHERE a1.probId = #probRestore.probId# 	
		]]>
		<isNotEmpty prepend="and" property="probRestore.assignee">
			<![CDATA[
				(a1.assignee = #probRestore.assignee# 
			]]>	
			<isNotEmpty prepend="OR" property="probRestore.areapower">
				<![CDATA[ 
					(a1.officeCode in ($probRestore.areapower$)
				]]>	
				<isNotEmpty prepend="and" property="probRestore.assigneeRole"><![CDATA[ a1.assigneeRole = #probRestore.assigneeRole#]]></isNotEmpty>
					)
			</isNotEmpty>
			)
		</isNotEmpty>
		<!-- <isEmpty property="probRestore.assignee">
			<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		</isEmpty> -->
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ a1.projectName like '%$probRestore.projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ a1.serialNum = #probRestore.serialNum# ]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ a1.itemModel like '$probRestore.itemModel$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ a1.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		<isNotEqual prepend="and" property="probRestore.restoreStatus" compareValue="0">
			<![CDATA[ a4.restoreStatus = #probRestore.restoreStatus#]]>
		</isNotEqual>
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset# , #displayParam.pagesize#
		</isNotEmpty>
;

-- L0076 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:611 | query_list_probRestore_task_project | fnd_basic_data, pm_project_soft_version, fnd_department, fnd_user_info
<![CDATA[
			SELECT a1.* , a2.`basicDataName` AS restoreStatusName ,a3.`departmentName` AS officeName,
				a4.restoreRemark ,a4.restoreStatus ,a5.`conp` , a5.`boot` ,a5.`cpld` ,a5.`pcb` ,a5.`executeTime` ,
				CASE WHEN a6.realName IS NOT NULL THEN a6.realName ELSE '服务经理' END AS assigneeName
			  FROM prob_restore a1
			LEFT JOIN prob_restore_process a4 ON a1.processId = a4.id
			LEFT JOIN fnd_basic_data a2 ON a4.`restoreStatus` = a2.`basicDataId` AND a2.`dataTypeCode` = '33'
			LEFT JOIN fnd_department a3 ON a1.`officeCode` = a3.`departmentNum`
			LEFT JOIN pm_project_soft_version a5 ON a1.`serialNum` = a5.`barcode` AND a5.`datastate` = 1 
			LEFT JOIN fnd_user_info a6 ON a1.`assignee` = a6.`username` 
			WHERE a1.probId = #probRestore.probId# 	
		]]>
		<isNotEmpty prepend="and" property="probRestore.assignee">
			<![CDATA[
				(a1.assignee = #probRestore.assignee# 
			]]>	
			<isNotEmpty prepend="OR" property="probRestore.areapower">
				<![CDATA[ 
					(a1.officeCode in ($probRestore.areapower$)
				]]>	
				<isNotEmpty prepend="and" property="probRestore.assigneeRole"><![CDATA[ a1.assigneeRole = #probRestore.assigneeRole#]]></isNotEmpty>
					)
			</isNotEmpty>
			)
		</isNotEmpty>
		<!-- <isEmpty property="probRestore.assignee">
			<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		</isEmpty> -->
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ a1.projectName like '%$probRestore.projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ a1.serialNum = #probRestore.serialNum# ]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ a1.itemModel like '$probRestore.itemModel$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ a1.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		<isNotEqual prepend="and" property="probRestore.restoreStatus" compareValue="0">
			<![CDATA[ a4.restoreStatus = #probRestore.restoreStatus#]]>
		</isNotEqual>
		GROUP BY a1.projectId, a1.assignee, a1.assigneeRole, a4.restoreStatus 
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset# , #displayParam.pagesize#
		</isNotEmpty>
;

-- L0077 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:719 | query_prob_task_weekly | fnd_user_info
<![CDATA[
			SELECT t2.`fileName` , CONCAT(t3.`username` , '-' , t3.`realName`) AS uploadUser , t2.`uploadTime` ,t1.`fileId`  FROM prob_restore_weekly t1 
			LEFT JOIN fnd_files t2 ON t1.`fileId` = t2.`id`
			LEFT JOIN fnd_user_info t3 ON t2.`uploadBy` = t3.`username` 
			WHERE t1.`probId` = #probId# 
		]]>
		<isNotEmpty property="uploaduser">
			<![CDATA[ AND t2.`uploadBy` = #uploaduser# ]]>
		</isNotEmpty>
;

-- L0078 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:730 | query_prob_assignee_emails | fnd_user_info
<![CDATA[
			SELECT GROUP_CONCAT(DISTINCT t2.email SEPARATOR ';') as emails FROM prob_restore t1
			LEFT JOIN fnd_user_info t2 ON t1.`assignee` = t2.`username` AND t2.`status` = 1
			WHERE t1.`id` IN ($restoreIds$)
		]]>
;

-- L0079 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:763 | query_hist_soft_version_list_by_probRestoreIds | pm_project_soft_change_logs, pm_project_soft_version
<![CDATA[
			SELECT 
			    pr.`serialNum` AS barCode, pr.`itemModel` AS itemName, pr.`projectId`, sv.`conp`, sv.`conpBak`, sv.`conpChange`, sv.`boot`, sv.`bootBak`, sv.`bootChange`, sv.`cpld`, sv.`cpldBak`, sv.`cpldChange`, sv.`pcb`, sv.`pcbBak`, sv.`pcbChange`, sv.`executeTime`, sv.`createTime` 
			FROM
			    `prob_restore` pr 
			    LEFT JOIN `pm_project_soft_version` sv 
			        ON pr.`serialNum` = sv.`barcode` 
			        AND sv.`datastate` = 1 
			    LEFT JOIN `pm_project_soft_change_logs` scl 
			        ON pr.`projectId` = scl.`projectId` 
			        AND scl.`latest` = 1
			WHERE pr.id IN ($restoreIds$)
		]]>
;

-- L0080 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:779 | query_officeMails_by_probRestoreIds | fnd_user_info
<![CDATA[
			SELECT GROUP_CONCAT(DISTINCT ui.email SEPARATOR ';') 
			FROM
			    `prob_restore` pr 
			    LEFT JOIN fnd_user_info ui 
			        ON pr.`officeCode` = ui.`dpNo` 
			        AND ui.`status` = 1 
	       	WHERE pr.id IN ($restoreIds$)
		]]>
;

-- L0081 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:791 | query_exportProb_list | fnd_basic_data, fnd_user_info
SELECT 
		    t1.*, t2.`basicDataName` AS priorityName, t4.`basicDataName` AS watchName, t3.basicDataName AS statusName, CONCAT(t1.trackingUser, "-", ui.realName) AS trackingUsername, t.affectedVersion 
		FROM
		    prob_main t1 
		    LEFT JOIN fnd_user_info ui 
		        ON ui.username = t1.trackingUser 
		    LEFT JOIN fnd_basic_data t2 
		        ON t1.`priority` = t2.`basicDataId` 
		        AND t2.`dataTypeCode` = '32' 
		        AND t2.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t3 
		        ON t1.`status` = t3.basicDataId 
		        AND t3.dataTypeCode = '31' 
		        AND t3.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t4 
		        ON t1.`watch` = t4.basicDataId 
		        AND t4.dataTypeCode = '30' 
		        AND t4.`effectiveTo` IS NULL 
		    LEFT JOIN 
		        (SELECT 
		            probId, GROUP_CONCAT(
		              DISTINCT  CONCAT_WS(
		                    "-", CONCAT("conp[", conp, "]"), CONCAT("cpld[", cpld, "]"), CONCAT("boot[", boot, "]"), CONCAT("pcb[", pcb, "]"), CONCAT("manual[", manualEntry, "]")
		                ) SEPARATOR ";"
		            ) AS affectedVersion 
		        FROM
		            `prob_softwares` 
		        WHERE datastate = 1 
		        GROUP BY probId) t 
		        ON t.probId = t1.`id` 
		WHERE t1.effectiveTo IS NULL
;

-- L0082 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:834 | query_prob_statistics_count | fb_items, fb_soft_version, pm_project_header, pm_project_member, pm_project_soft_change_logs, pm_project_soft_version, fnd_department
select count(*) from statistic_tempTable
        <!-- (
	        SELECT 
	             1
	        FROM
	            (SELECT 
	                sv.`projectId`, fi.`itemname`, CONCAT(
	                    "出厂版本信息:[conp:", fsv.`conp`, ",cpld:", fsv.`cpld`, ",boot:", fsv.`boot`, ",pcb:", fsv.`pcb`, "];\r\n", GROUP_CONCAT(
	                        CONCAT(
	                            scl.`createTime`, "：", scl.changeRemark, "，conp:[", 
	                            CASE
	                                WHEN sv.`conpChange` = 1 
	                                THEN CONCAT(sv.`conpBak`, "->", sv.`conp`) 
	                                ELSE sv.`conp` 
	                            END, "]", "，cpld:[", 
	                            CASE
	                                WHEN sv.`cpldChange` = 1 
	                                THEN CONCAT(sv.`cpldBak`, "->", sv.`cpld`) 
	                                ELSE sv.`cpld` 
	                            END, "]", "，boot:[", 
	                            CASE
	                                WHEN sv.`bootChange` = 1 
	                                THEN CONCAT(sv.`bootBak`, "->", sv.`boot`) 
	                                ELSE sv.`boot` 
	                            END, "]", "，pcb:[", 
	                            CASE
	                                WHEN sv.`pcbChange` = 1 
	                                THEN CONCAT(sv.`pcbBak`, "->", sv.`pcb`) 
	                                ELSE sv.`pcb` 
	                            END, "]"
	                        ) SEPARATOR ";\r\n"
	                    )
	                ) AS softInfo, COUNT(*) AS updateCount, MAX(ps.`probId`) AS probId, MAX(sv.`executeTime`) AS executeTime 
	            FROM
	                pm_project_soft_version sv 
	                LEFT JOIN pm_project_soft_change_logs scl 
	                    ON sv.`projectId` = scl.projectId 
	                    AND sv.`logId` = scl.id 
	                LEFT JOIN fb_items fi 
	                    ON fi.`item` = SUBSTR(sv.`barcode`, 1, 8) 
	                LEFT JOIN fb_soft_version fsv 
	                    ON sv.`barcode` = fsv.`serial_number`
	                LEFT JOIN `prob_softwares` ps 
	                    ON 
	                    CASE
	                        WHEN ps.`conp` IS NOT NULL 
	                        THEN ps.`conp` = SUBSTRING_INDEX(sv.`conpBak`, "->", - 1) 
	                        ELSE 1 = 1 
	                    END 
	                    AND 
	                    CASE
	                        WHEN ps.`cpld` IS NOT NULL 
	                        THEN ps.`cpld` = SUBSTRING_INDEX(sv.`cpldBak`, "->", - 1) 
	                        ELSE 1 = 1 
	                    END 
	                    AND 
	                    CASE
	                        WHEN ps.`boot` IS NOT NULL 
	                        THEN ps.`boot` = SUBSTRING_INDEX(sv.`bootBak`, "->", - 1) 
	                        ELSE 1 = 1 
	                    END 
	                    AND 
	                    CASE
	                        WHEN ps.`pcb` IS NOT NULL 
	                        THEN ps.`pcb` = SUBSTRING_INDEX(sv.`pcbBak`, "->", - 1) 
	                        ELSE 1 = 1 
	                    END 
	                    AND ps.`datastate` = 1
	            WHERE sv.`executeTime` >= #startTime#
	            <isNotEmpty prepend="and" property="endTime">
	               <![CDATA[ sv.`executeTime` <= '$endTime$ 23:59:59']]>
	            </isNotEmpty>
	            GROUP BY sv.`projectId`, sv.`barcode`) sf 
	            LEFT JOIN pm_project_header ph 
	                ON sf.projectId = ph.`projectId` 
	            LEFT JOIN pm_project_member pm1 
	                ON ph.`projectId` = pm1.`projectId` 
	                AND pm1.`memberRole` = "30" 
	                AND pm1.`effectiveTo` IS NULL 
	                AND pm1.`fromFlag` = 1 
	            LEFT JOIN pm_project_member pm2 
	                ON ph.`projectId` = pm2.`projectId` 
	                AND pm2.`memberRole` = "30" 
	                AND pm2.`effectiveTo` IS NULL 
	                AND pm1.`fromFlag` = 2 
	            LEFT JOIN pm_project_member sm 
	                ON ph.`projectId` = sm.`projectId` 
	                AND sm.`memberRole` = "20" 
	                AND sm.`effectiveTo` IS NULL 
	            LEFT JOIN fnd_department fd 
	                ON ph.`column001` = fd.`departmentNum` 
	            LEFT JOIN prob_main pbm 
	                ON pbm.id = sf.probId 
	        WHERE (
	                (
	                    ph.`column012` = 0 
	                    OR ph.`column012` IS NULL
	                ) 
	                AND ph.columno12_readonly = - 1
	            ) 
	            OR ph.columno12_readonly = 0 
	        GROUP BY sf.projectId, sf.itemName
         ) t -->
;

-- L0083 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:940 | query_prob_statistics | fb_items, fb_soft_version, pm_project_header, pm_project_member, pm_project_soft_change_logs, pm_project_soft_version, fnd_department
<!-- SELECT 
		    ph.`projectId`, ph.`projectCode`, ph.`projectName`, sf.itemName, sf.softInfo, ph.`column001` AS officeCode, fd.`departmentName` AS officeName, sm.`memberName` AS serviceManagerName, pm1.`memberName` AS programManagerNameA, pm2.`memberName` AS programManagerNameB, MAX(sf.executeTime) AS executeTime, sf.updateCount, MAX(sf.probId) AS probId, pbm.`theme` AS probTheme 
		FROM
		    (SELECT 
		        sv.`projectId`, fi.`itemname`, CONCAT(
		            "出厂版本信息:[conp:", fsv.`conp`, ",cpld:", fsv.`cpld`, ",boot:", fsv.`boot`, ",pcb:", fsv.`pcb`, "];\r\n", GROUP_CONCAT(
		                CONCAT(
		                    scl.`createTime`, "：", scl.changeRemark, "，conp:[", 
		                    CASE
		                        WHEN sv.`conpChange` = 1 
		                        THEN CONCAT(sv.`conpBak`, "->", sv.`conp`) 
		                        ELSE sv.`conp` 
		                    END, "]", "，cpld:[", 
		                    CASE
		                        WHEN sv.`cpldChange` = 1 
		                        THEN CONCAT(sv.`cpldBak`, "->", sv.`cpld`) 
		                        ELSE sv.`cpld` 
		                    END, "]", "，boot:[", 
		                    CASE
		                        WHEN sv.`bootChange` = 1 
		                        THEN CONCAT(sv.`bootBak`, "->", sv.`boot`) 
		                        ELSE sv.`boot` 
		                    END, "]", "，pcb:[", 
		                    CASE
		                        WHEN sv.`pcbChange` = 1 
		                        THEN CONCAT(sv.`pcbBak`, "->", sv.`pcb`) 
		                        ELSE sv.`pcb` 
		                    END, "]"
		                ) SEPARATOR ";\r\n"
		            )
		        ) AS softInfo, COUNT(*) AS updateCount, MAX(ps.`probId`) AS probId, MAX(sv.`executeTime`) AS executeTime 
		    FROM
		        pm_project_soft_version sv 
		        LEFT JOIN pm_project_soft_change_logs scl 
		            ON sv.`projectId` = scl.projectId 
		            AND sv.`logId` = scl.id 
		        LEFT JOIN fb_items fi 
		            ON fi.`item` = SUBSTR(sv.`barcode`, 1, 8) 
		        LEFT JOIN fb_soft_version fsv 
		            ON sv.`barcode` = fsv.`serial_number`
		        LEFT JOIN `prob_softwares` ps 
		            ON 
		            CASE
		                WHEN ps.`conp` IS NOT NULL 
		                THEN ps.`conp` = SUBSTRING_INDEX(sv.`conpBak`, "->", - 1) 
		                ELSE 1 = 1 
		            END 
		            AND 
		            CASE
		                WHEN ps.`cpld` IS NOT NULL 
		                THEN ps.`cpld` = SUBSTRING_INDEX(sv.`cpldBak`, "->", - 1) 
		                ELSE 1 = 1 
		            END 
		            AND 
		            CASE
		                WHEN ps.`boot` IS NOT NULL 
		                THEN ps.`boot` = SUBSTRING_INDEX(sv.`bootBak`, "->", - 1) 
		                ELSE 1 = 1 
		            END 
		            AND 
		            CASE
		                WHEN ps.`pcb` IS NOT NULL 
		                THEN ps.`pcb` = SUBSTRING_INDEX(sv.`pcbBak`, "->", - 1) 
		                ELSE 1 = 1 
		            END 
		            AND ps.`datastate` = 1
		    WHERE sv.`executeTime` >= #probStatistic.startTime#
		    <isNotEmpty prepend="and" property="probStatistic.endTime">
		       <![CDATA[ sv.`executeTime` <= '$probStatistic.endTime$ 23:59:59']]>
		    </isNotEmpty>
		    GROUP BY sv.`projectId`, sv.`barcode`) sf 
		    LEFT JOIN pm_project_header ph 
		        ON sf.projectId = ph.`projectId` 
		    LEFT JOIN pm_project_member pm1 
		        ON ph.`projectId` = pm1.`projectId` 
		        AND pm1.`memberRole` = "30" 
		        AND pm1.`effectiveTo` IS NULL 
		        AND pm1.`fromFlag` = 1 
		    LEFT JOIN pm_project_member pm2 
		        ON ph.`projectId` = pm2.`projectId` 
		        AND pm2.`memberRole` = "30" 
		        AND pm2.`effectiveTo` IS NULL 
		        AND pm1.`fromFlag` = 2 
		    LEFT JOIN pm_project_member sm 
		        ON ph.`projectId` = sm.`projectId` 
		        AND sm.`memberRole` = "20" 
		        AND sm.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_department fd 
		        ON ph.`column001` = fd.`departmentNum` 
		    LEFT JOIN prob_main pbm 
		        ON pbm.id = sf.probId 
		WHERE (
		        (
		            ph.`column012` = 0 
		            OR ph.`column012` IS NULL
		        ) 
		        AND ph.columno12_readonly = - 1
		    ) 
		    OR ph.columno12_readonly = 0 
		GROUP BY sf.projectId, sf.itemName -->
		select * from statistic_tempTable
		<isNotEmpty prepend=" order by " property="displayParam.sort">
            $displayParam.sort$
            <isEqual prepend=" " property="displayParam.order" compareValue="desc">
                desc
              </isEqual>
            <isEqual prepend=" " property="displayParam.order" compareValue="asc">
                asc
            </isEqual>
        </isNotEmpty>
        <isEmpty prepend=" order by " property="displayParam.sort">
            executeTime desc
        </isEmpty>
        <isNotEmpty property="displayParam.offset">
            limit #displayParam.offset#,  #displayParam.pagesize#
        </isNotEmpty>
;

-- L0084 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:1442 | query_prob_read_log | fnd_user_info
SELECT 
		    rl.*, IFNULL(
		        CONCAT(ui.`username`, "-", ui.`realName`), rl.reader
		    ) AS readerName 
		FROM
		    prob_read_log rl 
		    LEFT JOIN fnd_user_info ui 
		        ON rl.`reader` = ui.`username` 
		where rl.probId = #probReadLog.probId#
		<isNotEmpty prepend="and" property="probReadLog.reader"> rl.reader = #probReadLog.reader# </isNotEmpty>
		<isNotEmpty prepend="and" property="probReadLog.status"> rl.status = #probReadLog.status# </isNotEmpty>
        order by rl.readTime desc
        <isNotEmpty property="displayParam.offset">
            limit #displayParam.offset#,  #displayParam.pagesize#
        </isNotEmpty>
;

-- L0085 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:1460 | query_prob_read_statistics | fnd_basic_data, fnd_user_info
SELECT 
		    p.probNum, p.`theme`, p.`watch`, bd1.`basicDataName` AS watchName, p.`status`, bd2.`basicDataName` AS statusName, 
		    ui.`username` AS render, CONCAT(ui.username, "-", ui.realName) AS readerName, rl.firstTime, rl.commitTime, rl.readStatus
		FROM
		    prob_main p 
		    LEFT JOIN `fnd_user_info` ui 
		        ON FALSE = FIND_IN_SET(ui.`roleIds`, ";1;,;9;,;20;") 
		    LEFT JOIN 
		        (SELECT 
		            probId, reader, MIN(readTime) AS firstTime, MAX(commitTime) AS commitTime, IFNULL(MAX(STATUS), 0) AS readStatus
		        FROM
		            prob_read_log 
		        GROUP BY `probId`, `reader`) rl 
		        ON ui.`username` = rl.`reader` 
		    LEFT JOIN fnd_basic_data bd1 
		        ON p.`watch` = bd1.`basicDataId` 
		        AND bd1.`dataTypeCode` = '30' 
		        AND bd1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data bd2 
		        ON p.`priority` = bd2.`basicDataId` 
		        AND bd2.`dataTypeCode` = '32' 
		    LEFT JOIN fnd_basic_data bd3 
		        ON p.`status` = bd3.basicDataId 
		        AND bd3.dataTypeCode = '31' 
		        AND bd3.`effectiveTo` IS NULL 
        <dynamic prepend="where">
            <isNotEmpty prepend="and" property="prob.probNum"> p.probNum = #probNum#</isNotEmpty>
            <isNotEmpty prepend="and" property="prob.theme"> p.theme = #theme#</isNotEmpty>
            <isNotEmpty prepend="and" property="probReadLog.reader"> p.probNum = #probNum#</isNotEmpty>
            <isNotEmpty prepend="and" property="probNum"> p.probNum = #probNum#</isNotEmpty>
        </dynamic>
		ORDER BY p.visibleRange, p.`id`
;

-- L0086 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config.xml:1495 | count_prob_read_statistics | fnd_basic_data, fnd_user_info
SELECT 
            p.probNum, p.`theme`, p.`watch`, bd1.`basicDataName` AS watchName, p.`status`, bd2.`basicDataName` AS statusName, CONCAT(ui.username, "-", ui.realName) AS readerName, rl.* 
        FROM
            prob_main p 
            LEFT JOIN `fnd_user_info` ui 
                ON FALSE = FIND_IN_SET(ui.`roleIds`, ";1;,;9;,;20;") 
            LEFT JOIN 
                (SELECT 
                    probId, reader, MIN(readTime) AS firstTime, MAX(commitTime) AS commitTime, IFNULL(MAX(STATUS), 0) AS readStatus
                FROM
                    prob_read_log 
                GROUP BY `probId`, `reader`) rl 
                ON ui.`username` = rl.`reader` 
            LEFT JOIN fnd_basic_data bd1 
                ON p.`watch` = bd1.`basicDataId` 
                AND bd1.`dataTypeCode` = '30' 
                AND bd1.`effectiveTo` IS NULL 
            LEFT JOIN fnd_basic_data bd2 
                ON p.`priority` = bd2.`basicDataId` 
                AND bd2.`dataTypeCode` = '32' 
            LEFT JOIN fnd_basic_data bd3 
                ON p.`status` = bd3.basicDataId 
                AND bd3.dataTypeCode = '31' 
                AND bd3.`effectiveTo` IS NULL 
        <dynamic prepend="where">
            <isNotEmpty prepend="and" property="probNum"> p.probNum = #probNum#</isNotEmpty>
            <isNotEmpty prepend="and" property="theme"> p.theme = #theme#</isNotEmpty>
            <isNotEmpty prepend="and" property="probNum"> p.probNum = #probNum#</isNotEmpty>
            <isNotEmpty prepend="and" property="probNum"> p.probNum = #probNum#</isNotEmpty>
        </dynamic>
        ORDER BY p.visibleRange, p.`id`
;

-- L0087 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config_bak.xml:27 | query_prob_count | fnd_basic_data
<![CDATA[
			SELECT count(*)
			FROM prob_main t1 
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			AND t2.`effectiveTo` IS NULL
		]]>	
		<isNotEmpty prepend=" " property="affectedVersion"> left join (
		SELECT 
		  probId,  GROUP_CONCAT(
		        CONCAT(
		            "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, "")
		        ) SEPARATOR ";"
		    ) AS affectedVersion
		FROM
		    prob_softwares 
		GROUP BY probId) a 
		on a.probId = t1.id
		</isNotEmpty>
			where t1.effectiveTo is null
		<isNotEmpty prepend="and" property="probNum"><![CDATA[ t1.probNum like '%$probNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="watch"><![CDATA[ t1.watch = #watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="theme"><![CDATA[ t1.theme like '%$theme$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="status"><![CDATA[ t1.`status` = #status#]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="productType"><![CDATA[ t1.productType like concat("%", #productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="desc"><![CDATA[ t1.desc like concat("%", #desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="affectedVersion"><![CDATA[ a.affectedVersion like concat("%", #affectedVersion#, "%")]]></isNotEmpty>
		
		<isNotEmpty property="visibleRange">
            <isNotEqual prepend="and" property="visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #visibleRange#
                <isNotEmpty prepend="or" property="trackingUser"> t1.trackingUser = #trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
;

-- L0088 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config_bak.xml:80 | query_prob_list | fnd_basic_data, fnd_user_info
<![CDATA[
			SELECT t1.id as probId, t1.probNum, t1.theme,  t1.watch, t4.basicDataName as watchName, t2.`basicDataName` AS priority, t1.status, t3.basicDataName AS statusName, t1.trackingUser, CONCAT(t1.trackingUser,"-",ui.realName) AS trackingUsername,  t1.createTime, t1.updateTime
			, t1.desc, t1.solution, t1.productType, a.affectedVersion 
			FROM prob_main t1 
			LEFT JOIN fnd_user_info ui ON ui.username = t1.trackingUser
			LEFT JOIN fnd_basic_data t4 ON t1.`watch` = t4.`basicDataId` AND t4.`dataTypeCode` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			LEFT JOIN fnd_basic_data t3 ON t1.`status` = t3.basicDataId AND t3.dataTypeCode = '31'
			AND t2.`effectiveTo` IS NULL
		]]>
			<!-- <isNotEmpty prepend=" " property="prob.affectedVersion">  -->
			left join (
		        SELECT 
		          probId,  GROUP_CONCAT(
		                CONCAT(
		                    IFNULL(CONCAT("conp:",conp), ""), IFNULL(CONCAT(" cpld:", cpld), ""), IFNULL(CONCAT(" boot:", boot), ""), IFNULL(CONCAT(" pcb:", pcb), "")
		                ) SEPARATOR ";<![CDATA[<br>]]>"
		            ) AS affectedVersion
		        FROM
		            prob_softwares 
		        GROUP BY probId) a 
		        on a.probId = t1.id
	     <!--    </isNotEmpty> -->
		WHERE t1.effectiveTo IS NULL
		<isNotEmpty prepend="and" property="prob.probNum"><![CDATA[ t1.probNum like '%$prob.probNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.watch"><![CDATA[ t1.watch = #prob.watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.theme"><![CDATA[ t1.theme like '%$prob.theme$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.status"><![CDATA[ t1.`status` = #prob.status#]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="prob.productType"><![CDATA[ t1.productType like concat("%", #prob.productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.desc"><![CDATA[ t1.desc like concat("%", #prob.desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedVersion"><![CDATA[ a.affectedVersion like concat("%", #prob.affectedVersion#, "%")]]></isNotEmpty>
        
        <isNotEmpty property="prob.visibleRange">
            <isNotEqual prepend="and" property="prob.visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #prob.visibleRange# 
                <isNotEmpty prepend="or" property="prob.trackingUser"> t1.trackingUser = #prob.trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
        
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isEmpty prepend=" order by " property="displayParam.sort">
            t1.createTime desc
        </isEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset#,  #displayParam.pagesize#
		</isNotEmpty>
;

-- L0089 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config_bak.xml:359 | query_prob_restore_list | fb_contract, fb_items, fb_shipment, fb_shipment_barcode, fb_soft_version, fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_soft_version, view_shipment_info_4_pm, fnd_department
<!-- <![CDATA[
			SELECT t1.* , b1.`itemname` as itemModel ,t6.`projectName` , t6.`column001`  AS officeCode , t9.`departmentName` AS officeName ,
			t4.`contractNo` , t2.`probId` , t6.`projectId` FROM 
			(SELECT a1.serial_number,CASE WHEN a2.conp IS NULL THEN a1.conp ELSE a2.conp END AS conp ,
				CASE WHEN a2.boot IS NULL THEN a1.boot ELSE a2.boot END AS boot,
				CASE WHEN a2.cpld IS NULL THEN a1.cpld ELSE a2.cpld END AS cpld,
				CASE WHEN a2.pcb IS NULL THEN a1.pcb ELSE a2.pcb END AS pcb
			 FROM fb_soft_version a1 
			LEFT JOIN pm_project_soft_version a2 ON a1.`serial_number` = a2.`barcode` AND a2.`datastate` = 1 ) t1 
			
			LEFT JOIN prob_softwares t2 ON CASE WHEN t2.`conp` IS NOT NULL THEN t1.`conp` = t2.`conp` ELSE 1=1 END 
			AND CASE WHEN t2.`boot` IS NOT NULL THEN t1.`boot` = t2.`boot` ELSE 1=1 END
			AND CASE WHEN t2.`cpld` IS NOT NULL THEN t1.`cpld` = t2.`cpld` ELSE 1=1 END
			AND CASE WHEN t2.`pcb` IS NOT NULL THEN t1.`pcb` = t2.`pcb` ELSE 1 =1 END
			LEFT JOIN view_shipment_info_4_pm t3 ON t1.`serial_number` = t3.`barcode`
			LEFT JOIN fb_items b1 ON t3.`itemCode` = b1.`item`
			LEFT JOIN pm_project_contract t4 ON t3.`contract_code` = t4.`contractNo`
			LEFT JOIN pm_project_group_relationship t5 ON t4.`projectGroupCode` = t5.`projectGroupCode`
			LEFT JOIN pm_project_header t6 ON t5.`projectCode` = t6.`projectCode`
			LEFT JOIN pm_project_member t7 ON t6.`projectId` = t7.`projectId` AND t7.`memberRole` = '30' AND t7.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t8 ON t6.`projectId` = t8.`projectId` AND t8.`memberRole` = '20' AND t8.`effectiveTo` IS NULL 
			LEFT JOIN fnd_department t9 ON t6.`column001` = t9.`departmentNum` 
			LEFT JOIN fnd_basic_data t10 ON t6.`projectState` = t10.`basicDataId` AND t10.`dataTypeCode` = '02' AND t10.`effectiveTo` IS NULL
			WHERE t2.`datastate` = 1 AND t2.`probId` =  #probRestore.probId# AND t4.`contractNo` IS NOT NULL
			AND t5.`projectCode` NOT LIKE '%his'
			AND NOT EXISTS(SELECT * FROM prob_restore WHERE serialNum = t1.serial_number)  
		]]> -->
		<![CDATA[
			SELECT t1.*, fi.`itemname` as itemModel, t6.`projectName`, t6.`column001` AS officeCode, t9.`departmentName` AS officeName, t4.`contractNo`,
			t2.`probId`, MAX(t6.`projectId`) AS projectId  
			FROM
			    (SELECT * FROM prob_softwares WHERE datastate = 1 AND probId = #probRestore.probId#) t2 
			    LEFT JOIN 
			        (SELECT  a1.serial_number, 
			            CASE WHEN a2.conp IS NULL THEN a1.conp ELSE a2.conp END AS conp, 
			            CASE WHEN a2.boot IS NULL THEN a1.boot ELSE a2.boot END AS boot, 
			            CASE WHEN a2.cpld IS NULL THEN a1.cpld ELSE a2.cpld END AS cpld, 
			            CASE WHEN a2.pcb IS NULL THEN a1.pcb ELSE a2.pcb END AS pcb 
			        FROM fb_soft_version a1 
			            LEFT JOIN pm_project_soft_version a2 
			                ON a1.`serial_number` = a2.`barcode` 
			                AND a2.`datastate` = 1) t1  
				ON  CASE WHEN t2.`conp` IS NOT NULL THEN t1.`conp` = t2.`conp` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`boot` IS NOT NULL THEN t1.`boot` = t2.`boot` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`cpld` IS NOT NULL THEN t1.`cpld` = t2.`cpld` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`pcb` IS NOT NULL THEN t1.`pcb` = t2.`pcb` ELSE 1 = 1 END 
			    INNER JOIN fb_shipment_barcode fsb 
			        ON fsb.`barcode` = t1.serial_number 
			        AND (
			            ISNULL(`fsb`.`rma_no`) 
			            OR (`fsb`.`rma_no` = '') 
			            OR (`fsb`.`rma_no` = 'null')
			        ) 
			    INNER JOIN fb_shipment fs ON fs.`packlist_id` = fsb.`pack_id` 
			    INNER JOIN fb_contract fc ON fc.`contract_id` = fs.`con_id`
			    INNER JOIN fb_items fi ON fi.`item` = fsb.`item`
			    INNER JOIN pm_project_contract t4 ON fc.`contract_code` = t4.`contractNo` 
			    INNER JOIN pm_project_group_relationship t5 ON t4.`projectGroupCode` = t5.`projectGroupCode` 
			    INNER JOIN pm_project_header t6 ON t5.`projectCode` = t6.`projectCode`
			    	AND (
			            (
			                column012 IS NOT NULL 
			                AND column012 <> 3
			            ) 
			            OR (
			                column012 IS NULL 
			                AND `columno12_readonly` <> 3
			            )
			        )  
			    LEFT JOIN fnd_department t9 ON t6.`column001` = t9.`departmentNum` 
			    LEFT JOIN fnd_basic_data t10 ON t6.`projectState` = t10.`basicDataId` AND t10.`dataTypeCode` = '02' AND t10.`effectiveTo` IS NULL 
			WHERE t4.`contractNo` IS NOT NULL 
			    AND t5.`projectCode` NOT LIKE '%his' 
			    AND NOT EXISTS 
			    (SELECT * FROM prob_restore WHERE serialNum = t1.serial_number AND probId = #probRestore.probId#) 
		]]>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ t1.serial_number like '$probRestore.serialNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ fi.itemname like '$probRestore.itemModel$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ t6.projectName like '%$probRestore.projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ t4.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ t6.column001 = #probRestore.officeCode#]]></isNotEmpty>
		<![CDATA[
			GROUP BY t1.serial_number
		]]>
;

-- L0090 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-prob-config_bak.xml:792 | query_exportProb_list | fnd_basic_data, fnd_user_info
SELECT 
		    t1.*, t2.`basicDataName` AS priorityName, t4.`basicDataName` AS watchName, t3.basicDataName AS statusName, CONCAT(t1.trackingUser, "-", ui.realName) AS trackingUsername, t.affectedVersion 
		FROM
		    prob_main t1 
		    LEFT JOIN fnd_user_info ui 
		        ON ui.username = t1.trackingUser 
		    LEFT JOIN fnd_basic_data t2 
		        ON t1.`priority` = t2.`basicDataId` 
		        AND t2.`dataTypeCode` = '32' 
		        AND t2.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t3 
		        ON t1.`status` = t3.basicDataId 
		        AND t3.dataTypeCode = '31' 
		        AND t3.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t4 
		        ON t1.`watch` = t4.basicDataId 
		        AND t4.dataTypeCode = '30' 
		        AND t4.`effectiveTo` IS NULL 
		    LEFT JOIN 
		        (SELECT 
		            probId, GROUP_CONCAT(
		                CONCAT_WS(
		                    "-", CONCAT("conp[", conp, "]"), CONCAT("cpld[", cpld, "]"), CONCAT("boot[", boot, "]"), CONCAT("conp[", pcb, "]")
		                ) SEPARATOR ";"
		            ) AS affectedVersion 
		        FROM
		            `prob_softwares` 
		        WHERE datastate = 1 
		        GROUP BY probId) t 
		        ON t.probId = t1.`id` 
		WHERE t1.effectiveTo IS NULL
;

-- L0091 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:1087 | select-quesnaire_template_header-list | fnd_basic_data, pm_cl_quesnaire_template_header
