-- L0102 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:1670 | select-evaluation_header-list | pm_project_header, fnd_department
<![CDATA[
            select a.*,         
            c.evaluationPeopleId as applyPersonId,c.evaluationPeopleName as applyPersonName,c.evaluationTime as applyTime,
            t2.departmentName AS officeName  
            from pm_cl_evaluation_header a          
            left join pm_cl_evaluation_header c on a.applyHeaderId=c.id
            left join pm_project_header t1 on a.projectId = t1.projectId
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum AND t2.`status` = 1
        ]]>
        <dynamic prepend="where">
             <isNotEqual prepend="and" property="id" compareValue="0">
                a.id=#id#
             </isNotEqual>
             <isNotEqual prepend="and" property="applyHeaderId" compareValue="0">
                a.applyHeaderId=#applyHeaderId#
             </isNotEqual>
            <isNotEqual prepend="and" property="evaluationType" compareValue="0">
                a.evaluationType=#evaluationType#
            </isNotEqual>
            <isNotEmpty prepend="and" property="projectCode">
                a.projectCode =#projectCode#
            </isNotEmpty>
            <isNotEmpty prepend="and" property="evaluationPeopleId">
                a.evaluationPeopleId =#evaluationPeopleId#
            </isNotEmpty>
            <isNotEqual prepend="and" property="status" compareValue="0">
                a.status=#status#
             </isNotEqual>
        </dynamic>
        <![CDATA[
            order by a.createdTime desc 
        ]]>
;

-- L0103 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:1732 | select-evaluation_header-objMap | pm_project_header, pm_project_member, fnd_department
<![CDATA[
            select 
            a.*, 
            c.evaluationPeopleId as applyPersonId,c.evaluationPeopleName as applyPersonName,c.evaluationTime as applyTime ,
            t2.departmentName AS officeName ,mm.memberName, 
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS implType 
            from (select * from pm_cl_evaluation_header  order by createdTime 
        ]]>
        <isEqual prepend=" " property="sqlText" compareValue="desc">
            desc) a
        </isEqual>
        <isEqual prepend=" " property="sqlText" compareValue="asc">
            asc) a
        </isEqual>
        <![CDATA[           
            left join pm_cl_evaluation_header c on a.applyHeaderId=c.id
            join pm_project_header t1 on c.projectId = t1.projectId and t1.projectState != 20
            LEFT JOIN 
                (SELECT 
                    m.projectId, GROUP_CONCAT(m.memberName) AS memberName 
                FROM
                    pm_project_member m 
                WHERE m.effectiveTo IS NULL 
                    AND m.memberRole = 60 
                GROUP BY m.projectId) mm 
                ON mm.projectId = t1.projectId 
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum AND t2.`status` = 1
        ]]>
        <dynamic prepend="where">
            <isNotEqual prepend="and" property="pmClEvaluationHeader.evaluationType" compareValue="0">
                a.evaluationType=#pmClEvaluationHeader.evaluationType#
            </isNotEqual>
        </dynamic>
        <![CDATA[
            group by a.projectCode
        ]]>
;

-- L0104 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:1777 | select-evaluation_header-objMap | pm_project_header, fnd_department
<![CDATA[
            select 
            a.*, 
            c.evaluationPeopleId as applyPersonId,c.evaluationPeopleName as applyPersonName,c.evaluationTime as applyTime ,
            t2.departmentName AS officeName ,mm.memberName, 
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS implType 
        ]]>
        FROM
            pm_cl_evaluation_header a 
            INNER JOIN 
                (SELECT 
                <isEqual property="sqlText" compareValue="desc">
                    MAX(id) AS id 
                </isEqual>
                <isEqual property="sqlText" compareValue="asc">
                    MIN(id) AS id 
                </isEqual>
                FROM
                    pm_cl_evaluation_header 
                GROUP BY projectId) b 
                ON b.id = a.id 
        <![CDATA[           
            left join pm_cl_evaluation_header c on a.applyHeaderId=c.id
            join pm_project_header t1 on c.projectId = t1.projectId and t1.projectState != 20
            LEFT JOIN 
                temp_final_customer mm 
                ON mm.projectId = t1.projectId 
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum AND t2.`status` = 1
        ]]>
        <dynamic prepend="where">
            <isNotEqual prepend="and" property="pmClEvaluationHeader.evaluationType" compareValue="0">
                a.evaluationType=#pmClEvaluationHeader.evaluationType#
            </isNotEqual>
        </dynamic>
        <![CDATA[
            group by a.projectCode
        ]]>
;

