-- L0109 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:1978 | query-orderline-fromsap-bycontractno | fb_items
SELECT
            podfs.contractNo contractNo,
            polfs.itemCode itemCode,
            polfs.itemDesc itemName,
            fi.itemname as model,
            polfs.orderQuantity orderQuantity,
            polfs.openQuantity openQuantity,
            polfs.orderNumber orderNumber,
            polfs.lineNum lineNum,
            (
                polfs.orderQuantity - polfs.openQuantity
            ) deliverQuantity
        FROM
            pm_order_line_from_sap polfs
        LEFT JOIN pm_order_data_from_sap podfs ON polfs.orderNumber = podfs.orderNumber
            AND podfs.`orderType` = 0
            AND polfs.compCode = podfs.compCode
        LEFT JOIN fb_items fi
            on polfs.itemCode=fi.item
        WHERE
            podfs.contractNo = #contractNo# and polfs.`lineType` = 0
;

-- L0110 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2049 | query-orderdatalist-byprojectid | fb_items, pm_project_product_line
<!-- SELECT
            pppl.id,
            pppl.projectId projectId,
            pppl.contractNo,
            pppl.itemCode itemCode,
            pppl.itemName itemName,
            fi.itemname as model,
            pppl.orderQuantity orderQuantity,
            pppl.deliverQuantity deliverQuantity,
            pppl.openQuantity openQuantity,
            CASE
        WHEN pppl.projectQuantity IS NULL THEN
            pppl.orderQuantity
        ELSE
            pppl.projectQuantity
        END AS projectQuantity
        FROM
            pm_project_product_line pppl 
        LEFT JOIN fb_items fi
            ON pppl.itemCode=fi.item
        WHERE
            pppl.projectId = #projectId# -->
        SELECT 
            pppl.id, pppl.projectId projectId, pppl.contractNo, pppl.itemCode itemCode, pppl.itemName itemName, fi.itemname AS model, SUM(pppl.orderQuantity) AS orderQuantity, SUM(pppl.deliverQuantity) AS deliverQuantity, SUM(pppl.openQuantity) openQuantity, 
            CASE
                WHEN pppl.projectQuantity IS NULL 
                THEN SUM(pppl.orderQuantity) 
                ELSE SUM(pppl.projectQuantity) 
            END AS projectQuantity 
        FROM
            pm_project_product_line pppl 
            LEFT JOIN fb_items fi 
                ON pppl.itemCode = fi.item 
        WHERE pppl.projectId = #projectId# 
        GROUP BY pppl.itemCode
;

-- L0111 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2106 | query-shipmentinfo-bycontractno | pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName, 
        vsep.receiveName receiveName, vsep.emsNum emsNum, vsep.packdate packdate, vsep.emsCompany emsCompany,NULL AS installAddress
        FROM view_shipment_info_4_pm vsip 
        LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
        WHERE vsip.contract_code in ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
            and contractNo in ($contractNo$) and projectId = #projectId#
        )
        UNION ALL 
        SELECT `contractNo`,`barcode`,`itemCode`,`itemName`,`receiveName`,`emsNum`,`packdate`,`emsCompany`,`installAddress` 
        FROM pm_project_shipment pps WHERE contractNo in ($contractNo$) and projectId = #projectId#
             AND EXISTS 
            (SELECT 
                1 
            FROM
                view_shipment_info_4_pm vsip 
                LEFT JOIN view_shipment_ems_4_pm vsep 
                    ON vsep.contract_code = vsip.contract_code 
                    AND vsep.packId = vsip.packId 
            WHERE vsip.contract_code IN ($contractNo$) 
                AND vsip.barcode = pps.barcode)
;

-- L0112 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2129 | query-shipmentinfo-bycontractno | fb_items, fb_shipment_barcode_relation, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName, 
	        vsep.receiveName receiveName, vsep.emsNum emsNum, vsep.packdate packdate, vsep.emsCompany emsCompany,NULL AS installAddress,
	        NULL AS chProjectId, NULL AS chContractNo, NULL AS transferProjectId, NULL AS transferContractNo, -1 AS transferFlag,
	        vsip.barcode2 barCode2, vsip.itemCode2 itemCode2, vsip.itemName2 itemName2
        FROM view_shipment_info_4_pm vsip 
	        LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
	        WHERE vsip.contract_code in ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
	            and contractNo in ($contractNo$) and projectId = #projectId#
	        )
	        <isNotEmpty prepend="and" property="profitCenter"> vsip.profitCenter = #profitCenter# </isNotEmpty>
        UNION ALL 
        SELECT pps.`contractNo`,pps.`barcode`,pps.`itemCode`,pps.`itemName`,pps.`receiveName`,pps.`emsNum`,pps.`packdate`,pps.`emsCompany`,pps.`installAddress`, 
	        pps.chProjectId, pps.chContractNo, pps.transferProjectId, pps.transferContractNo, pps.transferFlag,
	        sbr.`sn2` AS barCode2, sbr.`item2` AS itemCode2, fi.describe_ AS itemName2
        FROM pm_project_shipment pps 
	        LEFT JOIN `fb_shipment_barcode_relation` sbr 
		        ON sbr.contract = REPLACE(pps.contractNo, '-C', '')
		        AND pps.barcode = sbr.sn1 
		    LEFT JOIN fb_items fi 
		        ON fi.`item` = sbr.`item2` 
        WHERE contractNo in ($contractNo$) and projectId = #projectId#
             <isEqual prepend="AND" property="excludeTransferOut" compareValue="">transferFlag != 1</isEqual>
             AND EXISTS 
            (SELECT 
                1 
            FROM
                view_shipment_info_4_pm vsip 
                LEFT JOIN view_shipment_ems_4_pm vsep 
                    ON vsep.contract_code = vsip.contract_code 
                    AND vsep.packId = vsip.packId 
            WHERE vsip.contract_code IN ($sourceContractNo$)
            <!-- WHERE FIND_IN_SET(vsip.contract_code, REPLACE(REPLACE(#contractNo#, '-C', ''), "'",'')) -->
                AND vsip.barcode = pps.barcode)
        ORDER BY transferFlag asc
;

