-- L0118 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2330 | query_hist_soft_version_change | pm_project_soft_change_logs
<![CDATA[
            SELECT id, CONCAT( changeVersion,'(' ,DATE_FORMAT(createTime,'%Y-%m-%d'),')' )AS `version` FROM pm_project_soft_change_logs 
                WHERE projectId = #projectId# ORDER BY createTime DESC;
        ]]>
