-- L0119 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2355 | query_hist_soft_version_list | fb_shipment_barcode_relation, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_soft_version
<!-- <![CDATA[
            SELECT * FROM pm_project_soft_version WHERE projectId = #projectId#  AND logId = #id#
             ORDER BY conpChange  DESC ,bootChange DESC , cpldChange DESC ,pcbChange DESC
        ]]> -->
        SELECT 
		    sv.*, MAX(sbr.`item2`) AS itemCode2, MAX(sbr.`sn2`) AS barCode2 
		FROM
		    pm_project_soft_version sv 
		    LEFT JOIN `pm_project_header` ph 
		        ON sv.`projectId` = ph.`projectId` 
		    LEFT JOIN `pm_project_group_relationship` pgr 
		        ON pgr.`projectCode` = ph.`projectCode` 
		    LEFT JOIN `pm_project_contract` pc 
		        ON pc.`projectGroupCode` = pgr.`projectGroupCode` 
		    LEFT JOIN `fb_shipment_barcode_relation` sbr 
		        ON sbr.contract = REPLACE(pc.contractNo, '-C', '')
		        AND sv.barcode = sbr.sn1 
		WHERE sv.projectId = #projectId# 
		    AND sv.logId = #id# 
	    GROUP BY sv.`id`
		ORDER BY sv.conpChange DESC, sv.bootChange DESC, sv.cpldChange DESC, sv.pcbChange DESC
;

