-- L0123 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2469 | query-projectplanevent-byproject | fnd_basic_data
<![CDATA[
            select distinct fbp.dataTypeCode dataTypeCode, fbp.basicDataId basicDataId, concat(fbp.dataTypeCode, '-', fbp.basicDataId) eventKey, 
            fbp.column010 column010, fbp.column011 column011, fbd.basicDataName eventValue from fnd_basic_prjstate fbp 
            left join fnd_basic_data fbd on fbd.dataTypeCode = fbp.dataTypeCode and fbd.basicDataId = fbp.basicDataId
            where fbp.column011 = #column011# and fbd.effectiveFrom <= now() and (fbd.effectiveTo > now() or fbd.effectiveTo is null)
        ]]>
        <isNotNull prepend="and " property="column010">fbp.column010 = #column010#</isNotNull>
        <isNull prepend="and " property="column010">fbp.column010 is null</isNull>
        ORDER BY fbd.`sortId`
;

-- L0124 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2498 | query_pm_member_list | fnd_basic_data, pm_project_member
<![CDATA[
            SELECT d.`basicDataName` as memberRoleName ,m.* ,CASE WHEN (m.effectiveFrom <= NOW() AND (m.effectiveTo IS NULL OR m.effectiveTo > NOW())) THEN 1 ELSE -1 END AS datastate FROM pm_project_member m LEFT JOIN fnd_basic_data d ON m.`memberRole` = d.`basicDataId` AND d.`dataTypeCode` = '03' WHERE projectId = #projectId#
        ]]>
;

-- L0125 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:2545 | query-projecttask-buprojectid | fnd_basic_data, pm_project_task
<![CDATA[
            select ppt.taskId, ppt.contractNo, ppt.projectId, concat(ppt.taskTypeCode, '-', ppt.taskTypeId) eventKeyStr, fbd.basicDataName eventValue, 
            ppt.eventPlanHappenDate eventPlanHappenDateStr, ppt.eventPlanHappenDateENG eventPlanHappenDateENGStr, ppt.eventActualFinishDate eventActualFinishDateStr,
            ppt.visibleFlag from pm_project_task ppt 
            left join fnd_basic_data fbd on fbd.dataTypeCode = ppt.taskTypeCode and fbd.basicDataId = ppt.taskTypeId
