-- L0146 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:3379 | query-cbData-list | fnd_act_hi_comment, pm_cl_callback, pm_cl_callback_quesnaire, pm_cl_quesnaire_result_header, pm_cl_quesnaire_result_line, pm_cl_quesnaire_template_line, pm_project_header, pm_project_member, fnd_department
<![CDATA[
            select 
            a.id as id,a.projectName as projectName,a.projectCode as projectCode,a.evaluationResult as evaResult,a.times as times,a.projectId as projectId,
            case when a.updatedTime is null then a.createdTime else a.updatedTime end as cbTime ,
            b.quesMarkScore as totalScore, b.quesMarkResult as cbResult,
            e1.questionAnswer as equExplain, e2.questionAnswer as opinion,
            a.evaluationComment as approveRemark,
            c1.questionScore  as projectScore,  c2.questionScore  as equScore,
            c3.questionScore  as engScore,  c4.questionScore  as otherScore ,t2.departmentName as officeName, t3.memberName as pmRealName,
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS serviceType 
            from (select aa.* ,count(aa.id)as times from (select *  from pm_cl_evaluation_header order by createdTime desc)aa where aa.evaluationType=3 and aa.status=1 group by aa.projectCode) a
            left join pm_cl_quesnaire_result_header b on a.id=b.evaluationHeaderId and b.status=1
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c1  on b.id=c1.quesnaireResultHeaderId  and c1.quesTypeForCB=10 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c2  on b.id=c2.quesnaireResultHeaderId  and c2.quesTypeForCB=20
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c3  on b.id=c3.quesnaireResultHeaderId  and c3.quesTypeForCB=30 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c4  on b.id=c4.quesnaireResultHeaderId  and c4.quesTypeForCB=40
            left join pm_cl_quesnaire_template_line d1 on b.quesnaireTemplateHeaderId=d1.quesnaireTemplateHeaderId and d1.questionNum=5
            left join pm_cl_quesnaire_result_line e1 on e1.quesnaireResultHeaderId=b.id and e1.quesnaireTemplateLineId=d1.id
            left join pm_cl_quesnaire_template_line d2 on b.quesnaireTemplateHeaderId=d2.quesnaireTemplateHeaderId and d2.questionNum=8
            left join pm_cl_quesnaire_result_line e2 on e2.quesnaireResultHeaderId=b.id and e2.quesnaireTemplateLineId=d2.id
            LEFT JOIN pm_project_header t1 ON a.projectId = t1.projectId
        LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum
        LEFT JOIN pm_project_member t3 ON t1.projectId = t3.projectId AND t3.memberRole = 30    AND t3.effectiveTo IS NULL
        ]]>
        <![CDATA[ 
            where t1.projectState != 20
        ]]>
        <isNotEmpty prepend="and" property="cbStartTime">
            <![CDATA[ 
            DATE_FORMAT(a.createdTime,'%Y-%m-%d')>=DATE_FORMAT(#cbStartTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="cbEndTime">
            <![CDATA[ 
            DATE_FORMAT(a.createdTime,'%Y-%m-%d')<=DATE_FORMAT(#cbEndTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="serviceType"><![CDATA[ (t1.column012 = #serviceType# or t1.columno12_readonly= #serviceType#)]]></isNotEmpty>
        <![CDATA[
            group by a.projectCode
        ]]>
        <![CDATA[
            UNION
            select  a.quesnaireId as id,t1.projectName as projectName,t1.projectCode as projectCode,b.quesMarkResult as evaResult,a.times as times,a.projectId as projectId,
                case when a.updateTime is null then a.createTime else a.updateTime end as cbTime ,
                b.quesMarkScore as totalScore, b.quesMarkResult as cbResult,
                e1.questionAnswer as equExplain, e2.questionAnswer as opinion,
                ahc.message as approveMessage,
                c1.questionScore  as projectScore,  c2.questionScore  as equScore,
                c3.questionScore  as engScore,  c4.questionScore  as otherScore ,t2.departmentName as officeName, t3.memberName as pmRealName,
                CASE
                    WHEN t1.column012 IS NULL 
                    AND t1.columno12_readonly = - 1 
                    THEN t1.column012 
                    WHEN t1.column012 IS NOT NULL 
                    THEN t1.column012 
                    ELSE t1.columno12_readonly 
                END AS serviceType 
                from (
                    SELECT 
                     cb.projectId,cb.applyState, cb.instId, cbq.*, cbq.quesnaireVersion as times
                    FROM
                      pm_cl_callback cb 
                      LEFT JOIN (SELECT * FROM pm_cl_callback_quesnaire WHERE quesnaireState = 1 AND id IN (SELECT MAX(id)  FROM `pm_cl_callback_quesnaire` GROUP BY callBackId)) cbq 
                        ON cb.id = cbq.callBackId 
                        AND cbq.quesnaireState = 1
                    where cb.applyState != -1 and cbq.quesnaireId IS NOT NULL AND cb.projectId NOT IN (SELECT DISTINCT projectId  FROM `pm_cl_evaluation_header`)
                    ORDER BY cbq.createTime desc
                ) a
                left join (select ach.* from (select max(id) as maxId from `fnd_act_hi_comment` ahc left join `act_hi_taskinst` aht on ahc.taskId = aht.ID_ where procdefKey = 'CallBack' and aht.TASK_DEF_KEY_ = 'usertask2' group by objId, procdefKey, instId) t left join fnd_act_hi_comment ach on ach.id = t.maxId) ahc on a.instId = ahc.instId 
                left join pm_cl_quesnaire_result_header b on a.quesnaireId=b.id and b.status=1
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c1  on b.id=c1.quesnaireResultHeaderId  and c1.quesTypeForCB=10 
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c2  on b.id=c2.quesnaireResultHeaderId  and c2.quesTypeForCB=20
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c3  on b.id=c3.quesnaireResultHeaderId  and c3.quesTypeForCB=30 
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c4  on b.id=c4.quesnaireResultHeaderId  and c4.quesTypeForCB=40
                left join pm_cl_quesnaire_template_line d1 on b.quesnaireTemplateHeaderId=d1.quesnaireTemplateHeaderId and d1.questionNum=5
                left join pm_cl_quesnaire_result_line e1 on e1.quesnaireResultHeaderId=b.id and e1.quesnaireTemplateLineId=d1.id
                left join pm_cl_quesnaire_template_line d2 on b.quesnaireTemplateHeaderId=d2.quesnaireTemplateHeaderId and d2.questionNum=8
                left join pm_cl_quesnaire_result_line e2 on e2.quesnaireResultHeaderId=b.id and e2.quesnaireTemplateLineId=d2.id
                LEFT JOIN pm_project_header t1 ON a.projectId = t1.projectId
                LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum
                LEFT JOIN pm_project_member t3 ON t1.projectId = t3.projectId AND t3.memberRole = 30    AND t3.effectiveTo IS null
            WHERE t1.projectState != 20
        ]]>
        <isNotEmpty prepend="and" property="cbStartTime">
            <![CDATA[ 
            DATE_FORMAT(a.createTime,'%Y-%m-%d')>=DATE_FORMAT(#cbStartTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="cbEndTime">
            <![CDATA[ 
            DATE_FORMAT(a.createTime,'%Y-%m-%d')<=DATE_FORMAT(#cbEndTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="serviceType"><![CDATA[ (t1.column012 = #serviceType# or t1.columno12_readonly= #serviceType#)]]></isNotEmpty>
        <![CDATA[
            group by t1.projectCode
        ]]>
;

