-- L0151 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:3545 | query_current_plan | fnd_basic_data, pm_project_task
<!-- 查找最小未完成节点 -->
        <!-- <![CDATA[
            SELECT
              t3.`basicDataId`
            FROM pm_project_task t1
             LEFT JOIN fnd_basic_data t2 ON t1.`taskTypeCode` = t2.`dataTypeCode` AND t1.`taskTypeId` = t2.`basicDataId`
             LEFT JOIN fnd_basic_data t3 ON t2.`basicDataName` = t3.`basicDataName` AND t3.`dataTypeCode` = '22' AND t3.`effectiveTo` IS NULL
            WHERE t1.`effectiveFrom` < NOW()
                   AND ISNULL(t1.`effectiveTo`
                         OR (t1.`effectiveTo` > NOW()))
                   AND ISNULL(t1.`eventActualFinishDate`)
                  AND projectId = #projectId#
            GROUP BY t1.`projectId`  
            ORDER BY MIN(t1.`taskTypeId`)
        ]]> -->
        <!-- 查找最大已完成节点的下一个最小的未完成节点，根据taskTypeId判断。必须要求taskTypeId有序 -->
        <!-- <![CDATA[
            SELECT 
                t3.basicDataId 
            FROM
                (SELECT 
                    MIN(t1.`taskTypeId`) AS taskTypeId, t1.taskTypeCode, t1.projectId 
                FROM
                    pm_project_task t1 
                    LEFT JOIN 
                        (SELECT 
                            MAX(t1.`taskTypeId`) AS taskTypeId, projectId 
                        FROM
                            pm_project_task t1 
                        WHERE t1.`effectiveFrom` < NOW() 
                            AND ISNULL(
                                t1.`effectiveTo` 
                                OR (t1.`effectiveTo` > NOW())
                            ) 
                            AND FALSE = ISNULL(t1.`eventActualFinishDate`) 
                            AND t1.projectId = #projectId#
                        GROUP BY t1.`projectId`) t 
                        ON t1.projectId = t.projectId 
                WHERE t1.`effectiveFrom` < NOW() 
                    AND ISNULL(
                        t1.`effectiveTo` 
                        OR (t1.`effectiveTo` > NOW())
                    ) 
                    AND ISNULL(t1.`eventActualFinishDate`) 
                    AND t1.projectId = #projectId#
                    AND t1.`taskTypeId` >= IFNULL(t.`taskTypeId`, 0) 
                GROUP BY t1.`projectId`) t1 
                LEFT JOIN fnd_basic_data t2 
                    ON t1.`taskTypeCode` = t2.`dataTypeCode` 
                    AND t1.`taskTypeId` = t2.`basicDataId` 
                LEFT JOIN fnd_basic_data t3 
                    ON t2.`basicDataName` = t3.`basicDataName` 
                    AND t3.`dataTypeCode` = '22' 
                    AND t3.`effectiveTo` IS NULL 
        ]]> -->
        
        <!-- 查找最大已完成节点的下一个最小的未完成节点，根据taskId判断。节点的插入顺序与实施顺序一直，所以用order by limit 1 取最大最小记录 -->
        <![CDATA[
            SELECT 
                t3.basicDataId 
            FROM
                (SELECT 
                    t1.`taskTypeId` AS taskTypeId, t1.taskTypeCode, t1.projectId 
                FROM
                    pm_project_task t1 
                    LEFT JOIN 
                        (SELECT 
                            t1.`taskTypeId` AS taskTypeId, projectId, taskId 
                        FROM
                            pm_project_task t1 
                        WHERE t1.`effectiveFrom` < NOW() 
                            AND ISNULL(
                                t1.`effectiveTo` 
                                OR (t1.`effectiveTo` > NOW())
                            ) 
                            AND FALSE = ISNULL(t1.`eventActualFinishDate`) 
                            AND t1.projectId = #projectId# 
                        ORDER BY taskId DESC 
                        LIMIT 1) t 
                        ON t1.projectId = t.projectId 
                WHERE t1.`effectiveFrom` < NOW() 
                    AND ISNULL(
                        t1.`effectiveTo` 
                        OR (t1.`effectiveTo` > NOW())
                    ) 
                    AND ISNULL(t1.`eventActualFinishDate`) 
                    AND t1.projectId = #projectId# 
                    AND t1.`taskId` >= IFNULL(t.`taskId`, 0) 
                ORDER BY t1.taskId ASC 
                LIMIT 1) t1 
                LEFT JOIN fnd_basic_data t2 
                    ON t1.`taskTypeCode` = t2.`dataTypeCode` 
                    AND t1.`taskTypeId` = t2.`basicDataId` 
                LEFT JOIN fnd_basic_data t3 
                    ON t2.`basicDataName` = t3.`basicDataName` 
                    AND t3.`dataTypeCode` = '22' 
        ]]>
;

-- L0152 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:3672 | query_deliver_name | fnd_basic_data
<![CDATA[
            SELECT t2.`basicDataName` FROM pm_basic_prj_deliver t1 
