-- L0153 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:3704 | query_call_back_list | fnd_basic_data, pm_cl_callback, fnd_user_info
<![CDATA[
            SELECT  CONCAT( t1.`applyBy`,'-' ,t4.`realName`) AS applyByName ,
            CASE WHEN t3.`realName` IS NULL THEN '回访人员' ELSE CONCAT(t3.username,'-' , t3.realName) END AS ASSIGNEE_Name, t2.`ASSIGNEE_`,
            t5.basicDataName AS applyStateName , t1.applyTime , t2.id_ AS taskId , t1.projectId ,t1.instId,t1.applyState ,t1.id AS callbackId
            ,t1.applyBy 
            FROM pm_cl_callback t1 
            LEFT JOIN act_ru_task t2 ON t1.`instId` = t2.`PROC_INST_ID_`
            LEFT JOIN fnd_user_info t3 ON t2.`ASSIGNEE_` = t3.`username` AND t3.`status` = 1
            LEFT JOIN fnd_user_info t4 ON t1.`applyBy` = t4.`username` 
            LEFT JOIN fnd_basic_data t5 ON t5.basicDataId = t1.applyState AND t5.dataTypeCode = '25' AND t5.effectiveTo IS NULL
            WHERE t1.`projectId` = #projectId#
        ]]>
;

