-- L0159 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:3813 | query_Project_PreAndFinalInspection | fnd_basic_data, pm_project_header, pm_project_task
SELECT 
            pt.*, ph.`projectName`, fbd.`basicDataName` AS eventKeyStr, DATEDIFF(eventPlanHappenDate, CURDATE()) AS eventValueStr 
        FROM
            `pm_project_task` pt 
            LEFT JOIN `pm_project_header` ph 
                ON pt.`projectId` = ph.`projectId` 
            LEFT JOIN `fnd_basic_data` fbd 
                ON pt.`taskTypeCode` = fbd.`dataTypeCode` 
                AND pt.`taskTypeId` = fbd.`basicDataId` 
        WHERE DATEDIFF(eventPlanHappenDate, CURDATE()) BETWEEN 25 
            AND 31 
            AND pt.`effectiveTo` IS NULL 
            AND ph.`effectiveTo` IS NULL 
            AND (taskTypeId = 60 
                OR taskTypeId = 70) 
            AND eventActualFinishDate IS NULL
            AND eventPlanHappenDate IS NOT NULL 
        GROUP BY pt.projectId, pt.taskTypeId
;

-- L0160 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:3835 | query_Project_ArrivalReceipt | fb_contract, fb_shipment, fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_state, pm_project_task, pm_project_group
<!-- SELECT 
            pt.*, ph.`projectName`, fbd.`basicDataName` AS eventKeyStr, DATEDIFF(eventPlanHappenDate, CURDATE()) AS eventValueStr 
           # CASE
           #     WHEN DATEDIFF(eventPlanHappenDate, CURDATE()) > 0 
           #     THEN 0 
           #     ELSE 1 
           # END AS visibleFlag 
        FROM
            `pm_project_task` pt 
            LEFT JOIN `pm_project_header` ph 
                ON pt.`projectId` = ph.`projectId` 
            LEFT JOIN `fnd_basic_data` fbd 
                ON pt.`taskTypeCode` = fbd.`dataTypeCode` 
                AND pt.`taskTypeId` = fbd.`basicDataId` 
        WHERE DATEDIFF(eventPlanHappenDate, CURDATE()) IN (10, 20, - 10) 
            AND pt.`effectiveTo` IS NULL 
            AND ph.`effectiveTo` IS NULL 
            AND (taskTypeId = 30) 
            AND eventActualFinishDate IS NULL 
            AND eventPlanHappenDate IS NOT NULL 
            AND ph.`column004` = "运营商市场部" 
            AND (
                ph.column010 = 10 
                OR ph.column010 IS NULL
            ) 
        GROUP BY pt.projectId, pt.taskTypeId -->
        <!-- <![CDATA[
            SELECT 
                *, DATEDIFF(CURDATE(), t.packdate) AS eventValueStr 
            FROM
                (SELECT 
                    ph.`projectId`, pc.`contractNo`, ph.`projectName`, MAX(fs.`packdate`) packdate, 
                    CASE
                        WHEN pt.eventPlanHappenDate IS NULL 
                        THEN DATE_ADD(MAX(fs.`packdate`), INTERVAL 31 DAY) 
                        ELSE pt.eventPlanHappenDate 
                    END AS eventPlanHappenDate, "到货验收" AS eventKeyStr 
                FROM
                    pm_project_header ph 
                    LEFT JOIN `pm_project_state` ps 
                        ON ps.`projectId` = ph.`projectId` 
                    LEFT JOIN pm_project_task pt 
                        ON ph.`projectId` = pt.`projectId` 
                        AND pt.`effectiveTo` IS NULL 
                    LEFT JOIN pm_project_group_relationship pgr 
                        ON ph.`projectCode` = pgr.`projectCode` 
                    LEFT JOIN pm_project_group pg 
                        ON pg.`projectGroupCode` = pgr.`projectGroupCode` 
                    LEFT JOIN pm_project_contract pc 
                        ON pg.`projectGroupCode` = pc.`projectGroupCode` 
                    LEFT JOIN fb_contract fc 
                        ON fc.`contract_code` = pc.`contractNo` 
                    LEFT JOIN fb_shipment fs 
                        ON fc.`contract_id` = fs.`con_id` 
                WHERE ps.`shipmentState` = - 1 
                    AND ph.`effectiveTo` IS NULL 
                    AND DATEDIFF(CURDATE(), fs.`packdate`) <= 41 
                    AND (
                        (
                            pt.taskTypeId = 30 
                            AND pt.eventActualFinishDate IS NULL
                        ) 
                        OR pt.`taskTypeId` IS NULL
                    ) 
                    AND ph.`column004` = "运营商市场部" 
                    AND (
                        ph.column011 = 10 
                        OR ph.column011 IS NULL
                    )
                    AND ph.`projectState` IN (30, 31, 32) 
                GROUP BY ph.`projectId`, pc.`contractNo`) t 
            WHERE DATEDIFF(CURDATE(), t.packdate) IN (10, 20, 41)
        ]]> -->
        
        <![CDATA[
            SELECT 
              *,
              DATEDIFF(CURDATE(), t.packdate) AS eventValueStr 
            FROM
              (SELECT 
                ph.`projectId`,
                pc.`contractNo`,
                ph.`projectName`,
                MAX(fs.`packdate`) packdate,
                CASE
                  WHEN pt.eventPlanHappenDate IS NULL 
                  THEN DATE_ADD(MAX(fs.`packdate`), INTERVAL (SELECT SUBSTRING_INDEX(var, ';', -1) FROM `fnd_sys_arg` WHERE CODE = 'arrivalReceipt.mailTimes') DAY) 
                  ELSE pt.eventPlanHappenDate 
                END AS eventPlanHappenDate,
                "到货验收" AS eventKeyStr 
              FROM
                pm_project_header ph 
                LEFT JOIN `pm_project_state` ps 
                  ON ps.`projectId` = ph.`projectId` 
                LEFT JOIN pm_project_task pt 
                  ON ph.`projectId` = pt.`projectId` 
                  AND pt.`effectiveTo` IS NULL 
                LEFT JOIN pm_project_group_relationship pgr 
                  ON ph.`projectCode` = pgr.`projectCode` 
                LEFT JOIN pm_project_group pg 
                  ON pg.`projectGroupCode` = pgr.`projectGroupCode` 
                LEFT JOIN pm_project_contract pc 
                  ON pg.`projectGroupCode` = pc.`projectGroupCode` 
                LEFT JOIN fb_contract fc 
                  ON fc.`contract_code` = pc.`contractNo` 
                LEFT JOIN fb_shipment fs 
                  ON fc.`contract_id` = fs.`con_id` 
              WHERE ps.`shipmentState` = - 1 
                AND ph.`effectiveTo` IS NULL 
                AND DATEDIFF(CURDATE(), fs.`packdate`) <= (SELECT SUBSTRING_INDEX(SUBSTR(var, 1, LOCATE(';', var) - 1), ',', -1) FROM `fnd_sys_arg` WHERE CODE = 'arrivalReceipt.mailTimes')
                AND (
                  (
                    pt.taskTypeId = 30 
                    AND pt.eventActualFinishDate IS NULL
                  ) 
                  OR pt.`taskTypeId` IS NULL
                ) 
                AND ph.`column004` = "运营商市场部" 
                AND (
                  ph.column011 = 10 
                  OR ph.column011 IS NULL
                ) 
                AND ph.`projectState` IN (30, 31, 32) 
              GROUP BY ph.`projectId`,
                pc.`contractNo`) t 
            WHERE FIND_IN_SET(DATEDIFF(CURDATE(), t.packdate), (SELECT SUBSTR(var, 1, LOCATE(';', var) - 1) FROM `fnd_sys_arg` WHERE CODE = 'arrivalReceipt.mailTimes'))
        ]]>
;

