-- L0163 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:4051 | query_existsProject_by_contractNo | pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_group
SELECT 
            h.* 
        FROM
            `pm_project_contract` c 
            LEFT JOIN `pm_project_group` g 
                ON c.`projectGroupCode` = g.`projectGroupCode` 
            LEFT JOIN `pm_project_group_relationship` gr 
                ON g.`projectGroupCode` = gr.`projectGroupCode` 
            LEFT JOIN `pm_project_header` h 
                ON h.`projectCode` = REPLACE(gr.`projectCode`, "-his", "")
        WHERE c.`contractNo` in ($contractNo$) 
            AND h.projectId IS NOT NULL
;

-- L0164 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:4074 | querySpotCheckList | fb_items, fb_shipment_barcode_relation, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT 
		    contractNo, itemCode, IF(
		        itemName = IFNULL(itemName2, itemName), itemName, CONCAT(t.itemName, '\r\n(', itemName2, ')')
		    ) AS itemName, t.qty, t.barCodes 
		FROM
		    (SELECT 
	            contractNo, IF(t.itemCode2 IS NULL, t.itemCode, CONCAT(t.itemCode, '\r\n(', itemCode2, ')')) AS itemCode, 
	            CASE WHEN fi.`itemname` IS NULL OR fi.itemname = '' OR fi.itemname = '/' THEN fi.describe_  ELSE fi.itemname END AS itemName, 
	            CASE WHEN fi2.`itemname` IS NULL OR fi2.itemname = '' OR fi2.itemname = '/' THEN fi2.describe_  ELSE fi2.itemname END AS itemName2, 
	            COUNT(1) AS qty,
	            CASE
	                WHEN igi.itemCode IS NULL 
	                THEN GROUP_CONCAT(IF(barCode2 IS NULL, barcode, CONCAT(barcode, '(', barCode2, ')')) SEPARATOR '、') 
	                ELSE '' 
	            END AS barCodes
	        FROM
	            (
	            SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, -1 AS transferFlag, vsip.barcode2 barCode2, vsip.itemcode2 
	            FROM view_shipment_info_4_pm vsip 
	                LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
	                WHERE vsip.contract_code in ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
	                    and contractNo in ($contractNo$) and projectId = #projectId#
	                )
                <isNotEmpty prepend="and" property="profitCenter"> vsip.profitCenter = #profitCenter# </isNotEmpty>
	            UNION ALL 
	            SELECT pps.`contractNo`, pps.`barcode`, pps.`itemCode`, pps.transferFlag, sbr.sn2 as barCode2, sbr.item2 
	            FROM pm_project_shipment pps 
		            LEFT JOIN `fb_shipment_barcode_relation` sbr 
				        ON sbr.contract = REPLACE(pps.contractNo, '-C', '')
				        AND pps.barcode = sbr.sn1 
	            WHERE contractNo in ($contractNo$) and projectId = #projectId#
	                 AND EXISTS 
	                (SELECT 
	                    1 
	                FROM
	                    view_shipment_info_4_pm vsip 
	                    LEFT JOIN view_shipment_ems_4_pm vsep 
	                        ON vsep.contract_code = vsip.contract_code 
	                        AND vsep.packId = vsip.packId 
	                WHERE FIND_IN_SET(vsip.contract_code ,REPLACE(REPLACE(#contractNo#, '-C', ''), "'",''))
	                    AND vsip.barcode = pps.barcode)
	            ORDER BY transferFlag asc) t
	            LEFT JOIN `fb_items` fi
	                ON fi.`item` = t.itemCode
	            LEFT JOIN `fb_items` fi2 
                    ON fi2.`item` = t.itemCode2 
	            LEFT JOIN `pm_project_spot_check_ignore_item` igi 
	                ON igi.itemCode = t.itemCode 
	        WHERE t.transferFlag != 1
	        GROUP BY t.itemCode) t
        ORDER BY t.contractNo, barCodes DESC, t.itemCode ASC;
;

-- L0165 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:4139 | query_project_notify_list | pm_project_notification, fnd_user_info
<![CDATA[
