                    AND pm2.memberRole = 30 
                LEFT JOIN fnd_department fd 
                    ON fd.`departmentNum` = t.officeCode 
        ]]> -->
        <dynamic prepend="where">
            <isNotEmpty prepend="and" property="officeCode"> t.officeCode = #officeCode# </isNotEmpty>
        </dynamic>          
        ORDER BY t.officeCode, t.packdate
;

-- L0168 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:4466 | queryProjectInspectionCounts | fnd_basic_data, pm_project_header, pm_project_state, fnd_department
SELECT 
            ph.`column001` AS officeCode, fd.`departmentName` AS officeName, ps.`projectPlanState`, planState.`basicDataName` AS planState, COUNT(*) as count 
        FROM
            pm_project_header ph 
            LEFT JOIN `pm_project_state` ps 
                ON ps.`projectId` = ph.`projectId` 
            LEFT JOIN fnd_basic_data planState 
                ON planState.`dataTypeCode` = '22' 
                AND planState.`effectiveTo` IS NULL 
                AND planState.`basicDataId` = ps.`projectPlanState` 
            LEFT JOIN fnd_department fd 
                ON fd.`departmentNum` = ph.column001 
        WHERE ph.`projectState` IN (30, 31, 32) 
            AND ph.`effectiveTo` IS NULL 
            AND ph.`column004` = "运营商市场部" 
            AND (
                ph.column011 = 10 
                OR ph.column011 IS NULL
            )
        GROUP BY officeCode, projectPlanState 
        ORDER BY officeCode, projectPlanState
;

-- L0169 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config.xml:4490 | queryValidMemberByProjectIdsAndRoles | pm_project_member
SELECT DISTINCT 
           pm.`memberCode`, pm.`memberName`, pm.`memberRole`, IFNULL(pm.email, po.salesmanMail) AS email 
        FROM
            `pm_project_member` pm 
            LEFT JOIN `pm_person_from_oa` po 
                ON po.`salesmanCode` = SUBSTR(pm.`memberCode`, - 5) 
        WHERE pm.`effectiveTo` IS NULL 
        <isNotEmpty prepend="and" property="projectIds"> FIND_IN_SET(projectId, #projectIds#) </isNotEmpty>
        <isNotEmpty prepend="and" property="memberRoles"> FIND_IN_SET(memberRole, #memberRoles#) </isNotEmpty>
;

