-- L0213 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:2389 | find_transfer_project_list | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, fnd_department, pm_project_group
<![CDATA[
            select * from (
                SELECT 
                    `ph`.`projectId` AS `projectId`, `ph`.`projectCode` AS `projectCode`, `rank`.`basicDataName` AS `rank`, (
                        CASE
                            WHEN (
                                `pr`.`mergeBranchMark` IS NOT NULL
                            ) 
                            THEN CONCAT(
                                `ph`.`projectName`, '-', `pr`.`mergeBranchMark`
                            ) 
                            ELSE `ph`.`projectName` 
                        END
                    ) AS `projectName`, `fd`.`basicDataName` AS `projectStateName`, `ph`.`projectState` AS `projectState`, GROUP_CONCAT(
                        DISTINCT `pc`.`contractNo` SEPARATOR ','
                    ) AS `contractNo`, `ph`.`column001` AS `officeCode`, `d`.`departmentName` AS `officeName` 
                FROM
                    `pm_project_header` `ph` 
                    LEFT JOIN `pm_project_group_relationship` `pr` 
                        ON (
                            (
                                `ph`.`projectCode` = `pr`.`projectCode`
                            )
                        ) 
                    LEFT JOIN `pm_project_contract` `pc` 
                        ON (
                            (
                                `pr`.`projectGroupCode` = `pc`.`projectGroupCode`
                            )
                        ) 
                    LEFT JOIN `pm_project_group` `pg` 
                        ON (
                            `pr`.`projectGroupCode` = `pg`.`projectGroupCode`
                        ) 
                        AND (`pg`.`projectType` = '10') 
                    LEFT JOIN `fnd_basic_data` `fd` 
                        ON (
                            `fd`.`basicDataId` = `ph`.`projectState`
                        ) 
                        AND (`fd`.`dataTypeCode` = '02') 
                        AND (`fd`.`effectiveFrom` < NOW()) 
                        AND (
                            (`fd`.`effectiveTo` > NOW()) 
                            OR ISNULL(`fd`.`effectiveTo`)
                        ) 
                    LEFT JOIN `fnd_basic_data` `rank` 
                        ON (
                            `ph`.`column010` = `rank`.`basicDataId`
                        ) 
                        AND (`rank`.`dataTypeCode` = '05') 
                        AND (`rank`.`effectiveFrom` <= NOW()) 
                        AND (
                            (`rank`.`effectiveTo` > NOW()) 
                            OR ISNULL(`rank`.`effectiveTo`)
                        ) 
                    LEFT JOIN `fnd_department` `d` 
                        ON (
                            `d`.`departmentNum` = `ph`.`column001`
                        ) 
                where ISNULL(`ph`.`effectiveTo`)
                GROUP BY `pc`.`projectGroupCode`, `ph`.`projectCode`
                ) t
        ]]>
        <dynamic prepend="where">
            <isNotEmpty prepend="and" property="projectName"><![CDATA[ projectName like '%$projectName$%']]></isNotEmpty>
            <isNotEmpty prepend="and" property="projectState"><![CDATA[ projectState in ( $projectState$ ) ]]></isNotEmpty>
            <isNotEmpty prepend="and" property="column001"><![CDATA[ officeCode = #column001#]]></isNotEmpty>
            <isNotEmpty prepend="and" property="projectCode"><![CDATA[ (contractNo like '%$projectCode$%' or projectCode like '%$projectCode$%')]]></isNotEmpty>
            <isNotEmpty prepend="and" property="column010"><![CDATA[ rank = #column010#]]></isNotEmpty>
        </dynamic>
;

-- L0214 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:2472 | query-transferShipmentInfo-bycontractno | pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT DISTINCT * FROM (
            SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName, 
            vsep.receiveName receiveName, vsep.emsNum emsNum, vsep.packdate packdate, vsep.emsCompany emsCompany,NULL AS installAddress
            FROM view_shipment_info_4_pm vsip 
            LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
            WHERE vsip.contract_code IN($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
                AND contractNo IN($contractNo$) and projectId = #projectId#
            )
            UNION ALL 
            SELECT `contractNo`,`barcode`,`itemCode`,`itemName`,`receiveName`,`emsNum`,`packdate`,`emsCompany`,`installAddress` 
            FROM pm_project_shipment pps WHERE contractNo IN($contractNo$) and projectId = #projectId#
                 AND transferFlag != 1
                 AND EXISTS 
                (SELECT 
                    1 
                FROM
                    view_shipment_info_4_pm vsip 
                    LEFT JOIN view_shipment_ems_4_pm vsep 
                        ON vsep.contract_code = vsip.contract_code 
                        AND vsep.packId = vsip.packId 
                WHERE FIND_IN_SET(vsip.contract_code ,REPLACE(REPLACE(#contractNo#, '-C', ''), "'",''))
                    AND vsip.barcode = pps.barcode)) ttt
        WHERE NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE ttt.barCode = pps1.barcode
                and pps1.contractNo IN($chContractNo$) and pps1.projectId = #chProjectId#
            )
;

-- L0215 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:2550 | query-projectdeliver-list | fnd_basic_data
select pbpd.id, concat(pbpd.dataTypeCodeSon, '-', pbpd.basicDataIdSon) deliverKey, fbd.basicDataName deliverValue, pbpd.isNeed ,
		  concat(pbpd.dataTypeCode, '-', pbpd.basicDataId) eventKey
		from pm_basic_prj_deliver pbpd
		left join fnd_basic_data fbd on pbpd.dataTypeCodeSon = fbd.dataTypeCode and pbpd.basicDataIdSon = fbd.basicDataId
		where pbpd.column011 = #column011# 
		    and pbpd.dataTypeCode = #dataTypeCode# 
            and pbpd.effectiveTo is null 
        <isNotNull prepend="and " property="basicDataId"> pbpd.basicDataId = #basicDataId# </isNotNull>
		<isNotNull prepend="and " property="column010"> pbpd.column010 = #column010# </isNotNull>
		<isNull prepend="and " property="column010"> pbpd.column010 is null </isNull>
;

-- L0216 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:2563 | queryNeededUndelivedCount | fnd_basic_data
SELECT 
		    COUNT(1) AS COUNT
		FROM
		    pm_basic_prj_deliver pbpd 
		    LEFT JOIN `pm_basic_deliver_detail` pbdd 
		        ON pbpd.`id` = pbdd.`deliverId` 
		        AND pbdd.`projectId` = #projectId# 
		    LEFT JOIN fnd_basic_data fbd 
		        ON pbpd.dataTypeCodeSon = fbd.dataTypeCode 
		        AND pbpd.basicDataIdSon = fbd.basicDataId 
		WHERE pbpd.column011 = #column011# 
		    AND pbpd.dataTypeCode = #dataTypeCode# 
		    AND pbpd.effectiveTo IS NULL 
		    AND pbpd.`isNeed` = 1
		    AND pbdd.id IS NULL
            <isNotNull prepend="and " property="column010"> pbpd.column010 = #column010# </isNotNull>
            <isNull prepend="and " property="column010"> pbpd.column010 is null </isNull>
;

-- L0217 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:2606 | query-deliverdetail-byprojectid | fnd_basic_data
<![CDATA[
			SELECT pbdd.id, pbdd.`projectId`, pbdd.`deliverableName`, pbdd.`deliverablePath`, 
			 fbd.`basicDataName` as deliverableType
			FROM `pm_basic_deliver_detail` pbdd
			INNER JOIN `pm_basic_prj_deliver` pbpd ON pbpd.id = pbdd.`deliverId`
			LEFT JOIN fnd_basic_data fbd ON fbd.`dataTypeCode` = pbpd.`dataTypeCodeSon` AND fbd.`basicDataId` = pbpd.`basicDataIdSon`
			WHERE pbdd.projectId = #projectId# AND pbdd.`effectiveFrom` <= NOW() AND (pbdd.`effectiveTo` > NOW() OR pbdd.`effectiveTo` IS NULL)
			order by pbdd.uploadTime desc
		]]>
;

-- L0218 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:2617 | queryDeliverDetailByProjectIdAndDeliverType | fnd_basic_data, fnd_user_info
<![CDATA[
            SELECT 
                pbdd.id, pbdd.`projectId`, pbdd.`deliverableName`, pbdd.`deliverablePath`, 
                fbd.`basicDataName` as deliverableType, 
                CONCAT(pbpd.dataTypeCode, "-", pbpd.basicDataId) AS eventKey,
                IFNULL(Concat(pbdd.uploadUser, "-", ui.realName), pbdd.uploadUser) as uploadUser, 
                pbdd.uploadTime
            FROM `pm_basic_deliver_detail` pbdd
	            INNER JOIN `pm_basic_prj_deliver` pbpd 
	               ON pbpd.id = pbdd.`deliverId`
	            LEFT JOIN fnd_basic_data fbd 
	               ON fbd.`dataTypeCode` = pbpd.`dataTypeCodeSon` AND fbd.`basicDataId` = pbpd.`basicDataIdSon`
	            LEFT JOIN fnd_user_info ui 
	               ON ui.username = pbdd.uploadUser
            WHERE pbdd.projectId = #projectId# 
            AND pbpd.dataTypeCode = #dataTypeCode#
            AND pbdd.`effectiveFrom` <= NOW() 
            AND (pbdd.`effectiveTo` > NOW() 
                OR pbdd.`effectiveTo` IS NULL)
            order by pbdd.uploadTime desc
        ]]>
;

