-- L0237 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3407 | query_call_back_list | fnd_basic_data, pm_cl_callback, fnd_user_info
<![CDATA[
			SELECT  CONCAT( t1.`applyBy`,'-' ,t4.`realName`) AS applyByName ,
			CASE WHEN t3.`realName` IS NULL THEN '回访人员' ELSE CONCAT(t3.username,'-' , t3.realName) END AS ASSIGNEE_Name, t2.`ASSIGNEE_`,
			t5.basicDataName AS applyStateName , t1.applyTime , t2.id_ AS taskId , t1.projectId ,t1.instId,t1.applyState ,t1.id AS callbackId
			,t1.applyBy 
			FROM pm_cl_callback t1 
			LEFT JOIN act_ru_task t2 ON t1.`instId` = t2.`PROC_INST_ID_`
			LEFT JOIN fnd_user_info t3 ON t2.`ASSIGNEE_` = t3.`username` AND t3.`status` = 1
			LEFT JOIN fnd_user_info t4 ON t1.`applyBy` = t4.`username` 
			LEFT JOIN fnd_basic_data t5 ON t5.basicDataId = t1.applyState AND t5.dataTypeCode = '25' AND t5.effectiveTo IS NULL
			WHERE t1.`projectId` = #projectId#
		]]>
;

-- L0238 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3421 | query_callbacking_size | pm_cl_callback
<![CDATA[
			SELECT COUNT(*) FROM pm_cl_callback 
			WHERE applyState = 1 AND projectId = #projectId# AND effectiveTo IS NULL;
		]]>
;

-- L0239 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3427 | query_call_back_run_list | fnd_basic_data, pm_cl_callback, fnd_user_info
<![CDATA[
			SELECT  CONCAT( t1.`applyBy`,'-' ,t4.`realName`) AS applyByName ,
			CASE WHEN t3.`realName` IS NULL THEN '回访人员' ELSE CONCAT(t3.username,'-' , t3.realName) END AS ASSIGNEE_Name, t2.`ASSIGNEE_`,
			t5.basicDataName AS applyStateName , t1.applyTime , t2.id_ AS taskId , t1.projectId ,t1.instId,t1.applyState ,t1.id AS callbackId
			,t1.applyBy 
			FROM pm_cl_callback t1 
			LEFT JOIN act_ru_task t2 ON t1.`instId` = t2.`PROC_INST_ID_`
			LEFT JOIN fnd_user_info t3 ON t2.`ASSIGNEE_` = t3.`username` AND t3.`status` = 1
			LEFT JOIN fnd_user_info t4 ON t1.`applyBy` = t4.`username` 
			LEFT JOIN fnd_basic_data t5 ON t5.basicDataId = t1.applyState AND t5.dataTypeCode = '25' AND t5.effectiveTo IS NULL
		]]>
		<dynamic prepend="where">
			<isNotEmpty property="applyState" prepend="and"><![CDATA[ t1.applyState = #applyState#]]></isNotEmpty>
			<isNotEmpty property="projectId" prepend="and"><![CDATA[ t1.projectId = #projectId#]]></isNotEmpty>
		</dynamic>
;

-- L0240 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3444 | query_project_list_by_officeAndMemberCode | pm_project_header, pm_project_member
<![CDATA[
		SELECT 
		  `ph`.`projectId` AS `projectId`,
		  `ph`.`projectCode` AS `projectCode`,
		  `ph`.`projectState` AS `projectState`,
		  `ph`.`column001` AS `officeCode`,
		  `pm1`.`memberCode` AS `serviceManagerCode`,
		  `pm1`.`memberName` AS `serviceManagerCodeforjson`,
		  `pm2`.`memberCode` AS `programManagerCode`,
		  `pm2`.`memberName` AS `programManagerCodeforjson`,
		  `pm3`.`memberCode` AS `programManagerCodeB`,
		  `pm3`.`memberName` AS `programManagerCodeforjsonB` 
		FROM
		  `pm_project_header` ph 
		  LEFT JOIN `pm_project_member` pm1 
		    ON `ph`.`projectId` = `pm1`.`projectId`
		    AND (`pm1`.`memberRole` = '20') 
		    AND (`pm1`.`effectiveFrom` < NOW()) 
		    AND (
		      (`pm1`.`effectiveTo` > NOW()) 
		      OR ISNULL(`pm1`.`effectiveTo`)
		    ) 
		  LEFT JOIN `pm_project_member` pm2 
		    ON (
		      `ph`.`projectId` = `pm2`.`projectId`
		    ) 
		    AND (`pm2`.`memberRole` = '30') 
		    AND pm2.`fromFlag` = 1 
		    AND (`pm2`.`effectiveFrom` < NOW()) 
		    AND (
		      (`pm2`.`effectiveTo` > NOW()) 
		      OR ISNULL(`pm2`.`effectiveTo`)
		    ) 
		  LEFT JOIN `pm_project_member` pm3 
		    ON (
		      `ph`.`projectId` = `pm3`.`projectId`
		    ) 
		    AND (`pm3`.`memberRole` = '30') 
		    AND pm3.`fromFlag` = 2 
		    AND (`pm3`.`effectiveFrom` < NOW()) 
		    AND (
		      (`pm3`.`effectiveTo` > NOW()) 
		      OR ISNULL(`pm3`.`effectiveTo`)
		    )
		where ISNULL(`ph`.`effectiveTo`) 
	   	]]>
	    <isNotEmpty prepend="and" property="projectState"><![CDATA[ ph.projectState in( $projectState$ )]]></isNotEmpty>
		<isNotEmpty prepend="and" property="column001"><![CDATA[ ph.column001 = #column001#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="serviceManagerCode"><![CDATA[ pm1.`memberCode` = #serviceManagerCode#]]></isNotEmpty>
	    <isNotEmpty prepend="and" property="programManagerCode"><![CDATA[ (pm2.`memberCode` = #programManagerCode# or pm3.`memberCode` = #programManagerCode#)]]></isNotEmpty>
;

