-- L0246 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3754 | query_existsProject_by_contractNo | pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_group
SELECT 
		    h.* 
		FROM
		    `pm_project_contract` c 
		    LEFT JOIN `pm_project_group` g 
		        ON c.`projectGroupCode` = g.`projectGroupCode` 
		    LEFT JOIN `pm_project_group_relationship` gr 
		        ON g.`projectGroupCode` = gr.`projectGroupCode` 
		    LEFT JOIN `pm_project_header` h 
		        ON h.`projectCode` = REPLACE(gr.`projectCode`, "-his", "")
		WHERE c.`contractNo` in ($contractNo$)
;

-- L0247 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3776 | querySpotCheckList | fb_items, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT 
		    contractNo, t.itemCode, 
		    CASE
		        WHEN fi.`itemname` IS NULL 
		        OR fi.itemname = '' 
		        OR fi.itemname = '/' 
		        THEN fi.describe_ 
		        ELSE fi.itemname 
		    END AS itemName, COUNT(1) AS qty,
		    CASE
		        WHEN igi.itemCode IS NULL 
		        THEN GROUP_CONCAT(barcode SEPARATOR '、') 
		        ELSE '' 
		    END AS barCodes
	    FROM
		    (
		    SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, -1 AS transferFlag
	        FROM view_shipment_info_4_pm vsip 
		        LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
		        WHERE vsip.contract_code in ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
		            and contractNo in ($contractNo$) and projectId = #projectId#
		        )
	        UNION ALL 
	        SELECT `contractNo`,`barcode`,`itemCode`, transferFlag
	        FROM pm_project_shipment pps WHERE contractNo in ($contractNo$) and projectId = #projectId#
	             AND EXISTS 
	            (SELECT 
	                1 
	            FROM
	                view_shipment_info_4_pm vsip 
	                LEFT JOIN view_shipment_ems_4_pm vsep 
	                    ON vsep.contract_code = vsip.contract_code 
	                    AND vsep.packId = vsip.packId 
	            WHERE FIND_IN_SET(vsip.contract_code ,REPLACE(REPLACE(#contractNo#, '-C', ''), "'",''))
	                AND vsip.barcode = pps.barcode)
	        ORDER BY transferFlag asc) t
		    LEFT JOIN `fb_items` fi
		        ON fi.`item` = t.itemCode
	        LEFT JOIN `pm_project_spot_check_ignore_item` igi 
	            ON igi.itemCode = t.itemCode 
	    WHERE t.transferFlag != 1
	    GROUP BY t.itemCode
	    ORDER BY t.contractNo, barCodes DESC, t.itemCode ASC;
;

-- L0248 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3833 | query_project_notify_list | pm_project_notification, fnd_user_info
<![CDATA[
			SELECT 
			    CONCAT(t1.`createBy`, '-', t6.`realName`) AS createBy ,t1.*
			FROM
			    pm_project_notification t1 
			    LEFT JOIN fnd_user_info t6 
			        ON t6.`username` = t1.`createBy` 
        ]]>
        WHERE t1.projectId = #projectId#
        ORDER BY t1.`createTime` DESC
;

-- L0249 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3847 | queryProjectInspectionOfficeCode | fb_contract, fb_shipment, fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_state, pm_project_task, pm_project_group
<![CDATA[
            SELECT DISTINCT 
			    t.officeCode 
			FROM
			    (SELECT 
			        ph.`projectId`, ph.column001 AS officeCode, pc.`contractNo`, ph.`projectName`, planState.`basicDataName` AS planStateName, MAX(fs.`packdate`) packdate, MAX(
			            IF (
			                pt.taskTypeId = 30, pt.eventActualFinishDate, NULL
			            )
			        ) AS arrivalFinishDate, MAX(
			            IF (
			                pt.taskTypeId = 60, pt.eventActualFinishDate, NULL
			            )
			        ) AS preInspectFinishDate, MAX(
			            IF (
			                pt.taskTypeId = 70, pt.eventActualFinishDate, NULL
			            )
			        ) AS finalInspectFinishDate 
			    FROM
			        pm_project_header ph 
			        LEFT JOIN `pm_project_state` ps 
			            ON ps.`projectId` = ph.`projectId` 
			        LEFT JOIN fnd_basic_data planState 
			            ON planState.`dataTypeCode` = '22' 
			            AND planState.`effectiveTo` IS NULL 
			            AND planState.`basicDataId` = ps.`projectPlanState` 
			        LEFT JOIN pm_project_task pt 
			            ON ph.`projectId` = pt.`projectId` 
			            AND pt.`effectiveTo` IS NULL 
			        LEFT JOIN pm_project_group_relationship pgr 
			            ON ph.`projectCode` = pgr.`projectCode` 
			        LEFT JOIN pm_project_group pg 
			            ON pg.`projectGroupCode` = pgr.`projectGroupCode` 
			        LEFT JOIN pm_project_contract pc 
			            ON pg.`projectGroupCode` = pc.`projectGroupCode` 
			        LEFT JOIN fb_contract fc 
			            ON fc.`contract_code` = pc.`contractNo` 
			        LEFT JOIN fb_shipment fs 
			            ON fc.`contract_id` = fs.`con_id` 
			    WHERE ps.`shipmentState` = - 1 
			        AND pt.`effectiveTo` IS NULL 
			        AND ph.`effectiveTo` IS NULL 
			        AND (
			            (
			                FIND_IN_SET(pt.taskTypeId, "30,60,70") 
			                AND ph.`projectId` IN 
			                (SELECT DISTINCT 
			                    projectId 
			                FROM
			                    pm_project_task pt 
			                WHERE FIND_IN_SET(pt.taskTypeId, "30,60,70") 
			                    AND pt.eventActualFinishDate IS NULL)
			            ) 
			            OR pt.`taskTypeId` IS NULL
			        ) 
			        AND ph.`column004` = "运营商市场部" 
			        AND (
			            ph.column011 = 10 
			            OR ph.column011 IS NULL
			        ) 
			        AND ph.`projectState` IN (30, 31, 32) 
			    GROUP BY ph.`projectId`, pc.`contractNo`) t 
			WHERE t.packdate IS NOT NULL
        ]]>
;

-- L0250 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:3914 | queryProjectInspection | fb_contract, fb_shipment, fnd_basic_data, pm_pb_plan_from_sms, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_state, pm_project_task, fnd_department, pm_project_group
<![CDATA[
			SELECT 
			   DISTINCT fd.`departmentName` AS officeName, t.*, IF(
			        LOCATE(
			            sales.`memberCode`, sales.`memberName`
			        ) > 0, IFNULL(sales.`memberName`, ""), CONCAT(
			            IFNULL(
			                CONCAT(sales.`memberCode`, "-"), ""
			            ), IFNULL(sales.`memberName`, "")
			        )
			    ) AS salesName, CONCAT(
			        IFNULL(pm1.`memberName`, ""), IFNULL(CONCAT("，", pm2.`memberName`), "")
			    ) AS programName, DATEDIFF(CURDATE(), t.packdate) AS packDays, DATEDIFF(
			        IFNULL(arrivalFinishDate, CURDATE()), t.arrival
			    ) AS arrivalDays, DATEDIFF(
			        IFNULL(preInspectFinishDate, CURDATE()), t.preInspect
			    ) AS preInspectDays, DATEDIFF(
			        IFNULL(finalInspectFinishDate, CURDATE()), t.finalInspect
			    ) AS finalInspectDays
			FROM
			    (SELECT 
			        t.*, 
			        DATE(IFNULL(
			            MAX(IF(pppfs.referenceEventName = '到货验收', pppfs.eventPlanHappenDate, NULL)), 
			            DATE_ADD(t.packdate, INTERVAL 25 DAY)
			        )) AS arrival, 
			        DATE(MAX(IF(pppfs.referenceEventName = '初验', pppfs.eventPlanHappenDate, NULL))) AS preInspect, 
			        DATE(MAX(IF(pppfs.referenceEventName = '终验', pppfs.eventPlanHappenDate, NULL))) AS finalInspect 
			    FROM
			        (SELECT 
			            ph.`projectId`, ph.column001 AS officeCode, pc.`contractNo`, ph.`projectName`, ps.`projectPlanState` AS planState, planState.`basicDataName` AS planStateName, MAX(fs.`packdate`) packdate, MAX(
			                IF (
			                    pt.taskTypeId = 30, pt.eventActualFinishDate, NULL
			                )
			            ) AS arrivalFinishDate, MAX(
			                IF (
			                    pt.taskTypeId = 60, pt.eventActualFinishDate, NULL
			                )
			            ) AS preInspectFinishDate, MAX(
			                IF (
			                    pt.taskTypeId = 70, pt.eventActualFinishDate, NULL
			                )
			            ) AS finalInspectFinishDate 
			        FROM
			            pm_project_header ph 
			            LEFT JOIN `pm_project_state` ps 
			                ON ps.`projectId` = ph.`projectId` 
			            LEFT JOIN fnd_basic_data planState 
			                ON planState.`dataTypeCode` = '22' 
			                AND planState.`effectiveTo` IS NULL 
			                AND planState.`basicDataId` = ps.`projectPlanState` 
			            LEFT JOIN pm_project_task pt 
			                ON ph.`projectId` = pt.`projectId` 
			                AND pt.`effectiveTo` IS NULL 
			            LEFT JOIN pm_project_group_relationship pgr 
			                ON ph.`projectCode` = pgr.`projectCode` 
			            LEFT JOIN pm_project_group pg 
			                ON pg.`projectGroupCode` = pgr.`projectGroupCode` 
			            LEFT JOIN pm_project_contract pc 
			                ON pg.`projectGroupCode` = pc.`projectGroupCode` 
			            LEFT JOIN fb_contract fc 
			                ON fc.`contract_code` = pc.`contractNo` 
			            LEFT JOIN fb_shipment fs 
			                ON fc.`contract_id` = fs.`con_id` 
			        WHERE ps.`shipmentState` = - 1 
			            AND pt.`effectiveTo` IS NULL 
			            AND ph.`effectiveTo` IS NULL 
			            AND (
			                (
			                    FIND_IN_SET(pt.taskTypeId, "30,60,70") 
			                    AND ph.`projectId` IN 
			                    (SELECT DISTINCT 
			                        projectId 
			                    FROM
			                        pm_project_task pt 
			                    WHERE FIND_IN_SET(pt.taskTypeId, "70") 
			                        AND pt.eventActualFinishDate IS NULL)
			                ) 
			                OR pt.`taskTypeId` IS NULL
			            ) 
			            AND ph.`column004` = "运营商市场部" 
			            AND (
			                ph.column011 = 10 
			                OR ph.column011 IS NULL
			            ) 
			            AND ph.`projectState` IN (30, 31, 32) 
			        GROUP BY ph.`projectId`, pc.`contractNo`) t 
			        LEFT JOIN 
			            (SELECT DISTINCT 
			                pppfs.id, pppfs.contractNo, pppfs.batchCode, pppfs.basicDataName, pppfs.referenceEventName, pppfs.eventPlanHappenDate, pppfs.afterDaysNum, pppfs.eventActualFinishDate, pppfs.marketingFeedback 
			            FROM
			                pm_pb_plan_from_sms pppfs 
			                LEFT JOIN fnd_basic_data fbd 
			                    ON fbd.basicDataName = pppfs.referenceEventName 
			            WHERE fbd.dataTypeCode IS NOT NULL) pppfs 
			            ON pppfs.contractNo = t.contractNo 
			    WHERE t.packdate IS NOT NULL 
			    GROUP BY t.`projectId`, t.`contractNo`) t 
			    LEFT JOIN pm_project_member sales 
			        ON sales.`projectId` = t.projectId 
			        AND sales.memberRole = 10 
			        AND sales.`effectiveTo` IS NULL 
			    LEFT JOIN pm_project_member pm1 
			        ON pm1.`projectId` = t.projectId 
			        AND pm1.memberRole = 30 
			        AND pm1.`effectiveTo` IS NULL 
			        AND pm1.`fromFlag` = 1 
			    LEFT JOIN pm_project_member pm2 
			        ON pm2.`projectId` = t.projectId 
			        AND pm2.`fromFlag` = 2 
			        AND pm2.`effectiveTo` IS NULL 
			        AND pm2.memberRole = 30 
			    LEFT JOIN fnd_department fd 
			        ON fd.`departmentNum` = t.officeCode 
        ]]>
