-- L0256 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-project-config2.xml:5212 | queryProjectSimplifyByProjectId | pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, fnd_department
<![CDATA[
	    SELECT pph.projectId,CASE WHEN pph.effectiveFrom < NOW() AND (pph.effectiveTo >= NOW() OR pph.effectiveTo IS NULL) THEN 0 ELSE 1 END AS projectStatus, 
			GROUP_CONCAT(ppc.contractNo) AS contractNo, pph.projectCode, 
			CASE WHEN ppgr.`mergeBranchMark` IS NULL THEN pph.projectName ELSE CONCAT( pph.projectName, '-',ppgr.`mergeBranchMark`) END AS projectName, 
			pph.projectState, pph.isback, pph.column001, fd.departmentName AS officeName, pph.column002, pph.column003, pph.column004, pph.column005, 
			pph.column006, pph.column007, pph.column008, pph.column009, pph.column010, pph.column011,
			CASE WHEN  pph.column012 IS NULL OR pph.column012 = '' THEN pph.columno12_readonly ELSE pph.column012 END AS column012, 
			pph.columno12_readonly AS column012Readonly, pph.column013, pph.column014, 
			CASE WHEN ppm1.memberCode IS NULL THEN ppm4.memberCode ELSE ppm1.memberCode END AS serviceManagerCode, 
			CASE WHEN ppm1.memberName IS NULL THEN ppm4.memberName ELSE ppm1.memberName END AS serviceManagerCodeforjson, 
			CASE WHEN ppm2.memberCode IS NULL THEN ppm5.memberCode ELSE ppm2.memberCode END AS programManagerCode,
			CASE WHEN ppm2.memberName IS NULL THEN ppm5.memberName ELSE ppm2.memberName END AS programManagerCodeforjson,
			ppm5.memberCode AS programManagerCodeB,
			ppm5.memberName AS programManagerCodeforjsonB
		FROM pm_project_header pph 
			LEFT JOIN pm_project_member ppm1 ON ppm1.projectId = pph.projectId AND ppm1.memberRole = '20' AND ppm1.fromFlag = 1
			AND (ppm1.effectiveFrom <= NOW() AND (ppm1.effectiveTo IS NULL))
			LEFT JOIN pm_project_member ppm4 ON ppm4.projectId = pph.projectId AND ppm4.memberRole = '20' AND ppm4.fromFlag = 2
			AND (ppm4.effectiveFrom <= NOW() AND (ppm4.effectiveTo IS NULL))
			LEFT JOIN pm_project_member ppm2 ON ppm2.projectId = pph.projectId AND ppm2.memberRole = '30' AND ppm2.fromFlag = 1
			AND (ppm2.effectiveFrom <= NOW() AND (ppm2.effectiveTo IS NULL))
			LEFT JOIN pm_project_member ppm5 ON ppm5.projectId = pph.projectId AND ppm5.memberRole = '30' AND ppm5.fromFlag = 2
			AND (ppm5.effectiveFrom <= NOW() AND (ppm5.effectiveTo IS NULL))
			LEFT JOIN pm_project_group_relationship ppgr ON ppgr.projectCode = pph.projectCode
			LEFT JOIN pm_project_contract ppc ON ppc.projectGroupCode = ppgr.projectGroupCode
			LEFT JOIN fnd_department fd ON fd.departmentNum = pph.column001
		WHERE pph.projectId = #projectId# LIMIT 1;
	]]>
;

-- L0257 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-refresh-data-config.xml:116 | query_pm_project_product_line | pm_project_product_line
<![CDATA[
            SELECT DISTINCT projectId , contractNo FROM `pm_project_product_line` 
            WHERE contractNo IS NOT NULL AND (projectQuantity IS NULL OR projectQuantity = 0);
        ]]>
;

-- L0258 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-refresh-data-config.xml:832 | query_pm_self_service_project | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_property_from_sms
<![CDATA[
            SELECT DISTINCT 
                IFNULL(IF(p.salesType = '01', p.projectName, pp.projectName), p.projectName) AS `projectName`, `p`.`contractNo` AS `contractNo`, `pp`.`officeCode` AS `column001` 
            FROM
                `view_distinct_contract` `v` 
                LEFT JOIN `pm_order_data_from_sap` `p` 
                    ON ((`v`.`id` = `p`.`id`)) 
                LEFT JOIN `pm_project_property_from_sms` `pp` 
                    ON (
                        (
                            `p`.`orderExecNumber` = `pp`.`orderExecNumber`
                        )
                    ) 
                LEFT JOIN fnd_basic_data fbd 
                    ON pp.serviceTypeName = fbd.basicDataId 
                    AND fbd.dataTypeCode = 21 
                    AND fbd.effectiveFrom <= NOW() 
                    AND (
                        fbd.effectiveTo > NOW() 
                        OR fbd.effectiveTo IS NULL
                    ) 
            WHERE NOT EXISTS 
                (SELECT 
                    1 
                FROM
                    (
                        `pm_project_contract` `t1` 
                        JOIN `pm_project_group_relationship` `t2` 
                            ON (
                                (
                                    `t1`.`projectGroupCode` = `t2`.`projectGroupCode`
                                )
                            )
                    ) 
                    JOIN `pm_project_header` `t3` 
                        ON (
                            `t2`.`projectCode` = `t3`.`projectCode`
                            OR `t3`.`projectCode` = REPLACE(`t2`.`projectCode`, "-his", "")
                        ) 
                        AND (`t3`.`effectiveFrom` <= NOW()) 
                        AND (
                            (`t3`.`effectiveTo` > NOW()) 
                            OR ISNULL(`t3`.`effectiveTo`)
                        ) 
                WHERE (
                        `p`.`contractNo` = `t1`.`contractNo`
