-- L0259 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-refresh-data-config.xml:885 | query_project_serviceManager_by_officeCode | fnd_department, fnd_user_info, fnd_user_power
SELECT 
            CASE
                WHEN fui.username IS NOT NULL 
                THEN fui.username 
                ELSE fupt.username 
            END AS memberCode,
            CONCAT (CASE
                        WHEN fui.username IS NOT NULL 
                        THEN fui.username 
                        ELSE fupt.username 
                    END, "-", 
                    CASE
                        WHEN fui.username IS NOT NULL 
                        THEN fui.realName 
                        ELSE fupt.realName 
                    END
            ) AS memberName
        FROM
            `fnd_department` fd 
            LEFT JOIN fnd_user_info fui 
                ON fd.`departmentNum` = fui.`dpNo` 
                AND roleIds LIKE "%;11;%" 
                AND fui.status = 1 
            LEFT JOIN 
                (SELECT 
                    fup.* ,fui2.realname
                FROM
                    fnd_user_power fup 
                    LEFT JOIN fnd_user_info fui2 
                        ON fup.`fndUserId` = fui2.`id` 
                    LEFT JOIN fnd_department fdt 
                        ON fdt.departmentNum = fui2.dpNO 
                WHERE (
                        roleIds LIKE "%;11;%" 
                        AND fui2.status = 1 
                        AND fup.effectiveTo IS NULL 
                        AND fdt.isparam = 1
                    ) 
                    OR fui2.roleIds LIKE "%;13;%") fupt 
                ON fupt.`areapower` LIKE CONCAT("%", fd.`departmentNum`, "%") 
        WHERE isparam = 1 and fd.departmentNum = #_parameter#
;

-- L0260 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-refresh-data-config.xml:1215 | query_project_sales_change | pm_project_header, pm_project_member
SELECT 
            ph.`projectId`, ph.`projectCode`, ph.`projectName`, sl.`memberCode`, sl.`memberName`, ppfs.salesManCode, ppfs.salesManName 
        FROM
            pm_project_header ph 
            LEFT JOIN temp_max_ppfs ppfs 
                ON ph.projectCode LIKE CONCAT(ppfs.projectCode, "%") 
            LEFT JOIN pm_project_member sl 
                ON sl.`memberRole` = '10' 
                AND ph.`projectId` = sl.`projectId`
                AND sl.`effectiveTo` IS NULL 
        WHERE ph.`projectState` IN ("30", "31", "32") 
            AND ppfs.salesManCode != sl.`memberCode` 
        GROUP BY ph.projectId
;

