-- L0268 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-report-config.xml:81 | query_reportline_trace_info | pm_project_header, pm_project_member, pm_project_state, fnd_department
<![CDATA[
			SELECT   t.conditionValue , COUNT(*) AS totalValue , ROUND(t.conditionValue /COUNT(*)*100 ,2) AS specificValue 
			 , t1.`column001` AS officeCode ,t4.departmentName as officeName,NOW() AS settingTime 
			FROM pm_project_header t1      
			LEFT JOIN pm_project_member t2 ON t1.`projectId` = t2.`projectId`      AND t2.`effectiveTo` IS NULL AND t2.`memberRole` = '30' AND t2.`fromFlag` = 1    
			LEFT JOIN (
				SELECT COUNT(*) AS conditionValue , t1.`column001` AS officeCode  
				FROM pm_project_header t1     
				LEFT JOIN pm_project_member t2 ON t1.`projectId` = t2.`projectId`      
				AND t2.`effectiveTo` IS NULL AND t2.`memberRole` = '30' AND t2.`fromFlag` = 1     
				LEFT JOIN pm_project_state t3 ON t1.`projectId` = t3.`projectId`   
				WHERE t1.projectState IN (30,31,32)  AND t2.`memberCode` IS NOT NULL    
				AND t1.column001 IS NOT NULL AND t1.effectiveTo IS NULL      AND t3.`projectPlanState` != 40    
				GROUP BY t1.column001  
			) t ON t1.`column001` = t.officeCode
			LEFT JOIN fnd_department t4 ON t1.`column001`  = t4.`departmentNum`  
			WHERE t1.projectState IN (30,31,32)  AND t2.`memberCode` IS NOT NULL     
				AND t1.column001 IS NOT NULL AND t1.effectiveTo IS NULL     
			GROUP BY t1.column001 
			ORDER BY specificValue DESC;
		]]>
;

