-- L0279 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-report-config.xml:434 | query_reportline_impl_info | pm_project_header, fnd_department
<![CDATA[
			SELECT COUNT(*)  AS conditionValue , a.total  AS totalValue , ROUND(COUNT(*) / a.total *100 ,2) AS specificValue ,'total' AS officeCode , 
				CONCAT('impl',c.ssfs ) AS dataTypeCode, NOW() AS settingTime ,'全国' AS officeName
			FROM ( SELECT  CASE WHEN column012 IS NULL AND columno12_readonly != -1 THEN columno12_readonly ELSE column012 END AS ssfs 
				FROM pm_project_header WHERE effectiveTo IS NULL AND createTime > #quarterStartTime# AND column001 IS NOT NULL
				AND (column004 LIKE '企业网%' OR column004 LIKE '渠道与商业%') ) c
			LEFT JOIN (
			      SELECT  COUNT(*) AS total FROM pm_project_header WHERE effectiveTo IS NULL AND createTime > #quarterStartTime# AND column001 IS NOT NULL 
					AND (column004 LIKE '企业网%' OR column004 LIKE '渠道与商业%') 
				) a ON 1=1
			GROUP BY  c.ssfs 
			UNION 
			SELECT COUNT(*) AS conditionValue ,t.size  AS totalValue , ROUND(COUNT(*)/t.size *100 ,2) AS specificValue, 
							c.officeCode ,CONCAT('impl', ssfs) AS dataTypeCode ,NOW() AS settingTime , t2.`departmentName` AS officeName 
			FROM ( 
				SELECT  CASE WHEN column012 IS NULL AND columno12_readonly != -1 THEN columno12_readonly ELSE column012 END AS ssfs ,
					IFNULL(column001, "") AS officeCode 
				FROM pm_project_header WHERE effectiveTo IS NULL AND createTime > #quarterStartTime# AND column001 IS NOT NULL
					AND (column004 LIKE '企业网%' OR column004 LIKE '渠道与商业%') ) c
			LEFT JOIN (
				SELECT COUNT(*) AS size ,officeCode  FROM ( 
					SELECT  CASE WHEN column012 IS NULL AND columno12_readonly != -1 THEN columno12_readonly ELSE column012 END AS ssfs ,
						IFNULL(column001, "") AS officeCode  
					FROM pm_project_header WHERE effectiveTo IS NULL AND createTime > #quarterStartTime# AND column001 IS NOT NULL
						AND (column004 LIKE '企业网%' OR column004 LIKE '渠道与商业%') ) a 
			   GROUP BY a.officeCode
			   ) t ON t.officeCode = c.officeCode
			LEFT JOIN fnd_department t2 ON c.officeCode = t2.`departmentNum`
			GROUP BY c.officeCode , c.ssfs 
		]]>
;

