-- L0301 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1570 | queryProjectListBak | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, fnd_department, pm_project_group
<![CDATA[
          select * from (
              SELECT 
                  `ph`.`projectId` AS `projectId`, `ph`.`projectCode` AS `projectCode`, `rank`.`basicDataName` AS `rank`, (
                      CASE
                          WHEN (
                              `pr`.`mergeBranchMark` IS NOT NULL
                          ) 
                          THEN CONCAT(
                              `ph`.`projectName`, '-', `pr`.`mergeBranchMark`
                          ) 
                          ELSE `ph`.`projectName` 
                      END
                  ) AS `projectName`, `fd`.`basicDataName` AS `projectStateName`, `ph`.`projectState` AS `projectState`, GROUP_CONCAT(
                      DISTINCT `pc`.`contractNo` SEPARATOR ','
                  ) AS `contractNo`, `ph`.`column001` AS `officeCode`, `d`.`departmentName` AS `officeName` 
              FROM
                  `pm_project_header` `ph` 
                  LEFT JOIN `pm_project_group_relationship` `pr` 
                      ON (
                          (
                              `ph`.`projectCode` = `pr`.`projectCode`
                          )
                      ) 
                  LEFT JOIN `pm_project_contract` `pc` 
                      ON (
                          (
                              `pr`.`projectGroupCode` = `pc`.`projectGroupCode`
                          )
                      ) 
                  LEFT JOIN `pm_project_group` `pg` 
                      ON (
                          `pr`.`projectGroupCode` = `pg`.`projectGroupCode`
                      ) 
                      AND (`pg`.`projectType` = '10') 
                  LEFT JOIN `fnd_basic_data` `fd` 
                      ON (
                          `fd`.`basicDataId` = `ph`.`projectState`
                      ) 
                      AND (`fd`.`dataTypeCode` = '02') 
                      AND (`fd`.`effectiveFrom` < NOW()) 
                      AND (
                          (`fd`.`effectiveTo` > NOW()) 
                          OR ISNULL(`fd`.`effectiveTo`)
                      ) 
                  LEFT JOIN `fnd_basic_data` `rank` 
                      ON (
                          `ph`.`column010` = `rank`.`basicDataId`
                      ) 
                      AND (`rank`.`dataTypeCode` = '05') 
                      AND (`rank`.`effectiveFrom` <= NOW()) 
                      AND (
                          (`rank`.`effectiveTo` > NOW()) 
                          OR ISNULL(`rank`.`effectiveTo`)
                      ) 
                  LEFT JOIN `fnd_department` `d` 
                      ON (
                          `d`.`departmentNum` = `ph`.`column001`
                      ) 
              where ISNULL(`ph`.`effectiveTo`)
      ]]>
                 <isNotEmpty prepend="AND" property="projectIds"> FIND_IN_SET(`ph`.projectId, #projectIds#)</isNotEmpty>
              <!-- GROUP BY `pc`.`projectGroupCode`, `ph`.`projectCode` -->
              GROUP BY `ph`.`projectCode`
              ) t
      <dynamic prepend="where">  <!--  <isNotEmpty prepend="and" property="projectName"><![CDATA[ projectName like '%$projectName$%']]></isNotEmpty>
          <isNotEmpty prepend="and" property="projectState"><![CDATA[ projectState in ( $projectState$ ) ]]></isNotEmpty>
          <isNotEmpty prepend="and" property="column001"><![CDATA[ officeCode = #column001#]]></isNotEmpty> -->
          
          <isNotEmpty property="contractNos">
              <iterate prepend="AND" open="(" close=")" property="contractNos" conjunction="or" >
                contractNo like '%$contractNos[]$%'
              </iterate>
          </isNotEmpty>
          <isNotEmpty prepend="AND" property="projectIds"> FIND_IN_SET(projectId, #projectIds#)</isNotEmpty>
          <!-- <isNotEmpty prepend="and" property="contractNo"><![CDATA[ (contractNo like'%$contractNo$%')]]></isNotEmpty> -->
          <!-- <isNotEmpty prepend="and" property="column010"><![CDATA[ rank = #column010#]]></isNotEmpty> -->
      </dynamic>
;

-- L0302 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1651 | queryProjectList | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, fnd_department, pm_project_group
<![CDATA[
            SELECT 
                *, `rank`.`basicDataName` AS `rank`, `fd`.`basicDataName` AS `projectStateName`, `d`.`departmentName` AS `officeName` 
            FROM
                (SELECT 
                    `ph`.`projectId` AS `projectId`, `ph`.`projectCode` AS `projectCode`, (
                        CASE
                            WHEN (
                                `pr`.`mergeBranchMark` IS NOT NULL
                            ) 
                            THEN CONCAT(
                                `ph`.`projectName`, '-', `pr`.`mergeBranchMark`
                            ) 
                            ELSE `ph`.`projectName` 
                        END
                    ) AS `projectName`, `ph`.`projectState` AS `projectState`, GROUP_CONCAT(
                        DISTINCT `pc`.`contractNo` SEPARATOR ','
                    ) AS `contractNo`, `ph`.`column001` AS `officeCode`, ph.`column010`, ph.salesType
                FROM
                    `pm_project_header` `ph` 
                    LEFT JOIN `pm_project_group_relationship` `pr` 
                        ON (
                            (
                                `ph`.`projectCode` = `pr`.`projectCode`
                            )
                        ) 
                    LEFT JOIN `pm_project_contract` `pc` 
                        ON (
                            (
                                `pr`.`projectGroupCode` = `pc`.`projectGroupCode`
                            )
                        ) 
                    LEFT JOIN `pm_project_group` `pg` 
                        ON (
                            `pr`.`projectGroupCode` = `pg`.`projectGroupCode`
                        ) 
                        AND (`pg`.`projectType` = '10') 
                WHERE ISNULL(`ph`.`effectiveTo`) 
        ]]>         <isNotEmpty prepend="AND" property="projectIds"> FIND_IN_SET(`ph`.projectId, #projectIds#)</isNotEmpty>
                    <isEmpty property="contractNos">
                        <isEmpty prepend="AND" property="projectIds"> `ph`.projectId = -1 </isEmpty>
                    </isEmpty>
                <!-- GROUP BY `pc`.`projectGroupCode`, `ph`.`projectCode` -->
                GROUP BY `ph`.`projectCode`
                ) t 
        <![CDATA[
                LEFT JOIN `fnd_basic_data` `fd` 
                    ON (
                        `fd`.`basicDataId` = `t`.`projectState`
                    ) 
                    AND (`fd`.`dataTypeCode` = '02') 
                    AND (`fd`.`effectiveFrom` < NOW()) 
                    AND (
                        (`fd`.`effectiveTo` > NOW()) 
                        OR ISNULL(`fd`.`effectiveTo`)
                    ) 
                LEFT JOIN `fnd_basic_data` `rank` 
                    ON (
                        `t`.`column010` = `rank`.`basicDataId`
                    ) 
                    AND (`rank`.`dataTypeCode` = '05') 
                    AND (`rank`.`effectiveFrom` <= NOW()) 
                    AND (
                        (`rank`.`effectiveTo` > NOW()) 
                        OR ISNULL(`rank`.`effectiveTo`)
                    ) 
                LEFT JOIN `fnd_department` `d` 
                    ON (
                        `d`.`departmentNum` = `t`.`officeCode`
                    )
      ]]>
      <dynamic prepend="where">
          <isNotEmpty property="contractNos">
              <iterate prepend="AND" open="(" close=")" property="contractNos" conjunction="or" >
                contractNo like '%$contractNos[]$%'
              </iterate>
          </isNotEmpty>
          <isNotEmpty prepend="AND" property="projectIds"> FIND_IN_SET(projectId, #projectIds#)</isNotEmpty>
          <isEmpty property="contractNos">
              <isEmpty prepend="AND" property="projectIds"> projectId = -1 </isEmpty>
          </isEmpty>
      </dynamic>
;

-- L0303 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1750 | queryShipmentinfoByContractNosAndProjectIds | fb_items, fb_shipment_barcode_relation, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
select * from (
      SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName, 
        NULL AS chProjectId, NULL AS chContractNo, NULL AS transferProjectId, NULL AS transferContractNo, -1 AS transferFlag,
        vsip.barcode2 barCode2, vsip.itemCode2 itemCode2, vsip.itemName2 itemName2
      FROM view_shipment_info_4_pm vsip 
      LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
      WHERE vsip.contract_code in ($contractNos$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
          and contractNo in ($contractNos$) and projectId in ($projectIds$)
      )
      <isNotEmpty property="contractProfitCenter">
          <iterate prepend="AND" property="contractProfitCenter" open="(" close=")" conjunction="OR">
	          <!-- vsip.contract_code = #contractProfitCenter[].contractNo# and vsip.`profitCenter` = #contractProfitCenter[].officeCode# -->
	          vsip.contract_code = #contractProfitCenter[].sourceContractNo# 
	          <isNotEmpty prepend="AND" property="contractProfitCenter[].officeCode">
	              vsip.`profitCenter` = #contractProfitCenter[].officeCode#
	          </isNotEmpty>
	      </iterate>
      </isNotEmpty>
      UNION ALL 
      SELECT pps.`contractNo`,pps.`barcode`,pps.`itemCode`,pps.`itemName`,
        pps.chProjectId, pps.chContractNo, pps.transferProjectId, pps.transferContractNo, pps.transferFlag,
        sbr.sn2 AS barCode2, sbr.item2 AS itemCode2, fi.describe_ AS itemName2
      FROM pm_project_shipment pps 
        LEFT JOIN `fb_shipment_barcode_relation` sbr ON sbr.contract = REPLACE(pps.contractNo, '-C', '') AND pps.barcode = sbr.sn1
        LEFT JOIN `fb_items` fi ON fi.item = sbr.item2  
      WHERE contractNo in ($contractNos$) and projectId in ($projectIds$)
           <isEqual prepend="AND" property="excludeTransferOut" compareValue="true">transferFlag != 1</isEqual>
           AND EXISTS 
          (SELECT 
              1 
          FROM
              view_shipment_info_4_pm vsip 
              LEFT JOIN view_shipment_ems_4_pm vsep 
                  ON vsep.contract_code = vsip.contract_code 
                  AND vsep.packId = vsip.packId 
          WHERE vsip.contract_code IN ($sourceContractNos$)
              <!-- FIND_IN_SET(vsip.contract_code ,REPLACE(REPLACE(#contractNos#, '-C', ''), "'",'')) -->
              AND vsip.barcode = pps.barcode)
      ORDER BY transferFlag asc) t
      order by t.contractNo, t.itemCode
;

-- L0304 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1793 | checkSubcontractName | pm_subcontract_project_header
SELECT COUNT(1) FROM `pm_subcontract_project_header` WHERE subcontractName LIKE CONCAT(#subcontractName# , "%")
      <isNotEmpty prepend="AND" property="id">
         id != #id#
      </isNotEmpty>
;

-- L0305 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1800 | queryContractNoEngineeFee | pm_project_property_from_sms
SELECT 
        pfs.`orderExecNumber`, dfs.`contractNo`, pfs.`projectCode`, 
        CASE
            WHEN pfs.`engineeFee` IS NOT NULL 
            THEN pfs.engineeFee 
            ELSE 0 
        END AS engineeFee, pfs.`objId`, pfs.`applyType` as procType
    FROM
        `pm_project_property_from_sms` pfs 
        LEFT JOIN `pm_order_data_from_sap` dfs 
            ON pfs.`orderExecNumber` = dfs.`orderExecNumber` 
    WHERE dfs.`contractNo` IS NOT NULL
       AND FIND_IN_SET(dfs.contractNo, #contractNos#)
;

-- L0306 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1816 | queryContractNoEngineeFeeWithSubPrice | pm_project_property_from_sms, pm_subcontract_project_price
SELECT 
        t.`orderExecNumber`, t.`contractNo`, t.`projectCode`, t.engineeFee, t.`objId`, t.procType
        <isNotEmpty prepend="," property="subcontractId"> spp.`id`, spp.subcontractId, spp.`price` </isNotEmpty>
    FROM
        (SELECT 
            MAX(pfs.`orderExecNumber`) AS `orderExecNumber`, dfs.`contractNo`, pfs.`projectCode`, 
            CASE
                WHEN pfs.`engineeFee` IS NOT NULL 
                THEN pfs.engineeFee 
                ELSE 0 
            END AS engineeFee, pfs.`objId`, pfs.`applyType` AS procType 
        FROM
            `pm_project_property_from_sms` pfs 
            LEFT JOIN `pm_order_data_from_sap` dfs 
                ON pfs.`orderExecNumber` = dfs.`orderExecNumber` 
        WHERE dfs.`contractNo` IS NOT NULL
           AND FIND_IN_SET(dfs.contractNo, #contractNos#)
        GROUP BY dfs.contractNo, pfs.projectCode, pfs.objId, pfs.applyType) t 
        <isNotEmpty prepend=" " property="subcontractId">
        LEFT JOIN `pm_subcontract_project_price` spp 
            ON t.`orderExecNumber` = spp.`orderExecNumber` 
            AND t.contractNo = spp.contractNo 
            AND t.projectCode = spp.`projectCode`
            AND spp.subcontractId = #subcontractId#
            AND FIND_IN_SET(spp.contractNo, #contractNos#) 
        </isNotEmpty>
        order by t.contractNo, t.orderExecNumber
;

-- L0307 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1892 | querySubcontractTaskList | pm_subcontract_project_header, fnd_department, fnd_user_info
SELECT DISTINCT 
        h.id AS subcontractId, h.contractNos, h.subcontractNo, h.subcontractName, h.officeCode, dep.departmentName AS officeName, h.profitDepCode, dep2.departmentName AS profitDepName, D.KEY_ AS processKey, D.NAME_ AS processName, RES.ID_ AS taskId, RES.NAME_ AS taskName, 
        CASE
            WHEN RES.ASSIGNEE_ = 'emlRole' THEN '工程管理部主管'
            WHEN RES.ASSIGNEE_ = 'role_10' THEN '工程管理部主管'
            WHEN RES.ASSIGNEE_ = 'emRole' THEN '工程管理部'
            WHEN RES.ASSIGNEE_ = 'cbRole' THEN '回访人员' 
            WHEN RES.ASSIGNEE_ = 'zrRole' THEN '办事处主任' 
	        WHEN RES.ASSIGNEE_ = 'role_9' THEN '办事处主任'
		    ELSE CONCAT(ui.username, '-', ui.realName) 
        END AS assigneeName, RES.CREATE_TIME_ AS createTime 
    FROM
        ACT_RU_TASK RES 
        INNER JOIN ACT_RU_VARIABLE A0 
            ON RES.PROC_INST_ID_ = A0.PROC_INST_ID_ 
        INNER JOIN ACT_RE_PROCDEF D 
            ON RES.PROC_DEF_ID_ = D.ID_ 
        INNER JOIN `pm_subcontract_project_header` h 
            ON h.`id` = A0.`LONG_` 
            AND A0.NAME_ = 'subcontractId' 
            AND A0.TASK_ID_ IS NULL 
            AND A0.NAME_ = 'subcontractId' 
            AND A0.TYPE_ = 'integer' 
        LEFT JOIN fnd_user_info ui 
            ON RES.`ASSIGNEE_` = ui.`username` 
            AND ui.`status` = 1 
        LEFT JOIN fnd_department dep 
            ON h.`officeCode` = dep.`departmentNum` 
            AND dep.`status` = 1 
        LEFT JOIN fnd_department dep2 
            ON h.profitDepCode = dep2.`departmentNum` 
            <!-- AND dep2.isParam = 1  -->
            AND dep.`status` = 1 
    WHERE RES.SUSPENSION_STATE_ = 1 
        <isNotEmpty property="processKey" prepend="AND">
            D.KEY_ = #processKey#
        </isNotEmpty>
        <isEmpty property="processKey" prepend="AND">
            (D.KEY_ = 'Subcontract' or D.KEY_ = 'SubcontractCallBack')
        </isEmpty>
        <isNotEmpty property="taskId" prepend="AND">
            RES.ID_ = #taskId#
        </isNotEmpty>
        <isNotEmpty property="taskKey" prepend="AND">
            RES.TASK_DEF_KEY_ = #taskKey#
        </isNotEmpty>
        AND (
            <isNotEmpty property="assignee" prepend="">
                RES.ASSIGNEE_ = #assignee#
            </isNotEmpty>
<!--             <isNotEmpty property="roleGroup" prepend="OR">
                RES.ASSIGNEE_ = #roleGroup# 
            </isNotEmpty>  -->
            <!-- <isNotEmpty property="roleGroup" prepend="OR" open="(" close=")">
                RES.ASSIGNEE_ = #roleGroup# 
                <isNotEmpty property="checkOffice" prepend="and">
                    FIND_IN_SET(h.`officeCode`, #areaPower#)
                </isNotEmpty>
                <isNotEmpty property="checkProfitDep" prepend="and">
                    FIND_IN_SET(h.`profitDepCode`, #areaPower#)
                </isNotEmpty>
            </isNotEmpty> -->
            <isNotEmpty property="roleGroups">
                <iterate property="roleGroups">
                    <isNotEmpty property="roleGroups[].roleGroup" prepend="OR" open="(" close=")">
                        RES.ASSIGNEE_ = #roleGroups[].roleGroup# 
                        <isNotEmpty property="roleGroups[].checkOffice" prepend="and">
                            FIND_IN_SET(h.`officeCode`, #areaPower#)
                        </isNotEmpty>
                        <isNotEmpty property="roleGroups[].checkProfitDep" prepend="and">
                            FIND_IN_SET(h.`profitDepCode`, #areaPower#)
                        </isNotEmpty>
                    </isNotEmpty>
                </iterate>
            </isNotEmpty>
            )
    ORDER BY RES.CREATE_TIME_ DESC
;

-- L0308 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:1972 | selectRejectedSubcontractProjectList | pm_subcontract_project_header, fnd_department
<![CDATA[
        SELECT DISTINCT 
            h.id AS subcontractId, h.contractNos, h.subcontractNo, h.subcontractName, h.officeCode, dep.departmentName AS officeName, h.profitDepCode,
            dep2.departmentName AS profitDepName, "Subcontract" AS processKey, "项目转包流程" AS processName, -1 AS taskId, "重新发起申请" AS taskName, "服务经理" AS assigneeName, NULL AS createTime 
        FROM
            `pm_subcontract_project_header` h 
            LEFT JOIN fnd_department dep 
                ON h.`officeCode` = dep.`departmentNum` 
                AND dep.`status` = 1 
            LEFT JOIN fnd_department dep2 
                ON h.profitDepCode = dep2.`departmentNum` 
                AND dep2.isParam = 1 
                AND dep.`status` = 1 
        WHERE h.`state` < 0 AND FIND_IN_SET(h.`officeCode`, #areaPower#)
    ]]>
;

-- L0309 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2047 | querySubcontractActivitiTaskList | pm_subcontract_project_header
SELECT DISTINCT 
        RES.* 
    FROM
        ACT_RU_TASK RES 
        INNER JOIN ACT_RU_VARIABLE A0 
            ON RES.PROC_INST_ID_ = A0.PROC_INST_ID_ 
        INNER JOIN ACT_RE_PROCDEF D 
            ON RES.PROC_DEF_ID_ = D.ID_ 
        INNER JOIN `pm_subcontract_project_header` h 
            ON h.`id` = A0.`LONG_` 
            AND A0.NAME_ = 'subcontractId' 
            AND A0.TASK_ID_ IS NULL 
            AND A0.NAME_ = 'subcontractId' 
            AND A0.TYPE_ = 'integer' 
    WHERE RES.SUSPENSION_STATE_ = 1 
        <isNotEmpty property="processKey" prepend="AND">
            D.KEY_ = #processKey#
        </isNotEmpty>
        <isEmpty property="processKey" prepend="AND">
            (D.KEY_ = 'Subcontract' or D.KEY_ = 'SubcontractCallBack')
        </isEmpty>
        <isNotEmpty property="taskId" prepend="AND">
            RES.ID_ = #taskId#
        </isNotEmpty>
        <isNotEmpty property="taskKey" prepend="AND">
            <iterate property="taskKey" open="(" close=")" conjunction="or">
               RES.TASK_DEF_KEY_ = #taskKey[]#
            </iterate>
        </isNotEmpty>
        <isNotEmpty property="subcontractId" prepend="AND">
            (A0.NAME_ = 'subcontractId' 
            AND A0.TYPE_ = 'integer'
            AND A0.LONG_ = #subcontractId# )
        </isNotEmpty>
        AND (
            <isEmpty property="assignee" prepend="">
                <isEmpty property="roleGroup" prepend="">
                    1 = 1
                </isEmpty>
            </isEmpty>
            <isNotEmpty property="assignee" prepend="">
                RES.ASSIGNEE_ = #assignee#
            </isNotEmpty>
            <isNotEmpty property="roleGroup" prepend="OR" open="(" close=")">
                <!-- RES.ASSIGNEE_ = #roleGroup#  -->
                FIND_IN_SET(RES.ASSIGNEE_, #roleGroup# )
                <isNotEmpty property="checkOffice" prepend="and">
                    FIND_IN_SET(h.`officeCode`, #areaPower#)
                </isNotEmpty>
                <isNotEmpty property="checkProfitDep" prepend="and">
                    FIND_IN_SET(h.`profitDepCode`, #areaPower#)
                </isNotEmpty>
            </isNotEmpty>
            )
    ORDER BY RES.CREATE_TIME_ DESC
;

-- L0310 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2105 | querySubcontractCommentList | fnd_act_hi_comment, fnd_basic_data, fnd_user_info
SELECT 
        rp.NAME_ AS processName, bd.basicDataName AS statusName, ht.NAME_ AS taskName, ach.message AS 'comment', ach.assigneeTime, 
        CASE
            WHEN ach.`procdefKey` = 'Subcontract' 
            THEN ach.objId 
            ELSE spc.subcontractId 
        END AS subcontractId, 
        CASE
            WHEN ach.taskId = spc.taskId 
            THEN spc.quesnaireId 
            ELSE NULL 
        END AS quesnaireId, 
        CASE
            WHEN ui.username IS NULL 
            THEN ach.assignee 
            ELSE CONCAT(ach.assignee, "-", ui.realName) 
        END AS assigneeName, ach.nextAssignee, ach.nextAssigneeName
    FROM
        `fnd_act_hi_comment` ach 
        LEFT JOIN `pm_subcontract_project_callback` spc 
            ON ach.`objId` = spc.`id` 
            AND ach.`procdefKey` = 'SubcontractCallback' 
        LEFT JOIN `fnd_basic_data` bd 
            ON bd.dataTypeCode = 'subcontractWorkFlowState' 
            AND bd.basicDataId = ach.result 
        LEFT JOIN fnd_user_info ui 
            ON ui.username = ach.assignee 
        LEFT JOIN `act_hi_taskinst` ht 
            ON ht.ID_ = ach.taskId 
            AND ht.PROC_INST_ID_ = ach.instId 
        LEFT JOIN `act_re_procdef` rp 
            ON rp.ID_ = ht.PROC_DEF_ID_
    WHERE (
            ach.`procdefKey` = 'SubcontractCallback' 
            <isNotEmpty prepend="AND" > spc.`subcontractId` = #subcontractId#</isNotEmpty>
        )
        OR (
            ach.`procdefKey` = 'Subcontract' 
            <isNotEmpty prepend="AND" > ach.`objId` = #subcontractId#</isNotEmpty>
        )
    ORDER BY ach.`assigneeTime` ASC
;

-- L0311 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2149 | querySubcontractInfoForProject | fnd_basic_data, pm_subcontract_project_header, fnd_department, fnd_user_info
SELECT
        h.*, d.`departmentName` AS officeName, d1.`departmentName` AS profitDepName, bd.`basicDataName` AS stateName, bd1.`basicDataName` AS callbackStateName, bd2.basicDataName as typeName, CONCAT(h.createBy, "-", ui.`realName`) AS createName 
    FROM
        pm_subcontract_project_header h 
        LEFT JOIN fnd_department d 
            ON h.`officeCode` = d.`departmentNum` 
        LEFT JOIN fnd_department d1 
            ON h.`profitDepCode` = d1.`departmentNum` 
        LEFT JOIN `fnd_basic_data` bd 
            ON h.`state` = bd.`basicDataId` 
            AND bd.`dataTypeCode` = 'subcontractState' 
        LEFT JOIN `fnd_basic_data` bd1 
            ON h.`callbackState` = bd1.`basicDataId` 
            AND bd1.`dataTypeCode` = 'subcontractCbState' 
        LEFT JOIN `fnd_basic_data` bd2 
            ON h.`type` = bd2.`basicDataId` 
            AND bd2.`dataTypeCode` = 'subcontractType' 
        LEFT JOIN fnd_user_info ui 
            ON ui.`username` = h.`createBy`
    WHERE h.`effectiveTo` IS NULL 
        AND FIND_IN_SET(#projectIds#, h.projectIds);
;

-- L0312 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2173 | querySubcontractExportData | fnd_act_hi_comment, fnd_basic_data, pm_subcontract_project_header, pm_subcontract_project_payment, fnd_department
select 
        h.`contractNos`, h.`subcontractNo`, h.`subcontractName`, bd.`basicDataName` AS typeName, h.`facilitatorName`, h.`subcontractAmount`, office.`departmentName` AS officeName, profitDep.`departmentName` AS profitDepName, h.`createTime` 
        <isEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> zrTask.zrApproverTime </isEqual>
        <isNotEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> h.zrApproveTime as zrApproverTime</isNotEqual>,
        bd1.`basicDataName` AS stateName, bd2.`basicDataName` AS callbackStateName, h.`isAccrued`, h.`isInvoiced`, pp.confirmTime, 
        CONCAT(
            ROUND(
                pp.paidAmount / CONVERT(
                    REPLACE(h.subcontractAmount, ',', ''), DECIMAL (25, 2)
                ) * 100, 2
            ), "%"
        ) AS paidRatio, pp.paidAmount, pp.paymentTime, pp.remark 
    from
        `pm_subcontract_project_header` h
    <isEqual property="searchTimeType" compareValue="zrApproverTime">
        left join 
            (select 
                objId as subcontractId, max(assigneeTime) as zrApproverTime 
            from
                `fnd_act_hi_comment` 
            where result = 1 
                and taskKey = 'approveZRTask' 
                and procdefKey = 'Subcontract' 
            group by procdefKey, objId) zrTask 
            on zrTask.subcontractId = h.`id` 
    </isEqual>
        left join 
            (select 
                t.`subcontractId`, t.confirmTime, t.paymentTime, t.remark, maxPay.paidAmount 
            from
                `pm_subcontract_project_payment` t 
                inner join 
                    (select 
                        max(IF(confirmTime is not null, id, null)) as maxPayId, sum(
                            if(
                                paymentTime is not null, convert(
                                    replace(amount, ",", ""), DECIMAL (25, 2)
                                ), 0
                            )
                        ) as paidAmount 
                    from
                        `pm_subcontract_project_payment` 
                    <!-- where confirmTime is not null  -->
                    group by subcontractId) maxPay 
                    on t.id = maxPay.maxPayId) pp 
            on pp.subcontractId = h.id
    <isEqual property="searchTimeType" compareValue="paymentTime">
        LEFT JOIN `pm_subcontract_project_payment` p 
            ON h.id = p.`subcontractId` 
    </isEqual>
        left join `fnd_basic_data` bd 
            on bd.`basicDataId` = h.`type` 
            and bd.`dataTypeCode` = 'SubcontractType' 
        LEFT JOIN `fnd_basic_data` bd1 
            ON h.`state` = bd1.`basicDataId` 
            AND bd1.`dataTypeCode` = 'subcontractState' 
        LEFT JOIN `fnd_basic_data` bd2 
            ON h.`callbackState` = bd2.`basicDataId` 
            AND bd2.`dataTypeCode` = 'subcontractCbState' 
        left join fnd_department office 
            on office.`departmentNum` = h.`officeCode` 
            and office.`status` = 1 
        left join fnd_department profitDep 
            on profitDep.`departmentNum` = h.`profitDepCode` 
            and profitDep.`status` = 1
    where h.effectiveTo is NULL
        <isNotEmpty prepend="AND" property="id"> h.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractName"> h.subcontractName like concat("%", #subcontractName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="contractNos"> (h.contractNos like concat("%", #contractNos#, "%") or h.subcontractNo like concat("%", #contractNos#, "%")) </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectIds"> h.projectIds like concat("%", #projectIds#, "%")  </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> h.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="state"> h.state = #state# </isNotEmpty>
        <isNotEmpty prepend="AND" property="callbackState"> callbackState = #callbackState#  </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorId"> h.facilitatorId = #facilitatorId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorName"> h.facilitatorName like concat("%", #facilitatorName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankInfo"> h.bankInfo = #bankInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankAccount"> h.bankAccount = #bankAccount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="officeCode"> h.officeCode = #officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="profitDepCode"> h.profitDepCode = #profitDepCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractNo"> h.subcontractNo = #subcontractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isAccrued"> h.isAccrued = #isAccrued# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isInvoiced"> isInvoiced = #isInvoiced# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractAmount"> subcontractAmount = #subcontractAmount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="reason"> h.reason = #reason# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remark"> h.remark = #remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveForm"> h.effectiveForm = #effectiveForm# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveTo"> h.effectiveTo = #effectiveTo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="zrApproveTime"> h.zrApproveTime = #zrApproveTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createBy"> h.createBy = #createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createTime"> h.createTime = #createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateBy"> h.updateBy = #updateBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateTime"> h.updateTime = #updateTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="areaPower"> (FIND_IN_SET(h.officeCode, #areaPower#) or FIND_IN_SET(h.profitDepCode, #areaPower#))</isNotEmpty>
        <isNotEmpty prepend="AND" property="projectId"> FIND_IN_SET(#projectId#, h.projectIds) </isNotEmpty>
        <isEqual property="searchTimeType" compareValue="createTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproverTime">
            <isNotNull prepend="AND" property="searchStartTime"> zrTask.zrApproverTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ zrTask.zrApproverTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproveTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.zrApproveTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.zrApproveTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="paymentTime">
            <isNotNull prepend="AND" property="searchStartTime"> p.paymentTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ p.paymentTime <= #searchEndTime# ]]> </isNotNull>
            GROUP BY h.id
        </isEqual>
     order by h.id desc
;

-- L0313 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2288 | querySubcontractPaiedAmount | pm_subcontract_project_payment
SELECT 
        SUM(REPLACE(amount, ",", "")) as paiedAmount
    FROM
        `pm_subcontract_project_payment` 
    WHERE paymentTime IS NOT NULL 
       and subcontractId = #subcontractId#
    GROUP BY subcontractId
;

-- L0314 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2299 | queryNextPaymentTask | pm_subcontract_project_header, pm_subcontract_project_payment
SELECT 
        ph.*, ppp.lastPaymentTime, ppp.monthDiff
    FROM
        ACT_RU_TASK ret 
        INNER JOIN ACT_RU_VARIABLE arv 
            ON ret.PROC_INST_ID_ = arv.PROC_INST_ID_ 
        INNER JOIN 
            (SELECT 
                MAX(paymentTime) AS lastPaymentTime, TIMESTAMPDIFF(MONTH, MAX(paymentTime), NOW()) AS monthDiff, subcontractId 
            FROM
                pm_subcontract_project_payment ppp 
            WHERE paymentTime IS NOT NULL 
            GROUP BY subcontractId) ppp 
            ON ppp.`subcontractId` = arv.`LONG_` 
            AND arv.NAME_ = 'subcontractId' 
            AND arv.TASK_ID_ IS NULL 
            AND arv.NAME_ = 'subcontractId' 
            AND arv.TYPE_ = 'integer' 
        INNER JOIN `pm_subcontract_project_header` ph 
            ON ph.`id` = ppp.`subcontractId` 
            AND ph.`type` = '10' 
    WHERE ret.TASK_DEF_KEY_ = 'applyPaymentTask' 
        AND ppp.monthDiff >= 10 
        AND DATE_FORMAT(NOW(), '%Y-%m-%d') = DATE_FORMAT(
            DATE_ADD(
                ppp.lastPaymentTime, INTERVAL ppp.monthDiff MONTH
            ), '%Y-%m-%d'
        )
;

-- L0315 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-subcontract-config.xml:2331 | querySSESubcontractPaymentList | pm_subcontract_project_header, pm_subcontract_project_payment, fnd_user_info
SELECT NULL AS id
        , sph.`id` AS subcontractId, ROUND(
            spps.`approveAmount` / REPLACE(sph.`subcontractAmount`, ",", "") * 100, 2
        ) AS ratio, FORMAT(spps.approveAmount, 2) AS amount, spps.`confirmTime`, spps.`paymentTime`, spps.`remark`, spps.`id` AS sseId, spps.`confirmTime` AS createTime, ui.`username` createBy, NULL AS updateTime, NULL AS updateBy 
    FROM
        `pm_subcontract_project_payment_sse` spps 
        LEFT JOIN `pm_subcontract_project_header` sph 
            ON sph.`subcontractNo` = REPLACE(spps.`subcontractNo`, " ", "") 
        LEFT JOIN `pm_subcontract_project_payment` spp 
            ON spps.`id` = spp.`sseId` 
        LEFT JOIN fnd_user_info ui 
            ON spps.`workNo` = SUBSTR(ui.`username`, 2) 
    WHERE sph.id IS NOT NULL 
        AND spp.`sseId` IS NULL 
    ORDER BY spps.`confirmTime`, sph.id
;

-- L0316 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:15 | check_notification_list | pm_project_notification
<![CDATA[
			( select * from ( SELECT 
			  b.`notifySubject`,
			  b.`notifyContent`,
			  b.`projectId`,
			  a.`id` AS stateId,
			  b.`createTime`,
			  a.`checkTime`,
			  notifyState 
			FROM
			  `pm_project_notification_state` a 
			  LEFT JOIN `pm_project_notification` b 
			    ON a.`notifyId` = b.`id` 
			WHERE notifyObject = #username# AND notifyState = 0
			ORDER BY 
			  b.`createTime` DESC ) as tmp )
			UNION ALL 
			(
			SELECT 
			  b.`notifySubject`,
			  b.`notifyContent`,
			  b.`projectId`,
			  a.`id` AS stateId,
			  b.`createTime`,
			  a.`checkTime`,
			  notifyState 
			FROM
			  `pm_project_notification_state` a 
			  LEFT JOIN `pm_project_notification` b 
			    ON a.`notifyId` = b.`id` 
			WHERE notifyObject = #username# AND notifyState = 1
			ORDER BY 
			  a.`checkTime` DESC,
			  b.`createTime` DESC 
			LIMIT 100 )
		]]>
;

-- L0317 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:68 | query_pm_task_list | fnd_basic_data, pm_project_header, pm_project_member, pm_project_state, pm_project_task, fnd_department
<![CDATA[
			SELECT  t0.`projectCode`, t0.`projectName` ,t4.`basicDataName` AS  projectStateName,t5.`basicDataName` AS taskName , t0.`projectId` ,
			 CASE WHEN t1.projectPlanState = 40 THEN  DATEDIFF(NOW() , t6.createTime) WHEN  t1.projectPlanState = 47 THEN  DATEDIFF(NOW() , t1.projectplanTime) ELSE  DATEDIFF( NOW() , t2.`eventPlanHappenDateENG`) END AS diff,
			 t2.`eventPlanHappenDateENG` , t6.`memberName` AS programManager , t8.departmentName AS officeName
			FROM 
			pm_project_header t0 
			LEFT JOIN pm_project_state t1  ON t0.`projectId` = t1.`projectId`
			LEFT JOIN fnd_basic_data t4 ON t1.`projectPlanState` = t4.`basicDataId` AND t4.`dataTypeCode` = '22'
			LEFT JOIN fnd_basic_data t3 ON t4.`basicDataName` = t3.`basicDataName`  AND t3.`dataTypeCode` = '09'
			LEFT JOIN pm_project_task t2 ON  t2.`taskTypeCode` = t3.`dataTypeCode` AND t2.`taskTypeId` = t3.`basicDataId` 
			AND t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL AND t2.`visibleFlag` = 1
			LEFT JOIN fnd_basic_data t5 ON t1.`projectPlanState` = t5.`basicDataId` AND t5.`dataTypeCode` = '23'
			LEFT JOIN pm_project_member t6 ON t6.`projectId` = t0.`projectId` AND t6.`memberRole` = '30' AND t6.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t7 ON t7.`projectId` = t0.`projectId` AND t7.`memberRole` = '20' AND t7.`effectiveTo` IS NULL
			LEFT JOIN fnd_department t8 ON t0.column001 = t8.departmentNum AND t8.`status` = 1
			WHERE t0.`projectState` IN ( 30 ,31,32) AND t0.`effectiveTo` IS NULL 
			AND ( t2.`eventPlanHappenDateENG` IS NULL OR ( DATEDIFF( t2.`eventPlanHappenDateENG` , NOW()) < 7))
			AND t1.`projectPlanState` != 48 AND t6.memberCode IS NOT NULL
		]]>
		<isNotEmpty prepend="and" property="taskQueryParam.projectName"><![CDATA[ t0.projectName like '%$taskQueryParam.projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="taskQueryParam.officeCode"><![CDATA[ t0.column001 = #taskQueryParam.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="taskQueryParam.programManager"><![CDATA[ t6.memberCode = #taskQueryParam.programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="taskQueryParam.serviceManager"><![CDATA[ (t7.memberCode = #taskQueryParam.serviceManager# or t6.memberCode = #taskQueryParam.serviceManager# )]]></isNotEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset#, #displayParam.pagesize# 
		</isNotEmpty>
;

-- L0318 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:97 | query_pm_task_count | fnd_basic_data, pm_project_header, pm_project_member, pm_project_state, pm_project_task
<![CDATA[
			SELECT  COUNT(1)
			FROM 
			pm_project_header t0 
			LEFT JOIN pm_project_state t1  ON t0.`projectId` = t1.`projectId`
			LEFT JOIN fnd_basic_data t4 ON t1.`projectPlanState` = t4.`basicDataId` AND t4.`dataTypeCode` = '22'
			LEFT JOIN fnd_basic_data t3 ON t4.`basicDataName` = t3.`basicDataName`  AND t3.`dataTypeCode` = '09'
			LEFT JOIN pm_project_task t2 ON  t2.`taskTypeCode` = t3.`dataTypeCode` AND t2.`taskTypeId` = t3.`basicDataId` 
			AND t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL AND t2.`visibleFlag` = 1
			LEFT JOIN fnd_basic_data t5 ON t1.`projectPlanState` = t5.`basicDataId` AND t5.`dataTypeCode` = '23'
			LEFT JOIN pm_project_member t6 ON t6.`projectId` = t0.`projectId` AND t6.`memberRole` = '30' AND t6.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t7 ON t7.`projectId` = t0.`projectId` AND t7.`memberRole` = '20' AND t7.`effectiveTo` IS NULL
			WHERE t0.`projectState` IN ( 30 ,31,32) AND t0.`effectiveTo` IS NULL 
			AND ( t2.`eventPlanHappenDateENG` IS NULL OR ( DATEDIFF( t2.`eventPlanHappenDateENG` , NOW()) < 7))
			AND t1.`projectPlanState` != 48 AND t6.memberCode IS NOT NULL
		]]>
		<isNotEmpty prepend="and" property="projectName"><![CDATA[ t0.projectName like '%$projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="officeCode"><![CDATA[ t0.column001 = #officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="programManager"><![CDATA[ t6.memberCode = #programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="serviceManager"><![CDATA[ (t7.memberCode = #serviceManager# or t6.memberCode = #serviceManager#)]]></isNotEmpty>
;

-- L0319 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:120 | query_notify_count | pm_project_header, pm_project_member, pm_project_notification, fnd_department
<![CDATA[
			SELECT COUNT(*)
			FROM pm_project_notification t1 
			LEFT JOIN pm_project_header t2 ON t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t3 ON t2.`projectId` = t3.`projectId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t2.`projectId` = t4.`projectId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_department t5 ON t2.`column001` = t5.`departmentNum` AND t5.`status` = 1 where 1 = 1 and t2.projectId is not null
		]]>
		<isNotEmpty prepend="and" property="projectName"><![CDATA[ t2.projectName like '%$projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="officeCode"><![CDATA[ t2.column001 = #officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="programManager"><![CDATA[ t4.memberCode = #programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="serviceManager"><![CDATA[ (t3.memberCode = #serviceManager# or t4.memberCode = #serviceManager#)]]></isNotEmpty>
;

-- L0320 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:143 | query_notify_list | pm_project_header, pm_project_member, pm_project_notification, fnd_department, fnd_user_info
<![CDATA[
			SELECT t1.`projectId`,t2.`projectName` , t5.`departmentName` , t1.`notifyContent`, t1.`createTime` ,
				CONCAT( t1.`createBy` ,'-' ,t6.`realName`) as createBy, t4.`memberName` AS programManager , t3.`memberName` AS serviceManager FROM pm_project_notification t1 
			LEFT JOIN pm_project_header t2 ON t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t3 ON t2.`projectId` = t3.`projectId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t2.`projectId` = t4.`projectId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_user_info t6 ON t6.`username` = t1.`createBy`
			LEFT JOIN fnd_department t5 ON t2.`column001` = t5.`departmentNum` AND t5.`status` = 1
			WHERE 1 = 1 and t2.projectId is not null
		]]>
		<isNotEmpty prepend="and" property="notifyQueryParam.projectName"><![CDATA[ t2.projectName like '%$notifyQueryParam.projectName$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="notifyQueryParam.officeCode"><![CDATA[ t2.column001 = #notifyQueryParam.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="notifyQueryParam.programManager"><![CDATA[ t4.memberCode = #notifyQueryParam.programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="notifyQueryParam.serviceManager"><![CDATA[( t3.memberCode = #notifyQueryParam.serviceManager# or t4.memberCode = #notifyQueryParam.serviceManager# )]]></isNotEmpty>
		<![CDATA[
			ORDER BY t1.`createTime` DESC
		]]>
		<isNotEmpty property="notifyDisplayParam.offset">
			limit #notifyDisplayParam.offset#, #notifyDisplayParam.pagesize# 
		</isNotEmpty>
;

-- L0321 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:176 | query_project_back_task_list | fnd_basic_data, pm_project_header, pm_project_member, fnd_department
<![CDATA[
			SELECT  t1.projectCode ,t1.projectName , t4.departmentName AS officeName ,t3.basicDataName AS taskName, 
			t5.memberName AS programManager,t1.projectId,
			CASE WHEN t1.isback = '38' THEN t2.memberCode ELSE '工程管理部' END AS ASSIGNEE_ ,
			'项目回退流程' as procTypeDesc
			FROM pm_project_header t1 
			LEFT JOIN pm_project_member t2 ON t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL  AND t2.`memberRole` = '20' 
			LEFT JOIN pm_project_member t5 ON t1.`projectId` = t5.`projectId` AND t5.`effectiveTo` IS NULL  AND t5.`memberRole` = '30' 
			LEFT JOIN fnd_basic_data t3 ON t3.dataTypeCode = '23' AND basicDataId = '50'
			LEFT JOIN fnd_department t4 ON t1.column001 = t4.departmentNum AND t4.`status` = 1
			WHERE   t1.`projectState` IN (30,31,32) 
			AND t1.effectiveTo IS NULL
		]]>
		<isNotEmpty prepend="and" property="backstate">
			<![CDATA[ t1.`isback` = #backstate#]]>	
		</isNotEmpty>
		<isNotEmpty prepend="and" property="assignee">
			<![CDATA[ t2.memberCode = #assignee#]]>
		</isNotEmpty>
;

-- L0322 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:198 | query_project_track_task_list | fnd_basic_data, pm_project_header, pm_project_member, fnd_department
<![CDATA[
			SELECT 
			    t1.projectCode, t1.projectName, t4.departmentName AS officeName, "不予跟踪确认" AS taskName, t1.isback, t5.memberName AS programManager, t1.projectId, '工程管理部' AS ASSIGNEE_, "不予跟踪确认流程" AS procTypeDesc 
			FROM
			    pm_project_header t1 
			    LEFT JOIN pm_project_member t2 
			        ON t1.`projectId` = t2.`projectId` 
			        AND t2.`effectiveTo` IS NULL 
			        AND t2.`memberRole` = '20' 
			    LEFT JOIN pm_project_member t5 
			        ON t1.`projectId` = t5.`projectId` 
			        AND t5.`effectiveTo` IS NULL 
			        AND t5.`memberRole` = '30' 
			    LEFT JOIN fnd_basic_data t3 
			        ON t3.dataTypeCode = '23' 
			        AND basicDataId = '50' 
			    LEFT JOIN fnd_department t4 
			        ON t1.column001 = t4.departmentNum 
			        AND t4.`status` = 1 
			WHERE t1.`projectState` IN (30, 31, 32, 20) 
			    AND t1.isback IN ('42', '50') 
			    AND t1.effectiveTo IS NULL ;
		]]>
;

-- L0323 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:240 | query_call_back_task | pm_cl_callback, pm_project_header, pm_project_member, fnd_department, fnd_user_info
<![CDATA[
			SELECT t3.`projectCode` , t3.`projectName` , t4.`departmentName` AS officeName,t5.`memberName`  as programManager, t1.`NAME_`  as taskName,t3.`projectId` ,
			CASE WHEN t6.`realName` IS NULL THEN '回访人员' ELSE CONCAT(t6.username,'-' , t6.realName) END AS ASSIGNEE_ 
			,t1.id_ , t2.applyTime ,t7.KEY_ ,t7.NAME_ as procTypeDesc , mm.memberName ,
		    CASE
		        WHEN t3.column012 IS NULL 
		        AND t3.columno12_readonly = - 1 
		        THEN t3.column012 
		        WHEN t3.column012 IS NOT NULL 
		        THEN t3.column012 
		        ELSE t3.columno12_readonly 
    		END AS implType, mm.memberName 
			FROM act_ru_task t1 
			JOIN pm_cl_callback t2 ON t1.`PROC_INST_ID_` = t2.instId AND t2.`instId` IS NOT NULL AND t2.`effectiveTo` IS NULL
			LEFT JOIN act_re_procdef t7 ON t1.PROC_DEF_ID_ = t7.ID_
			LEFT JOIN pm_project_header t3 ON t2.`projectId` = t3.`projectId`
			LEFT JOIN fnd_department t4 ON t3.`column001` = t4.`departmentNum` AND t4.`status`  = 1
			LEFT JOIN pm_project_member t5 ON t3.`projectId` = t5.`projectId` AND t5.`memberRole` = '30' AND t5.`effectiveTo` IS NULL
			LEFT JOIN 
		        (SELECT 
		            m.projectId, GROUP_CONCAT(m.memberName) AS memberName 
		        FROM
		            pm_project_member m 
		        WHERE m.effectiveTo IS NULL 
		            AND m.memberRole = 60 
		        GROUP BY m.projectId) mm 
		        ON mm.projectId = t3.projectId 
			LEFT JOIN fnd_user_info t6 ON t1.`ASSIGNEE_` = t6.`username` AND t6.`status` = 1
			WHERE t3.projectState != 20 
		]]>
		<isEqual compareValue="1" property="callbackRole" prepend="and"><![CDATA[ 
			(
			ASSIGNEE_ = 'callbackRole' 
			or ASSIGNEE_ = #assignee#
			)]]>
		</isEqual>
		<isEqual compareValue="0" property="callbackRole" prepend="and">
			<![CDATA[ ASSIGNEE_ = #assignee#]]>
		</isEqual>
;

-- L0324 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:294 | query_presales_task | pm_project_member, fnd_department, fnd_user_info
<![CDATA[
			SELECT t1.`projectCode` ,t1.`projectName` ,t2.`departmentName`, t3.`memberName` ,t0.`NAME_`  ,
			CASE WHEN t6.`realName` IS NULL THEN '工程管理部' ELSE CONCAT(t6.username,'-' , t6.realName) END AS ASSIGNEE_ ,
			t0.`CREATE_TIME_` AS createTime ,t7.KEY_ ,t0.ID_,t1.presalesId,t7.NAME_ as procTypeDesc
			FROM act_ru_task t0 
			JOIN pm_presales_project_header t1 ON t0.`PROC_INST_ID_` = t1.`instId` 
			LEFT JOIN fnd_department t2 ON t1.`officeCode` = t2.`departmentNum` AND t2.`status` = 1
			LEFT JOIN pm_project_member t3 ON t3.`projectId` = t1.`presalesId` AND t3.`memberRole` = '30' AND t3.`effectiveTo` IS NULL
			LEFT JOIN fnd_user_info t6 ON t0.`ASSIGNEE_` = t6.`username` AND t6.`status` = 1
			LEFT JOIN act_re_procdef t7 ON t0.PROC_DEF_ID_ = t7.ID_
			WHERE 1 =1
		]]>
		<isEqual compareValue="1" property="emRole" prepend="and"><![CDATA[ 
			(
			ASSIGNEE_ = 'emRole' 
			or ASSIGNEE_ = #assignee#
			)]]>
		</isEqual>
		<isEqual compareValue="0" property="emRole" prepend="and">
			<![CDATA[ ASSIGNEE_ = #assignee#]]>
		</isEqual>
;

-- L0325 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:329 | query_callback_his_list | fnd_act_hi_comment, pm_cl_callback, pm_project_header, fnd_user_info
<![CDATA[
			SELECT t3.`projectCode` ,t3.`projectName` ,t4.`NAME_` ,'项目人员回访' AS taskName,t1.`applyBy` , 
				t5.`realName`  AS applyName, t6.`realName`  AS assigneeName,t2.`assigneeTime` , t2.`result` ,t1.`projectId`
			FROM pm_cl_callback t1  LEFT JOIN fnd_act_hi_comment t2 ON t1.`instId` = t2.`instId`
			LEFT JOIN pm_project_header t3 ON t1.`projectId` = t3.`projectId`
			LEFT JOIN act_re_procdef t4 ON t2.`procdefKey` = t4.`KEY_` 
			LEFT JOIN fnd_user_info t5 ON t1.`applyBy` = t5.`username` AND t5.`effectiveTo` IS NULL 
			LEFT JOIN fnd_user_info t6 ON t2.`assignee` = t6.`username` AND t6.`effectiveTo` IS NULL
			WHERE t2.`assignee` = #username# and t2.procdefKey = 'CallBack'
		]]>
;

-- L0326 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:401 | query_probTask_list | fnd_basic_data, fnd_department, fnd_user_info
SELECT 
			m.id AS probId, m.probNum, m.theme, m.createTime, m.status, t1.`basicDataName` AS watchName, t2.`basicDataName` AS statusName, t3.basicDataName AS priorityName, t4.username as trackingUser, CONCAT(t4.username, '-', t4.realName) AS trackingUsername, d.`departmentName` AS officeName 
		FROM
		    `prob_main` m 
		    LEFT JOIN `prob_restore` r 
			ON m.`id` = r.`probId`
		    LEFT JOIN `prob_restore_process` rp 
			ON r.`processId` = rp.`id` 
		    LEFT JOIN fnd_department d 
			ON r.`officeCode` = d.`departmentNum` 
		    LEFT JOIN fnd_basic_data t1 
			ON m.`watch` = t1.`basicDataId` 
			AND t1.`dataTypeCode` = '30' 
			AND t1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t2 
			ON m.`status` = t2.basicDataId 
			AND t2.dataTypeCode = '31' 
			AND t1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t3 
			ON m.`priority` = t3.`basicDataId` 
			AND t3.`dataTypeCode` = '32' 
			AND t1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_user_info t4 
			ON m.trackingUser = t4.username 
		<dynamic prepend="where">
			<isEqual property="isProbAdmin" compareValue="0">
					(
						<isNotEmpty prepend="and" property="assignee">
							(<![CDATA[
								( r.assignee = #assignee# 
							]]>	
							<isNotEmpty prepend="OR" property="areapower">
								<![CDATA[ 
									r.officeCode IN ($areapower$)
								]]>	
							</isNotEmpty>
								)  AND rp.`restoreStatus` = '10'
							)
						</isNotEmpty>
						OR m.watch = 15
					)
				<![CDATA[ 
					AND (
					m.`status` <> '10' 
					AND m.`status` <> '6' 
					AND m.`status` <> '8'
					AND m.`status` <> '1'
				) 
				]]>
			</isEqual>
			<isEqual property="isProbAdmin" compareValue="1">
				<![CDATA[ 
					 (
					m.`status` <> '10' 
					AND m.`status` <> '6'
				) 
				]]>
			</isEqual>
			<isEqual property="isProbAdmin" compareValue="2">
				<![CDATA[ 
					 (
					m.`status` = '4' 
					OR m.`status` = '5'
				) 
				]]>
			</isEqual>
			<isEqual property="isProbAdmin" compareValue="3">
				<![CDATA[ 
					 (
					m.`status` = '6' and m.`trackingUser` = #assignee#
				) 
				]]>
			</isEqual>
			<![CDATA[ and m.effectiveTo is null]]>
		</dynamic>
		GROUP BY m.`id` 
		ORDER BY m.`watch` ASC, m.`priority` DESC, m.`id` DESC
;

-- L0327 | D:/IDEAWorkspace/PMS/PMS-struts/bin/sql-map-work-config.xml:481 | queryProjectSupervisionTask | pm_project_member, pm_project_supervision, fnd_department
SELECT 
		    ps.`projectId` AS applyNum , ps.`projectCode`, ps.`projectName`, 
		    d.`departmentName` AS officeName, pm.`memberName` AS realName, 
		    '工程人员' AS assigneeName, ps.`createTime`, 
		    "ProjectSupervision" AS procTypeName, "项目督查" AS procTypeDesc, "填写督查问卷" AS name 
		FROM
		    `pm_project_supervision` ps 
		    LEFT JOIN pm_project_member pm 
		        ON ps.`projectId` = pm.`projectId` 
		        AND pm.`memberRole` = 30 
		        AND pm.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_department d 
		        ON ps.`officeCode` = d.`departmentNum` 
		WHERE isdelete = FALSE 
		    AND state = FALSE
;

-- L0328 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-maintenance-config.xml:180 | selectProjectMaintenanceList | pm_project_maintenance, pm_project_member
select m.* from pm_project_maintenance m
        LEFT JOIN pm_project_member sm 
            ON m.`projectId` = sm.`projectId` 
            AND sm.`memberRole` = '20' 
            AND sm.`effectiveTo` IS NULL 
            AND sm.`fromFlag` = 1 
        LEFT JOIN pm_project_member pm 
            ON m.`projectId` = pm.`projectId` 
            AND pm.`memberRole` = '30' 
            AND pm.`effectiveTo` IS NULL 
            AND pm.`fromFlag` = 1 
        LEFT JOIN pm_project_member pm2 
            ON m.`projectId` = pm2.`projectId` 
            AND pm2.`memberRole` = '30' 
            AND pm2.`effectiveTo` IS NULL 
            AND pm2.`fromFlag` = 2 
    <dynamic prepend="where">
        <isNotEmpty prepend="AND" property="id"> m.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectId"> m.projectId = #projectId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectCode"> m.projectCode like concat("%", #projectCode#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectName"> m.projectName like concat("%", #projectName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectType"> m.projectType = #projectType# </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectExecutionState"> m.projectExecutionState = #projectExecutionState# </isNotEmpty>
        <isNotEmpty prepend="AND" property="contractNo"> m.contractNo = #contractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="officeCode"> m.officeCode = #officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="compId"> m.compId = #compId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> m.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="category"> m.category = #category# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subCategory"> m.subCategory = #subCategory# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processTime"> m.processTime = #processTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processDesc"> m.processDesc = #processDesc# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processStep"> m.processStep = #processStep# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remainProblem"> m.remainProblem = #remainProblem# </isNotEmpty>
        <isNotEmpty prepend="AND" property="transitHour"> m.transitHour = #transitHour# </isNotEmpty>
        <isNotEmpty prepend="AND" property="processHour"> m.processHour = #processHour# </isNotEmpty>
        <isNotEmpty prepend="AND" property="itemModel"> m.itemModel = #itemModel# </isNotEmpty>
        <isNotEmpty prepend="AND" property="softVersion"> m.softVersion = #softVersion# </isNotEmpty>
        <isNotEmpty prepend="AND" property="enabledFeatures"> m.enabledFeatures = #enabledFeatures# </isNotEmpty>
        <isNotEmpty prepend="AND" property="hasReport"> m.hasReport = #hasReport# </isNotEmpty>
        <isNotEmpty prepend="AND" property="quesnaireId"> m.quesnaireId = #quesnaireId# </isNotEmpty>
