            <isNotEmpty prepend="AND" property="areaPower"> FIND_IN_SET(m.officeCode, #areaPower#)</isNotEmpty>
        </isEmpty>
        
        <isNotEmpty prepend="AND" property="processStartTime"> <![CDATA[ m.processTime >= #processStartTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="processEndTime"> <![CDATA[ m.processTime <= #processEndTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="createStartTime"> <![CDATA[ m.createTime >= #createStartTime# ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="createEndTime"> <![CDATA[ m.createTime <= #createEndTime# ]]> </isNotEmpty>
        
        <!-- <isNotEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(m.createTime, #currentDate#) ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(m.createTime, now()) ]]> </isEmpty> -->
        <!-- <isNotEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(IFNULL(m.updateTime, m.createTime), #currentDate#) ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentDate"> <![CDATA[ 0 = DATEDIFF(IFNULL(m.updateTime, m.createTime), now()) ]]> </isEmpty> -->
        <!-- <isNotEmpty prepend="AND" property="currentTime"> <![CDATA[ TIMESTAMPDIFF(HOUR, m.createTime, #currentTime#) BETWEEN 0 AND 23 ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentTime"> <![CDATA[ TIMESTAMPDIFF(HOUR, m.createTime, now()) BETWEEN 0 AND 23 ]]> </isEmpty> -->
        <isNotEmpty prepend="AND" property="currentTime"> <![CDATA[ m.createTime BETWEEN DATE_ADD(#currentTime#, INTERVAL -1 DAY) AND #currentTime# ]]> </isNotEmpty>
        <isEmpty prepend="AND" property="currentTime"> <![CDATA[ m.createTime BETWEEN DATE_ADD(now(), INTERVAL -1 DAY) AND now() ]]> </isEmpty>
   
        <isNotEmpty prepend="AND" property="warrantyStatus"> m.warrantyStatus = #warrantyStatus# </isNotEmpty>
        <isNotEmpty prepend="AND" property="industryName"> m.industryName = #industryName# </isNotEmpty>
        <isNotEmpty prepend="AND" property="userOffice"> m.userOffice = #userOffice# </isNotEmpty> 
        <isNotEmpty prepend="AND" property="year"> m.year = #year# </isNotEmpty>
        <isNotEmpty prepend="AND" property="quarter"> m.quarter = #quarter# </isNotEmpty>
        <isNotEmpty prepend="AND" property="month"> m.month = #month# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wsCount"> m.wsCount = #wsCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wafCount"> m.wafCount = #wafCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wsYearCount"> m.wsYearCount = #wsYearCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="wafYearCount"> m.wafYearCount = #wafYearCount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="warrantyInfo"> m.warrantyInfo = #warrantyInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="serviceInfo"> m.serviceInfo = #serviceInfo# </isNotEmpty>
    </dynamic>
;

-- L0334 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-maintenance-config.xml:1978 | queryDepartmentSectary | ehr_employee, fnd_department, fnd_user_info
SELECT 
	    ui.`username`, ui.`realName`, ui.`dpNo`, d.`departmentName`, 
	    IFNULL(ve.`depLV2Code`, ve.`depLV1Code`) AS depCode, ve.`depAllName`, 
	    e.`workNo` AS sectary, e.`name` AS sectaryName, e.`email` AS sectaryEmail, e.`mobile` AS sectaryPhone,
	    ms.`sectary` AS sectary1, ms2.`sectary` AS sectary2
	FROM
	    `fnd_user_info` ui 
	    LEFT JOIN `pm_project_maintenance_sectary_from_sse` ms 
	        ON ms.`depNum` = LEFT(ui.`dpNo`, 6)
	    LEFT JOIN `fnd_department` d 
	        ON d.`departmentNum` = ui.`dpNo` 
	    LEFT JOIN view_ehr_employee ve 
	        ON ve.`workNo` = RIGHT(ui.`username`, 5) 
	    LEFT JOIN `pm_project_maintenance_sectary_from_sse` ms2 
	        ON ms2.`depNum` = IFNULL(ve.`depLV2Code`, ve.`depLV1Code`) 
	    LEFT JOIN ehr_employee e
		ON e.`workNo` = IFNULL(ms.`sectary`, ms2.`sectary` )
	WHERE ui.`status` = 1
	<isNotEmpty prepend="AND" property="username"> ui.username = #username# </isNotEmpty>
;

-- L0335 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:27 | query_prob_count | fnd_basic_data
<![CDATA[
			SELECT count(*)
			FROM prob_main t1 
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			AND t2.`effectiveTo` IS NULL
		]]>	
		<isEqual prepend=" " property="checkSoft" compareValue="true"> 
			LEFT JOIN (
				SELECT 
				  probId, <!-- GROUP_CONCAT(
				      DISTINCT CONCAT(
				            "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, ""), " manual:", IFNULL(manualEntry, "")
				        ) SEPARATOR ";"
				    ) AS affectedVersion -->
				    GROUP_CONCAT(
		              DISTINCT concat_ws(
		                    " ", CONCAT("conp:", conp), CONCAT("cpld:", cpld), CONCAT("boot:", boot), CONCAT("pcb:", pcb), CONCAT("manual:", manualEntry)
		                ) SEPARATOR ";"
		            ) AS affectedVersion,
		            GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
				FROM
				    prob_softwares 
				where datastate = 1    
				GROUP BY probId) a 
				on a.probId = t1.id
			<isNotEmpty property="softVersionParserList">
			LEFT JOIN (
		        SELECT 
		          probId, GROUP_CONCAT(
		              DISTINCT concat_ws(
		                    " ", CONCAT("conp:", conp), CONCAT("cpld:", cpld), CONCAT("boot:", boot), CONCAT("pcb:", pcb), CONCAT("manual:", manualEntry)
		                ) SEPARATOR ";"
		            ) AS affectedVersion,
		            GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
		        FROM
		            prob_softwares 
		        where datastate = 1
		        <isNotEmpty prepend="AND" property="affectedType"> affectedType in (#affectedType#, 0) </isNotEmpty>
		        <iterate prepend="AND" property="softVersionParserList" open="(" close=")" conjunction="OR" >
		        	#softVersionParserList[].mark# between 
		        	<iterate property="softVersionParserList[].markAllPartsSet">REPLACE(</iterate> 
		        	markStart
		        	<iterate property="softVersionParserList[].markAllPartsSet">
		        		, #softVersionParserList[].markAllPartsSet[].key#, #softVersionParserList[].markAllPartsSet[].value#)
		        	</iterate>
		        	and 
		        	<iterate property="softVersionParserList[].markAllPartsSet">REPLACE(</iterate>
		        	markEnd
		        	<iterate property="softVersionParserList[].markAllPartsSet">
		        		, #softVersionParserList[].markAllPartsSet[].key#, #softVersionParserList[].markAllPartsSet[].value#)
	        		</iterate>
		        </iterate>
		        GROUP BY probId
	        ) sf ON sf.probId = t1.id
	        </isNotEmpty>
		</isEqual>
			where t1.effectiveTo is null
		<isNotEmpty prepend="and" property="probNum"><![CDATA[ t1.probNum like '%$probNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="watch"><![CDATA[ t1.watch = #watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="theme"><![CDATA[ t1.theme like '%$theme$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="status"><![CDATA[ t1.`status` = #status#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="statusList">
			t1.status in
			<iterate open="(" close=")" conjunction="," property="statusList">
				#statusList[]#
			</iterate>
		</isNotEmpty>
		
		<isNotEmpty prepend="and" property="productType"><![CDATA[ t1.productType like concat("%", #productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="desc"><![CDATA[ t1.desc like concat("%", #desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="affectedType"> sf.probId is not null <!-- #affectedType# = sf.affectedTypes --> </isNotEmpty>
        <isNotEmpty prepend="and" property="affectedVersion">
        	(
        	<![CDATA[ a.affectedVersion like concat("%", #affectedVersion#, "%") ]]>
        	<isNotEmpty prepend="or" property="softVersionParserList"> sf.probId is not null </isNotEmpty>
        	)
       	</isNotEmpty>
		
		<isNotEmpty property="visibleRange">
            <isNotEqual prepend="and" property="visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #visibleRange#
                <isNotEmpty prepend="or" property="trackingUser"> t1.trackingUser = #trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
;

-- L0336 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:125 | query_prob_list | fnd_basic_data, fnd_user_info
<![CDATA[
			SELECT t1.id as probId, t1.probNum, t1.theme,  t1.watch, t4.basicDataName as watchName, t2.`basicDataName` AS priority, t1.status, t3.basicDataName AS statusName, t1.trackingUser, CONCAT(t1.trackingUser,"-",ui.realName) AS trackingUsername,  t1.createTime, t1.updateTime 
			FROM prob_main t1 
			LEFT JOIN fnd_user_info ui ON ui.username = t1.trackingUser
			LEFT JOIN fnd_basic_data t4 ON t1.`watch` = t4.`basicDataId` AND t4.`dataTypeCode` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			LEFT JOIN fnd_basic_data t3 ON t1.`status` = t3.basicDataId AND t3.dataTypeCode = '31'
			AND t2.`effectiveTo` IS NULL
		]]>
		<isEqual prepend=" " property="prob.checkSoft" compareValue="true"> 
			LEFT JOIN (
		        SELECT 
		          probId,  <!-- GROUP_CONCAT(
		              DISTINCT CONCAT(
		                    "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, ""), " manual:", IFNULL(manualEntry, "")
		                ) SEPARATOR ";"
		            ) AS affectedVersion -->
		            GROUP_CONCAT(
		              DISTINCT concat_ws(
		                    " ", CONCAT("conp:", conp), CONCAT("cpld:", cpld), CONCAT("boot:", boot), CONCAT("pcb:", pcb), CONCAT("manual:", manualEntry)
		                ) SEPARATOR ";"
		            ) AS affectedVersion,
		            GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
		        FROM
		            prob_softwares 
		        where datastate = 1
		        GROUP BY probId) a 
		        ON a.probId = t1.id
	        <isNotEmpty property="prob.softVersionParserList">
	        LEFT JOIN (
		        SELECT 
		          probId, GROUP_CONCAT(
		              DISTINCT concat_ws(
		                    " ", CONCAT("conp:", conp), CONCAT("cpld:", cpld), CONCAT("boot:", boot), CONCAT("pcb:", pcb), CONCAT("manual:", manualEntry)
		                ) SEPARATOR ";"
		            ) AS affectedVersion,
		            GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
		        FROM
		            prob_softwares 
		        where datastate = 1
		        <isNotEmpty prepend="AND" property="prob.affectedType"> affectedType in (#prob.affectedType#, 0) </isNotEmpty>
		        <iterate prepend="AND" property="prob.softVersionParserList" open="(" close=")" conjunction="OR" >
		        	#prob.softVersionParserList[].mark# between 
		        	<iterate property="prob.softVersionParserList[].markAllPartsSet">REPLACE(</iterate> 
		        	markStart
		        	<iterate property="prob.softVersionParserList[].markAllPartsSet">
		        		, #prob.softVersionParserList[].markAllPartsSet[].key#, #prob.softVersionParserList[].markAllPartsSet[].value#)
		        	</iterate>
		        	and 
		        	<iterate property="prob.softVersionParserList[].markAllPartsSet">REPLACE(</iterate>
		        	markEnd
		        	<iterate property="prob.softVersionParserList[].markAllPartsSet">
		        		, #prob.softVersionParserList[].markAllPartsSet[].key#, #prob.softVersionParserList[].markAllPartsSet[].value#)
	        		</iterate>
		        </iterate>
		        GROUP BY probId
	        ) sf ON sf.probId = t1.id
	        </isNotEmpty>
        </isEqual>
		WHERE t1.effectiveTo IS NULL
		<isNotEmpty prepend="and" property="prob.probNum"><![CDATA[ t1.probNum like '%$prob.probNum$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.watch"><![CDATA[ t1.watch = #prob.watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.theme"><![CDATA[ t1.theme like '%$prob.theme$%']]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.status"><![CDATA[ t1.`status` = #prob.status#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.statusList">
			t1.status in
			<iterate open="(" close=")" conjunction="," property="prob.statusList">
				#prob.statusList[]#
			</iterate>
		</isNotEmpty>
		
		<isNotEmpty prepend="and" property="prob.productType"><![CDATA[ t1.productType like concat("%", #prob.productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.desc"><![CDATA[ t1.desc like concat("%", #prob.desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedType"> sf.probId is not null <!-- #prob.affectedType# = sf.affectedTypes --> </isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedVersion">
        	(
        	<![CDATA[ a.affectedVersion like concat("%", #prob.affectedVersion#, "%") ]]>
        	<isNotEmpty prepend="or" property="prob.softVersionParserList"> sf.probId is not null </isNotEmpty>
        	)
       	</isNotEmpty>
        
        <isNotEmpty property="prob.visibleRange">
            <isNotEqual prepend="and" property="prob.visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #prob.visibleRange# 
                <isNotEmpty prepend="or" property="prob.trackingUser"> t1.trackingUser = #prob.trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
        
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isEmpty prepend=" order by " property="displayParam.sort">
            t1.createTime desc
        </isEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset#,  #displayParam.pagesize#
		</isNotEmpty>
;

-- L0337 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:451 | query_prob_soft_version | fnd_basic_data
<![CDATA[
			SELECT 
			    ps.*, bd.`basicDataName` as affectedTypeName 
			FROM
			    prob_softwares ps 
			    LEFT JOIN fnd_basic_data bd 
			        ON bd.`dataTypeCode` = 'sofeVersionAffectedType' 
			        AND ps.`affectedType` = bd.`basicDataId` 
			WHERE ps.datastate = 1
		]]>
			<isNotEmpty prepend="AND" property="probId"> ps.probId = #probId# </isNotEmpty>
			<isNotEmpty prepend="AND" property="splited"> ps.splited = #splited# </isNotEmpty>
			<isNotEmpty prepend="AND" property="affectedType"> ps.affectedType = #affectedType# </isNotEmpty>
;

-- L0338 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:915 | query_exportProb_list | fnd_basic_data, fnd_user_info
SELECT 
		    t1.*, t2.`basicDataName` AS priorityName, t4.`basicDataName` AS watchName, t3.basicDataName AS statusName, CONCAT(t1.trackingUser, "-", ui.realName) AS trackingUsername, t.affectedVersion 
		FROM
		    prob_main t1 
		    LEFT JOIN fnd_user_info ui 
		        ON ui.username = t1.trackingUser 
		    LEFT JOIN fnd_basic_data t2 
		        ON t1.`priority` = t2.`basicDataId` 
		        AND t2.`dataTypeCode` = '32' 
		        AND t2.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t3 
		        ON t1.`status` = t3.basicDataId 
		        AND t3.dataTypeCode = '31' 
		        AND t3.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t4 
		        ON t1.`watch` = t4.basicDataId 
		        AND t4.dataTypeCode = '30' 
		        AND t4.`effectiveTo` IS NULL 
		    LEFT JOIN 
		        (SELECT 
		            probId, <!-- GROUP_CONCAT(
		              DISTINCT  CONCAT_WS(
		                    "-", CONCAT("conp[", conp, "]"), CONCAT("cpld[", cpld, "]"), CONCAT("boot[", boot, "]"), CONCAT("pcb[", pcb, "]"), CONCAT("manual[", manualEntry, "]")
		                ) SEPARATOR ";\r\n"
		            ) AS affectedVersion  -->
		            GROUP_CONCAT(
		              DISTINCT CONCAT(bd.`basicDataName`, ":", CONCAT_WS(
		                    "-", CONCAT("conp[", conp, "]"), CONCAT("cpld[", cpld, "]"), CONCAT("boot[", boot, "]"), CONCAT("pcb[", pcb, "]"), CONCAT("", manualEntry, "")
		                )) SEPARATOR ";\r\n"
		            ) AS affectedVersion
		        FROM
		            `prob_softwares` ps 
			    LEFT JOIN fnd_basic_data bd 
			        ON bd.`dataTypeCode` = 'sofeVersionAffectedType' 
			        AND ps.`affectedType` = bd.`basicDataId` 
		        WHERE datastate = 1 
		        GROUP BY probId) t 
		        ON t.probId = t1.`id` 
		WHERE t1.effectiveTo IS NULL
;

-- L0339 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1231 | query-max-project-group-id | pm_project_group
select max(id) from pm_project_group
;

-- L0340 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1267 | query-project-bycontractno | fnd_basic_data, pm_project_header, pm_project_member, pm_project_property_from_sms, fnd_department
<![CDATA[
            SELECT t1.basicDataName AS serviceType, pppfs.agentName, pppfs.customerProjectName, IFNULL(pppfs.majorProjectLevel, "无") majorProjectLevel,
            podfs.contractNo contractNo, CASE WHEN pppfs.projectCode IS NULL THEN podfs.contractNo ELSE pppfs.projectCode END AS projectCode, 
            IFNULL(IF(podfs.salesType = '01', podfs.projectName, pppfs.projectName), podfs.projectName) AS projectName,
            podfs.orderCreateTime orderCreateTime, podfs.customerCode customerCode, podfs.customerName customerName, pppfs.salesManCode salesManCode, 
            pppfs.salesManName salesManName, pppfs.marketCode marketCode, pppfs.marketName marketName, pppfs.systemId systemId, pppfs.systemName systemName, 
            pppfs.expendId expendId, pppfs.expendName expendName, pppfs.industryId, pppfs.industryName industryName, pppfs.officeCode officeCode, 
            fd.departmentName officeName, ppm.memberCode memberCode, ppm.memberName memberName, pph.column008 column008, pph.column010 column010, pph.column011 column011,
            pph.column012 column012, TRIM(IF(TRIM(IFNULL(pppfs.finalCustomerName, "")) > "", pppfs.finalCustomerName, pph.column013)) column013, podfs.compCode, c.id AS compId, podfs.salesType
            FROM pm_order_data_from_sap podfs
            LEFT JOIN pm_project_property_from_sms pppfs ON podfs.orderExecNumber = pppfs.orderExecNumber 
            LEFT JOIN pm_project_header pph ON podfs.contractNo = pph.projectCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pppfs.officeCode
            LEFT JOIN pm_project_member ppm ON pph.projectId = ppm.projectId
                 AND ppm.effectiveFrom <= NOW() AND (ppm.effectiveTo > NOW() OR ppm.effectiveTo IS NULL)
            LEFT JOIN fnd_basic_data t1 ON pppfs.serviceTypeName = t1.basicDataId AND t1.dataTypeCode = 21
                 AND t1.effectiveFrom <= NOW() AND ( t1.effectiveTo > NOW() OR t1.effectiveTo IS NULL )
            LEFT JOIN fnd_company c ON c.code = podfs.compCode
            where podfs.contractNo = #contractNo#   AND  podfs.`orderType` = 0 order by podfs.id desc limit 1
        ]]>
;

-- L0341 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1290 | query-project-bycontractnoAndType | fnd_basic_data, pm_project_header, pm_project_member, pm_project_property_from_sms, fnd_department
<![CDATA[
            SELECT t1.basicDataName AS serviceType, pppfs.agentName, pppfs.customerProjectName, IFNULL(pppfs.majorProjectLevel, "无") majorProjectLevel,
            podfs.contractNo contractNo, CASE WHEN pppfs.projectCode IS NULL THEN podfs.contractNo ELSE pppfs.projectCode END AS projectCode, 
            IFNULL(IF(podfs.salesType = '01', podfs.projectName, pppfs.projectName), podfs.projectName) AS projectName,
            podfs.orderCreateTime orderCreateTime, podfs.customerCode customerCode, podfs.customerName customerName, pppfs.salesManCode salesManCode, 
            pppfs.salesManName salesManName, pppfs.marketCode marketCode, pppfs.marketName marketName, pppfs.systemId systemId, pppfs.systemName systemName, 
            pppfs.expendId expendId, pppfs.expendName expendName, pppfs.industryId, pppfs.industryName industryName, pppfs.officeCode officeCode, 
            fd.departmentName officeName, ppm.memberCode memberCode, ppm.memberName memberName, pph.column008 column008, pph.column010 column010, pph.column011 column011,
            pph.column012 column012, TRIM(IF(TRIM(IFNULL(pppfs.finalCustomerName, "")) > "", pppfs.finalCustomerName, pph.column013)) column013, podfs.compCode, c.id AS compId, podfs.salesType
            FROM pm_order_data_from_sap podfs
            LEFT JOIN pm_project_property_from_sms pppfs ON podfs.orderExecNumber = pppfs.orderExecNumber 
            LEFT JOIN pm_project_header pph ON podfs.contractNo = pph.projectCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pppfs.officeCode
            LEFT JOIN pm_project_member ppm ON pph.projectId = ppm.projectId
                 AND ppm.effectiveFrom <= NOW() AND (ppm.effectiveTo > NOW() OR ppm.effectiveTo IS NULL)
            LEFT JOIN fnd_basic_data t1 ON pppfs.serviceTypeName = t1.basicDataId AND t1.dataTypeCode = 21
                 AND t1.effectiveFrom <= NOW() AND ( t1.effectiveTo > NOW() OR t1.effectiveTo IS NULL )
            LEFT JOIN fnd_company c ON c.code = podfs.compCode
            where podfs.contractNo = #contractNo# AND  podfs.`orderType` = 0 
        ]]>
        <isNotEmpty prepend="and" property="projectType"> pppfs.projectType = #projectType# </isNotEmpty>
        order by podfs.id desc limit 1
;

-- L0342 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:3196 | query_project_group_count | pm_project
<![CDATA[
            SELECT COUNT(1) FROM pm_project WHERE projectCode LIKE '%$projectCode$%' AND effectiveTo IS NULL
        ]]>
;

-- L0343 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:3304 | queryProjectContractCountByContractNoAndType | pm_project_contract, pm_project_group_relationship, pm_project
<![CDATA[
        select count(1) from pm_project_contract t1
          JOIN pm_project_group_relationship t2 ON t1.`projectGroupCode` = t2.`projectGroupCode`
          JOIN pm_project t3 ON t2.`projectCode` = t3.`projectCode` AND t3.`effectiveFrom` <= NOW() 
        AND (t3.`effectiveTo` > NOW() OR t3.`effectiveTo` IS NULL)  
        where contractNo in ($contractNo$)
        ]]>
        <isNotEmpty prepend="and" property="projectType">
            t3.projectType = #projectType# 
        </isNotEmpty>
;

-- L0344 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:3444 | query-cbData-list | fnd_act_hi_comment, pm_cl_callback, pm_cl_callback_quesnaire, pm_cl_quesnaire_result_header, pm_cl_quesnaire_result_line, pm_cl_quesnaire_template_line, pm_project_header, pm_project_member, fnd_department
<!-- 5.7以上不支持desc group by  -->
        <!-- (select aa.* ,count(aa.id)as times from (select *  from pm_cl_evaluation_header order by createdTime desc)aa where aa.evaluationType=3 and aa.status=1 group by aa.projectCode) a -->
        <![CDATA[
            select 
            a.id as id,a.projectName as projectName,a.projectCode as projectCode,a.evaluationResult as evaResult,a.times as times,a.projectId as projectId,
            case when a.updatedTime is null then a.createdTime else a.updatedTime end as cbTime ,
            b.quesMarkScore as totalScore, b.quesMarkResult as cbResult,
            e1.questionAnswer as equExplain, e2.questionAnswer as opinion,
            a.evaluationComment as approveRemark,
            c1.questionScore  as projectScore,  c2.questionScore  as equScore,
            c3.questionScore  as engScore,  c4.questionScore  as otherScore ,t2.departmentName as officeName, t3.memberName as pmRealName,
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS serviceType, t1.compId, fc.name AS companyName, fc.abbr AS companyAbbr
            from 
            (
			    select aa.*, a.times from (SELECT MAX(aa.id) AS id, COUNT(aa.id) AS times FROM pm_cl_evaluation_header aa WHERE aa.evaluationType = 3 AND aa.status = 1 GROUP BY aa.projectCode) a
			    left join pm_cl_evaluation_header aa
			    on aa.id = a.id
		    ) a
            left join pm_cl_quesnaire_result_header b on a.id=b.evaluationHeaderId and b.status=1
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c1  on b.id=c1.quesnaireResultHeaderId  and c1.quesTypeForCB=10 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c2  on b.id=c2.quesnaireResultHeaderId  and c2.quesTypeForCB=20
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c3  on b.id=c3.quesnaireResultHeaderId  and c3.quesTypeForCB=30 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c4  on b.id=c4.quesnaireResultHeaderId  and c4.quesTypeForCB=40
            left join pm_cl_quesnaire_template_line d1 on b.quesnaireTemplateHeaderId=d1.quesnaireTemplateHeaderId and d1.questionNum=5
            left join pm_cl_quesnaire_result_line e1 on e1.quesnaireResultHeaderId=b.id and e1.quesnaireTemplateLineId=d1.id
            left join pm_cl_quesnaire_template_line d2 on b.quesnaireTemplateHeaderId=d2.quesnaireTemplateHeaderId and d2.questionNum=8
            left join pm_cl_quesnaire_result_line e2 on e2.quesnaireResultHeaderId=b.id and e2.quesnaireTemplateLineId=d2.id
            LEFT JOIN pm_project_header t1 ON a.projectId = t1.projectId
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum
            LEFT JOIN pm_project_member t3 ON t1.projectId = t3.projectId AND t3.memberRole = 30    AND t3.effectiveTo IS NULL
            LEFT JOIN `fnd_company` fc ON t1.compId = fc.id
        ]]>
        <![CDATA[ 
            where t1.projectState != 20
        ]]>
        <isNotEmpty prepend="and" property="cbStartTime">
            <![CDATA[ 
            DATE_FORMAT(a.createdTime,'%Y-%m-%d')>=DATE_FORMAT(#cbStartTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="cbEndTime">
            <![CDATA[ 
            DATE_FORMAT(a.createdTime,'%Y-%m-%d')<=DATE_FORMAT(#cbEndTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="serviceType"><![CDATA[ (t1.column012 = #serviceType# or t1.columno12_readonly= #serviceType#)]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCode"><![CDATA[ t1.column001 = #officeCode# ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCodes"><![CDATA[ FIND_IN_SET(t1.column001, #officeCodes#) ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="compId"><![CDATA[ t1.compId = #compId# ]]></isNotEmpty>
        <![CDATA[
            group by a.projectCode
        ]]>
        <![CDATA[
            UNION
            select  a.quesnaireId as id,t1.projectName as projectName,t1.projectCode as projectCode,b.quesMarkResult as evaResult,a.times as times,a.projectId as projectId,
                case when a.updateTime is null then a.createTime else a.updateTime end as cbTime ,
                b.quesMarkScore as totalScore, b.quesMarkResult as cbResult,
                e1.questionAnswer as equExplain, e2.questionAnswer as opinion,
                ahc.message as approveMessage,
                c1.questionScore  as projectScore,  c2.questionScore  as equScore,
                c3.questionScore  as engScore,  c4.questionScore  as otherScore ,t2.departmentName as officeName, t3.memberName as pmRealName,
                CASE
                    WHEN t1.column012 IS NULL 
                    AND t1.columno12_readonly = - 1 
                    THEN t1.column012 
                    WHEN t1.column012 IS NOT NULL 
                    THEN t1.column012 
                    ELSE t1.columno12_readonly 
                END AS serviceType, t1.compId, fc.name AS companyName, fc.abbr AS companyAbbr
                from (
                    SELECT 
                     cb.projectId,cb.applyState, cb.instId, cbq.*, cbq.quesnaireVersion as times
                    FROM
                      pm_cl_callback cb 
                      LEFT JOIN (SELECT * FROM pm_cl_callback_quesnaire WHERE quesnaireState = 1 AND id IN (SELECT MAX(id)  FROM `pm_cl_callback_quesnaire` GROUP BY callBackId)) cbq 
                        ON cb.id = cbq.callBackId 
                        AND cbq.quesnaireState = 1
                    where cb.applyState != -1 and cbq.quesnaireId IS NOT NULL AND cb.projectId NOT IN (SELECT DISTINCT projectId  FROM `pm_cl_evaluation_header`)
                    ORDER BY cbq.createTime desc
                ) a
                INNER JOIN 
			    (
			        SELECT 
			         cb.projectId, MAX(cbq.createTime) createTime
			        FROM
			          pm_cl_callback cb 
			          LEFT JOIN (SELECT * FROM pm_cl_callback_quesnaire WHERE quesnaireState = 1 AND id IN (SELECT MAX(id)  FROM `pm_cl_callback_quesnaire` GROUP BY callBackId)) cbq 
			        ON cb.id = cbq.callBackId 
			        AND cbq.quesnaireState = 1
			        WHERE cb.applyState != -1 AND cbq.quesnaireId IS NOT NULL AND cb.projectId NOT IN (SELECT DISTINCT projectId  FROM `pm_cl_evaluation_header`)
			        GROUP BY cb.`projectId`
			    ) ma ON ma.createTime = a.createTime AND ma.projectId = a.projectId
                left join (select ach.* from (select max(id) as maxId from `fnd_act_hi_comment` ahc left join `act_hi_taskinst` aht on ahc.taskId = aht.ID_ where procdefKey = 'CallBack' and aht.TASK_DEF_KEY_ = 'usertask2' group by objId, procdefKey, instId) t left join fnd_act_hi_comment ach on ach.id = t.maxId) ahc on a.instId = ahc.instId 
                left join pm_cl_quesnaire_result_header b on a.quesnaireId=b.id and b.status=1
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c1  on b.id=c1.quesnaireResultHeaderId  and c1.quesTypeForCB=10 
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c2  on b.id=c2.quesnaireResultHeaderId  and c2.quesTypeForCB=20
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c3  on b.id=c3.quesnaireResultHeaderId  and c3.quesTypeForCB=30 
                left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c4  on b.id=c4.quesnaireResultHeaderId  and c4.quesTypeForCB=40
                left join pm_cl_quesnaire_template_line d1 on b.quesnaireTemplateHeaderId=d1.quesnaireTemplateHeaderId and d1.questionNum=5
                left join pm_cl_quesnaire_result_line e1 on e1.quesnaireResultHeaderId=b.id and e1.quesnaireTemplateLineId=d1.id
                left join pm_cl_quesnaire_template_line d2 on b.quesnaireTemplateHeaderId=d2.quesnaireTemplateHeaderId and d2.questionNum=8
                left join pm_cl_quesnaire_result_line e2 on e2.quesnaireResultHeaderId=b.id and e2.quesnaireTemplateLineId=d2.id
                LEFT JOIN pm_project_header t1 ON a.projectId = t1.projectId
                LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum
                LEFT JOIN pm_project_member t3 ON t1.projectId = t3.projectId AND t3.memberRole = 30    AND t3.effectiveTo IS null
                LEFT JOIN `fnd_company` fc ON t1.compId = fc.id
            WHERE t1.projectState != 20
        ]]>
        <isNotEmpty prepend="and" property="cbStartTime">
            <![CDATA[ 
            DATE_FORMAT(a.createTime,'%Y-%m-%d')>=DATE_FORMAT(#cbStartTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="cbEndTime">
            <![CDATA[ 
            DATE_FORMAT(a.createTime,'%Y-%m-%d')<=DATE_FORMAT(#cbEndTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="serviceType"><![CDATA[ (t1.column012 = #serviceType# or t1.columno12_readonly= #serviceType#)]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCode"><![CDATA[ t1.column001 = #officeCode# ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCodes"><![CDATA[ FIND_IN_SET(t1.column001, #officeCodes#) ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="compId"><![CDATA[ t1.compId = #compId# ]]></isNotEmpty>
        <![CDATA[
            group by t1.projectCode
        ]]>
;

-- L0345 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:3589 | query_history_project_shipment_size | pm_project_shipment
<![CDATA[
            SELECT COUNT(*) FROM `pm_project_shipment` pps WHERE projectId = #projectId#
        ]]>
