-- L0346 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:5630 | queryProjectSimplifyByProjectId | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_state, fnd_department
<![CDATA[
        SELECT pph.projectId,CASE WHEN pph.effectiveFrom < NOW() AND (pph.effectiveTo >= NOW() OR pph.effectiveTo IS NULL) THEN 0 ELSE 1 END AS projectStatus, 
            GROUP_CONCAT(ppc.contractNo) AS contractNo, pph.projectCode, pph.compId,
            CASE WHEN ppgr.`mergeBranchMark` IS NULL THEN pph.projectName ELSE CONCAT( pph.projectName, '-',ppgr.`mergeBranchMark`) END AS projectName, 
            pph.projectState, pph.isback, pph.column001, fd.departmentName AS officeName, pph.column002, pph.column003, pph.column004, pph.column005, 
            pph.column006, pph.column007, pph.column008, pph.column009, pph.column010, pph.column011,
            CASE WHEN  pph.column012 IS NULL OR pph.column012 = '' THEN pph.columno12_readonly ELSE pph.column012 END AS column012, 
            pph.columno12_readonly AS column012Readonly, pph.column013, pph.column014, pph.salesType,
            CASE WHEN ppm1.memberCode IS NULL THEN ppm4.memberCode ELSE ppm1.memberCode END AS serviceManagerCode, 
            CASE WHEN ppm1.memberName IS NULL THEN ppm4.memberName ELSE ppm1.memberName END AS serviceManagerCodeforjson, 
            CASE WHEN ppm2.memberCode IS NULL THEN ppm5.memberCode ELSE ppm2.memberCode END AS programManagerCode,
            CASE WHEN ppm2.memberName IS NULL THEN ppm5.memberName ELSE ppm2.memberName END AS programManagerCodeforjson,
            ppm5.memberCode AS programManagerCodeB,
            ppm5.memberName AS programManagerCodeforjsonB,
            GROUP_CONCAT(ppm6.memberCode) AS teamMemberCodes,
            executionState.`basicDataName` AS executionStateName, ps.executionState, 
            closeProcessState.`basicDataName` AS closeProcessStateName, ps.closeProcessState
        FROM pm_project_header pph 
            LEFT JOIN pm_project_member ppm1 ON ppm1.projectId = pph.projectId AND ppm1.memberRole = '20' AND ppm1.fromFlag = 1
            AND (ppm1.effectiveFrom <= NOW() AND (ppm1.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm4 ON ppm4.projectId = pph.projectId AND ppm4.memberRole = '20' AND ppm4.fromFlag = 2
            AND (ppm4.effectiveFrom <= NOW() AND (ppm4.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm2 ON ppm2.projectId = pph.projectId AND ppm2.memberRole = '30' AND ppm2.fromFlag = 1
            AND (ppm2.effectiveFrom <= NOW() AND (ppm2.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm5 ON ppm5.projectId = pph.projectId AND ppm5.memberRole = '30' AND ppm5.fromFlag = 2
            AND (ppm5.effectiveFrom <= NOW() AND (ppm5.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm6 ON ppm6.projectId = pph.projectId AND ppm6.memberRole = '40'
            AND (ppm6.effectiveFrom <= NOW() AND (ppm6.effectiveTo IS NULL))
            LEFT JOIN pm_project_group_relationship ppgr ON ppgr.projectCode = pph.projectCode
            LEFT JOIN pm_project_contract ppc ON ppc.projectGroupCode = ppgr.projectGroupCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pph.column001
            LEFT JOIN `pm_project_state` ps ON ps.projectId = pph.projectId
            LEFT JOIN fnd_basic_data executionState ON executionState.`dataTypeCode` = 'projectExecutionState' AND executionState.`basicDataId` = ps.`executionState`
            LEFT JOIN fnd_basic_data closeProcessState ON closeProcessState.`dataTypeCode` = 'projectCloseProcessState' AND closeProcessState.`basicDataId` = ps.`closeProcessState`
            
        WHERE pph.projectId = #projectId# LIMIT 1;
    ]]>
;

-- L0347 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-refresh-data-config.xml:844 | query_pm_self_service_project | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_property_from_sms
<![CDATA[
            SELECT DISTINCT 
                IFNULL(IF(p.salesType = '01', p.projectName, pp.projectName), p.projectName) AS `projectName`, `p`.`contractNo` AS `contractNo`, `pp`.`officeCode` AS `column001` 
            FROM
                `view_distinct_contract` `v` 
                LEFT JOIN `pm_order_data_from_sap` `p` 
                    ON ((`v`.`id` = `p`.`id`)) 
                LEFT JOIN `pm_project_property_from_sms` `pp` 
                    ON (
                        (
                            `p`.`orderExecNumber` = `pp`.`orderExecNumber`
                        )
                    ) 
                LEFT JOIN fnd_basic_data fbd 
                    ON pp.serviceTypeName = fbd.basicDataId 
                    AND fbd.dataTypeCode = 21 
                    AND fbd.effectiveFrom <= NOW() 
                    AND (
                        fbd.effectiveTo > NOW() 
                        OR fbd.effectiveTo IS NULL
                    ) 
            WHERE NOT EXISTS 
                (SELECT 
                    1 
                FROM
                    (
                        `pm_project_contract` `t1` 
                        JOIN `pm_project_group_relationship` `t2` 
                            ON (
                                (
                                    `t1`.`projectGroupCode` = `t2`.`projectGroupCode`
                                )
                            )
                    ) 
                    JOIN `pm_project_header` `t3` 
      ]]>
                           ON (
<!--                            `t2`.`projectCode` = `t3`.`projectCode` -->
<!--                                 OR  -->
                                `t3`.`projectCode` = REPLACE(`t2`.`projectCode`, "-his", "")
                            )
       <![CDATA[
                        AND (`t3`.`effectiveFrom` <= NOW()) 
                        AND (
                            (`t3`.`effectiveTo` > NOW()) 
                            OR ISNULL(`t3`.`effectiveTo`)
                        ) 
                WHERE (
                        `p`.`contractNo` = `t1`.`contractNo`
                    )) 
                AND v.contractNo IS NOT NULL
               AND fbd.`basicDataName` = 3
       ]]>
;

-- L0348 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-report-config.xml:604 | queryProjectSummaryStatus | pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_state, fnd_department
select 
		    ph.*, group_concat(distinct pc.contractNo) as contractNo,
		    fd.`departmentName` as officeName, ps.`shipmentState`, ps.`projectPlanState`, ps.`executionState`, ps.`closeProcessState` 
		from
		    pm_project_header ph 
		    left join `pm_project_group_relationship` pgr
				on ph.`projectCode` = pgr.`projectCode`
		    left join `pm_project_contract` pc
				on pc.`projectGroupCode` = pgr.`projectGroupCode`
		    left join `pm_project_state` ps 
		        on ph.`projectId` = ps.`projectId` 
		    left join `fnd_department` fd 
		        on ph.`column001` = fd.`departmentNum` 
		where ph.effectiveTo IS NULL 
			<dynamic prepend="and" open="(" close=")">
			    <!-- 1 = 1 -->
				<isNotEmpty prepend="and" property="column011"> ph.column011 = #column011# </isNotEmpty>
				<isNotEmpty prepend="and" property="column004"> ph.column004 = #column004# </isNotEmpty>
			</dynamic>
			<isNotEmpty property="exceptZQYY">
	             = !#exceptZQYY#
	        </isNotEmpty>
			<isNotEmpty prepend="and" property="column001"> ph.column001 = #column001# </isNotEmpty>
	        <isNotEmpty prepend="and" property="projectState"> FIND_IN_SET(ph.projectState, #projectState#) </isNotEmpty>
	        <isNotEmpty prepend="and" property="shipmentState"> FIND_IN_SET(ps.shipmentState, #shipmentState#) </isNotEmpty>
			<isNotEmpty prepend="and" property="projectPlanState"> FIND_IN_SET(ps.projectPlanState, #projectPlanState#) </isNotEmpty>
			<isNotEmpty prepend="and" property="executionState"> FIND_IN_SET(IFNULL(ps.executionState, ""), #executionState#) </isNotEmpty>
			<isNotEmpty prepend="and" property="closeProcessState"> FIND_IN_SET(ps.closeProcessState, #closeProcessState#) </isNotEmpty>
	        <isNotEmpty property="querys">
		        <iterate property="querys" prepend="and" open="(" close=")" conjunction=" or " >
		           (
		            1 = 1
	                <isNotEmpty property="querys[].exceptZQYY" prepend="and">
	                     ( 1 = 1
	                </isNotEmpty>
	                <isNotEmpty prepend="and" property="querys[].column011"> ph.column011 = #querys[].column011# </isNotEmpty>
	                <isNotEmpty prepend="and" property="querys[].column004"> ph.column004 = #querys[].column004# </isNotEmpty>
		            <isNotEmpty property="querys[].exceptZQYY">
		                 ) = !#querys[].exceptZQYY#
		            </isNotEmpty>
		            <isNotEmpty prepend="and" property="querys[].column001"> ph.column001 = #querys[].column001# </isNotEmpty>
		            <isNotEmpty prepend="and" property="querys[].projectState"> FIND_IN_SET(ph.projectState, #querys[].projectState#) </isNotEmpty>
		            <isNotEmpty prepend="and" property="querys[].shipmentState"> FIND_IN_SET(ps.shipmentState, #querys[].shipmentState#) </isNotEmpty>
		            <isNotEmpty prepend="and" property="querys[].projectPlanState"> FIND_IN_SET(ps.projectPlanState, #querys[].projectPlanState#) </isNotEmpty>
		            <isNotEmpty prepend="and" property="querys[].executionState"> FIND_IN_SET(IFNULL(ps.executionState, ""), #querys[].executionState#) </isNotEmpty>
		            <isNotEmpty prepend="and" property="querys[].closeProcessState"> FIND_IN_SET(ps.closeProcessState, #querys[].closeProcessState#) </isNotEmpty>
		           )
		        </iterate>
	        </isNotEmpty>
		group by ph.`projectId`
;

