-- L0355 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-subcontract-config.xml:1060 | selectSubcontractDeliverVOList | fnd_basic_data, fnd_user_info
SELECT 
        fl.*, 
        CASE
            WHEN ui.username IS NOT NULL 
            THEN CONCAT(ui.username, "-", ui.realName) 
            ELSE fl.uploadBy 
        END AS uploadName, bd.`basicDataName` AS typeName 
    FROM
        pm_subcontract_deliver_files fl 
        LEFT JOIN `fnd_basic_data` bd 
            ON fl.`type` = bd.`basicDataId` 
            AND bd.`dataTypeCode` = 'subcontractDeliverState' 
        LEFT JOIN fnd_user_info ui 
            ON ui.`username` = fl.`uploadBy`
    <dynamic prepend="where">
        <isNotEmpty prepend="AND" property="id"> fl.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractId"> fl.subcontractId = #subcontractId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="fileName"> fl.fileName = #fileName# </isNotEmpty>
        <isNotEmpty prepend="AND" property="filePath"> fl.filePath = #filePath# </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> fl.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="uploadBy"> fl.uploadBy = #uploadBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="uploadTime"> fl.uploadTime = #uploadTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveFrom"> fl.effectiveFrom = #effectiveFrom# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveTo"> <![CDATA[ #effectiveTo# <= IFNULL(fl.effectiveTo, "9999-12-31") ]]> </isNotEmpty>
    </dynamic>
;

-- L0356 | D:/IDEAWorkspace/PMS/PMS-struts/config-ibaits/sql-map-subcontract-config.xml:2173 | querySubcontractExportData | fnd_act_hi_comment, fnd_basic_data, pm_subcontract_project_header, pm_subcontract_project_payment, fnd_department, fnd_user_info
select 
        h.`contractNos`, h.`subcontractNo`, h.`subcontractName`, bd.`basicDataName` AS typeName, h.`facilitatorName`, h.`subcontractAmount`, 
        office.`departmentName` AS officeName, profitDep.`departmentName` AS profitDepName, 
        h.`createTime`, CONCAT(h.createBy, "-", ui.`realName`) AS createName
        <isEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> zrTask.zrApproverTime </isEqual>
        <isNotEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> h.zrApproveTime as zrApproverTime</isNotEqual>,
        bd1.`basicDataName` AS stateName, bd2.`basicDataName` AS callbackStateName, h.`isAccrued`, h.`isInvoiced`, pp.confirmTime, 
        CONCAT(
            ROUND(
                pp.paidAmount / CONVERT(
                    REPLACE(h.subcontractAmount, ',', ''), DECIMAL (25, 2)
                ) * 100, 2
            ), "%"
        ) AS paidRatio, pp.paidAmount, pp.paymentTime, pp.remark 
    from
        `pm_subcontract_project_header` h
    <isEqual property="searchTimeType" compareValue="zrApproverTime">
        left join 
            (select 
                objId as subcontractId, max(assigneeTime) as zrApproverTime 
            from
                `fnd_act_hi_comment` 
            where result = 1 
                and taskKey = 'approveZRTask' 
                and procdefKey = 'Subcontract' 
            group by procdefKey, objId) zrTask 
            on zrTask.subcontractId = h.`id` 
    </isEqual>
        left join 
            (select 
                t.`subcontractId`, t.confirmTime, t.paymentTime, t.remark, maxPay.paidAmount 
            from
                `pm_subcontract_project_payment` t 
                inner join 
                    (select 
                        max(IF(confirmTime is not null, id, null)) as maxPayId, sum(
                            if(
                                paymentTime is not null, convert(
                                    replace(amount, ",", ""), DECIMAL (25, 2)
                                ), 0
                            )
                        ) as paidAmount 
                    from
                        `pm_subcontract_project_payment` 
                    <!-- where confirmTime is not null  -->
                    group by subcontractId) maxPay 
                    on t.id = maxPay.maxPayId) pp 
            on pp.subcontractId = h.id
    <isEqual property="searchTimeType" compareValue="paymentTime">
        LEFT JOIN `pm_subcontract_project_payment` p 
            ON h.id = p.`subcontractId` 
    </isEqual>
        left join `fnd_basic_data` bd 
            on bd.`basicDataId` = h.`type` 
            and bd.`dataTypeCode` = 'SubcontractType' 
        LEFT JOIN `fnd_basic_data` bd1 
            ON h.`state` = bd1.`basicDataId` 
            AND bd1.`dataTypeCode` = 'subcontractState' 
        LEFT JOIN `fnd_basic_data` bd2 
            ON h.`callbackState` = bd2.`basicDataId` 
            AND bd2.`dataTypeCode` = 'subcontractCbState' 
        left join fnd_department office 
            on office.`departmentNum` = h.`officeCode` 
            and office.`status` = 1 
        left join fnd_department profitDep 
            on profitDep.`departmentNum` = h.`profitDepCode` 
            and profitDep.`status` = 1
        LEFT JOIN fnd_user_info ui 
            ON ui.`username` = h.`createBy`
    where h.effectiveTo is NULL
        <isNotEmpty prepend="AND" property="id"> h.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractName"> h.subcontractName like concat("%", #subcontractName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="contractNos"> (h.contractNos like concat("%", #contractNos#, "%") or h.subcontractNo like concat("%", #contractNos#, "%")) </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectIds"> h.projectIds like concat("%", #projectIds#, "%")  </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> h.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="state"> h.state = #state# </isNotEmpty>
        <isNotEmpty prepend="AND" property="callbackState"> callbackState = #callbackState#  </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorId"> h.facilitatorId = #facilitatorId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorName"> h.facilitatorName like concat("%", #facilitatorName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankInfo"> h.bankInfo = #bankInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankAccount"> h.bankAccount = #bankAccount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="officeCode"> h.officeCode = #officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="profitDepCode"> h.profitDepCode = #profitDepCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractNo"> h.subcontractNo = #subcontractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isAccrued"> h.isAccrued = #isAccrued# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isInvoiced"> isInvoiced = #isInvoiced# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractAmount"> subcontractAmount = #subcontractAmount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="reason"> h.reason = #reason# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remark"> h.remark = #remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveFrom"> h.effectiveFrom = #effectiveFrom# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveTo"> h.effectiveTo = #effectiveTo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="zrApproveTime"> h.zrApproveTime = #zrApproveTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createBy"> h.createBy = #createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createTime"> h.createTime = #createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateBy"> h.updateBy = #updateBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateTime"> h.updateTime = #updateTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="areaPower"> (FIND_IN_SET(h.officeCode, #areaPower#) or FIND_IN_SET(h.profitDepCode, #areaPower#))</isNotEmpty>
        <isNotEmpty prepend="AND" property="projectId"> FIND_IN_SET(#projectId#, h.projectIds) </isNotEmpty>
        <isEqual property="searchTimeType" compareValue="createTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproverTime">
            <isNotNull prepend="AND" property="searchStartTime"> zrTask.zrApproverTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ zrTask.zrApproverTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproveTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.zrApproveTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.zrApproveTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="paymentTime">
            <isNotNull prepend="AND" property="searchStartTime"> p.paymentTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ p.paymentTime <= #searchEndTime# ]]> </isNotNull>
            GROUP BY h.id
        </isEqual>
     order by h.id desc
;

