-- L0363 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/DailyReportMapper.xml:785 | selectBySelectivePageable | fnd_basic_data, pm_project_member, pm_project, t_user_info
select <!-- distinct -->
	    dr.*, bpt.`basicDataName` as projectTypeName, bt.`basicDataName` as typeName, bc.`basicDataName` as categoryName, bsc.`basicDataName` as subCategoryName 
	from
	    pm_daily_report AS `dr` 
	    left join pm_project ph 
	        on dr.projectId = ph.`projectId` 
	        and dr.`projectType` = ph.`projectType` 
    <if test="(model.userPower != null and '' != model.userPower) or (model.memberCode != null and '' != model.memberCode)">
    <![CDATA[
	    left join pm_project_member pm 
	        on ph.projectId = pm.projectId 
	        and pm.effectiveFrom <= now() 
	        and (
	            pm.effectiveTo > now() 
	            or pm.effectiveTo is null
	        ) 
	        and pm.`memberRole` in ("20", "30", "80") 
    ]]>
		<if test="model.userPower != null and '' != model.userPower">
			and pm.memberCode = #{model.userPower}
		</if>
		<if test="model.memberCode != null and '' != model.memberCode">
			and pm.memberCode = #{model.memberCode}
		</if>
    </if>
    <if test="model.userIdPower != null and '' != model.userIdPower">
	    left join t_user_info ui 
	        on (
	            dr.`officeCode` = ui.`custom3` 
	            or find_in_set(dr.`officeCode`, ui.`custom5`)
	        ) 
	        and find_in_set(dr.projectType, concat(IFNULL(ui.custom4, ""), ",30,40")) 
    	<if test="model != null and model.orgId != null">
			and ui.compID = #{model.orgId, jdbcType=INTEGER}
		</if>
        <if test="model.userIdPower != null and '' != model.userIdPower">
			AND ui.id = #{model.userIdPower}
		</if>
	</if>
	    left join `fnd_basic_data` bpt 
	        on bpt.`dataTypeCode` = 'af_dailyReportProjectType' 
	        and dr.`projectType` = bpt.`basicDataId` 
	    left join `fnd_basic_data` bt 
	        on bt.`dataTypeCode` = 'af_dailyReportType' 
	        and dr.`type` = bt.`basicDataId` 
	    left join `fnd_basic_data` bc 
	        on bc.`dataTypeCode` = 'af_dailyReportCategory' 
	        and dr.`category` = bc.`basicDataId` 
	    left join `fnd_basic_data` bsc 
	        on bsc.`dataTypeCode` = 'af_dailyReportSubCategory' 
	        and dr.`subCategory` = bsc.`basicDataId`
	<where>
		<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
			(
				(
				<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
					<if test="model.projectTypes != null">
						FIND_IN_SET(dr.`projectType`, CONCAT(#{model.projectTypes, jdbcType=VARCHAR}, ",30,40")) AND 
					</if>
					<if test="model.officeCodes != null">
						FIND_IN_SET(dr.`officeCode`, #{model.officeCodes}) AND
					</if>
					1 = 1
				</trim>
				)
				<if test="(model.userPower != null and '' != model.userPower) or (model.userIdPower != null and '' != model.userIdPower)">
					OR (
					<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
						<if test="model.userPower != null and '' != model.userPower">
								pm.memberCode = #{model.userPower} or 
								dr.customInfo -> "$.serviceManagerCode" = #{model.userPower} or 
						        dr.customInfo -> "$.programManagerCode" = #{model.userPower} or 
						        dr.createBy = #{model.userPower} or
						</if>
						<if test="model.userIdPower != null and '' != model.userIdPower">
						        ui.id = #{model.userIdPower} or 
						</if>
					</trim>
					)
				</if>
				<if test="(model.memberCode != null and '' != model.memberCode)">
					OR (
					<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
						<if test="model.memberCode != null and '' != model.memberCode">
								pm.memberCode = #{model.memberCode} or 
								dr.customInfo -> "$.serviceManagerCode" = #{model.memberCode} or 
						        dr.customInfo -> "$.programManagerCode" = #{model.memberCode} or 
						        dr.createBy = #{model.memberCode} or
						</if>
					</trim>
					)
				</if>
			) AND
			<include refid="sql_model_where_selective" />
			<include refid="sql_fuzzy_search" />
		</trim>
	</where>
	<include refid="sql_pageable_limit" />
;

