-- L0365 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/DailyReportMapper.xml:981 | checkPermission | pm_project_member, pm_project, t_user_info
select 
		    max(dr.createBy = #{user.userName}) as `all`, 
		    max(dr.createBy = #{user.userName}) as `edit`, 
		    count(pm.id) > 0 or count(ui.id) > 0
		    or dr.customInfo -> "$.serviceManagerCode" = #{user.userName}
	        or dr.customInfo -> "$.programManagerCode" = #{user.userName} as `view`, 
		    group_concat(distinct pm.memberRole) memberRoles, 
		    #{permissionTypes} as permissionTypes,
		    #{user.userInfoId} as userInfoId,
		    count(ui.id) > 0 hasPower,
		    <if test="model.projectId != null">
		    	IFNULL(ph.disabled, (select IF(disabled, 1, 0) as disabled from pm_project where projectId = #{model.projectId} limit 1)) as disabled
	    	</if>
	    	<if test="model.projectId == null or model.projectId == ''">
		    	false as disabled
	    	</if>
  	<![CDATA[
		from
		    `pm_daily_report` dr 
		    left join pm_project ph 
		        on dr.projectId = ph.`projectId` 
		        and dr.`projectType` = ph.`projectType` 
		    left join pm_project_member pm 
		        on ph.projectId = pm.projectId 
		        and pm.effectiveFrom <= now() 
		        and (
		            pm.effectiveTo > now() 
		            or pm.effectiveTo is null
		        ) 
		        and pm.`memberRole` in ("20", "30", "80") 
		        and pm.memberCode = #{user.userName}
  	]]>
		    left join t_user_info ui 
		        on ui.`id` = #{user.userInfoId}
		        <if test="model.officeCodes != null">
					AND FIND_IN_SET(dr.`officeCode`, #{model.officeCodes})
			        AND (
			            dr.`officeCode` = ui.`custom3` 
			            or find_in_set(dr.`officeCode`, ui.`custom5`)
			        ) 
				</if>
		        and find_in_set(
		            dr.projectType, concat(IFNULL(ui.custom4, ""), ",30,40")
		        ) 
		        <if test="model != null and model.orgId != null">
					and ui.compID = #{model.orgId, jdbcType=INTEGER}
				</if>
	<where>
		<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
			<if test="model.id != null">
				dr.`id` = #{model.id, jdbcType=INTEGER} AND
			</if>
			<if test="model.projectId != null">
				dr.`projectId` = #{model.projectId, jdbcType=INTEGER} AND
			</if>
			(
				(
