				    )
				</if>
			) AND
<!-- 			<if test="model.projectCode != null and '' != model.projectCode">
				dr.`projectCode` like concat("%", #{model.projectCode, jdbcType=VARCHAR}, "%") AND
			</if>
			<if test="model.projectName != null and '' != model.projectName">
