        <if test="updateBy != null"> and h.updateBy = #{updateBy} </if>
        <if test="updateTime != null"> and h.updateTime = #{updateTime} </if>
        <if test="areaPower != null"> and (FIND_IN_SET(h.officeCode, #{areaPower}) or FIND_IN_SET(h.profitDepCode, #{areaPower}))</if>
        <if test="projectId != null"> and FIND_IN_SET(#{projectId}, h.projectIds) </if>
		<if test="pageParam != null">
			<if test="pageParam.fuzzySearch == true and pageParam.fuzzy != ''">
				and (
