	        and ph.`projectId` = alr.`projectId`
	        and alr.`disabled` = false 
	        and apr.`disabled` = false 
	        and IFNULL(apr.`effectiveTo`, "9999-12-31") > now() 
	    left join `fnd_basic_data` bd 
	        on l.`status` = bd.`basicDataId` 
	        and bd.`dataTypeCode` = 'processStatus'
	    left join `fnd_basic_data` bd2 
