-- L0381 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/IndustryLeakMapper.xml:457 | selectBySelectivePageable | fnd_basic_data, pm_project_member, pm_project
select 
    	JSON_SET(IFNULL(l.`customInfo`, "{}"), '$.statusName', bd.basicDataName, '$.trackStatusName', bd2.basicDataName ) as customInfo,
	    l.*<!-- , 
	    bd.basicDataName as `customInfo.statusName`, bd2.basicDataName as `customInfo.trackStatusName`  -->
	from af_industry_leak as l
	<if test="model != null and model.checkProject == true">
    left join `af_industry_asset_leak_relation` lpr 
        on lpr.leakId = l.id 
        and lpr.`disabled` = false 
        and l.`disabled` = false 
        and IFNULL(lpr.`effectiveTo`, "9999-12-31") > now() 
    left join `pm_project` ph 
        on ph.`projectId` = lpr.`projectId` 
    </if>
    left join `fnd_basic_data` bd 
        on l.`status` = bd.`basicDataId` 
        and bd.`dataTypeCode` = 'processStatus'
    left join `fnd_basic_data` bd2 
        on l.`trackStatus` = bd2.`basicDataId` 
        and bd2.`dataTypeCode` = 'trackStatus' 
	<where>
		<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
			<if test="model != null and model.checkProject == true">
				(
					(
					<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
						1 = 1 AND
						<if test="model.projectTypes != null">
							FIND_IN_SET(ph.`projectType`, #{model.projectTypes}) AND 
						</if>
						<if test="model.officeCodes != null">
							FIND_IN_SET(ph.`column001`, #{model.officeCodes}) AND
						</if>
					</trim>
					)
					<if test="model.memberCode != null and model.memberCode != ''">
						<!-- OR pm.memberCode like concat("%", #{model.memberCode}, "%") -->
						OR EXISTS 
				        (SELECT 
				            1 
				        FROM
				            pm_project_member pm 
				        WHERE pm.projectId = ph.`projectId` 
				            AND pm.projectType = ph.`projectType` 
				            AND IFNULL(pm.effectiveTo, "9999-12-31") > NOW()
				            AND pm.memberCode = #{model.memberCode})
					</if>
				) AND
			</if>
			<include refid="sql_model_where_selective" />
		</trim>
	</where>
	<if test="model != null and model.checkProject == true">
		group by l.id
	</if>
	<include refid="sql_pageable_limit" />
;

