-- L0394 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:789 | selectBySelectivePageable | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_member, pm_project, sms_ofst_contract_head_sap
SELECT 
    	ph.*, bd.`basicDataName` as projectStateName, bd2.`basicDataName` as projectTypeName, c.compAbbr, c.compName
    	<if test="model != null and model.matchCollectMoney == true">
    	, GROUP_CONCAT(distinct och.contract_num) AS collectContractNos, SUM(och.contract_money_amount) AS contractAmount,
    	SUM(och.collected_money_amount) AS collectedAmount, SUM(och.delivered_money_amount) AS deliveredAmount,
    	<!-- ROUND(SUM(och.collected_money_amount) / SUM(och.delivered_money_amount), 2) AS collectedRatio  -->
    	ROUND(SUM(och.collected_money_amount) / SUM(och.contract_money_amount), 2) AS collectedRatio
    	</if>
    FROM pm_project AS ph
    <if test="model != null and model.matchCollectMoney == true">
    LEFT JOIN `pm_project_group_relationship` pgr 
        ON pgr.projectCode = ph.projectCode 
    LEFT JOIN `pm_project_contract` pc 
        ON pc.projectGroupCode = pgr.projectGroupCode 
    LEFT JOIN `sms_ofst_contract_head_sap` och 
        ON och.contract_num = pc.contractNo 
    </if>
    LEFT JOIN fnd_basic_data bd 
        ON bd.`dataTypeCode` = concat(ph.`projectType`, "_projectState") 
        AND bd.`basicDataId` = ph.`projectState` 
    LEFT JOIN fnd_basic_data bd2 
        ON bd2.`dataTypeCode` = "projectTypes"
        AND bd2.`basicDataId` = ph.projectType
    LEFT JOIN `t_company` c
		ON c.id = ph.`compId`
    <!-- <if test="model != null and model.memberCode != null and model.memberCode != ''">
    <![CDATA[
    LEFT JOIN pm_project_member pm 
        ON pm.projectId = ph.`projectId` 
        AND pm.projectType = ph.`projectType` 
        AND NOW() < IFNULL(pm.effectiveTo, "9999-12-31" )
    ]]>
    </if> -->
	<where>
		<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
			<if test="model != null ">
			(
				(
				<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
					1 = 1 AND
					<if test="model.projectTypes != null">
						FIND_IN_SET(ph.`projectType`, #{model.projectTypes}) AND 
					</if>
					<if test="model.officeCodes != null">
						FIND_IN_SET(ph.`column001`, #{model.officeCodes}) AND
					</if>
				</trim>
				)
				<if test="model.memberCode != null and model.memberCode != ''">
					<!-- or pm.memberCode like concat("%", #{model.memberCode}, "%") -->
					OR EXISTS 
			        (SELECT 
			            1 
			        FROM
			            pm_project_member pm 
			        WHERE pm.projectId = ph.`projectId` 
			            AND pm.projectType = ph.`projectType` 
			            AND IFNULL(pm.effectiveTo, "9999-12-31") > NOW()
			            AND pm.memberCode = #{model.memberCode})
				</if>
			) AND
			</if>
			<if test="model.projectIds != null and model.projectIds != ''">
				FIND_IN_SET(ph.`projectId`, #{model.projectIds}) AND 
			</if>
			<include refid="sql_model_where_selective" />
			<include refid="sql_fuzzy_search" />
		</trim>
	</where>
	<if test="model != null and model.matchCollectMoney == true">
	GROUP BY ph.projectId
	</if>
	<include refid="sql_pageable_limit" />
;

-- L0395 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:864 | countBySelectivePageable | pm_project_member, pm_project
