-- L0400 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1263 | queryProjectByContractNoAndType | fnd_basic_data, pm_project_member, fnd_department, pm_project
select podfs.id as podfsId, t1.basicDataName as column012, pppfs.projectType, pppfs.objId as relateId, pppfs.channelName as agentChannel,
            <!-- ifnull(podfs.contractNo, pppfs.orderExecNumber) as contractNo,  -->
            ifnull(podfs.contractNo, pppfs.projectCode) as contractNo, 
            case when pppfs.projectCode is null then podfs.contractNo else pppfs.projectCode end as projectCode, 
            ifnull(if(podfs.salesType = '01' and #{projectType} = '10', podfs.projectName, pppfs.projectName), podfs.projectName) as projectName,
            podfs.orderCreateTime column009, podfs.customerCode column002, podfs.customerName column003, pppfs.salesManCode salesManCode, 
            concat(pppfs.salesManCode, "-", pppfs.salesManName) salesManName, pppfs.marketCode marketCode, pppfs.marketName column004, pppfs.systemId systemId, pppfs.systemName column005, 
            pppfs.expendId expendId, pppfs.expendName column006, pppfs.industryId, pppfs.industryName column007, pppfs.officeCode column001, 
            fd.departmentName officeName, 
<!--             ppm.memberCode serviceManagerCode, ppm.memberName serviceManagerCodeforjson,  -->
            pph.column008 column008, pph.column010 column010, pph.column011 column011,
            pph.column012 column012, IFNULL(t1.basicDataName, -1) as column012Readonly, pph.column013 column013, ifnull(podfs.compCode, pppfs.corporationCode) as compCode, ifnull(c.id, c1.id) as compId, 
            ifnull(podfs.salesType, pppfs.projectType) as salesType, pppfs.projectMoney as smsProjectAmount, pppfs.afProjectMoney as smsAfProjectAmount, pppfs.projectCode as smsProjectCode, 
            pppfs.submitTime as smsSubmitTime, pppfs.orderExecNumber as smsOrderExecNumber, pppfs.predBidDate as smsPredBidDate
  			<if test="projectType == 'afxx'">
<!-- 			    ,pppfs.receiveMen as customerPerson, pppfs.reveiveContactWay as customerTel, pppfs.receiveAddress as customerAddress,
			    pppfs.lendCause as afxxReason, pppfs.requireInDate,
			    pppfs.pspm, pppfs.pspmName, pppfs.salesMenTel, pppfs.decPath
 -->			   
 				,concat(
				'{',
				    concat('"customerPerson":"', ifnull(pppfs.receiveMen, ""), '"'), 
				    concat(',"customerTel":"', ifnull(pppfs.reveiveContactWay,""), '"'), 
				    concat(',"customerAddress":"', ifnull(pppfs.receiveAddress,""), '"'),
				    concat(',"afxxReason":"', ifnull( pppfs.lendCause, ""), '"'), 
				    concat(',"requireInDate":"', ifnull(pppfs.requireInDate, ""), '"'), 
				    concat(',"pspm":"', ifnull( pppfs.pspm, ""), '"'), 
				    concat(',"pspmName":"', ifnull( pppfs.pspmName, ""), '"'), 
				    concat(',"salesMenTel":"', ifnull( pppfs.salesMenTel, ""), '"'), 
				    concat(',"decPath":"', ifnull( pppfs.decPath, ""), '"')
				, '}') as customInfo
  			</if>
        from pm_project_property_af_from_sms pppfs 
            left join pm_order_data_from_sap podfs on podfs.orderExecNumber = pppfs.orderExecNumber 
            left join pm_project pph on podfs.contractNo = pph.projectCode and pppfs.projectType = pph.projectType
            left join fnd_department fd on fd.departmentNum = pppfs.officeCode
<!--             left join pm_project_member ppm on pph.projectId = ppm.projectId -->
<!--                  and ppm.effectiveFrom <= now() and (ppm.effectiveTo > now() or ppm.effectiveTo is null) -->
  	<![CDATA[
            left join fnd_basic_data t1 on pppfs.serviceTypeName = t1.basicDataId and t1.dataTypeCode = 21
                 and t1.effectiveFrom <= now() and ( t1.effectiveTo > now() or t1.effectiveTo is null )
            left join fnd_company c on c.code = podfs.compCode
            left join fnd_company c1 on c1.code = pppfs.corporationCode
  	]]>
    where pppfs.projectType = #{projectType}
    <choose>
    	<when test="projectType == 'afxx'">
			and pppfs.projectCode = #{contractNo}
			<!-- and pppfs.orderExecNumber = #{contractNo} -->
    	</when>
    	<otherwise> and podfs.contractNo = #{contractNo} </otherwise>
    </choose>
    <!-- order by podfs.id desc limit 1 -->
    <!-- 补充订单申报但是没有合同签订的项目信息 -->
    union all
    select podfs.id as podfsId, t1.basicDataName as column012, pppfs.projectType, pppfs.objId as relateId, pppfs.channelName as agentChannel,
            <!-- ifnull(podfs.contractNo, pppfs.orderExecNumber) as contractNo,  -->
            ifnull(podfs.contractNo, pppfs.projectCode) as contractNo, 
            case when pppfs.projectCode is null then podfs.contractNo else pppfs.projectCode end as projectCode, 
            ifnull(if(podfs.salesType = '01' and #{projectType} = '10', podfs.projectName, pppfs.projectName), podfs.projectName) as projectName,
            podfs.orderCreateTime column009, podfs.customerCode column002, podfs.customerName column003, pppfs.salesManCode salesManCode, 
            concat(pppfs.salesManCode, "-", pppfs.salesManName) salesManName, pppfs.marketCode marketCode, pppfs.marketName column004, pppfs.systemId systemId, pppfs.systemName column005, 
            pppfs.expendId expendId, pppfs.expendName column006, pppfs.industryId, pppfs.industryName column007, pppfs.officeCode column001, 
            fd.departmentName officeName, 
<!--             ppm.memberCode serviceManagerCode, ppm.memberName serviceManagerCodeforjson,  -->
            pph.column008 column008, pph.column010 column010, pph.column011 column011,
            pph.column012 column012, IFNULL(t1.basicDataName, -1) as column012Readonly, pph.column013 column013, ifnull(podfs.compCode, pppfs.corporationCode) as compCode, ifnull(c.id, c1.id) as compId, 
            ifnull(podfs.salesType, pppfs.projectType) as salesType, pppfs.projectMoney as smsProjectAmount, pppfs.afProjectMoney as smsAfProjectAmount, pppfs.projectCode as smsProjectCode, 
            pppfs.submitTime as smsSubmitTime, pppfs.orderExecNumber as smsOrderExecNumber, pppfs.predBidDate as smsPredBidDate
  			<if test="projectType == 'afxx'">
<!-- 			    ,pppfs.receiveMen as customerPerson, pppfs.reveiveContactWay as customerTel, pppfs.receiveAddress as customerAddress,
			    pppfs.lendCause as afxxReason, pppfs.requireInDate,
			    pppfs.pspm, pppfs.pspmName, pppfs.salesMenTel, pppfs.decPath
 -->			   
 				,concat(
				'{',
				    concat('"customerPerson":"', ifnull(pppfs.receiveMen, ""), '"'), 
				    concat(',"customerTel":"', ifnull(pppfs.reveiveContactWay,""), '"'), 
				    concat(',"customerAddress":"', ifnull(pppfs.receiveAddress,""), '"'),
				    concat(',"afxxReason":"', ifnull( pppfs.lendCause, ""), '"'), 
				    concat(',"requireInDate":"', ifnull(pppfs.requireInDate, ""), '"'), 
				    concat(',"pspm":"', ifnull( pppfs.pspm, ""), '"'), 
				    concat(',"pspmName":"', ifnull( pppfs.pspmName, ""), '"'), 
				    concat(',"salesMenTel":"', ifnull( pppfs.salesMenTel, ""), '"'), 
				    concat(',"decPath":"', ifnull( pppfs.decPath, ""), '"')
				, '}') as customInfo
  			</if>
        from pm_project_property_af_from_sms pppfs 
            left join pm_order_data_from_sap podfs on podfs.orderExecNumber = pppfs.orderExecNumber 
            left join pm_project pph on podfs.contractNo = pph.projectCode and pppfs.projectType = pph.projectType
            left join fnd_department fd on fd.departmentNum = pppfs.officeCode
<!--             left join pm_project_member ppm on pph.projectId = ppm.projectId -->
<!--                  and ppm.effectiveFrom <= now() and (ppm.effectiveTo > now() or ppm.effectiveTo is null) -->
  	<![CDATA[
            left join fnd_basic_data t1 on pppfs.serviceTypeName = t1.basicDataId and t1.dataTypeCode = 21
                 and t1.effectiveFrom <= now() and ( t1.effectiveTo > now() or t1.effectiveTo is null )
            left join fnd_company c on c.code = podfs.compCode
            left join fnd_company c1 on c1.code = pppfs.corporationCode
  	]]>
    where pppfs.projectType = #{projectType}
		and pppfs.projectCode = #{contractNo}
		<!-- and pppfs.orderExecNumber = #{contractNo} -->
    order by podfsId desc, relateId desc
    limit 1
;

-- L0401 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1447 | checkPermission | pm_project_member, pm_project, t_user_info
<![CDATA[
	  	select 
		    count(IF(pm.`memberRole` in (20,30,40), pm.id, null)) > 0 
		    	and count(ui.id) > 0 as `all`, 
		    count(IF(pm.`memberRole` in (20,30,40), pm.id, null)) > 0 as edit, 
		    count(IFNULL(pm.id, ui.id)) > 0 view,
		    group_concat(distinct ph.projectType) as projectTypes,
		    max(ph.projectState) as maxState,
		    group_concat(distinct pm.memberRole) memberRoles, 
		    #{permissionTypes} as permissionTypes,
		    #{user.userInfoId} as userInfoId,
		    count(ui.id) > 0 hasPower,
		    ph.disabled as disabled
		from
		    pm_project ph 
		    left join pm_project_member pm 
		        on ph.projectId = pm.projectId 
		        and pm.effectiveFrom <= now() 
		        and (
		            pm.effectiveTo > now() 
		            or pm.effectiveTo is null
		        ) 
		        and pm.memberCode = #{user.userName}
	]]>
		    left join t_user_info ui 
		        on ui.`id` = #{user.userInfoId}
		        <if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
			        and find_in_set(ph.`column001`, ui.`custom5`) 
				</if>
		        and find_in_set(ph.projectType, ui.custom4)
		<!-- where (
		        pm.memberCode = #{user.userName}
		        or ui.id = #{user.userInfoId}
		    ) -->
	<where>
		<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
			<if test="model != null">
				<if test="model.projectId != null">
					AND ph.projectId = #{model.projectId}
				</if>
				<if test="model.projectIds != null">
					AND FIND_IN_SET(ph.projectId, #{model.projectIds})
				</if>
				AND (
					(
					<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
						1 = 1
						<if test="model.projectTypes != null">
							AND FIND_IN_SET(ph.`projectType`, #{model.projectTypes})
						</if>
						<if test="model.officeCodes != null">
							AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
						</if>
					</trim>
					)
					<if test="model.memberCode != null and model.memberCode != ''">
						OR pm.memberCode like concat("%", #{model.memberCode}, "%")
					</if>
				) 
				<!-- <if test="model.projectTypes != null">
					AND FIND_IN_SET(ph.`projectType`, #{model.projectTypes})
				</if>
				<if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
				</if> -->
			</if>
		</trim>
	</where>
;

-- L0402 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1519 | selectPermissionByMemberRole | fnd_basic_data, t_role
select 
	    p.`permission_name` 
	from
	    `t_permission` p 
	    left join `t_role_permission` rp 
	        on rp.permission_id = p.permission_id 
	    left join `t_role` r
	        on rp.role_id = r.role_id 
	    left join `fnd_basic_data` db 
	        on db.dataTypeCode = 'afProjectMember' 
        <if test="memberRoles != null and memberRoles != ''">
	        and find_in_set(db.basicDataId, #{memberRoles}) 
        </if>
        <if test="memberRoles == null or memberRoles == ''">
        	and p.permission_name regexp ":detail|:list"
        </if>
	        and r.role_name = db.basicDataAttri1 
	where r.role_name = db.basicDataAttri1
	<if test="permissionTypes != null">
	    and p.permission_name regexp #{permissionTypes}
	</if>
;

-- L0403 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1544 | selectRoleByMemberRole | fnd_basic_data, t_role, t_user_info, t_user_role
select 
	    r.`role_name` 
	from
	    t_user_info ui 
	    inner join t_user_role ur 
	        on ui.`user_id` = ur.`user_id` 
	        and ur.`comp_id` = ui.`compID` 
	    inner join `t_role` r 
	        on ur.`role_id` = r.`role_id` 
	    left join `fnd_basic_data` db 
	        on db.dataTypeCode = 'afProjectMember' 
        <if test="memberRoles != null and memberRoles != ''">
	        and find_in_set(db.basicDataId, #{memberRoles}) 
        </if>
	        and r.role_name = db.basicDataAttri1 
	where ui.id = #{userInfoId}
		and (
	        r.role_name = db.basicDataAttri1 
	        or r.`role_name` in ("admin", "projectAdmin") 
			<if test="hasPower == true">
		        or r.`role_name` in ("projectSubAdmin", "projectAreaManager")
			</if>
	    )
;

-- L0404 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1587 | selectAllProjectRelateInfos | pm_project
select 
	    *, concat(
	        "insert into ", tableName, "(", columns, ") select ", replace(
	            replace(
	                replace(
	                    replace(
	                        columns, "projectId", "'?' as projectId"
	                    ), "projectType", "'?' as projectType"
	                ), "objId", "'?' as objId"
	            ), "objType", "'?' as objType"
	        ), " from ", tableName, " where ", replace(queryColumns, ",", "='?' AND "), "='?' "
	    ) as `insertSql`, IF(
	        queryColumns = "projectIds", concat(
	            "update ", tableName, " set projectIds = concat(projectIds, ',?') where FIND_IN_SET('?', ", queryColumns, ")"
	        ), null
	    ) as `updateSql` 
	from
	    (select 
	        t.`TABLE_NAME` as tableName, group_concat(distinct pc.column_name order by pc.`ORDINAL_POSITION`) primaryKeys, group_concat(
	            distinct c.column_name 
	            order by c.`ORDINAL_POSITION`
	        ) queryColumns, group_concat(
	            distinct ac.column_name 
	            order by ac.`ORDINAL_POSITION`
	        ) columns 
	    from
	        information_schema.tables t 
	        left join information_schema.columns ac 
	            on t.`TABLE_CATALOG` = ac.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = ac.`TABLE_NAME` 
	            and ac.`COLUMN_KEY` != "PRI" 
	        left join information_schema.columns c 
	            on t.`TABLE_CATALOG` = c.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = c.`TABLE_NAME` 
	            and c.COLUMN_NAME in ('projectId', 'projectType', 'projectIds', 'objType', 'objId') 
	        left join information_schema.columns pc 
	            on t.`TABLE_CATALOG` = pc.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = pc.`TABLE_NAME` 
	            and pc.`COLUMN_KEY` = "PRI" 
	    where t.TABLE_SCHEMA = #{schema}
	        and c.TABLE_SCHEMA = #{schema}
	        and pc.TABLE_SCHEMA = #{schema}
	        and ac.TABLE_SCHEMA = #{schema}
	        and t.TABLE_TYPE = 'BASE TABLE' 
	    group by tableName) t 
	where queryColumns in (
	       "projectId", "projectIds", "projectId,projectType", "objType,objId"
	    ) 
	    and tableName not in ('pm_project')
;

-- L0405 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1640 | selectAllProjectRelateInfosPrepare | pm_project
select 
	    *, concat(
	        "insert into ", tableName, "(", columns, ") select ", replace(
	            replace(
	                replace(
	                    replace(
	                        replace(
	                            replace(
	                                replace(
	                                    replace(
	                                        columnsWithAlias, concat(tableAlias, ".projectId,"), "'?' as projectId,"
	                                    ), concat(tableAlias, ".projectType,"), "'?' as projectType,"
	                                ), concat(tableAlias, ".objId,"), "'?' as objId,"
	                            ), concat(tableAlias, ".objType,"), "'?' as objType,"
	                        ), concat(tableAlias, ".projectCode,"), concat("IFNULL(nph.projectCode, ", tableAlias, ".projectCode) projectCode,")
	                    ), concat(tableAlias, ".projectName,"), concat("IFNULL(nph.projectName, ", tableAlias, ".projectName) projectName,")
	                ), concat(tableAlias, ".contractNo,"), concat("IFNULL(nph.customInfo ->> '$.contractNo', ", tableAlias, ".contractNo) contractNo,")
	            ), concat(tableAlias, ".officeCode,"), concat("IFNULL(nph.column001, ", tableAlias, ".officeCode) officeCode,")
	        ), " from ", tableName, " as ", tableAlias, 
	        " left join pm_project nph on nph.projectId = '?' and nph.projectType = '?' ", 
	        " where ", replace(queryColumnsWithAlias, ",", "='?' AND "), "='?' "
	    ) as `insertSql`, IF(
	        queryColumns = "projectIds", concat(
	            "update ", tableName, " as ", tableAlias, " set ", tableAlias, ".projectIds = concat(projectIds, ',?') where FIND_IN_SET('?', ", queryColumnsWithAlias, ")"
	        ), null
	    ) as `updateSql`, 
	    IF(hasCustomInfo <!-- or hasEffectiveTo or hasDisabled or hasDeleted -->, 
			concat(
			    "update ", tableName, " as ", tableAlias, 
			    " set ", 
				concat_ws(",",
					IF(hasCustomInfo, concat(tableAlias, ".customInfo = JSON_MERGE_PATCH(IFNULL(", tableAlias, ".customInfo, '{}'), '{\"transferProjectId\": ?, \"transferProjectFlag\": 1}')"), null)
					<!-- ,IF(hasEffectiveTo, concat(tableAlias, ".effectiveTo = now()"), null)
					,IF(hasDisabled, concat(tableAlias, ".disabled = true"), null)
					,IF(hasDeleted, concat(tableAlias, ".deleted = true"), null) -->
				),
			    " where ", 
			    replace(
					queryColumnsWithAlias, ",", "='?' AND "
				), "='?' "
			), null
	    ) as transferFlagSql
	from
	    (select 
	        t.`TABLE_NAME` as tableName, t.tableAlias, 
	        group_concat(distinct pc.column_name order by pc.`ORDINAL_POSITION`) primaryKeys, 
        	group_concat(distinct c.column_name order by c.`column_name`) queryColumns,
			concat(group_concat(distinct c.column_name order by c.`column_name`), ",", group_concat(distinct ac.column_name order by ac.`ORDINAL_POSITION`)) columns, 
			concat(group_concat(distinct concat(t.tableAlias, ".", c.column_name) order by c.`column_name`), ",", group_concat(distinct concat(t.tableAlias, ".", ac.column_name) order by ac.`ORDINAL_POSITION`)) columnsWithAlias, 
			group_concat(distinct concat(t.tableAlias, ".", c.column_name) order by c.`column_name`) queryColumnsWithAlias,
			max(ac.`COLUMN_NAME` = 'customInfo') as hasCustomInfo,
			max(ac.`COLUMN_NAME` = 'effectiveTo') as hasEffectiveTo,
	        max(ac.`COLUMN_NAME` = 'disabled') as hasDisabled,
	        max(ac.`COLUMN_NAME` = 'deleted') as hasDeleted
	    from
        <![CDATA[
	        (select 
	            t.*, GROUP_CONCAT(
	                SUBSTRING(
	                    SUBSTRING_INDEX(
	                        SUBSTRING_INDEX(t.TABLE_NAME, '_', sh.id + 1), '_', - 1
	                    ), 1, 1
	                ) separator ""
	            ) as tableAlias 
	        from
	            information_schema.tables t 
	            left join find_in_set_help sh 
	                on sh.id < (LENGTH(t.TABLE_NAME) - LENGTH(REPLACE(t.TABLE_NAME, '_', '')) + 1) 
	        where t.TABLE_SCHEMA = database() 
	            and t.TABLE_TYPE = 'BASE TABLE' 
	        group by t.TABLE_NAME) t 
        ]]>
	        left join information_schema.columns ac 
	            on t.`TABLE_CATALOG` = ac.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = ac.`TABLE_NAME` 
	            and ac.`COLUMN_KEY` != "PRI" 
	            and ac.COLUMN_NAME not in (
	                'projectId', 'projectType', 'projectIds', 'objType', 'objId'
	            ) 
	        left join information_schema.columns c 
	            on t.`TABLE_CATALOG` = c.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = c.`TABLE_NAME` 
	            and c.COLUMN_NAME in (
	                'projectId', 'projectType', 'projectIds', 'objType', 'objId'
	            ) 
	        left join information_schema.columns pc 
	            on t.`TABLE_CATALOG` = pc.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = pc.`TABLE_NAME` 
	            and pc.`COLUMN_KEY` = "PRI" 
	    where t.TABLE_SCHEMA = database() 
	        and c.TABLE_SCHEMA = database() 
	        and pc.TABLE_SCHEMA = database() 
	        and ac.TABLE_SCHEMA = database() 
	        and t.TABLE_TYPE = 'BASE TABLE' 
	    group by tableName) t 
	where queryColumns in (
	        "projectId", "projectIds", "projectId,projectType", "objId,objType"
	    ) 
	    and tableName not in ('pm_project')
;

-- L0406 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1743 | selectAllProjectRelateInfosBak | pm_project
select 
	    *, concat(
	        "insert into ", tableName, "(", columns, ") select * from ( select ", replace(
	            replace(
	                replace(
	                    replace(
	                        replace(
	                            replace(
	                                replace(
	                                    replace(
	                                        columnsWithAlias, concat(tableAlias, ".projectId,"), "'$projectId$' as projectId,"
	                                    ), concat(tableAlias, ".projectType,"), "'$projectType$' as projectType,"
	                                ), concat(tableAlias, ".objId,"), "'$objId$' as objId,"
	                            ), concat(tableAlias, ".objType,"), "'$objType$' as objType,"
	                        ), concat(tableAlias, ".projectCode,"), concat("IFNULL(nph.projectCode, ", tableAlias, ".projectCode) projectCode,")
	                    ), concat(tableAlias, ".projectName,"), concat("IFNULL(nph.projectName, ", tableAlias, ".projectName) projectName,")
	                ), concat(tableAlias, ".contractNo,"), concat("IFNULL(nph.customInfo ->> '$.contractNo', ", tableAlias, ".contractNo) contractNo,")
	            ), concat(tableAlias, ".officeCode,"), concat("IFNULL(nph.column001, ", tableAlias, ".officeCode) officeCode,")
	        ), " from ", tableName, " as ", tableAlias, 
	        " left join pm_project nph on nph.projectId = '$projectId$' and nph.projectType = '$projectType$' ", 
	        " where ", whereColumns
			, " ) ", tableAlias
	    ) as `insertSql`, IF(
	        queryColumns = "projectIds", concat(
	            "update ", tableName, " as ", tableAlias, " set ", tableAlias, ".projectIds = concat(projectIds, ',$projectId$') where FIND_IN_SET('$oldProjectId$', ", queryColumnsWithAlias, ")"
	        ), null
	    ) as `updateSql`, 
	    IF(hasCustomInfo <!-- or hasEffectiveTo or hasDisabled or hasDeleted  -->
			, concat(
			    "update ", tableName, " as ", tableAlias, 
			    " set ", 
				concat_ws(",",
					IF(hasCustomInfo, concat(tableAlias, ".customInfo = JSON_MERGE_PATCH(IFNULL(", tableAlias, ".customInfo, '{}'), '{\"transferProjectId\": $projectId$, \"transferProjectFlag\": 1}')"), null)
					<!-- ,IF(hasEffectiveTo, concat(tableAlias, ".effectiveTo = now()"), null)
 					,IF(hasDisabled, concat(tableAlias, ".disabled = true"), null)
 					,IF(hasDeleted, concat(tableAlias, ".deleted = true"), null) -->
				),
			    " where ", whereColumns
			), null
	    ) as transferFlagSql
<![CDATA[
		, concat(
            "MD5(concat_ws('&', IFNULL(", REPLACE(
                replace(
                    replace(columnsWithAlias, concat(tableAlias, ".projectId,"), ''), concat(tableAlias, ".projectType,"), ''
                ), ",", ",'NULL'),IFNULL("
            ), ",'NULL')", ")", ")"
        ) md5Sql 
]]>
	from
	(select *, 
		replace(
            replace(
                replace(
                    replace(
                        replace(
                            replace(
                                replace(
                                    replace(
                                        columnsWithAlias, concat(tableAlias, ".projectId,"), "'$projectId$' as projectId,"
                                    ), concat(tableAlias, ".projectType,"), "'$projectType$' as projectType,"
                                ), concat(tableAlias, ".objId,"), "'$objId$' as objId,"
                            ), concat(tableAlias, ".objType,"), "'$objType$' as objType,"
                        ), concat(tableAlias, ".projectCode,"), concat("IFNULL(nph.projectCode, ", tableAlias, ".projectCode) projectCode,")
                    ), concat(tableAlias, ".projectName,"), concat("IFNULL(nph.projectName, ", tableAlias, ".projectName) projectName,")
                ), concat(tableAlias, ".contractNo,"), concat("IFNULL(nph.customInfo ->> '$.contractNo', ", tableAlias, ".contractNo) contractNo,")
            ), concat(tableAlias, ".officeCode,"), concat("IFNULL(nph.column001, ", tableAlias, ".officeCode) officeCode,")
        ) as selectColumns, 
        replace(
		    replace(
				replace(
				    replace(
						replace(
						    replace(
								concat(queryColumnsWithAlias, ",$"), "projectId,", "projectId='$oldProjectId$' AND "
						    ), "projectType,", "projectType='$oldProjectType$' AND "
						), "objId,", "objId='$oldObjId$' AND "
				    ), "objType,", "objType='$oldObjType$' AND "
				), "projectIds,", "projectIds='$oldProjectId$' AND "
		    ), " AND $", ""
		) as whereColumns 
	from 
	    (select 
	        t.`TABLE_NAME` as tableName, t.tableAlias, 
	        group_concat(distinct pc.column_name order by pc.`ORDINAL_POSITION`) primaryKeys, 
        	group_concat(distinct c.column_name order by c.`column_name`) queryColumns,
			concat(group_concat(distinct c.column_name order by c.`column_name`), ",", group_concat(distinct ac.column_name order by ac.`ORDINAL_POSITION`)) columns, 
			concat(group_concat(distinct concat(t.tableAlias, ".", c.column_name) order by c.`column_name`), ",", group_concat(distinct concat(t.tableAlias, ".", ac.column_name) order by ac.`ORDINAL_POSITION`)) columnsWithAlias, 
			group_concat(distinct concat(t.tableAlias, ".", c.column_name) order by c.`column_name`) queryColumnsWithAlias,
			max(ac.`COLUMN_NAME` = 'customInfo') as hasCustomInfo,
			max(ac.`COLUMN_NAME` = 'effectiveTo') as hasEffectiveTo,
	        max(ac.`COLUMN_NAME` = 'disabled') as hasDisabled,
	        max(ac.`COLUMN_NAME` = 'deleted') as hasDeleted
	    from
	        (select 
	            t.*, GROUP_CONCAT(
	                SUBSTRING(
	                    SUBSTRING_INDEX(
	                        SUBSTRING_INDEX(t.TABLE_NAME, '_', sh.id + 1), '_', - 1
	                    ), 1, 1
	                ) separator ""
	            ) as tableAlias 
	        from
	            information_schema.tables t 
	            left join find_in_set_help sh 
<![CDATA[    		on sh.id < (LENGTH(t.TABLE_NAME) - LENGTH(REPLACE(t.TABLE_NAME, '_', '')) + 1) ]]>
	        where t.TABLE_SCHEMA = database() 
	            and t.TABLE_TYPE = 'BASE TABLE' 
	        group by t.TABLE_NAME) t 
	        left join information_schema.columns ac 
	            on t.`TABLE_CATALOG` = ac.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = ac.`TABLE_NAME` 
	            and ac.`COLUMN_KEY` != "PRI" 
	            and ac.COLUMN_NAME not in (
	                'projectId', 'projectType', 'projectIds', 'objType', 'objId'
	            ) 
	        left join information_schema.columns c 
