-- L0427 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectTaskMapper.xml:626 | selectProjectDeliverBySelective | fnd_basic_data, pm_project_task, t_user, t_user_info
SELECT 
		    pbdd.id, pbdd.taskId, pbdd.`projectId`, pbdd.`projectType`, pbdd.`deliverableName`, pbdd.`deliverId`, pbdd.`deliverablePath`, fbd.`basicDataName` as deliverableType, IFNULL(
		        concat(pbdd.uploadUser, "-", ui.realName), pbdd.uploadUser
		    ) as uploadUser, pbdd.uploadTime, pt.taskName, pt.customInfo as taskCustomInfo
		FROM
		    `pm_basic_deliver_detail` pbdd 
		    inner JOIN `pm_basic_prj_deliver` pbpd 
		        ON pbpd.id = pbdd.`deliverId` 
		    LEFT JOIN fnd_basic_data fbd 
		        ON fbd.`dataTypeCode` = pbpd.`dataTypeCodeSon` 
		        AND fbd.`basicDataId` = pbpd.`basicDataIdSon` 
		    left join pm_project_task pt 
		        on pt.`taskId` = pbdd.`taskId` 
		    LEFT JOIN t_user u 
		        ON u.`user_name` = pbdd.`uploadUser` 
		    LEFT JOIN t_user_info ui 
		        ON ui.`user_id` = u.`user_id` 
		        <if test="orgId != null">
			        and ui.`compID` = #{orgId}
				</if>
       <where>
			<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
       			<if test="projectId != null"> AND pbdd.projectId = #{projectId} </if>
       			<if test="projectType != null"> AND pbdd.projectType = #{projectType} </if>
		        <if test="taskId != null"> AND pbdd.taskId = #{taskId} </if>
				<if test="ids != null ">
					<foreach collection="ids" item="item" open="and pbdd.id in (" close=")" separator=",">#{item}</foreach>
				</if>
		      	<![CDATA[
		          	AND pbdd.`effectiveFrom` <= NOW() AND (pbdd.`effectiveTo` > NOW() OR pbdd.`effectiveTo` IS NULL)
		      	]]>
			</trim>
       </where>
      order by pbdd.uploadTime desc
;

-- L0428 | D:/IDEAWorkspace/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectTaskMapper.xml:673 | checkPermission | pm_project_member, pm_project_task, pm_project, t_user_info
<![CDATA[
	  	select 
		    count(IF(pm.`memberRole` in (20,30,40), pm.id, null)) > 0 
		    	and count(ui.id) > 0 as `all`, 
		    count(IF(pm.`memberRole` in (20,30,40), pm.id, null)) > 0 as edit, 
		    count(IFNULL(pm.id, ui.id)) > 0 view, 
		    max(ph.projectState) as maxState,
		    group_concat(distinct pm.memberRole) memberRoles, 
		    #{permissionTypes} as permissionTypes,
		    #{user.userInfoId} as userInfoId,
		    count(ui.id) > 0 hasPower,
		    ph.disabled as disabled
		from
		    pm_project ph 
		    left join pm_project_task pt 
		        on pt.projectId = ph.projectId 
		        and pt.projectType = ph.projectType 
		    left join pm_project_member pm 
		        on ph.projectId = pm.projectId 
		        and pm.effectiveFrom <= now() 
		        and (
		            pm.effectiveTo > now() 
		            or pm.effectiveTo is null
		        ) 
		        and pm.memberCode = #{user.userName}
  	]]>
		    left join t_user_info ui 
		        on ui.`id` = #{user.userInfoId}
		        <if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
			        and find_in_set(ph.`column001`, ui.`custom5`) 
				</if>
		        and find_in_set(ph.projectType, ui.custom4) 
		where <!-- (
		        pm.memberCode = #{user.userName}
		        or ui.id = #{user.userInfoId}
		    )  -->
		(
			(
			<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
				1 = 1
				<if test="model.projectTypes != null">
					AND FIND_IN_SET(ph.`projectType`, #{model.projectTypes})
				</if>
				<if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
				</if>
			</trim>
			)
			or pm.memberCode = #{user.userName}
	        or ui.id = #{user.userInfoId}
		) 
	<if test="model != null">
		<if test="model.taskId != null">
			AND pt.taskId = #{model.taskId}
		</if>
		<if test="model.projectId != null">
			AND ph.projectId = #{model.projectId}
		</if>
		<if test="model.projectIds != null">
			AND FIND_IN_SET(ph.projectId, #{model.projectIds})
		</if>
		<!-- <if test="model.projectType != null">
			AND FIND_IN_SET(ph.projectType, #{model.projectType})
		</if>
		<if test="model.officeCodes != null">
			AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
		</if> -->
	</if>
;

