-- L0478 | D:/IDEAWorkspace/PMS/core/src/main/java/com/dp/plat/core/mapping/UserMapper.xml:1043 | findUserByParam | t_role, t_user, t_user_info, t_user_role
SELECT 
	    u.user_id, u.user_name, u.status, ui.id AS userInfoId, ui.realName, ui.mobile, ui.telphone, ui.avatar, ui.birthday, ui.email, ui.sex, GROUP_CONCAT(DISTINCT r.`role_name_zn`) AS roles 
	FROM
	    t_user_info ui 
	    LEFT JOIN t_user u 
	        ON u.`user_id` = ui.`user_id` 
	    LEFT JOIN t_user_role ru 
	        ON ui.`user_id` = ru.`user_id` 
	    LEFT JOIN t_role_menu rm 
	        ON rm.`role_id` = ru.`role_id` 
	    LEFT JOIN t_menu m 
	        ON m.`id` = rm.`menu_id` 
	    LEFT JOIN t_role r 
	        ON rm.`role_id` = r.`role_id` 
	<where>
		<trim prefixOverrides="AND | OR" suffixOverrides="AND | OR">
			<if test="roleName != null and roleName !=''">
				r.role_name like concat(#{roleName}, '%') AND
			</if>
			<if test="menuName != null and menuName !=''">
				m.name like concat(#{menuName}, '%') AND
			</if>
			<if test="compID != null">
				ui.compID = #{compID} AND
			</if>
		</trim>
	</where>
	GROUP BY ui.`id`
;

