			 	departmentNum like CONCAT('%', #departmentNum#, '%')
			 </isNotEmpty>
			 <isNotEmpty prepend="AND" property="departmentName">
			 	departmentName like CONCAT('%', #departmentName#, '%')
			 </isNotEmpty>
		</dynamic>
;

-- L0502 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-admin-config.xml:467 | query-departmentlist | fnd_department
