-- L0508 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-admin-config.xml:907 | query_user_with_dpNo_role_orin_areaPower | fnd_user_info, fnd_user_power
<![CDATA[
            SELECT u.username, u.realName, u.dpNo, u.email FROM fnd_user_info u 
            left join fnd_user_power up on up.fndUserId = u.id
            WHERE u.`status` = 1 and  u.roleIds LIKE CONCAT('%;', #roleid#, ';%')
        ]]>
        <dynamic>
            <isNotEmpty prepend="and" property="dpNo"><![CDATA[ u.dpNo=#dpNo#]]></isNotEmpty>
            <!-- 反向查询，确定areaPower中是否有该部门权限 -->
            <isNotEmpty prepend="and" property="areaPower"><![CDATA[ (u.dpNo = #areaPower# or FIND_IN_SET(#areaPower#, up.areaPower))]]></isNotEmpty>
        </dynamic>
;

