-- L0519 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-presales-config.xml:56 | query_presales_byid | fnd_basic_data, pm_project_member, pm_project_task, fnd_department
<![CDATA[
			SELECT t1.* ,CASE WHEN t1.presalesCode IS NULL THEN t1.projectCode ELSE t1.presalesCode END AS pcode , t1.projectCode as opcode, t2.`departmentName` AS officeName , 
			t3.`memberCode`  AS serviceManager,t3.`memberName` AS serviceManagerName,
			t4.`memberCode` AS projectManager ,t4.`memberName` AS projectManagerName, t5.ASSIGNEE_ as taskAssignee,
			t5.`ID_` AS taskId , t6.`quesnaireId` , t6.`quesnaireState` ,t5.TASK_DEF_KEY_ AS taskDefKey ,t7.eventActualFinishDate,
			t8.`basicDataName` as projectTypeName,
			pppd.applyDuration, pppd.totalDuration, pppd.serviceDuration, pppd.programDuration, pppd.testDuration, pppd.callbackDuration, pppd.serviceApproveDuration
			, t1.customInfo, t1.source
			FROM pm_presales_project_header t1
			LEFT JOIN fnd_department t2 ON t1.`officeCode` = t2.`departmentNum`
			LEFT JOIN pm_project_member t3 ON t3.`projectId` = t1.`presalesId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t4.`projectId` = t1.`presalesId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN act_ru_task t5 ON t5.`PROC_INST_ID_` = t1.`instId`
			LEFT JOIN pm_presales_project_callback t6 ON t1.`presalesId` = t6.`presalesId` AND t5.`ID_` = t6.`taskId`
			LEFT JOIN pm_project_task t7 ON t7.projectId = t1.presalesId AND t7.taskTypeId = "completeTest"
			LEFT JOIN fnd_basic_data t8 ON t8.`basicDataId` = t1.`projectType` AND t8.`dataTypeCode` = "presalesType" AND t8.`effectiveTo` IS NULL
			LEFT JOIN view_presales_project_duration pppd ON pppd.presalesId = t1.presalesId
			WHERE t1.presalesId = #presalesId#
		]]>
;

-- L0520 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-presales-config.xml:104 | query_presales_count | pm_project_member
<![CDATA[
			SELECT COUNT(DISTINCT t1.`presalesId`) FROM pm_presales_project_header t1 LEFT JOIN act_ru_task t2 ON t1.`instId` = t2.`PROC_INST_ID_`
			LEFT JOIN pm_project_member t3 ON t1.`presalesId` = t3.`projectId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t1.`presalesId` = t4.`projectId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
		]]>
		<isEqual property="searchTimeType" compareValue="testCompleteTime">
            LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            LEFT JOIN `pm_presales_project_callback` pcb ON pcb.presalesId = t1.presalesId AND pcb.quesnaireState = 1
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
        </isEqual>
			WHERE 1 = 1
		<isNotEmpty prepend="and" property="serviceManager">
		 	<![CDATA[ (t3.`memberCode` = #serviceManager#  or t4.`memberCode` = #serviceManager# ) ]]> 
		</isNotEmpty>
		<isNotEmpty prepend="and" property="projectManager">
			<![CDATA[ t4.`memberCode` = #projectManager#]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="presalesCode">
			<![CDATA[( t1.projectCode = #presalesCode# or t1.presalesCode = #presalesCode# )]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="projectName">
			<![CDATA[ t1.projectName like CONCAT('%', #projectName#, '%')]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="projectType">
            <![CDATA[ t1.projectType = #projectType#]]>
        </isNotEmpty>
		<isNotEmpty prepend="and" property="officeCode">
			<![CDATA[ t1.officeCode = #officeCode#]]>
		</isNotEmpty>
		<iterate prepend="AND" property="officeCodeList" open=" t1.officeCode in (" close=") " conjunction=",">#officeCodeList[]#</iterate>
		<isNotEmpty prepend="and" property="projectState">
			<![CDATA[ t1.projectState = #projectState#]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="projectStates">
            <![CDATA[ FIND_IN_SET(t1.projectState, #projectStates#) ]]>
        </isNotEmpty>
		<isNotEmpty prepend="and" property="hasTransfer">
            <![CDATA[ t1.hasTransfer = #hasTransfer#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="hasRma">
            <![CDATA[ t1.hasRma = #hasRma#]]>
        </isNotEmpty>
        <isEqual property="searchTimeType" compareValue="applyTime">
            <isNotNull prepend="AND" property="searchStartTime"> t1.applyTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ t1.applyTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="endTime">
            <isNotNull prepend="AND" property="searchStartTime"> t1.endTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ t1.endTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="testCompleteTime">
            <isNotNull prepend="AND" property="searchStartTime"> cbt.START_TIME_ >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ cbt.START_TIME_ <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            <isNotNull prepend="AND" property="searchStartTime"> pcb.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ pcb.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            <isNotNull prepend="AND" property="searchStartTime"> cbt.END_TIME_ >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ cbt.END_TIME_ <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
;

-- L0521 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-presales-config.xml:208 | query_presales_list | fnd_basic_data, pm_project_member, fnd_department, fnd_user_info
<![CDATA[
			SELECT t1.* ,CASE WHEN t1.presalesCode IS NULL THEN t1.projectCode ELSE t1.presalesCode END AS pcode ,t5.`departmentName` AS officeName , 
				t3.`memberCode`  AS serviceManager,t3.`memberName` AS serviceManagerName,
				t4.`memberCode` AS projectManager ,t4.`memberName` AS projectManagerName ,
				t2.`ID_`  AS taskId,t2.`ASSIGNEE_` ,t2.`NAME_` , CONCAT(t6.`username` , '-',t6.`realName`) AS ASSIGNEE_NAME,
				t2.TASK_DEF_KEY_ AS taskDefKey ,t7.`basicDataName` AS projectStateName,
				t8.`basicDataName` AS projectTypeName
				, t1.customInfo, t1.source
			FROM pm_presales_project_header t1 LEFT JOIN act_ru_task t2 ON t1.`instId` = t2.`PROC_INST_ID_`
			LEFT JOIN pm_project_member t3 ON t1.`presalesId` = t3.`projectId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t1.`presalesId` = t4.`projectId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_department t5 ON t1.`officeCode` = t5.`departmentNum` AND t5.`status` = 1
			LEFT JOIN fnd_user_info t6 ON t2.`ASSIGNEE_` = t6.`username`
			LEFT JOIN fnd_basic_data t7 ON t7.`basicDataId` = t1.`projectState` AND t7.`dataTypeCode` = 27 AND t7.`effectiveTo` IS NULL
			LEFT JOIN fnd_basic_data t8 ON t8.`basicDataId` = t1.`projectType` AND t8.`dataTypeCode` = "presalesType" AND t8.`effectiveTo` IS NULL
		]]>
		<isEqual property="presales.searchTimeType" compareValue="testCompleteTime">
			LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
		</isEqual>
		<isEqual property="presales.searchTimeType" compareValue="callbackQuesnarieTime">
            LEFT JOIN `pm_presales_project_callback` pcb ON pcb.presalesId = t1.presalesId AND pcb.quesnaireState = 1
        </isEqual>
		<isEqual property="presales.searchTimeType" compareValue="callbackCompleteTime">
		    LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
        </isEqual>
			where 1 = 1 
		<isNotEmpty prepend="and" property="presales.serviceManager">
		 	<![CDATA[ (t3.`memberCode` = #presales.serviceManager#  or t4.`memberCode` = #presales.serviceManager# ) ]]> 
		</isNotEmpty>
		<isNotEmpty prepend="and" property="presales.projectManager">
			<![CDATA[ t4.`memberCode` = #presales.projectManager#]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="presales.presalesCode">
			<![CDATA[ (t1.projectCode = #presales.presalesCode# or t1.presalesCode = #presales.presalesCode# )]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="presales.projectName">
			<![CDATA[ t1.projectName like CONCAT('%', #presales.projectName#, '%')]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="presales.projectType">
            <![CDATA[ t1.projectType = #presales.projectType#]]>
        </isNotEmpty>
		<isNotEmpty prepend="and" property="presales.officeCode">
			<![CDATA[ t1.officeCode = #presales.officeCode#]]>
		</isNotEmpty>
        <iterate prepend="AND" property="presales.officeCodeList" open=" t1.officeCode in (" close=") " conjunction=",">#presales.officeCodeList[]#</iterate>
		<isNotEmpty prepend="and" property="presales.projectState">
			<![CDATA[ t1.projectState = #presales.projectState#]]>
		</isNotEmpty>
		<isNotEmpty prepend="and" property="presales.projectStates">
            <![CDATA[ FIND_IN_SET(t1.projectState, #presales.projectStates#) ]]>
        </isNotEmpty>
		<isNotEmpty prepend="and" property="presales.hasTransfer">
            <![CDATA[ t1.hasTransfer = #presales.hasTransfer#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="presales.hasRma">
            <![CDATA[ t1.hasRma = #presales.hasRma#]]>
        </isNotEmpty>
        
        
        <isEqual property="presales.searchTimeType" compareValue="applyTime">
            <isNotNull prepend="AND" property="presales.searchStartTime"> t1.applyTime >= #presales.searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="presales.searchEndTime"> <![CDATA[ t1.applyTime <= #presales.searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="presales.searchTimeType" compareValue="endTime">
            <isNotNull prepend="AND" property="presales.searchStartTime"> t1.endTime >= #presales.searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="presales.searchEndTime"> <![CDATA[ t1.endTime <= #presales.searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="presales.searchTimeType" compareValue="testCompleteTime">
            <isNotNull prepend="AND" property="presales.searchStartTime"> cbt.START_TIME_ >= #presales.searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="presales.searchEndTime"> <![CDATA[ cbt.START_TIME_ <= #presales.searchEndTime# ]]> </isNotNull>
            GROUP BY t1.presalesId
        </isEqual>
        <isEqual property="presales.searchTimeType" compareValue="callbackQuesnarieTime">
            <isNotNull prepend="AND" property="presales.searchStartTime"> pcb.createTime >= #presales.searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="presales.searchEndTime"> <![CDATA[ pcb.createTime <= #presales.searchEndTime# ]]> </isNotNull>
            GROUP BY t1.presalesId
        </isEqual>
        <isEqual property="presales.searchTimeType" compareValue="callbackCompleteTime">
            <isNotNull prepend="AND" property="presales.searchStartTime"> cbt.END_TIME_ >= #presales.searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="presales.searchEndTime"> <![CDATA[ cbt.END_TIME_ <= #presales.searchEndTime# ]]> </isNotNull>
            GROUP BY t1.presalesId
        </isEqual>
		<![CDATA[ ORDER BY t1.`applyTime` DESC]]>
		<isNotEmpty property="displayParam.offset">
			<![CDATA[ limit #displayParam.offset#, #displayParam.pagesize# ]]> 
		</isNotEmpty>
;

-- L0522 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-presales-config.xml:559 | queryPresalesExportData | fnd_basic_data, pm_project_member, pm_project_task, fnd_department, fnd_user_info
SELECT 
	    <isEqual property="searchTimeType" compareValue="testCompleteTime">
	        <isNotEqual property="exportDetail" compareValue="2">DISTINCT</isNotEqual>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            <isNotEqual property="exportDetail" compareValue="2">DISTINCT</isNotEqual>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            <isNotEqual property="exportDetail" compareValue="2">DISTINCT</isNotEqual>
        </isEqual>
		    t1.presalesId, t1.instId, IFNULL(t1.applyState, - 1) AS applyState, t1.applyTime, t1.endTime, t1.projectState, 
		    t1.projectCode, t1.projectName, t1.projectType, t1.marketName, t1.systemName, t1.expendName, t1.industryName, 
		    t1.officeCode, t1.salesman, t1.productManager, t1.closeRemark,
		    IF(
		        t1.confirmFileIds IS NULL 
		        AND pd.deliverableType IS NULL, '否', '是'
		    ) AS isUpload, t1.hasTransfer AS hasTransfer, t1.hasRma AS hasRma,  IFNULL(
		        pd.deliverableType, IF(
		            t1.confirmFileIds IS NOT NULL, '历史附件', ''
		        )
		    ) AS deliverableType, IFNULL(pt.taskTypeName, IF(t1.projectState = 10, "待开始", "已完成")) AS taskTypeName, 
		    CASE
		        WHEN t1.presalesCode IS NULL 
		        THEN t1.projectCode 
		        ELSE t1.presalesCode 
		    END AS presalesCode, t5.`departmentName` AS officeName, t3.`memberCode` AS serviceManager, t3.`memberName` AS serviceManagerName, t4.`memberCode` AS projectManager, t4.`memberName` AS projectManagerName, t2.`ID_` AS taskId, t2.`ASSIGNEE_` AS taskAssignee, t2.`NAME_` AS taskName, t2.TASK_DEF_KEY_ AS taskDefKey, CONCAT(t6.`username`, '-', t6.`realName`) AS taskAssigneeName, t7.`basicDataName` AS projectStateName, t8.basicDataName AS projectTypeName 
		    , t1.customInfo, t1.source
		<!-- exportDetail: 0-基于项目， 1-基于设备， 2-基于回访  -->
		<isNotEqual prepend="," property="exportDetail" compareValue="1">
		    pppd.applyDuration, pppd.totalDuration, pppd.serviceDuration, pppd.programDuration, pppd.testDuration, pppd.callbackDuration, pppd.serviceApproveDuration 
		</isNotEqual>
		<isEqual prepend="," property="exportDetail" compareValue="1">
            IFNULL(tl1.`itemCode`, rma.itemcode) AS itemCode, 
            IFNULL(tl1.`itemModel`, rma.itemModel) AS itemModel, 
            tl1.`productFirstName`, tl1.`productTypeName`, tl1.`productNum`, 
            rma.orderQty, rma.dlvQty, rma.rmaQty, rma.deliveryDate, rma.rmaDate
        </isEqual>
		<isEqual prepend="," property="exportDetail" compareValue="2">
            cbt.START_TIME_ AS callbackStartTime, pcb.createTime as callbackQuesnarieTime, cbt.END_TIME_ AS callbackEndTime, pcb.taskId as callbackTaskId, IFNULL(pcb.quesnaireId, 0) AS quesnaireId, pqsl.*
        </isEqual>
		FROM
		    pm_presales_project_header t1 
		    LEFT JOIN act_ru_task t2 
		        ON t1.`instId` = t2.`PROC_INST_ID_` 
		    LEFT JOIN pm_project_member t3 
		        ON t1.`presalesId` = t3.`projectId` 
		        AND t3.`memberRole` = '20' 
		        AND t3.`effectiveTo` IS NULL 
		    LEFT JOIN pm_project_member t4 
		        ON t1.`presalesId` = t4.`projectId` 
		        AND t4.`memberRole` = '30' 
		        AND t4.`effectiveTo` IS NULL 
		    LEFT JOIN 
		        (SELECT 
		            ptt.projectId, SUBSTRING_INDEX(
		                GROUP_CONCAT(
		                    bd.basicDataName 
		                    ORDER BY bd.`sortId` ASC
		                ), ",", 1
		            ) AS taskTypeName 
		        FROM
		            `pm_project_task` ptt 
		            LEFT JOIN `fnd_basic_data` bd 
		                ON ptt.`taskTypeCode` = bd.`dataTypeCode` 
		                AND ptt.`taskTypeId` = bd.`basicDataId` 
		        WHERE projectType = '20' 
		            AND eventActualFinishDate IS NULL 
		        GROUP BY projectId) pt 
		        ON pt.projectId = t1.presalesId 
		    LEFT JOIN 
		        (SELECT 
		            projectId, GROUP_CONCAT(DISTINCT deliverableType) AS deliverableType 
		        FROM
		            `pm_basic_deliver_detail` pd 
		        WHERE projectType = 20 
		        GROUP BY projectId, projectType) pd 
		        ON pd.projectId = t1.presalesId 
		<isNotEqual property="exportDetail" compareValue="1">    
		    LEFT JOIN `view_presales_project_duration_temp` pppd 
		        ON pppd.presalesId = t1.presalesId 
        </isNotEqual>
	    <isEqual property="exportDetail" compareValue="1">    
            LEFT JOIN 
                pm_presales_project_rma_info rma 
                ON t1.projectCode = rma.contract
            LEFT JOIN 
                temp_presales_product_line tl1 
                ON t1.presalesId = tl1.presalesId 
                AND rma.itemcode = tl1.itemCode 
        </isEqual>
        <isNotEqual property="exportDetail" compareValue="2">
          <isEqual property="searchTimeType" compareValue="testCompleteTime">
            LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
          </isEqual>
          <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            LEFT JOIN `pm_presales_project_callback` pcb ON pcb.presalesId = t1.presalesId AND pcb.quesnaireState = 1
          </isEqual>
          <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            LEFT JOIN `act_hi_taskinst` cbt ON cbt.PROC_INST_ID_ = t1.instId AND cbt.TASK_DEF_KEY_ = 'usertask4' 
          </isEqual>
        </isNotEqual>
        <isEqual property="exportDetail" compareValue="2">
            LEFT JOIN `act_hi_taskinst` cbt 
                ON cbt.PROC_INST_ID_ = t1.instId 
                AND cbt.TASK_DEF_KEY_ = 'usertask4' 
            LEFT JOIN `pm_presales_project_callback` pcb 
                ON pcb.presalesId = t1.presalesId 
                AND pcb.taskId = cbt.ID_ 
                AND pcb.quesnaireState = 1
            LEFT JOIN presales_tempQuesnaireResultTable pqsl 
                ON pqsl.quesnaireResultHeaderId = pcb.`quesnaireId`
        </isEqual>
		    LEFT JOIN fnd_department t5 
		        ON t1.`officeCode` = t5.`departmentNum` 
		        AND t5.`status` = 1 
		    LEFT JOIN fnd_user_info t6 
		        ON t2.`ASSIGNEE_` = t6.`username` 
		    LEFT JOIN fnd_basic_data t7 
		        ON t7.`basicDataId` = t1.`projectState` 
		        AND t7.`dataTypeCode` = 27 
		        AND t7.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t8 
		        ON t8.`basicDataId` = t1.`projectType` 
		        AND t8.`dataTypeCode` = "presalesType" 
		        AND t8.`effectiveTo` IS NULL 
		WHERE 1 = 1
		<isNotEmpty prepend="and" property="serviceManager">
            <![CDATA[ (t3.`memberCode` = #serviceManager#  or t4.`memberCode` = #serviceManager# ) ]]> 
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectManager">
            <![CDATA[ t4.`memberCode` = #projectManager#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="presalesCode">
            <![CDATA[ (t1.projectCode = #presalesCode# or t1.presalesCode = #presalesCode# )]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectName">
            <![CDATA[ t1.projectName like CONCAT('%', #projectName#, '%')]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="officeCode">
            <![CDATA[ t1.officeCode = #officeCode#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectType">
            <![CDATA[ t1.projectType = #projectType#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectState">
            <![CDATA[ t1.projectState = #projectState#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="projectStates">
            <![CDATA[ FIND_IN_SET(t1.projectState, #projectStates#) ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="hasTransfer">
            <![CDATA[ t1.hasTransfer = #hasTransfer#]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="hasRma">
            <![CDATA[ t1.hasRma = #hasRma#]]>
        </isNotEmpty>
        <isEqual property="searchTimeType" compareValue="applyTime">
            <isNotNull prepend="AND" property="searchStartTime"> t1.applyTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ t1.applyTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="endTime">
            <isNotNull prepend="AND" property="searchStartTime"> t1.endTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ t1.endTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="testCompleteTime">
            <isNotNull prepend="AND" property="searchStartTime"> cbt.START_TIME_ >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ cbt.START_TIME_ <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackQuesnarieTime">
            <isNotNull prepend="AND" property="searchStartTime"> pcb.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ pcb.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="callbackCompleteTime">
            <isNotNull prepend="AND" property="searchStartTime"> cbt.END_TIME_ >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ cbt.END_TIME_ <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
         ORDER BY t1.`applyTime` DESC
;

-- L0523 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:91 | query_prob_count | fnd_basic_data
<![CDATA[
			SELECT count(*)
			FROM prob_main t1 
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			AND t2.`effectiveTo` IS NULL
		]]>	
		<isEqual prepend=" " property="checkSoft" compareValue="true"> 
			LEFT JOIN (
				SELECT 
				  probId, <!-- GROUP_CONCAT(
				      DISTINCT CONCAT(
				            "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, ""), " manual:", IFNULL(manualEntry, "")
				        ) SEPARATOR ";"
				    ) AS affectedVersion -->
				    GROUP_CONCAT(
		              DISTINCT concat_ws(
		                    " ", CONCAT("conp:", conp), CONCAT("cpld:", cpld), CONCAT("boot:", boot), CONCAT("pcb:", pcb), CONCAT("manual:", manualEntry)
		                ) SEPARATOR ";"
		            ) AS affectedVersion,
		            GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
				FROM
				    prob_softwares 
				where datastate = 1  
				<include refid="sqlWhereIterateSoftVersionList"/>  
		        GROUP BY probId
	        ) sf ON sf.probId = t1.id
		</isEqual>
			where t1.effectiveTo is null
		<isNotEmpty prepend="and" property="probNum"><![CDATA[ t1.probNum like CONCAT('%', #probNum#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="watch"><![CDATA[ t1.watch = #watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="theme"><![CDATA[ t1.theme like CONCAT('%', #theme#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="status"><![CDATA[ t1.`status` = #status#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="statusList">
			t1.status in
			<iterate open="(" close=")" conjunction="," property="statusList">
				#statusList[]#
			</iterate>
		</isNotEmpty>
		
		<isNotEmpty prepend="and" property="productType"><![CDATA[ t1.productType like concat("%", #productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="desc"><![CDATA[ t1.desc like concat("%", #desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="affectedType"> sf.probId is not null <!-- #affectedType# = sf.affectedTypes --> </isNotEmpty>
        <isNotEmpty prepend="and" property="affectedVersion">
        	(
        	<![CDATA[ sf.affectedVersion like concat("%", #affectedVersion#, "%") ]]>
        	<isNotEmpty prepend="or" property="softVersionParserList"> sf.probId is not null </isNotEmpty>
        	)
       	</isNotEmpty>
		
		<isNotEmpty property="visibleRange">
            <isNotEqual prepend="and" property="visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #visibleRange#
                <isNotEmpty prepend="or" property="trackingUser"> t1.trackingUser = #trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
        
        <isNotEmpty property="customInfo">
            <isNotEmpty prepend="and" property="customInfo.trackingUserSearch"> t1.trackingUser = #customInfo.trackingUserSearch# </isNotEmpty>
        </isNotEmpty>
        <!-- 或匹配，包含任意一个 -->
        <isNotEmpty prepend="and" property="relatedSceneTypesMark"><![CDATA[ t1.`relatedSceneTypesMark` & #relatedSceneTypesMark# > 0]]></isNotEmpty>
        <!-- 同时包含多个（AND 逻辑） -->
        <!-- <isNotEmpty prepend="and" property="relatedSceneTypesMark"><![CDATA[ t1.`relatedSceneTypesMark` & #relatedSceneTypesMark# = #relatedSceneTypesMark# ]]></isNotEmpty> -->
        <isNotEmpty prepend="and" property="mitigationActionTypesMark"><![CDATA[ t1.`mitigationActionTypesMark` & #mitigationActionTypesMark# > 0]]></isNotEmpty>
        <isNotEmpty prepend="and" property="solutionActionTypesMark"><![CDATA[ t1.`solutionActionTypesMark` & #solutionActionTypesMark# > 0]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probTicketNo"><![CDATA[ t1.probTicketNo like CONCAT('%', #probTicketNo#, '%')]]></isNotEmpty>
;

-- L0524 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:171 | query_prob_list | fnd_basic_data, fnd_user_info
SELECT t1.id as probId, t1.probNum, t1.theme,  t1.watch, t4.basicDataName as watchName<!-- , t1.`priority` AS priority -->, t2.`basicDataName` AS priority, t2.`basicDataName` AS priorityName, t1.status
				, t3.basicDataName AS statusName, t1.trackingUser, CONCAT(t1.trackingUser,"-",ui.realName) AS trackingUsername,  t1.createTime, t1.updateTime 
				<!-- , t1.desc, t1.solution, t1.productType -->
				, t1.customInfo
                , t1.relatedSceneTypes, t1.relatedSceneTypesMark
                , t1.mitigationActionTypes, t1.mitigationActionTypesMark
                , t1.solutionActionTypes, t1.solutionActionTypesMark
				, t1.probTicketNo
			FROM prob_main t1 
			LEFT JOIN fnd_user_info ui ON ui.username = t1.trackingUser
			LEFT JOIN fnd_basic_data t4 ON t1.`watch` = t4.`basicDataId` AND t4.`dataTypeCode` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_basic_data t2 ON t1.`priority` = t2.`basicDataId` AND t2.`dataTypeCode` = '32' 
			LEFT JOIN fnd_basic_data t3 ON t1.`status` = t3.basicDataId AND t3.dataTypeCode = '31' AND t2.`effectiveTo` IS NULL
		<isEqual prepend=" " property="prob.checkSoft" compareValue="true"> 
			LEFT JOIN (
		        SELECT 
		          probId,  <!-- GROUP_CONCAT(
		              DISTINCT CONCAT(
		                    "conp:", IFNULL(conp, ""), " cpld:", IFNULL(cpld, ""), " boot:", IFNULL(boot, ""), " pcb:", IFNULL(pcb, ""), " manual:", IFNULL(manualEntry, "")
		                ) SEPARATOR ";"
		            ) AS affectedVersion -->
		            GROUP_CONCAT(
		              DISTINCT concat_ws(
		                    " ", CONCAT("conp:", conp), CONCAT("cpld:", cpld), CONCAT("boot:", boot), CONCAT("pcb:", pcb), CONCAT("manual:", manualEntry)
		                ) SEPARATOR ";"
		            ) AS affectedVersion,
		            GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
		        FROM
		            prob_softwares 
		        where datastate = 1
		        <include refid="sqlWhereIterateSoftVersionList"/>  
		        GROUP BY probId
	        ) sf ON sf.probId = t1.id
        </isEqual>
		WHERE t1.effectiveTo IS NULL
		<isNotEmpty prepend="and" property="prob.probNum"><![CDATA[ t1.probNum like CONCAT('%', #prob.probNum#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.watch"><![CDATA[ t1.watch = #prob.watch#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.theme"><![CDATA[ t1.theme like CONCAT('%', #prob.theme#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.status"><![CDATA[ t1.`status` = #prob.status#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="prob.statusList">
			t1.status in
			<iterate open="(" close=")" conjunction="," property="prob.statusList">
				#prob.statusList[]#
			</iterate>
		</isNotEmpty>
		
		<isNotEmpty prepend="and" property="prob.productType"><![CDATA[ t1.productType like concat("%", #prob.productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.desc"><![CDATA[ t1.desc like concat("%", #prob.desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedType"> sf.probId is not null <!-- #prob.affectedType# = sf.affectedTypes --> </isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedVersion">
        	(
        	<![CDATA[ sf.affectedVersion like concat("%", #prob.affectedVersion#, "%") ]]>
        	<isNotEmpty prepend="or" property="prob.softVersionParserList"> sf.probId is not null </isNotEmpty>
        	)
       	</isNotEmpty>
        
        <isNotEmpty property="prob.visibleRange">
            <isNotEqual prepend="and" property="prob.visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #prob.visibleRange# 
                <isNotEmpty prepend="or" property="prob.trackingUser"> t1.trackingUser = #prob.trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
        
        <isNotEmpty property="prob.customInfo">
            <isNotEmpty prepend="and" property="prob.customInfo.trackingUserSearch"> t1.trackingUser = #prob.customInfo.trackingUserSearch# </isNotEmpty>
        </isNotEmpty>
		<!-- 或匹配，包含任意一个 -->
        <isNotEmpty prepend="and" property="prob.relatedSceneTypesMark"><![CDATA[ t1.`relatedSceneTypesMark` & #prob.relatedSceneTypesMark# > 0]]></isNotEmpty>
        <!-- 同时包含多个（AND 逻辑） -->
        <!-- <isNotEmpty prepend="and" property="prob.relatedSceneTypesMark"><![CDATA[ t1.`relatedSceneTypesMark` & #prob.relatedSceneTypesMark# = #prob.relatedSceneTypesMark# ]]></isNotEmpty> -->
        <isNotEmpty prepend="and" property="prob.mitigationActionTypesMark"><![CDATA[ t1.`mitigationActionTypesMark` & #prob.mitigationActionTypesMark# > 0]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.solutionActionTypesMark"><![CDATA[ t1.`solutionActionTypesMark` & #prob.solutionActionTypesMark# > 0]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="prob.probTicketNo"><![CDATA[ t1.probTicketNo like CONCAT('%', #prob.probTicketNo#, '%')]]></isNotEmpty>
		
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isEmpty prepend=" order by " property="displayParam.sort">
            t1.createTime desc
        </isEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset#,  #displayParam.pagesize#
		</isNotEmpty>
;

-- L0525 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:389 | check_soft_version_list | fb_soft_version, pm_project_soft_version
SELECT  DISTINCT 
		<isNotEmpty property="conp">
			conp 
		</isNotEmpty>
		<isEmpty property="conp">
			null as conp
		</isEmpty>
		<isNotEmpty property="cpld">
			,cpld 
		</isNotEmpty>
		<isEmpty property="cpld">
			,null as cpld 
		</isEmpty>
		<isNotEmpty property="boot">
			,boot 
		</isNotEmpty>
		<isEmpty property="boot">
			,null as boot
		</isEmpty>
		<isNotEmpty property="pcb">
			,pcb
		</isNotEmpty>
		<isEmpty property="pcb">
			,null as pcb
		</isEmpty>
		FROM 
			(SELECT conp, cpld, boot, pcb  FROM fb_soft_version 
		    UNION
		    SELECT conp, cpld, boot, pcb FROM `pm_project_soft_version` 
		    UNION
            SELECT conp, cpld, boot, pcb FROM prob_soft_version) t
		WHERE 1 = 1		
		<isEqual property="conpCondition" compareValue="between">
			<isNotEmpty prepend="and" property="conp"><![CDATA[ conp between #conp1# and #conp2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="conpCondition" compareValue="between">
		    <isEqual property="conpCondition" compareValue="regexp">
	            <isNotEmpty prepend="and" property="conp"><![CDATA[ conp regexp #conp#]]> </isNotEmpty>
	        </isEqual>
	        <isNotEqual property="conpCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="conp"><![CDATA[ conp like CONCAT('%', #conp#, '%')]]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		<isEqual property="cpldCondition" compareValue="between">
		    <isNotEmpty prepend="and" property="cpld"><![CDATA[ cpld between #cpld1# and #cpld2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="cpldCondition" compareValue="between">
		    <isEqual property="cpldCondition" compareValue="regexp">
                <isNotEmpty prepend="and" property="cpld"><![CDATA[ cpld regexp #cpld#]]> </isNotEmpty>
            </isEqual>
            <isNotEqual property="cpldCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="cpld"><![CDATA[ cpld like CONCAT('%', #cpld#, '%')]]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		<isEqual property="bootCondition" compareValue="between">
			<isNotEmpty prepend="and" property="boot"><![CDATA[ boot between #boot1# and #boot2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="bootCondition" compareValue="between">
		    <isEqual property="bootCondition" compareValue="regexp">
                <isNotEmpty prepend="and" property="boot"><![CDATA[ boot regexp #boot#]]> </isNotEmpty>
            </isEqual>
            <isNotEqual property="bootCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="boot"><![CDATA[ boot like CONCAT('%', #boot#, '%')]]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		<isEqual property="pcbCondition" compareValue="between">
			<isNotEmpty prepend="and" property="pcb"><![CDATA[ pcb between #pcb1# and #pcb2# ]]> </isNotEmpty>
		</isEqual>
		<isNotEqual property="pcbCondition" compareValue="between">
		    <isEqual property="pcbCondition" compareValue="regexp">
                <isNotEmpty prepend="and" property="pcb"><![CDATA[ pcb regexp #pcb#]]> </isNotEmpty>
            </isEqual>
            <isNotEqual property="pcbCondition" compareValue="regexp">
				<isNotEmpty prepend="and" property="pcb"><![CDATA[ pcb like CONCAT('%', #pcb#, '%')]]> </isNotEmpty>
            </isNotEqual>
		</isNotEqual>
		order by 1
		<isNotEmpty prepend="," property="conp">
			 conp 
		</isNotEmpty>
		<isNotEmpty prepend="," property="cpld">
			cpld 
		</isNotEmpty>
		<isNotEmpty prepend="," property="boot">
			boot 
		</isNotEmpty>
		<isNotEmpty prepend="," property="pcb">
			pcb
		</isNotEmpty>
;

-- L0526 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:561 | query_prob_restore_list_old | fb_contract, fb_items, fb_shipment, fb_shipment_barcode, fb_soft_version, fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_soft_version, fnd_department
<![CDATA[
			SELECT t1.*, fi.`itemname` as itemModel, t6.`projectCode`, t6.`projectName`, t6.`column001` AS officeCode, t9.`departmentName` AS officeName, t4.`contractNo`
	            , t6.column004 as marketCode, t6.column004 as marketName
	            , t6.column005 as systemCode, t6.column005 as systemName
	            , t6.column006 as expendCode, t6.column006 as expendName
	            , t6.column007 as industryCode, t6.column007 as industryName
	            
				, t2.`probId`, MAX(t6.`projectId`) AS projectId  
				, null AS probNum, null AS theme
			FROM
			    (SELECT * FROM prob_softwares WHERE datastate = 1 AND manualEntry is null AND probId = #probRestore.probId#) t2 
			    LEFT JOIN 
			        (SELECT  a1.serial_number AS barCode, 
			            CASE WHEN a2.conp IS NULL THEN a1.conp ELSE a2.conp END AS conp, 
			            CASE WHEN a2.boot IS NULL THEN a1.boot ELSE a2.boot END AS boot, 
			            CASE WHEN a2.cpld IS NULL THEN a1.cpld ELSE a2.cpld END AS cpld, 
			            CASE WHEN a2.pcb IS NULL THEN a1.pcb ELSE a2.pcb END AS pcb 
			        FROM fb_soft_version a1 
			            LEFT JOIN pm_project_soft_version a2 
			                ON a1.`serial_number` = a2.`barcode` 
			                AND a2.`datastate` = 1) t1  
				ON  CASE WHEN t2.`conp` IS NOT NULL THEN t1.`conp` = t2.`conp` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`boot` IS NOT NULL THEN t1.`boot` = t2.`boot` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`cpld` IS NOT NULL THEN t1.`cpld` = t2.`cpld` ELSE 1 = 1 END 
			        AND 
			        CASE WHEN t2.`pcb` IS NOT NULL THEN t1.`pcb` = t2.`pcb` ELSE 1 = 1 END 
			    INNER JOIN fb_shipment_barcode fsb 
			        ON fsb.`barcode` = t1.serial_number 
			        AND (
			            ISNULL(`fsb`.`rma_no`) 
			            OR (`fsb`.`rma_no` = '') 
			            OR (`fsb`.`rma_no` = 'null')
			        ) 
			    INNER JOIN fb_shipment fs ON fs.`packlist_id` = fsb.`pack_id` 
			    INNER JOIN fb_contract fc ON fc.`contract_id` = fs.`con_id`
			    INNER JOIN fb_items fi ON fi.`item` = fsb.`item`
			    INNER JOIN pm_project_contract t4 ON fc.`contract_code` = t4.`contractNo` 
			    INNER JOIN pm_project_group_relationship t5 ON t4.`projectGroupCode` = t5.`projectGroupCode` 
			    INNER JOIN pm_project_header t6 ON t5.`projectCode` = t6.`projectCode`
			    	AND (
			            (
			                column012 IS NOT NULL 
			                AND column012 <> 3
			            ) 
			            OR (
			                column012 IS NULL 
			                AND `columno12_readonly` <> 3
			            )
			        )  
			    LEFT JOIN fnd_department t9 ON t6.`column001` = t9.`departmentNum` 
			    LEFT JOIN fnd_basic_data t10 ON t6.`projectState` = t10.`basicDataId` AND t10.`dataTypeCode` = '02' AND t10.`effectiveTo` IS NULL 
			WHERE t4.`contractNo` IS NOT NULL 
			    AND t5.`projectCode` NOT LIKE '%his' 
			    AND NOT EXISTS 
			    (SELECT * FROM prob_restore WHERE serialNum = t1.serial_number AND probId = #probRestore.probId#) 
		]]>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ t1.serial_number like concat(#probRestore.serialNum#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ fi.itemname like concat(#probRestore.itemModel#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ t6.projectName like concat('%', #probRestore.projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ t4.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ t6.column001 = #probRestore.officeCode#]]></isNotEmpty>
		<![CDATA[
			GROUP BY t1.serial_number
		]]>
;

-- L0527 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:725 | count_prob_restore_list | fb_items, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_soft_version, fnd_department
SELECT COUNT(*)
        <include refid="sqlFromProbAffectedProjectSoftVersion"/>
;

-- L0528 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:729 | query_prob_restore_list | fb_items, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_soft_version, fnd_department
<include refid="sqlQueryProbAffectedProjectSoftVersion"/>
        <isNotEmpty property="displayParam.offset">
