-- L0529 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:861 | query_list_probRestore_task | fnd_basic_data, pm_project_header, pm_project_soft_version, fnd_department, fnd_user_info
<![CDATA[
			SELECT a1.* , a2.`basicDataName` AS restoreStatusName ,a3.`departmentName` AS officeName,
				a4.restoreRemark ,a4.restoreStatus ,sv.`conp` , sv.`boot` ,sv.`cpld` ,sv.`pcb` ,sv.`executeTime` ,
				CASE WHEN a6.realName IS NOT NULL THEN a6.realName ELSE '服务经理' END AS assigneeName
				
				, ph.projectCode
				, ph.column004 as marketCode, ph.column004 as marketName
                , ph.column005 as systemCode, ph.column005 as systemName
                , ph.column006 as expendCode, ph.column006 as expendName
                , ph.column007 as industryCode, ph.column007 as industryName
		]]>
                <!-- 查询受影响的技术公告，用来判断是否已经完成更新任务的处理 -->
                , JSON_EXTRACT((
                    <include refid="sqlSubSelectProjectSoftVersionAffectedProbs"/>
		            AND sw.probId = #probRestore.probId#
                ), '$$[0]') AS prob
			FROM prob_restore a1
				LEFT JOIN prob_restore_process a4 ON a1.processId = a4.id
				LEFT JOIN fnd_basic_data a2 ON a4.`restoreStatus` = a2.`basicDataId` AND a2.`dataTypeCode` = '33'
				LEFT JOIN fnd_department a3 ON a1.`officeCode` = a3.`departmentNum`
				LEFT JOIN pm_project_soft_version sv ON a1.`serialNum` = sv.`barcode` AND sv.`datastate` = 1 
				LEFT JOIN pm_project_header ph ON ph.projectId = sv.projectId
				LEFT JOIN fnd_user_info a6 ON a1.`assignee` = a6.`username` 
			WHERE a1.probId = #probRestore.probId# 	
		<isNotEmpty prepend="and" property="probRestore.assignee">
			<![CDATA[
				(a1.assignee = #probRestore.assignee# 
			]]>	
			<isNotEmpty prepend="OR" property="probRestore.areapower">
				<![CDATA[ 
					(a1.officeCode in ($probRestore.areapower$)
				]]>	
				<isNotEmpty prepend="and" property="probRestore.assigneeRole"><![CDATA[ a1.assigneeRole = #probRestore.assigneeRole#]]></isNotEmpty>
					)
			</isNotEmpty>
			)
		</isNotEmpty>
		<!-- <isEmpty property="probRestore.assignee">
			<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		</isEmpty> -->
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ a1.projectName like concat('%', #probRestore.projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ a1.serialNum = #probRestore.serialNum# ]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ a1.itemModel like concat(#probRestore.itemModel#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ a1.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="probRestore.projectCode"><![CDATA[ ph.projectCode like concat(#probRestore.projectCode#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.marketCode"><![CDATA[ ph.column004 = #probRestore.marketCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="probRestore.systemCode"><![CDATA[ ph.column005 = #probRestore.systemCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="probRestore.expendCode"><![CDATA[ ph.column006 = #probRestore.expendCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="probRestore.industryCode"><![CDATA[ ph.column007 = #probRestore.industryCode#]]></isNotEmpty>
        
		<isNotEqual prepend="and" property="probRestore.restoreStatus" compareValue="0">
			<![CDATA[ a4.restoreStatus = #probRestore.restoreStatus#]]>
		</isNotEqual>
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset# , #displayParam.pagesize#
		</isNotEmpty>
;

-- L0530 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:930 | query_list_probRestore_task_project | fnd_basic_data, pm_project_header, pm_project_soft_version, fnd_department, fnd_user_info
<![CDATA[
			SELECT a1.* , a2.`basicDataName` AS restoreStatusName ,a3.`departmentName` AS officeName,
				a4.restoreRemark ,a4.restoreStatus ,sv.`conp` , sv.`boot` ,sv.`cpld` ,sv.`pcb` ,sv.`executeTime` ,
				CASE WHEN a6.realName IS NOT NULL THEN a6.realName ELSE '服务经理' END AS assigneeName
				
				, ph.projectCode
			    , ph.column004 as marketCode, ph.column004 as marketName
			    , ph.column005 as systemCode, ph.column005 as systemName
			    , ph.column006 as expendCode, ph.column006 as expendName
			    , ph.column007 as industryCode, ph.column007 as industryName
		]]>
			    <!-- 查询受影响的技术公告，用来判断是否已经完成更新任务的处理 -->
			    , JSON_EXTRACT((
                    <include refid="sqlSubSelectProjectSoftVersionAffectedProbs"/>
                    AND sw.probId = #probRestore.probId#
                ), '$$[0]') AS prob
			FROM prob_restore a1
			LEFT JOIN prob_restore_process a4 ON a1.processId = a4.id
			LEFT JOIN fnd_basic_data a2 ON a4.`restoreStatus` = a2.`basicDataId` AND a2.`dataTypeCode` = '33'
			LEFT JOIN fnd_department a3 ON a1.`officeCode` = a3.`departmentNum`
			LEFT JOIN pm_project_soft_version sv ON a1.`serialNum` = sv.`barcode` AND sv.`datastate` = 1 
			LEFT JOIN pm_project_header ph ON ph.projectId = sv.projectId
			LEFT JOIN fnd_user_info a6 ON a1.`assignee` = a6.`username` 
			WHERE a1.probId = #probRestore.probId# 	
		<isNotEmpty prepend="and" property="probRestore.assignee">
			<![CDATA[
				(a1.assignee = #probRestore.assignee# 
			]]>	
			<isNotEmpty prepend="OR" property="probRestore.areapower">
				<![CDATA[ 
					(a1.officeCode in ($probRestore.areapower$)
				]]>	
				<isNotEmpty prepend="and" property="probRestore.assigneeRole"><![CDATA[ a1.assigneeRole = #probRestore.assigneeRole#]]></isNotEmpty>
					)
			</isNotEmpty>
			)
		</isNotEmpty>
		<!-- <isEmpty property="probRestore.assignee">
			<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		</isEmpty> -->
		<isNotEmpty prepend="and" property="probRestore.officeCode"><![CDATA[ a1.officeCode = #probRestore.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.projectName"><![CDATA[ a1.projectName like concat('%', #probRestore.projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.serialNum"><![CDATA[ a1.serialNum = #probRestore.serialNum# ]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.itemModel"><![CDATA[ a1.itemModel like concat(#probRestore.itemModel#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.contractNo"><![CDATA[ a1.contractNo = #probRestore.contractNo#]]></isNotEmpty>
		
		<isNotEmpty prepend="and" property="probRestore.projectCode"><![CDATA[ ph.projectCode like concat(#probRestore.projectCode#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="probRestore.marketCode"><![CDATA[ ph.column004 = #probRestore.marketCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="probRestore.systemCode"><![CDATA[ ph.column005 = #probRestore.systemCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="probRestore.expendCode"><![CDATA[ ph.column006 = #probRestore.expendCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="probRestore.industryCode"><![CDATA[ ph.column007 = #probRestore.industryCode#]]></isNotEmpty>
        
		<isNotEqual prepend="and" property="probRestore.restoreStatus" compareValue="0">
			<![CDATA[ a4.restoreStatus = #probRestore.restoreStatus#]]>
		</isNotEqual>
		GROUP BY a1.projectId, a1.assignee, a1.assigneeRole, a4.restoreStatus 
		<isNotEmpty prepend=" order by " property="displayParam.sort">
			$displayParam.sort$
			<isEqual prepend=" " property="displayParam.order" compareValue="desc">
				desc
		      </isEqual>
			<isEqual prepend=" " property="displayParam.order" compareValue="asc">
				asc
		    </isEqual>
		</isNotEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset# , #displayParam.pagesize#
		</isNotEmpty>
;

-- L0531 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:1068 | query_prob_assignee_emails | fnd_user_info
<![CDATA[
			SELECT GROUP_CONCAT(DISTINCT t2.email SEPARATOR ';') as emails FROM prob_restore t1
			LEFT JOIN fnd_user_info t2 ON t1.`assignee` = t2.`username` AND t2.`status` = 1
			WHERE FIND_IN_SET(t1.`id`, #restoreIds#)
		]]>
;

-- L0532 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:1101 | query_hist_soft_version_list_by_probRestoreIds | pm_project_soft_change_logs, pm_project_soft_version
<![CDATA[
			SELECT 
			    pr.`serialNum` AS barCode, pr.`itemModel` AS itemName, pr.`projectId`, sv.`conp`, sv.`conpBak`, sv.`conpChange`, sv.`boot`, sv.`bootBak`, sv.`bootChange`, sv.`cpld`, sv.`cpldBak`, sv.`cpldChange`, sv.`pcb`, sv.`pcbBak`, sv.`pcbChange`, sv.`executeTime`, sv.`createTime` 
			FROM
			    `prob_restore` pr 
			    LEFT JOIN `pm_project_soft_version` sv 
			        ON pr.`serialNum` = sv.`barcode` 
			        AND sv.`datastate` = 1 
			    LEFT JOIN `pm_project_soft_change_logs` scl 
			        ON pr.`projectId` = scl.`projectId` 
			        AND scl.`latest` = 1
			WHERE FIND_IN_SET(pr.id, #restoreIds#)
		]]>
;

-- L0533 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:1117 | query_officeMails_by_probRestoreIds | fnd_user_info
<![CDATA[
			SELECT GROUP_CONCAT(DISTINCT ui.email SEPARATOR ';') 
			FROM
			    `prob_restore` pr 
			    LEFT JOIN fnd_user_info ui 
			        ON pr.`officeCode` = ui.`dpNo` 
			        AND ui.`status` = 1 
	       	WHERE FIND_IN_SET(pr.id, #restoreIds#)
		]]>
;

-- L0534 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-prob-config.xml:1129 | query_exportProb_list | fnd_basic_data, fnd_user_info
SELECT 
		    t1.*, t2.`basicDataName` AS priorityName, t4.`basicDataName` AS watchName, t3.basicDataName AS statusName, CONCAT(t1.trackingUser, "-", ui.realName) AS trackingUsername, sf.affectedVersion 
		FROM
		    prob_main t1 
		    LEFT JOIN fnd_user_info ui 
		        ON ui.username = t1.trackingUser 
		    LEFT JOIN fnd_basic_data t2 
		        ON t1.`priority` = t2.`basicDataId` 
		        AND t2.`dataTypeCode` = '32' 
		        AND t2.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t3 
		        ON t1.`status` = t3.basicDataId 
		        AND t3.dataTypeCode = '31' 
		        AND t3.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t4 
		        ON t1.`watch` = t4.basicDataId 
		        AND t4.dataTypeCode = '30' 
		        AND t4.`effectiveTo` IS NULL 
		    LEFT JOIN 
		        (SELECT 
		            probId, <!-- GROUP_CONCAT(
		              DISTINCT  CONCAT_WS(
		                    "-", CONCAT("conp[", conp, "]"), CONCAT("cpld[", cpld, "]"), CONCAT("boot[", boot, "]"), CONCAT("pcb[", pcb, "]"), CONCAT("manual[", manualEntry, "]")
		                ) SEPARATOR ";\r\n"
		            ) AS affectedVersion  -->
		            GROUP_CONCAT(
		              DISTINCT CONCAT(bd.`basicDataName`, ":", CONCAT_WS(
		                    "-", CONCAT("conp[", conp, "]"), CONCAT("cpld[", cpld, "]"), CONCAT("boot[", boot, "]"), CONCAT("pcb[", pcb, "]"), CONCAT("", manualEntry, "")
		                )) SEPARATOR ";\r\n"
		            ) AS affectedVersion,
                    GROUP_CONCAT(DISTINCT affectedType) AS affectedTypes
		        FROM
		            `prob_softwares` ps 
			    LEFT JOIN fnd_basic_data bd 
			        ON bd.`dataTypeCode` = 'sofeVersionAffectedType' 
			        AND ps.`affectedType` = bd.`basicDataId` 
		        WHERE datastate = 1
                <include refid="sqlWhereIterateSoftVersionList"/>  
                GROUP BY probId) sf 
		        ON sf.probId = t1.`id` 
        WHERE t1.effectiveTo IS NULL
        <isNotEmpty prepend="and" property="prob.probNum"><![CDATA[ t1.probNum like CONCAT('%', #prob.probNum#, '%')]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.watch"><![CDATA[ t1.watch = #prob.watch#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.theme"><![CDATA[ t1.theme like CONCAT('%', #prob.theme#, '%')]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.status"><![CDATA[ t1.`status` = #prob.status#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.statusList">
            t1.status in
            <iterate open="(" close=")" conjunction="," property="prob.statusList">
                #prob.statusList[]#
            </iterate>
        </isNotEmpty>
        
        <isNotEmpty prepend="and" property="prob.productType"><![CDATA[ t1.productType like concat("%", #prob.productType#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.desc"><![CDATA[ t1.desc like concat("%", #prob.desc#, "%")]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedType"> sf.probId is not null <!-- #prob.affectedType# = sf.affectedTypes --> </isNotEmpty>
        <isNotEmpty prepend="and" property="prob.affectedVersion">
            (
            <![CDATA[ sf.affectedVersion like concat("%", #prob.affectedVersion#, "%") ]]>
            <isNotEmpty prepend="or" property="prob.softVersionParserList"> sf.probId is not null </isNotEmpty>
            )
        </isNotEmpty>
        
        <isNotEmpty property="prob.visibleRange">
            <isNotEqual prepend="and" property="prob.visibleRange" compareValue="-1" open="(" close=")">
                t1.visibleRange = #prob.visibleRange# 
                <isNotEmpty prepend="or" property="prob.trackingUser"> t1.trackingUser = #prob.trackingUser# </isNotEmpty>
            </isNotEqual>
        </isNotEmpty>
        
        <isNotEmpty property="prob.customInfo">
            <isNotEmpty prepend="and" property="prob.customInfo.trackingUserSearch"> t1.trackingUser = #prob.customInfo.trackingUserSearch# </isNotEmpty>
        </isNotEmpty>
        <!-- 或匹配，包含任意一个 -->
        <isNotEmpty prepend="and" property="prob.relatedSceneTypesMark"><![CDATA[ t1.`relatedSceneTypesMark` & #prob.relatedSceneTypesMark# > 0]]></isNotEmpty>
        <!-- 同时包含多个（AND 逻辑） -->
        <!-- <isNotEmpty prepend="and" property="prob.relatedSceneTypesMark"><![CDATA[ t1.`relatedSceneTypesMark` & #prob.relatedSceneTypesMark# = #prob.relatedSceneTypesMark# ]]></isNotEmpty> -->
        <isNotEmpty prepend="and" property="prob.mitigationActionTypesMark"><![CDATA[ t1.`mitigationActionTypesMark` & #prob.mitigationActionTypesMark# > 0]]></isNotEmpty>
        <isNotEmpty prepend="and" property="prob.solutionActionTypesMark"><![CDATA[ t1.`solutionActionTypesMark` & #prob.solutionActionTypesMark# > 0]]></isNotEmpty>
        
        <isNotEmpty prepend="and" property="prob.probTicketNo"><![CDATA[ t1.probTicketNo like CONCAT('%', #prob.probTicketNo#, '%')]]></isNotEmpty>
;

