-- L0541 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1317 | query-project-bycontractno | fnd_basic_data, pm_project_header, pm_project_member, pm_project_property_from_sms, fnd_department
<![CDATA[
            SELECT t1.basicDataName AS serviceType, pppfs.agentName, pppfs.customerProjectName, IFNULL(pppfs.majorProjectLevel, "无") majorProjectLevel,
                podfs.contractNo contractNo, CASE WHEN pppfs.projectCode IS NULL THEN podfs.contractNo ELSE pppfs.projectCode END AS projectCode, 
                IFNULL(IF(podfs.salesType = '01', podfs.projectName, pppfs.projectName), podfs.projectName) AS projectName,
                podfs.orderCreateTime orderCreateTime, podfs.customerCode customerCode, podfs.customerName customerName, pppfs.salesManCode salesManCode, 
                pppfs.salesManName salesManName, pppfs.marketCode marketCode, pppfs.marketName marketName, pppfs.systemId systemId, pppfs.systemName systemName, 
                pppfs.expendId expendId, pppfs.expendName expendName, pppfs.industryId, pppfs.industryName industryName, pppfs.officeCode officeCode, 
                fd.departmentName officeName, ppm.memberCode memberCode, ppm.memberName memberName, pph.column008 column008, pph.column010 column010, pph.column011 column011,
                pph.column012 column012, TRIM(IF(TRIM(IFNULL(pppfs.finalCustomerName, "")) > "", pppfs.finalCustomerName, pph.column013)) column013, podfs.compCode, c.id AS compId, podfs.salesType,
                concat("{'smsProjectAmount':'", IFNULL(pppfs.projectMoney, 0), "'}") as customInfo
            FROM pm_order_data_from_sap podfs
            LEFT JOIN pm_project_property_from_sms pppfs ON podfs.orderExecNumber = pppfs.orderExecNumber 
            LEFT JOIN pm_project_header pph ON podfs.contractNo = pph.projectCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pppfs.officeCode
            LEFT JOIN pm_project_member ppm ON pph.projectId = ppm.projectId
                 AND ppm.effectiveFrom <= NOW() AND (ppm.effectiveTo > NOW() OR ppm.effectiveTo IS NULL)
            LEFT JOIN fnd_basic_data t1 ON pppfs.serviceTypeName = t1.basicDataId AND t1.dataTypeCode = 21
                 AND t1.effectiveFrom <= NOW() AND ( t1.effectiveTo > NOW() OR t1.effectiveTo IS NULL )
            LEFT JOIN fnd_company c ON c.code = podfs.compCode
            where podfs.contractNo = #contractNo#   AND  podfs.`orderType` = 0 order by podfs.id desc limit 1
        ]]>
;

-- L0542 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1341 | query-project-bycontractnoAndType | fnd_basic_data, pm_project_header, pm_project_member, pm_project_property_from_sms, fnd_department
<![CDATA[
            SELECT t1.basicDataName AS serviceType, pppfs.agentName, pppfs.customerProjectName, IFNULL(pppfs.majorProjectLevel, "无") majorProjectLevel,
                podfs.contractNo contractNo, CASE WHEN pppfs.projectCode IS NULL THEN podfs.contractNo ELSE pppfs.projectCode END AS projectCode, 
                IFNULL(IF(podfs.salesType = '01', podfs.projectName, pppfs.projectName), podfs.projectName) AS projectName,
                podfs.orderCreateTime orderCreateTime, podfs.customerCode customerCode, podfs.customerName customerName, pppfs.salesManCode salesManCode, 
                pppfs.salesManName salesManName, pppfs.marketCode marketCode, pppfs.marketName marketName, pppfs.systemId systemId, pppfs.systemName systemName, 
                pppfs.expendId expendId, pppfs.expendName expendName, pppfs.industryId, pppfs.industryName industryName, pppfs.officeCode officeCode, 
                fd.departmentName officeName, ppm.memberCode memberCode, ppm.memberName memberName, pph.column008 column008, pph.column010 column010, pph.column011 column011,
                pph.column012 column012, TRIM(IF(TRIM(IFNULL(pppfs.finalCustomerName, "")) > "", pppfs.finalCustomerName, pph.column013)) column013, podfs.compCode, c.id AS compId, podfs.salesType,
                concat("{'smsProjectAmount':'", IFNULL(pppfs.projectMoney, 0), "'}") as customInfo
            FROM pm_order_data_from_sap podfs
            LEFT JOIN pm_project_property_from_sms pppfs ON podfs.orderExecNumber = pppfs.orderExecNumber 
            LEFT JOIN pm_project_header pph ON podfs.contractNo = pph.projectCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pppfs.officeCode
            LEFT JOIN pm_project_member ppm ON pph.projectId = ppm.projectId
                 AND ppm.effectiveFrom <= NOW() AND (ppm.effectiveTo > NOW() OR ppm.effectiveTo IS NULL)
            LEFT JOIN fnd_basic_data t1 ON pppfs.serviceTypeName = t1.basicDataId AND t1.dataTypeCode = 21
                 AND t1.effectiveFrom <= NOW() AND ( t1.effectiveTo > NOW() OR t1.effectiveTo IS NULL )
            LEFT JOIN fnd_company c ON c.code = podfs.compCode
            where podfs.contractNo = #contractNo# AND  podfs.`orderType` = 0 
        ]]>
        <isNotEmpty prepend="and" property="projectType"> pppfs.projectType = #projectType# </isNotEmpty>
        order by podfs.id desc limit 1
;

-- L0543 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1420 | query_project_byId | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_related_party, pm_project_state, fnd_department
<![CDATA[
        SELECT pph.projectId,CASE WHEN pph.effectiveFrom < NOW() AND (pph.effectiveTo >= NOW() OR pph.effectiveTo IS NULL) THEN 0 ELSE 1 END AS projectStatus, GROUP_CONCAT(DISTINCT ppc.contractNo) AS contractNo, pph.projectCode, CASE WHEN ppgr.`mergeBranchMark` IS NULL THEN pph.projectName ELSE 
             CONCAT( pph.projectName, '-',ppgr.`mergeBranchMark`
            ) END AS projectName , pph.projectState,state.`basicDataName` AS projectStateName, pph.isback, pph.isback, pph.column001, fd.departmentName, pph.column002, pph.column003, pph.column004, pph.column005, 
            pph.column006, pph.column007, pph.column008, pph.column009, pph.column010, pph.column011,case when  pph.column012 is null or pph.column012 = '' then pph.columno12_readonly else pph.column012 end as column012, 
            pph.columno12_readonly,  pph.column013, pph.column014, pph.compId, pph.customerProjectName, pph.majorProjectLevel, pph.salesType,
            case when ppm1.memberCode is null then ppm4.memberCode else ppm1.memberCode end as serviceManagerCode, 
            case when ppm1.memberName is null then ppm4.memberName else ppm1.memberName end as serviceManagerCodeforjson, 
            case when ppm2.memberCode is null then ppm5.memberCode else ppm2.memberCode end as programManagerCode,
            case when ppm2.memberName is null then ppm5.memberName else ppm2.memberName end as programManagerCodeforjson,
            ppm5.memberCode as programManagerCodeB,
            ppm5.memberName as programManagerCodeforjsonB,
            pph.projectStartTime,
            case when ppm3.memberCode is null then ppm6.memberCode else ppm3.memberCode end as salesManCode, 
            case when ppm3.memberName is null then ppm6.memberName else ppm3.memberName end as salesManName, 
            pprp1.partyName partyName1, pprp2.partyName partyName2, pprp3.partyName partyName3,
            executionState.`basicDataName` AS executionStateName, ps.executionState, 
            closeProcessState.`basicDataName` AS closeProcessStateName, ps.closeProcessState
            , pph.customInfo
        FROM pm_project_header pph 
            LEFT JOIN pm_project_member ppm1 ON ppm1.projectId = pph.projectId AND ppm1.memberRole = '20' AND ppm1.fromFlag = 1
            AND (ppm1.effectiveFrom <= NOW() AND (ppm1.effectiveTo > NOW() OR ppm1.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm4 ON ppm4.projectId = pph.projectId AND ppm4.memberRole = '20' AND ppm4.fromFlag = 2
            AND (ppm4.effectiveFrom <= NOW() AND (ppm4.effectiveTo > NOW() OR ppm4.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm2 ON ppm2.projectId = pph.projectId AND ppm2.memberRole = '30' AND ppm2.fromFlag = 1
            AND (ppm2.effectiveFrom <= NOW() AND (ppm2.effectiveTo > NOW() OR ppm2.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm5 ON ppm5.projectId = pph.projectId AND ppm5.memberRole = '30' AND ppm5.fromFlag = 2
            AND (ppm5.effectiveFrom <= NOW() AND (ppm5.effectiveTo > NOW() OR ppm5.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm3 ON ppm3.projectId = pph.projectId AND ppm3.memberRole = '10' AND ppm3.fromFlag = 1
            AND (ppm3.effectiveFrom <= NOW() AND (ppm3.effectiveTo > NOW() OR ppm3.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm6 ON ppm6.projectId = pph.projectId AND ppm6.memberRole = '10' AND ppm6.fromFlag = 2
            AND (ppm6.effectiveFrom <= NOW() AND (ppm6.effectiveTo > NOW() OR ppm6.effectiveTo IS NULL))
            LEFT JOIN pm_project_group_relationship ppgr ON ppgr.projectCode = pph.projectCode
            LEFT JOIN pm_project_contract ppc ON ppc.projectGroupCode = ppgr.projectGroupCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pph.column001
            LEFT JOIN pm_project_related_party pprp1 ON pprp1.projectId = pph.projectId AND pprp1.partyRole = '10'
            AND (pprp1.effectiveFrom <= NOW() AND (pprp1.effectiveTo > NOW() OR pprp1.effectiveTo IS NULL))
            LEFT JOIN pm_project_related_party pprp2 ON pprp2.projectId = pph.projectId AND pprp2.partyRole = '20'
            AND (pprp2.effectiveFrom <= NOW() AND (pprp2.effectiveTo > NOW() OR pprp2.effectiveTo IS NULL))
            LEFT JOIN pm_project_related_party pprp3 ON pprp3.projectId = pph.projectId AND pprp3.partyRole = '30'
            AND (pprp3.effectiveFrom <= NOW() AND (pprp3.effectiveTo > NOW() OR pprp3.effectiveTo IS NULL))
            LEFT JOIN `fnd_basic_data` state ON  state.`basicDataId` = pph.projectState AND state.`dataTypeCode` = '02'
            LEFT JOIN `pm_project_state` ps ON ps.projectId = pph.projectId
            LEFT JOIN fnd_basic_data executionState ON executionState.`dataTypeCode` = 'projectExecutionState' AND executionState.`basicDataId` = ps.`executionState`
            LEFT JOIN fnd_basic_data closeProcessState ON closeProcessState.`dataTypeCode` = 'projectCloseProcessState' AND closeProcessState.`basicDataId` = ps.`closeProcessState`
        WHERE pph.projectId = #projectId# LIMIT 1
        ]]>
;

-- L0544 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1470 | query_project_by_power_Id | fb_contract, fb_shipment, fb_shipment_barcode, fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_property_from_sms, pm_project_related_party, pm_project_state, fnd_department, pm_project_group
