-- L0545 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:1797 | select-evaluation_header-objMap | pm_project_header, pm_project_member, fnd_department
<![CDATA[
            select 
            a.*, 
            c.evaluationPeopleId as applyPersonId,c.evaluationPeopleName as applyPersonName,c.evaluationTime as applyTime ,
            t2.departmentName AS officeName ,mm.memberName, 
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS implType 
            from (select * from pm_cl_evaluation_header  order by createdTime 
        ]]>
        <isEqual prepend=" " property="sqlText" compareValue="desc">
            desc) a
        </isEqual>
        <isEqual prepend=" " property="sqlText" compareValue="asc">
            asc) a
        </isEqual>
        <![CDATA[           
            left join pm_cl_evaluation_header c on a.applyHeaderId=c.id
            join pm_project_header t1 on c.projectId = t1.projectId and t1.projectState != 20
            LEFT JOIN 
                (SELECT 
                    m.projectId, GROUP_CONCAT(m.memberName) AS memberName 
                FROM
                    pm_project_member m 
                WHERE m.effectiveTo IS NULL 
                    AND m.memberRole = '60' 
                GROUP BY m.projectId) mm 
                ON mm.projectId = t1.projectId 
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum AND t2.`status` = 1
        ]]>
        <dynamic prepend="where">
            <isNotEqual prepend="and" property="pmClEvaluationHeader.evaluationType" compareValue="0">
                a.evaluationType=#pmClEvaluationHeader.evaluationType#
            </isNotEqual>
        </dynamic>
        <![CDATA[
            group by a.projectCode
        ]]>
;

-- L0546 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:2043 | query-orderline-fromsap-bycontractno | fb_items
SELECT
            podfs.contractNo contractNo,
            polfs.itemCode itemCode,
            polfs.itemDesc itemName,
            fi.itemname as model,
            polfs.orderQuantity orderQuantity,
            polfs.openQuantity openQuantity,
            polfs.orderNumber orderNumber,
            polfs.lineNum lineNum,
            (
                polfs.orderQuantity - polfs.openQuantity
            ) deliverQuantity
        FROM
            pm_order_line_from_sap polfs
        LEFT JOIN pm_order_data_from_sap podfs ON polfs.orderNumber = podfs.orderNumber
            AND podfs.orderType = polfs.lineType
            AND podfs.`orderType` = 0
            AND polfs.compCode = podfs.compCode
        LEFT JOIN fb_items fi
            on polfs.itemCode=fi.item
        WHERE
            podfs.contractNo = #contractNo# and polfs.`lineType` = 0
;

-- L0547 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:2116 | queryOrderDataDetailListByProjectId | fb_items, pm_project_product_line
SELECT pppl.id, pppl.projectId AS projectId, pppl.contractNo, pppl.itemCode AS itemCode, pppl.itemName AS itemName
		    , fi.itemname AS model, pppl.orderQuantity AS orderQuantity, pppl.deliverQuantity AS deliverQuantity, pppl.openQuantity AS openQuantity
		    , CASE 
		        WHEN pppl.projectQuantity IS NULL THEN pppl.orderQuantity
		        ELSE pppl.projectQuantity
		    END AS projectQuantity
		FROM pm_project_product_line pppl
		    LEFT JOIN fb_items fi ON pppl.itemCode = fi.item
		WHERE pppl.projectId = #projectId#
;

-- L0548 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:2252 | query-shipmentinfo-bycontractno | fb_items, fb_shipment_barcode_relation, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm, view_warranty
SELECT pps.*, vw.`warrantyStartTime`, vw.`warrantyEndTime`, vw.`warrantyMonth`, vw.`diff` AS warrantyDiff FROM (
            <include refid="sqlShipmentInfoByContractNo"/>
       ) pps
       LEFT JOIN `view_warranty` vw
           ON <!-- vw.`contract_code` = pps.contractNo  -->
           vw.contract_code in ($sourceContractNo$)
           AND vw.`barcode` = pps.barcode
       ORDER BY transferFlag asc
;

-- L0549 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:2308 | query_soft_version_list | fb_items, fb_shipment_barcode_relation, fb_soft_version, pm_project_shipment, pm_project_soft_version, view_shipment_ems_4_pm, view_shipment_info_4_pm
<!-- <![CDATA[
             SELECT  vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName,  
                CASE WHEN t3.conp IS NULL THEN t.`conp` ELSE t3.conp END AS conp,t3.conpBak,t3.conpChange,
                CASE WHEN t3.boot IS NULL THEN t.`boot` ELSE t3.boot END AS boot,t3.bootBak ,t3.bootChange, 
                CASE WHEN t3.cpld IS NULL THEN t.`cpld` ELSE t3.cpld END AS cpld,t3.cpldBak , t3.cpldChange,   
                CASE WHEN t3.pcb IS NULL THEN t.`pcb` ELSE t3.pcb END AS pcb ,t3.pcbBak ,t3.pcbChange   
            FROM view_shipment_info_4_pm vsip   
                LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId    
                LEFT JOIN fb_soft_version t ON vsip.`barcode` = t.`serial_number`    
                LEFT JOIN pm_project_soft_version t3 ON vsip.`barcode` = t3.`barcode` AND t3.`datastate` = 1   
            WHERE vsip.contract_code IN ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment WHERE vsip.barcode = barcode)    
                AND t.conp IS NOT NULL    
            UNION ALL     
            SELECT `contractNo`,t1.`barcode`,`itemCode`,`itemName`,    
                CASE WHEN t4.conp IS NULL THEN t2.`conp` ELSE t4.conp END AS conp,  t4.conpBak ,t4.conpChange,
                CASE WHEN t4.boot IS NULL THEN t2.`boot` ELSE t4.boot END AS boot,   t4.bootBak ,t4.bootChange,
                CASE WHEN t4.cpld IS NULL THEN t2.`cpld` ELSE t4.cpld END AS cpld,   t4.cpldBak , t4.cpldChange,
                CASE WHEN t4.pcb IS NULL THEN t2.`pcb` ELSE t4.pcb END AS pcb   , t4.pcbBak ,t4.pcbChange 
            FROM pm_project_shipment t1    
                LEFT JOIN fb_soft_version t2 ON t1.`barcode` = t2.`serial_number`   
                LEFT JOIN pm_project_soft_version t4 ON t1.`projectId` = t4.`projectId` AND t1.`barcode` = t4.`barcode` AND t4.`datastate` = 1   
            WHERE contractNo IN ($contractNo$) AND t1.projectId = #projectId#    AND t2.conp IS NOT NULL   
            
        ]]> -->
        SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName,  
            CASE WHEN sv.conp IS NULL THEN t.`conp` ELSE sv.conp END AS conp,sv.conpBak,sv.conpChange,
            CASE WHEN sv.boot IS NULL THEN t.`boot` ELSE sv.boot END AS boot,sv.bootBak ,sv.bootChange, 
            CASE WHEN sv.cpld IS NULL THEN t.`cpld` ELSE sv.cpld END AS cpld,sv.cpldBak , sv.cpldChange,   
            CASE WHEN sv.pcb IS NULL THEN t.`pcb` ELSE sv.pcb END AS pcb ,sv.pcbBak ,sv.pcbChange,
            vsip.barcode2 barCode2, vsip.itemCode2 itemCode2, vsip.itemName2 itemName2
        <isEqual property="queryAffectedProbs" compareValue="true" prepend="," >
            (<include refid="sqlSubSelectProjectSoftVersionAffectedProbs"/>) AS affectedProbs
        </isEqual>
        <isNotEqual property="queryAffectedProbs" compareValue="true" prepend="," > NULL AS affectedProbs </isNotEqual> 
        FROM view_shipment_info_4_pm vsip   
            LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId    
            LEFT JOIN fb_soft_version t ON vsip.`barcode` = t.`serial_number`    
            LEFT JOIN pm_project_soft_version sv ON vsip.`barcode` = sv.`barcode` AND sv.`datastate` = 1   
        <isNotEmpty property="itemFilters">
            LEFT JOIN fb_items fi ON fi.item = vsip.itemCode
        </isNotEmpty>
        WHERE vsip.contract_code IN ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment WHERE vsip.barcode = barcode and projectId = #projectId#)    
        <isNotEmpty prepend="and" property="profitCenter"> vsip.profitCenter = #profitCenter# </isNotEmpty>
        <isNotEmpty prepend="AND" property="itemFilters">
            <iterate property="itemFilters" conjunction="OR" open="(" close=")">
                <include refid="sqlItemFilters"/>
            </iterate>
        </isNotEmpty>
        UNION ALL     
        SELECT DISTINCT t1.`contractNo`,t1.`barcode`,t1.`itemCode`,t1.`itemName`,    
            CASE WHEN sv.conp IS NULL THEN t2.`conp` ELSE sv.conp END AS conp,  sv.conpBak ,sv.conpChange,
            CASE WHEN sv.boot IS NULL THEN t2.`boot` ELSE sv.boot END AS boot,   sv.bootBak ,sv.bootChange,
            CASE WHEN sv.cpld IS NULL THEN t2.`cpld` ELSE sv.cpld END AS cpld,   sv.cpldBak , sv.cpldChange,
            CASE WHEN sv.pcb IS NULL THEN t2.`pcb` ELSE sv.pcb END AS pcb   , sv.pcbBak ,sv.pcbChange,
            sbr.sn2 AS barCode2, sbr.item2 AS itemCode2, f.describe_ AS itemName2
        <isEqual property="queryAffectedProbs" compareValue="true" prepend="," >
            (<include refid="sqlSubSelectProjectSoftVersionAffectedProbs"/>) AS affectedProbs
        </isEqual>
        <isNotEqual property="queryAffectedProbs" compareValue="true" prepend="," > NULL AS affectedProbs </isNotEqual> 
        FROM pm_project_shipment t1    
            LEFT JOIN `fb_shipment_barcode_relation` sbr ON sbr.contract = REPLACE(t1.contractNo, '-C', '') AND t1.barcode = sbr.sn1 
            LEFT JOIN fb_soft_version t2 ON t1.`barcode` = t2.`serial_number`   
            LEFT JOIN pm_project_soft_version sv ON t1.`projectId` = sv.`projectId` AND t1.`barcode` = sv.`barcode` AND sv.`datastate` = 1   
            LEFT JOIN `fb_items` f ON f.item = sbr.item2
        <isNotEmpty property="itemFilters">
            LEFT JOIN `fb_items` fi ON fi.item = t1.itemCode
        </isNotEmpty>
        WHERE t1.contractNo IN ($contractNo$) AND t1.projectId = #projectId# AND t1.transferFlag != 1 
        AND EXISTS (SELECT 1 
            FROM
                view_shipment_info_4_pm vsip 
                LEFT JOIN view_shipment_ems_4_pm vsep 
                    ON vsep.contract_code = vsip.contract_code 
                    AND vsep.packId = vsip.packId 
            WHERE vsip.contract_code IN ($sourceContractNo$)
                AND vsip.barcode = t1.barcode
        )
        <isNotEmpty prepend="AND" property="itemFilters">
            <iterate property="itemFilters" conjunction="OR" open="(" close=")">
                <include refid="sqlItemFilters"/>
            </iterate>
        </isNotEmpty>
;

-- L0550 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:2393 | query_hist_soft_version_list_factory | fb_soft_version, view_shipment_ems_4_pm, view_shipment_info_4_pm
<![CDATA[
            SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, vsip.itemName itemName, 
               t.`conp`, null as conpBak, null as conpChange ,t.`boot` , null as bootBak , null as bootChange,
               t.`cpld`, null as cpldBak, null as cpldChange, t.`pcb` , null as pcbBak , null as pcbChange,
               vsip.barcode2 barCode2, vsip.itemCode2 itemCode2, vsip.itemName2 itemName2
               , NULL AS affectedProbs
            FROM view_shipment_info_4_pm vsip 
            LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
            LEFT JOIN fb_soft_version t ON vsip.`barcode` = t.`serial_number`
            WHERE vsip.contract_code IN ($contractNo$) 
            AND t.conp IS NOT NULL
        ]]>
;

