-- L0564 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:3672 | query-cbData-list | fnd_act_hi_comment, pm_cl_callback, pm_cl_callback_quesnaire, pm_cl_quesnaire_result_header, pm_cl_quesnaire_result_line, pm_cl_quesnaire_template_line, pm_cl_quesnaire_template_options, pm_project_header, pm_project_member, fnd_department
<!-- 5.7以上不支持desc group by  -->
        <!-- (select aa.* ,count(aa.id)as times from (select *  from pm_cl_evaluation_header order by createdTime desc)aa where aa.evaluationType=3 and aa.status=1 group by aa.projectCode) a -->
        select 
            a.id as id,a.projectName as projectName,a.projectCode as projectCode,a.evaluationResult as evaResult,a.times as times,a.projectId as projectId,
            case when a.updatedTime is null then a.createdTime else a.updatedTime end as cbTime ,
            b.quesMarkScore as totalScore, b.quesMarkResult as cbResult,
            e1.questionAnswer as equExplain, e2.questionAnswer as opinion,
            a.evaluationComment as approveRemark,
            <!-- c1.questionScore  as projectScore,  c2.questionScore  as equScore,
            c3.questionScore  as engScore,  c4.questionScore  as otherScore , -->
            c.questionScore10  AS projectScore,  c.questionScore20  AS equScore,
            c.questionScore30  AS engScore,  c.questionScore40  AS otherScore,
            t2.departmentName as officeName, t3.memberName as pmRealName,
        <![CDATA[
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS serviceType, t1.compId, fc.name AS companyName, fc.abbr AS companyAbbr
            , CONCAT('{"productHarmfulSubstanceControl":"', er3.questionOptionsContent, '"', '}') AS `customInfo`
            from 
            (
                select aa.*, a.times from (SELECT MAX(aa.id) AS id, COUNT(aa.id) AS times FROM pm_cl_evaluation_header aa WHERE aa.evaluationType = 3 AND aa.status = 1 GROUP BY aa.projectCode) a
                left join pm_cl_evaluation_header aa
                on aa.id = a.id
            ) a
            left join pm_cl_quesnaire_result_header b on a.id=b.evaluationHeaderId and b.status=1
        ]]>
            LEFT JOIN (SELECT quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,SUM(IF(c1.quesTypeForCB=10, questionScore, NULL)) AS questionScore10,SUM(IF(c1.quesTypeForCB=20, questionScore, NULL)) AS questionScore20,SUM(IF(c1.quesTypeForCB=30, questionScore, NULL)) AS questionScore30,SUM(IF(c1.quesTypeForCB=40, questionScore, NULL)) AS questionScore40  FROM pm_cl_quesnaire_result_line c1 WHERE quesTypeForCB IN (10,20,30,40) GROUP BY quesnaireResultHeaderId) c  ON b.id=c.quesnaireResultHeaderId
            <!--
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c1  on b.id=c1.quesnaireResultHeaderId  and c1.quesTypeForCB=10 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c2  on b.id=c2.quesnaireResultHeaderId  and c2.quesTypeForCB=20
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c3  on b.id=c3.quesnaireResultHeaderId  and c3.quesTypeForCB=30 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c4  on b.id=c4.quesnaireResultHeaderId  and c4.quesTypeForCB=40
             -->
            left join pm_cl_quesnaire_template_line d1 on b.quesnaireTemplateHeaderId=d1.quesnaireTemplateHeaderId and d1.questionNum=5
            left join pm_cl_quesnaire_result_line e1 on e1.quesnaireResultHeaderId=b.id and e1.quesnaireTemplateLineId=d1.id
            left join pm_cl_quesnaire_template_line d2 on b.quesnaireTemplateHeaderId=d2.quesnaireTemplateHeaderId and d2.questionNum=8
            left join pm_cl_quesnaire_result_line e2 on e2.quesnaireResultHeaderId=b.id and e2.quesnaireTemplateLineId=d2.id
            LEFT JOIN pm_cl_quesnaire_template_line d3 ON b.quesnaireTemplateHeaderId=d3.quesnaireTemplateHeaderId AND d3.questionNum=9
            LEFT JOIN pm_cl_quesnaire_result_line e3 ON e3.quesnaireResultHeaderId=b.id AND e3.quesnaireTemplateLineId=d3.id
            LEFT JOIN pm_cl_quesnaire_template_options er3 ON er3.questionId = d3.id AND er3.id = e3.questionTemplateOptId
            LEFT JOIN pm_project_header t1 ON a.projectId = t1.projectId
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum
            LEFT JOIN pm_project_member t3 ON t1.projectId = t3.projectId AND t3.memberRole = '30'    AND t3.effectiveTo IS NULL
            LEFT JOIN `fnd_company` fc ON t1.compId = fc.id
    <![CDATA[ 
        where t1.projectState != 20
    ]]>
        <isNotEmpty prepend="and" property="cbStartTime">
            <![CDATA[ 
            DATE_FORMAT(a.createdTime,'%Y-%m-%d')>=DATE_FORMAT(#cbStartTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="cbEndTime">
            <![CDATA[ 
            DATE_FORMAT(a.createdTime,'%Y-%m-%d')<=DATE_FORMAT(#cbEndTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="serviceType"><![CDATA[ (t1.column012 = #serviceType# or t1.columno12_readonly= #serviceType#)]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCode"><![CDATA[ t1.column001 = #officeCode# ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCodes"><![CDATA[ FIND_IN_SET(t1.column001, #officeCodes#) ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="compId"><![CDATA[ t1.compId = #compId# ]]></isNotEmpty>
    <![CDATA[
        group by a.projectCode
    ]]>
        UNION
        select  a.quesnaireId as id,t1.projectName as projectName,t1.projectCode as projectCode,b.quesMarkResult as evaResult,a.times as times,a.projectId as projectId,
            case when a.updateTime is null then a.createTime else a.updateTime end as cbTime ,
            b.quesMarkScore as totalScore, b.quesMarkResult as cbResult,
            e1.questionAnswer as equExplain, e2.questionAnswer as opinion,
            ahc.message as approveMessage,
            <!-- c1.questionScore  as projectScore,  c2.questionScore  as equScore,
            c3.questionScore  as engScore,  c4.questionScore  as otherScore , -->
            c.questionScore10  AS projectScore,  c.questionScore20  AS equScore,
            c.questionScore30  AS engScore,  c.questionScore40  AS otherScore,
            t2.departmentName as officeName, t3.memberName as pmRealName,
    <![CDATA[
            CASE
                WHEN t1.column012 IS NULL 
                AND t1.columno12_readonly = - 1 
                THEN t1.column012 
                WHEN t1.column012 IS NOT NULL 
                THEN t1.column012 
                ELSE t1.columno12_readonly 
            END AS serviceType, t1.compId, fc.name AS companyName, fc.abbr AS companyAbbr
            , CONCAT('{"productHarmfulSubstanceControl":"', er3.questionOptionsContent, '"', '}') AS `customInfo`
        from (
            SELECT 
                cb.projectId,cb.applyState, cb.instId, cbq.*, cbq.quesnaireVersion as times
            FROM
                pm_cl_callback cb 
                LEFT JOIN (SELECT * FROM pm_cl_callback_quesnaire WHERE quesnaireState = 1 AND id IN (SELECT MAX(id)  FROM `pm_cl_callback_quesnaire` GROUP BY callBackId)) cbq 
                    ON cb.id = cbq.callBackId 
                    AND cbq.quesnaireState = 1
            where cb.applyState != -1 and cbq.quesnaireId IS NOT NULL AND cb.projectId NOT IN (SELECT DISTINCT projectId  FROM `pm_cl_evaluation_header`)
            ORDER BY cbq.createTime desc
            ) a
            INNER JOIN (
                SELECT 
                    cb.projectId, MAX(cbq.createTime) createTime
                FROM
                    pm_cl_callback cb 
                    LEFT JOIN (SELECT * FROM pm_cl_callback_quesnaire WHERE quesnaireState = 1 AND id IN (SELECT MAX(id)  FROM `pm_cl_callback_quesnaire` GROUP BY callBackId)) cbq 
                        ON cb.id = cbq.callBackId 
                        AND cbq.quesnaireState = 1
                WHERE cb.applyState != -1 AND cbq.quesnaireId IS NOT NULL AND cb.projectId NOT IN (SELECT DISTINCT projectId  FROM `pm_cl_evaluation_header`)
                GROUP BY cb.`projectId`
            ) ma ON ma.createTime = a.createTime AND ma.projectId = a.projectId
            left join (select ach.* from (select max(id) as maxId from `fnd_act_hi_comment` ahc left join `act_hi_taskinst` aht on ahc.taskId = aht.ID_ where procdefKey = 'CallBack' and aht.TASK_DEF_KEY_ = 'usertask2' group by objId, procdefKey, instId) t left join fnd_act_hi_comment ach on ach.id = t.maxId) ahc on a.instId = ahc.instId 
            left join pm_cl_quesnaire_result_header b on a.quesnaireId=b.id and b.status=1
    ]]>
            LEFT JOIN (SELECT quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,SUM(IF(c1.quesTypeForCB=10, questionScore, NULL)) AS questionScore10,SUM(IF(c1.quesTypeForCB=20, questionScore, NULL)) AS questionScore20,SUM(IF(c1.quesTypeForCB=30, questionScore, NULL)) AS questionScore30,SUM(IF(c1.quesTypeForCB=40, questionScore, NULL)) AS questionScore40  FROM pm_cl_quesnaire_result_line c1 WHERE quesTypeForCB IN (10,20,30,40) GROUP BY quesnaireResultHeaderId) c  ON b.id=c.quesnaireResultHeaderId
            <!-- 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c1  on b.id=c1.quesnaireResultHeaderId  and c1.quesTypeForCB=10 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c2  on b.id=c2.quesnaireResultHeaderId  and c2.quesTypeForCB=20
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c3  on b.id=c3.quesnaireResultHeaderId  and c3.quesTypeForCB=30 
            left join (select quesnaireTemplateHeaderId,quesnaireResultHeaderId,quesTypeForCB,sum(questionScore) as questionScore  from pm_cl_quesnaire_result_line group by quesnaireResultHeaderId,quesTypeForCB) c4  on b.id=c4.quesnaireResultHeaderId  and c4.quesTypeForCB=40
             -->
            left join pm_cl_quesnaire_template_line d1 on b.quesnaireTemplateHeaderId=d1.quesnaireTemplateHeaderId and d1.questionNum=5
            left join pm_cl_quesnaire_result_line e1 on e1.quesnaireResultHeaderId=b.id and e1.quesnaireTemplateLineId=d1.id
            left join pm_cl_quesnaire_template_line d2 on b.quesnaireTemplateHeaderId=d2.quesnaireTemplateHeaderId and d2.questionNum=8
            left join pm_cl_quesnaire_result_line e2 on e2.quesnaireResultHeaderId=b.id and e2.quesnaireTemplateLineId=d2.id
            LEFT JOIN pm_cl_quesnaire_template_line d3 ON b.quesnaireTemplateHeaderId=d3.quesnaireTemplateHeaderId AND d3.questionNum=9
            LEFT JOIN pm_cl_quesnaire_result_line e3 ON e3.quesnaireResultHeaderId=b.id AND e3.quesnaireTemplateLineId=d3.id
            LEFT JOIN pm_cl_quesnaire_template_options er3 ON er3.questionId = d3.id AND er3.id = e3.questionTemplateOptId
            LEFT JOIN pm_project_header t1 ON a.projectId = t1.projectId
            LEFT JOIN fnd_department t2 ON t1.column001 = t2.departmentNum
            LEFT JOIN pm_project_member t3 ON t1.projectId = t3.projectId AND t3.memberRole = '30'    AND t3.effectiveTo IS null
            LEFT JOIN `fnd_company` fc ON t1.compId = fc.id
        WHERE t1.projectState != 20
        <isNotEmpty prepend="and" property="cbStartTime">
            <![CDATA[ 
            DATE_FORMAT(a.createTime,'%Y-%m-%d')>=DATE_FORMAT(#cbStartTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="cbEndTime">
            <![CDATA[ 
            DATE_FORMAT(a.createTime,'%Y-%m-%d')<=DATE_FORMAT(#cbEndTime#,'%Y-%m-%d')
            ]]>
        </isNotEmpty>
        <isNotEmpty prepend="and" property="serviceType"><![CDATA[ (t1.column012 = #serviceType# or t1.columno12_readonly= #serviceType#)]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCode"><![CDATA[ t1.column001 = #officeCode# ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="officeCodes"><![CDATA[ FIND_IN_SET(t1.column001, #officeCodes#) ]]></isNotEmpty>
        <isNotEmpty prepend="and" property="compId"><![CDATA[ t1.compId = #compId# ]]></isNotEmpty>
        <![CDATA[
            group by t1.projectCode
        ]]>
;

-- L0565 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4085 | query_project_list_by_officeAndMemberCode | pm_project_header, pm_project_member
<![CDATA[
        SELECT 
          `ph`.`projectId` AS `projectId`,
          `ph`.`projectCode` AS `projectCode`,
          `ph`.`projectState` AS `projectState`,
          `ph`.`column001` AS `officeCode`,
          `pm1`.`memberCode` AS `serviceManagerCode`,
          `pm1`.`memberName` AS `serviceManagerCodeforjson`,
          `pm2`.`memberCode` AS `programManagerCode`,
          `pm2`.`memberName` AS `programManagerCodeforjson`,
          `pm3`.`memberCode` AS `programManagerCodeB`,
          `pm3`.`memberName` AS `programManagerCodeforjsonB` 
        FROM
          `pm_project_header` ph 
          LEFT JOIN `pm_project_member` pm1 
            ON `ph`.`projectId` = `pm1`.`projectId`
            AND (`pm1`.`memberRole` = '20') 
            AND (`pm1`.`effectiveFrom` < NOW()) 
            AND (
              (`pm1`.`effectiveTo` > NOW()) 
              OR ISNULL(`pm1`.`effectiveTo`)
            ) 
          LEFT JOIN `pm_project_member` pm2 
            ON (
              `ph`.`projectId` = `pm2`.`projectId`
            ) 
            AND (`pm2`.`memberRole` = '30') 
            AND pm2.`fromFlag` = 1 
            AND (`pm2`.`effectiveFrom` < NOW()) 
            AND (
              (`pm2`.`effectiveTo` > NOW()) 
              OR ISNULL(`pm2`.`effectiveTo`)
            ) 
          LEFT JOIN `pm_project_member` pm3 
            ON (
              `ph`.`projectId` = `pm3`.`projectId`
            ) 
            AND (`pm3`.`memberRole` = '30') 
            AND pm3.`fromFlag` = 2 
            AND (`pm3`.`effectiveFrom` < NOW()) 
            AND (
              (`pm3`.`effectiveTo` > NOW()) 
              OR ISNULL(`pm3`.`effectiveTo`)
            )
        where ISNULL(`ph`.`effectiveTo`) 
        ]]>
        <isNotEmpty prepend="and" property="projectState"><![CDATA[ FIND_IN_SET(ph.projectState, #projectState# )]]></isNotEmpty>
        <isNotEmpty prepend="and" property="column001"><![CDATA[ ph.column001 = #column001#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="serviceManagerCode"><![CDATA[ pm1.`memberCode` = #serviceManagerCode#]]></isNotEmpty>
        <isNotEmpty prepend="and" property="programManagerCode"><![CDATA[ (pm2.`memberCode` = #programManagerCode# or pm3.`memberCode` = #programManagerCode#)]]></isNotEmpty>
;

-- L0566 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4156 | queryProjectLeaseLineByProjectCode | pm_project_product_lease_line_from_crm
SELECT c.*
		FROM pm_project_product_lease_line_from_crm c
		INNER JOIN (
		    SELECT projectCode, MAX(orderExecNumber) AS max_order
		    FROM pm_project_product_lease_line_from_crm c
		    WHERE c.projectCode = #projectCode#
		    GROUP BY projectCode
		) m ON c.projectCode = m.projectCode 
		   AND c.orderExecNumber = m.max_order
	    WHERE c.projectCode = #projectCode#;
;

-- L0567 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4169 | queryProjectLeaseLineSizeByProjectCode | pm_project_product_lease_line_from_crm
SELECT count(*)
        FROM pm_project_product_lease_line_from_crm c
        INNER JOIN (
            SELECT projectCode, MAX(orderExecNumber) AS max_order
            FROM pm_project_product_lease_line_from_crm c
            WHERE c.projectCode = #projectCode#
            GROUP BY projectCode
        ) m ON c.projectCode = m.projectCode 
            AND c.orderExecNumber = m.max_order
        WHERE c.projectCode = #projectCode#;
;

-- L0568 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4182 | queryProjectProductConfigLevelInfoByProjectCode | pm_project_product_config_level_info_from_crm
SELECT c.*
            , SUBSTRING_INDEX(bomPaths, ',', level -1) AS parentBomPaths
		    , concat(c.itemGroup, "_", SUBSTRING_INDEX(bomPaths, ',', level -1)) parentGroupPaths
		    , concat(c.itemGroup, "_", bomPaths) groupPaths
        FROM pm_project_product_config_level_info_from_crm c
        INNER JOIN (
            SELECT projectCode, MAX(orderExecNumber) AS max_order
            FROM pm_project_product_config_level_info_from_crm c
            WHERE c.projectCode = #projectCode#
            GROUP BY projectCode
        ) m ON c.projectCode = m.projectCode 
           AND c.orderExecNumber = m.max_order
        WHERE c.projectCode = #projectCode#
        ORDER BY c.projectCode, itemGroup, bomPaths;
;

-- L0569 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4199 | queryProjectProductConfigLevelInfoSizeByProjectCode | pm_project_product_config_level_info_from_crm
SELECT count(*)
        FROM pm_project_product_config_level_info_from_crm c
        INNER JOIN (
            SELECT projectCode, MAX(orderExecNumber) AS max_order
            FROM pm_project_product_config_level_info_from_crm c
            WHERE c.projectCode = #projectCode#
            GROUP BY projectCode
        ) m ON c.projectCode = m.projectCode 
            AND c.orderExecNumber = m.max_order
        WHERE c.projectCode = #projectCode#;
;

-- L0570 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4474 | querySpotCheckList | fb_items, fb_shipment_barcode_relation, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT 
            contractNo, itemCode, IF(
                itemName = IFNULL(itemName2, itemName), itemName, CONCAT(t.itemName, '\r\n(', itemName2, ')')
            ) AS itemName, t.qty, t.barCodes 
        FROM
            (SELECT 
                contractNo, IF(t.itemCode2 IS NULL, t.itemCode, CONCAT(t.itemCode, '\r\n(', itemCode2, ')')) AS itemCode, 
                CASE WHEN fi.`itemname` IS NULL OR fi.itemname = '' OR fi.itemname = '/' THEN fi.describe_  ELSE fi.itemname END AS itemName, 
                CASE WHEN fi2.`itemname` IS NULL OR fi2.itemname = '' OR fi2.itemname = '/' THEN fi2.describe_  ELSE fi2.itemname END AS itemName2, 
                COUNT(1) AS qty,
                CASE
                    WHEN igi.itemCode IS NULL 
                    THEN GROUP_CONCAT(IF(barCode2 IS NULL, barcode, CONCAT(barcode, '(', barCode2, ')')) ORDER BY barCode SEPARATOR '、') 
                    ELSE '' 
                END AS barCodes
            FROM
                (
                SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, -1 AS transferFlag, vsip.barcode2 barCode2, vsip.itemcode2 
                FROM view_shipment_info_4_pm vsip 
                    LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
                    WHERE vsip.contract_code in ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
                        and contractNo in ($contractNo$) and projectId = #projectId#
                    )
                <isNotEmpty prepend="and" property="profitCenter"> vsip.profitCenter = #profitCenter# </isNotEmpty>
                UNION ALL 
                SELECT DISTINCT pps.`contractNo`, pps.`barcode`, pps.`itemCode`, pps.transferFlag, sbr.sn2 as barCode2, sbr.item2 
                FROM pm_project_shipment pps 
                    LEFT JOIN `fb_shipment_barcode_relation` sbr 
                        ON sbr.contract = REPLACE(pps.contractNo, '-C', '')
                        AND pps.barcode = sbr.sn1 
                WHERE contractNo in ($contractNo$) and projectId = #projectId#
                     AND EXISTS 
                    (SELECT 
                        1 
                    FROM
                        view_shipment_info_4_pm vsip 
                        LEFT JOIN view_shipment_ems_4_pm vsep 
                            ON vsep.contract_code = vsip.contract_code 
                            AND vsep.packId = vsip.packId 
                    WHERE vsip.contract_code in ($sourceContractNo$)
                       <!-- FIND_IN_SET(vsip.contract_code ,REPLACE(REPLACE(#contractNo#, '-C', ''), "'",'')) -->
                        AND vsip.barcode = pps.barcode)
                ORDER BY transferFlag asc) t
                LEFT JOIN `fb_items` fi
                    ON fi.`item` = t.itemCode
                LEFT JOIN `fb_items` fi2 
                    ON fi2.`item` = t.itemCode2 
                LEFT JOIN `pm_project_spot_check_ignore_item` igi 
                    ON igi.itemCode = t.itemCode 
            WHERE t.transferFlag != 1
            GROUP BY t.itemCode) t
        ORDER BY t.contractNo, barCodes DESC, t.itemCode ASC;
;

-- L0571 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4541 | queryOverWarrantyRemindList | fb_items, fb_shipment_barcode_relation, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm, view_warranty
SELECT 
            contractNo, itemCode, 
            IF(itemModel = IFNULL(itemModel2, itemModel), itemModel, CONCAT(t.itemModel, '\r\n(', itemModel2, ')')) AS itemModel, 
            IF(itemName = IFNULL(itemName2, itemName), itemName, CONCAT(t.itemName, '\r\n(', itemName2, ')')) AS itemName, 
            t.qty, t.barCodes, t.warrantyEndTime 
        FROM
            (SELECT 
                contractNo, IF(t.itemCode2 IS NULL, t.itemCode, CONCAT(t.itemCode, '\r\n(', itemCode2, ')')) AS itemCode, 
                CASE WHEN fi.`itemname` IS NULL OR fi.itemname = '' OR fi.itemname = '/' THEN fi.describe_  ELSE fi.itemname END AS itemModel, 
                CASE WHEN fi2.`itemname` IS NULL OR fi2.itemname = '' OR fi2.itemname = '/' THEN fi2.describe_  ELSE fi2.itemname END AS itemModel2, 
                fi.describe_ AS itemName, fi2.describe_ AS itemName2,
                COUNT(1) AS qty,
                GROUP_CONCAT(DISTINCT IF(t.barCode2 IS NULL, t.barcode, CONCAT(t.barcode, '(', t.barCode2, ')')) ORDER BY t.barCode SEPARATOR '、' ) AS barCodes, 
                MIN(vw.warrantyEndTime) AS warrantyEndTime
            FROM
                (
                SELECT DISTINCT vsip.contract_code contractNo, vsip.barcode barCode, vsip.itemCode itemCode, -1 AS transferFlag, vsip.barcode2 barCode2, vsip.itemcode2 
                FROM view_shipment_info_4_pm vsip 
                    LEFT JOIN view_shipment_ems_4_pm vsep ON vsep.contract_code = vsip.contract_code AND vsep.packId = vsip.packId
                    WHERE vsip.contract_code in ($contractNo$) AND NOT EXISTS(SELECT 1 FROM pm_project_shipment pps1 WHERE vsip.barcode = pps1.barcode
                        and contractNo in ($contractNo$) and projectId = #projectId#
                    )
                <isNotEmpty prepend="and" property="profitCenter"> vsip.profitCenter = #profitCenter# </isNotEmpty>
                UNION ALL 
                SELECT DISTINCT pps.`contractNo`, pps.`barcode`, pps.`itemCode`, pps.transferFlag, sbr.sn2 as barCode2, sbr.item2 
                FROM pm_project_shipment pps 
                    LEFT JOIN `fb_shipment_barcode_relation` sbr 
                        ON sbr.contract = REPLACE(pps.contractNo, '-C', '')
                        AND pps.barcode = sbr.sn1 
                WHERE contractNo in ($contractNo$) AND projectId = #projectId#
                     AND EXISTS 
                    (SELECT 
                        1 
                    FROM
                        view_shipment_info_4_pm vsip 
                        LEFT JOIN view_shipment_ems_4_pm vsep 
                            ON vsep.contract_code = vsip.contract_code 
                            AND vsep.packId = vsip.packId 
                    WHERE vsip.contract_code in ($sourceContractNo$)
                        <!-- FIND_IN_SET(vsip.contract_code ,REPLACE(REPLACE(#contractNo#, '-C', ''), "'",'')) -->
                        AND vsip.barcode = pps.barcode)
                <!-- ORDER BY transferFlag asc -->
                ) t
                LEFT JOIN `fb_items` fi
                    ON fi.`item` = t.itemCode
                LEFT JOIN `fb_items` fi2 
                    ON fi2.`item` = t.itemCode2 
                LEFT JOIN `view_warranty` vw
                    ON vw.contract_code in ($sourceContractNo$)
                    AND vw.barcode = t.barcode
            WHERE t.transferFlag != 1
                AND vw.warrantyEndTime IS NOT NULL
            GROUP BY t.itemCode, vw.warrantyEndTime) t
        ORDER BY t.contractNo, t.itemCode, warrantyEndTime, t.qty DESC;
       <!-- GROUP BY t.itemCode) t
        ORDER BY t.contractNo, LEFT(t.itemCode, 4) ASC, warrantyEndTime, t.qty DESC; -->
;

-- L0572 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:4683 | queryProjectInspection | fb_contract, fb_shipment, fnd_basic_data, pm_pb_plan_from_sms, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_state, pm_project_task, fnd_department, pm_project_group
<![CDATA[
            SELECT 
               DISTINCT fd.`departmentName` AS officeName, t.*, IF(
                    LOCATE(
                        sales.`memberCode`, sales.`memberName`
                    ) > 0, IFNULL(sales.`memberName`, ""), CONCAT(
                        IFNULL(
                            CONCAT(sales.`memberCode`, "-"), ""
                        ), IFNULL(sales.`memberName`, "")
                    )
                ) AS salesName, CONCAT(
                    IFNULL(pm1.`memberName`, ""), IFNULL(CONCAT("，", pm2.`memberName`), "")
                ) AS programName, DATEDIFF(CURDATE(), t.packdate) AS packDays, DATEDIFF(
                    IFNULL(arrivalFinishDate, CURDATE()), t.arrival
                ) AS arrivalDays, DATEDIFF(
                    IFNULL(preInspectFinishDate, CURDATE()), t.preInspect
                ) AS preInspectDays, DATEDIFF(
                    IFNULL(finalInspectFinishDate, CURDATE()), t.finalInspect
                ) AS finalInspectDays
            FROM
                (SELECT 
                    t.*, 
                    DATE(IFNULL(
                        MAX(IF(pppfs.referenceEventName = '到货验收', pppfs.eventPlanHappenDate, NULL)), 
                        DATE_ADD(t.packdate, INTERVAL 25 DAY)
                    )) AS arrival, 
                    DATE(MAX(IF(pppfs.referenceEventName = '初验', pppfs.eventPlanHappenDate, NULL))) AS preInspect, 
                    DATE(MAX(IF(pppfs.referenceEventName = '终验', pppfs.eventPlanHappenDate, NULL))) AS finalInspect 
                FROM
                    (SELECT 
                        ph.`projectId`, ph.column001 AS officeCode, pc.`contractNo`, ph.`projectName`, 
                        ps.`projectPlanState` AS planState, planState.`basicDataName` AS planStateName, 
                        IF(IFNULL(ps.`executionState`, "") = "", ps.projectPlanState, executionState) AS executionState, 
                        IF(IFNULL(ps.`executionState`, "") = "", planState.`basicDataName`, execState.`basicDataName`) AS executionStateName, 
                        MAX(fs.`packdate`) packdate, MAX(
                            IF (
                                pt.taskTypeId = 30, pt.eventActualFinishDate, NULL
                            )
                        ) AS arrivalFinishDate, MAX(
                            IF (
                                pt.taskTypeId = 60, pt.eventActualFinishDate, NULL
                            )
                        ) AS preInspectFinishDate, MAX(
                            IF (
                                pt.taskTypeId = 70, pt.eventActualFinishDate, NULL
                            )
                        ) AS finalInspectFinishDate 
                    FROM
                        pm_project_header ph 
                        LEFT JOIN `pm_project_state` ps 
                            ON ps.`projectId` = ph.`projectId` 
                        LEFT JOIN fnd_basic_data planState 
                            ON planState.`dataTypeCode` = '22' 
                            AND planState.`effectiveTo` IS NULL 
                            AND planState.`basicDataId` = ps.`projectPlanState` 
                        LEFT JOIN fnd_basic_data execState 
                            ON execState.`dataTypeCode` = 'projectExecutionState' 
                            AND execState.`effectiveTo` IS NULL 
                            AND execState.`basicDataId` = ps.`executionState` 
                        LEFT JOIN pm_project_task pt 
                            ON ph.`projectId` = pt.`projectId` 
                            AND pt.`effectiveTo` IS NULL 
                        LEFT JOIN pm_project_group_relationship pgr 
                            ON ph.`projectCode` = pgr.`projectCode` 
                        LEFT JOIN pm_project_group pg 
                            ON pg.`projectGroupCode` = pgr.`projectGroupCode` 
                        LEFT JOIN pm_project_contract pc 
                            ON pg.`projectGroupCode` = pc.`projectGroupCode` 
                        LEFT JOIN fb_contract fc 
                            ON fc.`contract_code` = pc.`contractNo` 
                        LEFT JOIN fb_shipment fs 
                            ON fc.`contract_id` = fs.`con_id` 
                    WHERE ps.`shipmentState` = - 1 
                        AND pt.`effectiveTo` IS NULL 
                        AND ph.`effectiveTo` IS NULL 
                        AND (
                            (
                                FIND_IN_SET(pt.taskTypeId, "30,60,70") 
                                AND ph.`projectId` IN 
                                (SELECT DISTINCT 
                                    projectId 
                                FROM
                                    pm_project_task pt 
                                WHERE FIND_IN_SET(pt.taskTypeId, "70") 
                                    AND pt.eventActualFinishDate IS NULL)
                            ) 
                            OR pt.`taskTypeId` IS NULL
                        ) 
                        AND ph.`column004` = "运营商市场部" 
                        AND (
                            ph.column011 = 10 
                            OR ph.column011 IS NULL
                        ) 
                        AND ph.`projectState` IN (30, 31, 32) 
                    GROUP BY ph.`projectId`, pc.`contractNo`) t 
                    LEFT JOIN 
                        (SELECT DISTINCT 
                            pppfs.id, pppfs.contractNo, pppfs.batchCode, pppfs.basicDataName, pppfs.referenceEventName, pppfs.eventPlanHappenDate, pppfs.afterDaysNum, pppfs.eventActualFinishDate, pppfs.marketingFeedback 
                        FROM
                            pm_pb_plan_from_sms pppfs 
                            LEFT JOIN fnd_basic_data fbd 
                                ON fbd.basicDataName = pppfs.referenceEventName 
                        WHERE fbd.dataTypeCode IS NOT NULL) pppfs 
                        ON pppfs.contractNo = t.contractNo 
                WHERE t.packdate IS NOT NULL 
                GROUP BY t.`projectId`, t.`contractNo`) t 
                LEFT JOIN pm_project_member sales 
                    ON sales.`projectId` = t.projectId 
                    AND sales.memberRole = '10' 
                    AND sales.`effectiveTo` IS NULL 
                LEFT JOIN pm_project_member pm1 
                    ON pm1.`projectId` = t.projectId 
                    AND pm1.memberRole = '30' 
                    AND pm1.`effectiveTo` IS NULL 
                    AND pm1.`fromFlag` = 1 
                LEFT JOIN pm_project_member pm2 
                    ON pm2.`projectId` = t.projectId 
                    AND pm2.`fromFlag` = 2 
                    AND pm2.`effectiveTo` IS NULL 
                    AND pm2.memberRole = '30' 
                LEFT JOIN fnd_department fd 
                    ON fd.`departmentNum` = t.officeCode 
        ]]>
        <!-- <![CDATA[
            SELECT 
               DISTINCT fd.`departmentName` AS officeName, t.*, IF(
                    LOCATE(
                        sales.`memberCode`, sales.`memberName`
                    ) > 0, IFNULL(sales.`memberName`, ""), CONCAT(
                        IFNULL(
                            CONCAT(sales.`memberCode`, "-"), ""
                        ), IFNULL(sales.`memberName`, "")
                    )
                ) AS salesName, CONCAT(
                    IFNULL(pm1.`memberName`, ""), IFNULL(CONCAT("，", pm2.`memberName`), "")
                ) AS programName, DATEDIFF(CURDATE(), t.packdate) AS packDays, DATEDIFF(
                    IFNULL(arrivalFinishDate, CURDATE()), t.arrival
                ) AS arrivalDays, DATEDIFF(
                    IFNULL(preInspectFinishDate, CURDATE()), t.preInspect
                ) AS preInspectDays, DATEDIFF(
                    IFNULL(finalInspectFinishDate, CURDATE()), t.finalInspect
                ) AS finalInspectDays
            FROM
                (SELECT 
                    t.*, MAX(
                        IF(
                            pppfs.referenceEventName = '到货验收', pppfs.eventPlanHappenDate, NULL
                        )
                    ) AS arrival, MAX(
                        IF(
                            pppfs.referenceEventName = '初验', IF(
                                t.`packdate` < '2018-10-19', DATE_ADD(
                                    pppfs.eventPlanHappenDate, INTERVAL 3 MONTH
                                ), pppfs.eventPlanHappenDate
                            ), NULL
                        )
                    ) AS preInspect, MAX(
                        IF(
                            pppfs.referenceEventName = '终验', IF(
                                t.`packdate` < '2018-10-19', DATE_ADD(
                                    pppfs.eventPlanHappenDate, INTERVAL 3 MONTH
                                ), pppfs.eventPlanHappenDate
                            ), NULL
                        )
                    ) AS finalInspect 
                FROM
                    (SELECT 
                        ph.`projectId`, ph.column001 AS officeCode, pc.`contractNo`, ph.`projectName`, ps.`projectPlanState` AS planState, planState.`basicDataName` AS planStateName, MAX(fs.`packdate`) packdate, MAX(
                            IF (
                                pt.taskTypeId = 30, pt.eventActualFinishDate, NULL
                            )
                        ) AS arrivalFinishDate, MAX(
                            IF (
                                pt.taskTypeId = 60, pt.eventActualFinishDate, NULL
                            )
                        ) AS preInspectFinishDate, MAX(
                            IF (
                                pt.taskTypeId = 70, pt.eventActualFinishDate, NULL
                            )
                        ) AS finalInspectFinishDate 
                    FROM
                        pm_project_header ph 
                        LEFT JOIN `pm_project_state` ps 
                            ON ps.`projectId` = ph.`projectId` 
                        LEFT JOIN fnd_basic_data planState 
                            ON planState.`dataTypeCode` = '22' 
                            AND planState.`effectiveTo` IS NULL 
                            AND planState.`basicDataId` = ps.`projectPlanState` 
                        LEFT JOIN pm_project_task pt 
                            ON ph.`projectId` = pt.`projectId` 
                            AND pt.`effectiveTo` IS NULL
                            AND FIND_IN_SET(pt.taskTypeId, "30,60,70")  
                        LEFT JOIN pm_project_group_relationship pgr 
                            ON ph.`projectCode` = pgr.`projectCode` 
                        LEFT JOIN pm_project_group pg 
                            ON pg.`projectGroupCode` = pgr.`projectGroupCode` 
                        LEFT JOIN pm_project_contract pc 
                            ON pg.`projectGroupCode` = pc.`projectGroupCode` 
                        LEFT JOIN fb_contract fc 
                            ON fc.`contract_code` = pc.`contractNo` 
                        LEFT JOIN fb_shipment fs 
                            ON fc.`contract_id` = fs.`con_id` 
                    WHERE ps.`shipmentState` = - 1 
                        AND ph.`effectiveTo` IS NULL 
                        AND ph.`column004` = "运营商市场部" 
                        AND (
                            ph.column011 = 10 
                            OR ph.column011 IS NULL
                        ) 
                        AND ph.`projectState` IN (30, 31, 32) 
                    GROUP BY ph.`projectId`, pc.`contractNo`) t 
                    LEFT JOIN 
                        (SELECT DISTINCT 
                            pppfs.id, pppfs.contractNo, pppfs.batchCode, pppfs.basicDataName, pppfs.referenceEventName, pppfs.eventPlanHappenDate, pppfs.afterDaysNum, pppfs.eventActualFinishDate, pppfs.marketingFeedback 
                        FROM
                            pm_pb_plan_from_sms pppfs 
                            LEFT JOIN fnd_basic_data fbd 
                                ON fbd.basicDataName = pppfs.referenceEventName 
                        WHERE fbd.dataTypeCode IS NOT NULL) pppfs 
                        ON pppfs.contractNo = t.contractNo 
                WHERE t.packdate IS NOT NULL 
                GROUP BY t.`projectId`, t.`contractNo`) t 
                LEFT JOIN pm_project_member sales 
                    ON sales.`projectId` = t.projectId 
                    AND sales.memberRole = '10' 
                    AND sales.`effectiveTo` IS NULL 
                LEFT JOIN pm_project_member pm1 
                    ON pm1.`projectId` = t.projectId 
                    AND pm1.memberRole = '30' 
                    AND pm1.`effectiveTo` IS NULL 
                    AND pm1.`fromFlag` = 1 
                LEFT JOIN pm_project_member pm2 
                    ON pm2.`projectId` = t.projectId 
                    AND pm2.`fromFlag` = 2 
                    AND pm2.`effectiveTo` IS NULL 
                    AND pm2.memberRole = '30' 
                LEFT JOIN fnd_department fd 
                    ON fd.`departmentNum` = t.officeCode 
        ]]> -->
        <dynamic prepend="where">
            <isNotEmpty prepend="and" property="officeCode"> t.officeCode = #officeCode# </isNotEmpty>
        </dynamic>          
        ORDER BY t.officeCode, t.packdate
;

-- L0573 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:5997 | queryProjectSimplifyByProjectId | fnd_basic_data, pm_project_contract, pm_project_group_relationship, pm_project_header, pm_project_member, pm_project_state, fnd_department
<![CDATA[
        SELECT pph.projectId,CASE WHEN pph.effectiveFrom < NOW() AND (pph.effectiveTo >= NOW() OR pph.effectiveTo IS NULL) THEN 0 ELSE 1 END AS projectStatus, 
            GROUP_CONCAT(DISTINCT ppc.contractNo) AS contractNo, pph.projectCode, pph.compId,
            CASE WHEN ppgr.`mergeBranchMark` IS NULL THEN pph.projectName ELSE CONCAT( pph.projectName, '-',ppgr.`mergeBranchMark`) END AS projectName, 
            pph.projectState, pph.isback, pph.column001, fd.departmentName AS officeName, pph.column002, pph.column003, pph.column004, pph.column005, 
            pph.column006, pph.column007, pph.column008, pph.column009, pph.column010, pph.column011,
            CASE WHEN  pph.column012 IS NULL OR pph.column012 = '' THEN pph.columno12_readonly ELSE pph.column012 END AS column012, 
            pph.columno12_readonly AS column012Readonly, pph.column013, pph.column014, pph.salesType,
            CASE WHEN ppm1.memberCode IS NULL THEN ppm4.memberCode ELSE ppm1.memberCode END AS serviceManagerCode, 
            CASE WHEN ppm1.memberName IS NULL THEN ppm4.memberName ELSE ppm1.memberName END AS serviceManagerCodeforjson, 
            CASE WHEN ppm2.memberCode IS NULL THEN ppm5.memberCode ELSE ppm2.memberCode END AS programManagerCode,
            CASE WHEN ppm2.memberName IS NULL THEN ppm5.memberName ELSE ppm2.memberName END AS programManagerCodeforjson,
            ppm5.memberCode AS programManagerCodeB,
            ppm5.memberName AS programManagerCodeforjsonB,
            GROUP_CONCAT(DISTINCT ppm6.memberCode) AS teamMemberCodes,
            executionState.`basicDataName` AS executionStateName, ps.executionState, 
            closeProcessState.`basicDataName` AS closeProcessStateName, ps.closeProcessState
            , pph.customInfo
        FROM pm_project_header pph 
            LEFT JOIN pm_project_member ppm1 ON ppm1.projectId = pph.projectId AND ppm1.memberRole = '20' AND ppm1.fromFlag = 1
            AND (ppm1.effectiveFrom <= NOW() AND (ppm1.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm4 ON ppm4.projectId = pph.projectId AND ppm4.memberRole = '20' AND ppm4.fromFlag = 2
            AND (ppm4.effectiveFrom <= NOW() AND (ppm4.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm2 ON ppm2.projectId = pph.projectId AND ppm2.memberRole = '30' AND ppm2.fromFlag = 1
            AND (ppm2.effectiveFrom <= NOW() AND (ppm2.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm5 ON ppm5.projectId = pph.projectId AND ppm5.memberRole = '30' AND ppm5.fromFlag = 2
            AND (ppm5.effectiveFrom <= NOW() AND (ppm5.effectiveTo IS NULL))
            LEFT JOIN pm_project_member ppm6 ON ppm6.projectId = pph.projectId AND ppm6.memberRole = '40'
            AND (ppm6.effectiveFrom <= NOW() AND (ppm6.effectiveTo IS NULL))
            LEFT JOIN pm_project_group_relationship ppgr ON ppgr.projectCode = pph.projectCode
            LEFT JOIN pm_project_contract ppc ON ppc.projectGroupCode = ppgr.projectGroupCode
            LEFT JOIN fnd_department fd ON fd.departmentNum = pph.column001
            LEFT JOIN `pm_project_state` ps ON ps.projectId = pph.projectId
            LEFT JOIN fnd_basic_data executionState ON executionState.`dataTypeCode` = 'projectExecutionState' AND executionState.`basicDataId` = ps.`executionState`
            LEFT JOIN fnd_basic_data closeProcessState ON closeProcessState.`dataTypeCode` = 'projectCloseProcessState' AND closeProcessState.`basicDataId` = ps.`closeProcessState`
            
        WHERE pph.projectId = #projectId# LIMIT 1;
    ]]>
;

-- L0574 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:6210 | querySoleAgentProject | pm_project_header, pm_project_property_from_sms
<!-- SELECT DISTINCT 
        ph.projectId, ph.projectCode, ph.projectName
    FROM
        `pm_project_header` ph 
        LEFT JOIN `pm_project_property_from_sms` ppfs 
            ON ppfs.`projectCode` = LEFT(ph.`projectCode`, 15) 
        INNER JOIN 
            (SELECT DISTINCT 
                orderExecNumber 
            FROM
                `pm_order_data_from_sap` ps 
            WHERE ps.`orderType` = 0 
                AND ps.`salesType` = "14") t 
            ON ppfs.`orderExecNumber` = t.orderExecNumber 
    WHERE ph.`effectiveTo` IS NULL -->
    SELECT DISTINCT
        sph.* 
    FROM
        soleAgentProjectTable sph 
        LEFT JOIN newOrderContractInfoTable nci 
            ON sph.projectId = nci.projectId 
        LEFT JOIN oldOrderContractInfoTable oci 
            ON sph.projectId = oci.projectId 
    WHERE nci.projectId IS NOT NULL 
        OR oci.projectId IS NOT NULL
;

-- L0575 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:6353 | selectContractAcceptanceDeliveryInfo | fnd_basic_data
SELECT a.contractNo, bd.basicDataId AS smsDeliverType, bd.`basicDataName` AS deliverablesReq
            , MAX(IF(bd.`basicDataId` = d.basicDataName, uploadTime, NULL)) AS actualDate
            , GROUP_CONCAT(IF(bd.`basicDataId` = d.basicDataName, deliverableName, NULL)) AS deliverableNames
            , GROUP_CONCAT(IF(bd.`basicDataId` = d.basicDataName, deliverablePath, NULL)) AS deliverablePaths
            , fc.account AS dataAreaId
        FROM `pm_basic_deliver_detail` `a`
            LEFT JOIN `pm_basic_prj_deliver` `b` ON `a`.`deliverId` = `b`.`id`
            LEFT JOIN `fnd_basic_data` `c`
            ON `b`.`dataTypeCodeSon` = `c`.`dataTypeCode`
                AND `b`.`basicDataIdSon` = `c`.`basicDataId`
            JOIN `fnd_basic_data` `d`
            ON `d`.`dataTypeCode` = '19'
                AND `b`.`basicDataIdSon` = `d`.`basicDataId`
            LEFT JOIN fnd_basic_data bd ON bd.dataTypeCode = 'd365DeliverablesReq'
            LEFT JOIN pm_order_data_from_sap pod ON pod.contractNo = a.contractNo
            LEFT JOIN fnd_company fc ON fc.code = pod.compCode
        WHERE `a`.`contractNo` IS NOT NULL
            AND a.`effectiveTo` IS NULL
            AND a.contractNo IN (
                SELECT DISTINCT contractNo
                FROM `pm_basic_deliver_detail`
                WHERE #dateDiff# >= DATEDIFF(NOW(), IFNULL(effectiveTo, uploadTime))
            )
        GROUP BY contractNo, smsDeliverType
;

-- L0576 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:6381 | selectProblemTicket | pm_project_incident_table_from_itr
select * from pm_project_incident_table_from_itr itr
        <dynamic prepend="WHERE">
            <isNotEmpty prepend="AND" property="projectCode"> itr.projectCode = #projectCode# </isNotEmpty>
            <isNotEmpty prepend="AND" property="contractNo"> itr.contractNo = #contractNo# </isNotEmpty>
            <isNotEmpty prepend="AND" property="contractNoList"> 
                itr.contractNo in (<iterate property="contractNoList" conjunction=","> #contractNoList[]# </iterate>)
            </isNotEmpty>
        </dynamic>
;

-- L0577 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:6392 | selectProblemTicketByProjectBarcode | fb_items, fb_shipment_barcode_relation, pm_project_incident_table_from_itr, pm_project_shipment, view_shipment_ems_4_pm, view_shipment_info_4_pm
SELECT itr.* FROM (<include refid="sqlShipmentInfoByContractNo"/>) sp
            INNER JOIN pm_project_incident_table_from_itr itr 
                ON sp.barCode = itr.barCode AND sp.contractNo = itr.contractNo
        <dynamic prepend="WHERE">
            <isNotEmpty prepend="AND" property="projectCode"> itr.projectCode = #projectCode# </isNotEmpty>
            <isNotEmpty prepend="AND" property="contractNoList">
                itr.contractNo in (<iterate property="contractNoList" conjunction=","> #contractNoList[]# </iterate>)
            </isNotEmpty>
        </dynamic>
;

-- L0578 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-project-config.xml:6405 | selectLicenseInfo | pm_project_license_info_from_license
select * from pm_project_license_info_from_license lic
        <dynamic prepend="WHERE">
            <isNotEmpty prepend="AND" property="contract"> lic.contract = #contract# </isNotEmpty>
            <isNotEmpty prepend="AND" property="contractNoList">
                lic.contract IN (<iterate property="contractNoList" conjunction=","> #contractNoList[]# </iterate>)
            </isNotEmpty>
        </dynamic>
;

-- L0579 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-refresh-data-common-config.xml:1051 | selectOrderLineFromERP | fb_items
SELECT `pol`.`id` AS `id`, `pol`.`orderNumber` AS `orderNumber`, `pol`.`lineNum` AS `lineNum`, `pol`.`itemCode` AS `itemCode`
            , IF('' = TRIM(IFNULL(pol.`itemDesc`, fi.describe_)), fi.describe_, pol.itemDesc) AS `itemDesc`
            , `pol`.`orderQuantity` AS `orderQuantity`, `pol`.`openQuantity` AS `openQuantity`, `pol`.`bundleCode` AS `bundleCode`, `pol`.`warrantyMonth` AS `warrantyMonth`, `pol`.`lineType` AS `lineType`
            , `fc`.`code` AS `compCode`, `pol`.`profitCenter` AS `profitCenter`, `pol`.`realOrderExecNumber` AS `realOrderExecNumber`, `pol`.`customInfo` AS `customInfo`, `pol`.`syncTime` AS `syncTime`
            , 'D365' AS `source`
        FROM `pm_order_line_from_erp_d365` `pol`
            LEFT JOIN `fnd_company` `fc` ON `fc`.`account` = `pol`.`compCode`
            LEFT JOIN fb_items fi ON pol.itemCode = fi.item
        UNION ALL
        SELECT `pol`.`id` AS `id`, `pol`.`orderNumber` AS `orderNumber`, `pol`.`lineNum` AS `lineNum`, `pol`.`itemCode` AS `itemCode`, `pol`.`itemDesc` AS `itemDesc`
            , `pol`.`orderQuantity` AS `orderQuantity`, `pol`.`openQuantity` AS `openQuantity`, `pol`.`bundleCode` AS `bundleCode`, `pol`.`warrantyMonth` AS `warrantyMonth`, `pol`.`lineType` AS `lineType`
            , `pol`.`compCode` AS `compCode`, `pol`.`profitCenter` AS `profitCenter`, NULL AS `realOrderExecNumber`, NULL AS `customInfo`, NULL AS `syncTime`
            , 'SAP' AS `source`
        FROM `pm_order_line_from_erp_sap` `pol`
;

-- L0580 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-refresh-data-common-config.xml:1083 | selectContractShimpentBarcodeToCRM | fb_contract, fb_shipment, fb_shipment_barcode, view_warranty
<!-- select contract_code, barcode, TRIM(item) AS itemCode, barcode2, TRIM(item2) AS itemCode2 from view_warranty vw
        where contract_type = 0 
        <isNotEmpty prepend="AND" property="beginDate" open="(" close=")"> 
            (   vw.packdate >= #beginDate# 
                <isNotEmpty prepend="AND" property="endDate"> #endDate# >= vw.packdate </isNotEmpty>
            ) 
            OR 
            (   vw.packdate >= #beginDate# 
                <isNotEmpty prepend="AND" property="endDate"> #endDate# >= vw.packdate </isNotEmpty>
            )
        </isNotEmpty>
        <isEmpty property="beginDate"> 
            <isNotEmpty prepend="AND" property="endDate"> (#endDate# >= vw.packdate or #endDate# >= vw.packdate) </isNotEmpty>
        </isEmpty> -->
        
        SELECT TRIM(contract_code) AS contract_code, TRIM(barcode) AS barcode
		    , TRIM(item) AS itemCode, TRIM(barcode2) AS barcode2
		    , TRIM(item2) AS itemCode2
		    , NULLIF(NULLIF(fsb.rma_no, ''), 'null') IS NOT NULL AS rmaState
		FROM fb_shipment_barcode fsb
		    LEFT JOIN fb_shipment fs ON fs.packlist_id = fsb.pack_id
		    LEFT JOIN fb_contract fc ON fc.contract_id = fs.con_id
		WHERE fc.contract_type IN (0) 
		<isNotEmpty prepend="AND" property="beginDate" open="(" close=")"> 
            (   fsb.updateTime >= #beginDate# 
                <isNotEmpty prepend="AND" property="endDate"> #endDate# >= fsb.updateTime </isNotEmpty>
            ) 
        </isNotEmpty>
        <isEmpty property="beginDate"> 
            <isNotEmpty prepend="AND" property="endDate"> (#endDate# >= fsb.updateTime) </isNotEmpty>
        </isEmpty>
        <isNotEmpty prepend="AND" property="contractNo"> fc.contract_code = #contractNo# </isNotEmpty>
        ORDER BY fsb.updateTime
;

-- L0581 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-refresh-data-common-config.xml:1138 | selectSubcontractPaymentToFP | fnd_basic_data, pm_subcontract_project_header, pm_subcontract_project_payment, fnd_department, fnd_user_info
SELECT h.id AS subcontractId, h.`contractNos`, h.`subcontractNo`, h.`subcontractName`, bd.`basicDataName` AS typeName
	        , h.facilitatorId, sf.account AS facilitatorAccount, h.facilitatorName
	        , CONVERT(REPLACE(h.subcontractAmount, ',', ''), DECIMAL(25, 2)) AS `subcontractAmount`
	        , office.`departmentName` AS officeName, profitDep.`departmentName` AS profitDepName, h.reason, h.`createTime`
	        , CONCAT(h.createBy, '-', ui.`realName`) AS createName
	        , h.customInfo, bd1.`basicDataName` AS stateName, bd2.`basicDataName` AS callbackStateName, h.`isAccrued`, h.`isInvoiced`
	        , ROUND(REPLACE(IFNULL(pp.customInfo ->> '$$.paidAmount', pp.amount), ',', '') / CONVERT(REPLACE(h.subcontractAmount, ',', ''), DECIMAL(25, 2)) * 100, 2) AS paidRatio
	        , pp.id AS id
	        , CONVERT(REPLACE(IFNULL(pp.customInfo ->> '$$.paidAmount', pp.amount), ',', ''), DECIMAL(25, 2)) AS paidAmount
	        , ROUND(REPLACE(pp.ratio, ',', ''), 2) AS applyRatio
	        , pp.confirmTime, pp.paymentTime, pp.remark, pp.customInfo AS extInfo, h.orgId
	        , fc.account AS dataAreaId
	        , pp.createBy AS confirmUser, ui2.`realName` AS confirmUserName
	    FROM `pm_subcontract_project_header` h
	        LEFT JOIN `pm_subcontract_project_payment` pp ON h.id = pp.`subcontractId`
	        LEFT JOIN `fnd_basic_data` bd
	        ON bd.`basicDataId` = h.`type`
	            AND bd.`dataTypeCode` = 'SubcontractType'
	        LEFT JOIN `fnd_basic_data` bd1
	        ON h.`state` = bd1.`basicDataId`
	            AND bd1.`dataTypeCode` = 'subcontractState'
	        LEFT JOIN `fnd_basic_data` bd2
	        ON h.`callbackState` = bd2.`basicDataId`
	            AND bd2.`dataTypeCode` = 'subcontractCbState'
	        LEFT JOIN fnd_department office
	        ON office.`departmentNum` = h.`officeCode`
	            AND office.`status` = 1
	        LEFT JOIN fnd_department profitDep
	        ON profitDep.`departmentNum` = h.`profitDepCode`
	            AND profitDep.`status` = 1
	        LEFT JOIN fnd_user_info ui ON ui.`username` = h.`createBy`
	        LEFT JOIN fnd_user_info ui2 ON ui2.`username` = pp.`createBy`
	        LEFT JOIN pm_subcontract_facilitator sf ON h.facilitatorId = sf.id
	        LEFT JOIN fnd_company fc ON h.orgId = fc.id
	    WHERE h.effectiveTo IS NULL
        <isNotEmpty prepend="AND" property="id"> h.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractName"> h.subcontractName like concat("%", #subcontractName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="contractNos"> (h.contractNos like concat("%", #contractNos#, "%") or h.subcontractNo like concat("%", #contractNos#, "%")) </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectIds"> h.projectIds like concat("%", #projectIds#, "%")  </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> h.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="state"> h.state = #state# </isNotEmpty>
        <isNotEmpty prepend="AND" property="callbackState"> callbackState = #callbackState#  </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorId"> h.facilitatorId = #facilitatorId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorName"> h.facilitatorName like concat("%", #facilitatorName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankInfo"> h.bankInfo = #bankInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankAccount"> h.bankAccount = #bankAccount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="officeCode"> h.officeCode = #officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="profitDepCode"> h.profitDepCode = #profitDepCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractNo"> h.subcontractNo = #subcontractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isAccrued"> h.isAccrued = #isAccrued# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isInvoiced"> isInvoiced = #isInvoiced# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractAmount"> subcontractAmount = #subcontractAmount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="reason"> h.reason = #reason# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remark"> h.remark = #remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveFrom"> h.effectiveFrom >= #effectiveFrom# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveTo"> <![CDATA[ #effectiveTo# <= IFNULL(h.effectiveTo, "9999-12-31") ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="zrApproveTime"> h.zrApproveTime = #zrApproveTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createBy"> h.createBy = #createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createTime"> h.createTime = #createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateBy"> h.updateBy = #updateBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateTime"> h.updateTime = #updateTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="orgId"> h.orgId = #orgId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="areaPower"> (FIND_IN_SET(h.officeCode, #areaPower#) or FIND_IN_SET(h.profitDepCode, #areaPower#))</isNotEmpty>
        <isNotEmpty prepend="AND" property="projectId"> FIND_IN_SET(#projectId#, h.projectIds) </isNotEmpty>
        <isNotEmpty prepend="AND" property="customInfo.purchId"> #customInfo.purchId# = h.`customInfo` ->> '$$.purchId' </isNotEmpty>
        <isEqual property="searchTimeType" compareValue="createTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproverTime">
            <isNotNull prepend="AND" property="searchStartTime"> zrTask.zrApproverTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ zrTask.zrApproverTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproveTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.zrApproveTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.zrApproveTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="confirmTime">
            <isNotNull prepend="AND" property="searchStartTime"> pp.confirmTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ pp.confirmTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
