-- L0585 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-subcontract-config.xml:299 | selectSubcontractProjectVOList | fnd_act_hi_comment, fnd_basic_data, pm_subcontract_project_header, pm_subcontract_project_payment, fnd_department, fnd_user_info
SELECT 
        h.*, d.`departmentName` AS officeName, d1.`departmentName` AS profitDepName, bd.`basicDataName` AS stateName,
        bd1.`basicDataName` as callbackStateName, bd2.basicDataName as typeName, 
        CONCAT(h.createBy, "-", ui.`realName`) AS createName 
        <isEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> zrApproverTime </isEqual>
        <isPropertyAvailable prepend="," property="extInfo.needPayment"> spp.customInfo AS extInfo </isPropertyAvailable>
    FROM
        pm_subcontract_project_header h 
    <isPropertyAvailable property="extInfo.needPayment">
        <include refid="sqlLeftJoinLatestPayment"/>
    </isPropertyAvailable>
        LEFT JOIN fnd_department d 
            ON h.`officeCode` = d.`departmentNum` 
        LEFT JOIN fnd_department d1 
            ON h.`profitDepCode` = d1.`departmentNum` 
        LEFT JOIN `fnd_basic_data` bd 
            ON h.`state` = bd.`basicDataId` 
            AND bd.`dataTypeCode` = 'subcontractState' 
        LEFT JOIN `fnd_basic_data` bd1 
            ON h.`callbackState` = bd1.`basicDataId` 
            AND bd1.`dataTypeCode` = 'subcontractCbState' 
        LEFT JOIN `fnd_basic_data` bd2 
            ON h.`type` = bd2.`basicDataId` 
            AND bd2.`dataTypeCode` = 'subcontractType' 
        LEFT JOIN fnd_user_info ui 
            ON ui.`username` = h.`createBy`
        <isEqual property="searchTimeType" compareValue="zrApproverTime">
            LEFT JOIN 
                (SELECT 
                    ach.`objId` AS subcontractId, MAX(ht.`END_TIME_`) AS zrApproverTime 
                FROM
                    `fnd_act_hi_comment` ach 
                    LEFT JOIN `act_hi_taskinst` ht 
                        ON ht.ID_ = ach.taskId 
                        AND ht.PROC_INST_ID_ = ach.instId 
                WHERE ach.`result` = 1 
                    AND ach.`procdefKey` = 'Subcontract' 
                    AND ht.`TASK_DEF_KEY_` = 'approveZRTask' 
                GROUP BY ach.`procdefKey`, ach.`objId`) zra 
                ON zra.subcontractId = h.`id`
        </isEqual>
        <isEqual property="searchTimeType" compareValue="paymentTime">
            LEFT JOIN `pm_subcontract_project_payment` p 
                ON h.id = p.`subcontractId` 
        </isEqual>
    WHERE h.`effectiveTo` IS NULL 
        <isNotEmpty prepend="AND" property="id"> h.id = #id# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractName"> h.subcontractName like concat("%", #subcontractName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="contractNos"> (h.contractNos like concat("%", #contractNos#, "%") or h.subcontractNo like concat("%", #contractNos#, "%")) </isNotEmpty>
        <isNotEmpty prepend="AND" property="projectIds"> h.projectIds like concat("%", #projectIds#, "%")  </isNotEmpty>
        <isNotEmpty prepend="AND" property="type"> h.type = #type# </isNotEmpty>
        <isNotEmpty prepend="AND" property="state"> h.state = #state# </isNotEmpty>
        <isNotEmpty prepend="AND" property="callbackState"> callbackState = #callbackState#  </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorId"> h.facilitatorId = #facilitatorId# </isNotEmpty>
        <isNotEmpty prepend="AND" property="facilitatorName"> h.facilitatorName like concat("%", #facilitatorName#, "%") </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankInfo"> h.bankInfo = #bankInfo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="bankAccount"> h.bankAccount = #bankAccount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="officeCode"> h.officeCode = #officeCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="profitDepCode"> h.profitDepCode = #profitDepCode# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractNo"> h.subcontractNo = #subcontractNo# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isAccrued"> h.isAccrued = #isAccrued# </isNotEmpty>
        <isNotEmpty prepend="AND" property="isInvoiced"> isInvoiced = #isInvoiced# </isNotEmpty>
        <isNotEmpty prepend="AND" property="subcontractAmount"> subcontractAmount = #subcontractAmount# </isNotEmpty>
        <isNotEmpty prepend="AND" property="reason"> h.reason = #reason# </isNotEmpty>
        <isNotEmpty prepend="AND" property="remark"> h.remark = #remark# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveFrom"> h.effectiveFrom >= #effectiveFrom# </isNotEmpty>
        <isNotEmpty prepend="AND" property="effectiveTo"> <![CDATA[ #effectiveTo# <= IFNULL(h.effectiveTo, "9999-12-31") ]]> </isNotEmpty>
        <isNotEmpty prepend="AND" property="zrApproveTime"> h.zrApproveTime = #zrApproveTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createBy"> h.createBy = #createBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="createTime"> h.createTime = #createTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateBy"> h.updateBy = #updateBy# </isNotEmpty>
        <isNotEmpty prepend="AND" property="updateTime"> h.updateTime = #updateTime# </isNotEmpty>
        <isNotEmpty prepend="AND" property="orgId"> h.orgId = #orgId# </isNotEmpty>
        
        <isNotEmpty prepend="AND" property="areaPower"> (FIND_IN_SET(h.officeCode, #areaPower#) or FIND_IN_SET(h.profitDepCode, #areaPower#))</isNotEmpty>
        <isNotEmpty prepend="AND" property="projectId"> FIND_IN_SET(#projectId#, h.projectIds) </isNotEmpty>
        
        <isNotEmpty prepend="AND" property="customInfo.purchId"> #customInfo.purchId# = h.`customInfo` ->> '$$.purchId' </isNotEmpty>
        <isPropertyAvailable property="extInfo.needPayment">
	        <include refid="sqlWhereLatestPayment"/>
	    </isPropertyAvailable>
    
        <isEqual property="searchTimeType" compareValue="createTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.createTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.createTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproverTime">
            <isNotNull prepend="AND" property="searchStartTime"> zra.zrApproverTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ zra.zrApproverTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="zrApproveTime">
            <isNotNull prepend="AND" property="searchStartTime"> h.zrApproveTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ h.zrApproveTime <= #searchEndTime# ]]> </isNotNull>
        </isEqual>
        <isEqual property="searchTimeType" compareValue="paymentTime">
            <isNotNull prepend="AND" property="searchStartTime"> p.paymentTime >= #searchStartTime# </isNotNull>
            <isNotNull prepend="AND" property="searchEndTime"> <![CDATA[ p.paymentTime <= #searchEndTime# ]]> </isNotNull>
            GROUP BY h.id
        </isEqual>
     order by h.id desc
;

