-- L0587 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-subcontract-config.xml:445 | selectSubcontractProjectVOListPageable | fnd_act_hi_comment, fnd_basic_data, pm_subcontract_project_header, pm_subcontract_project_payment, fnd_department, fnd_user_info
SELECT 
        h.*, d.`departmentName` AS officeName, d1.`departmentName` AS profitDepName, bd.`basicDataName` AS stateName,
        bd1.`basicDataName` as callbackStateName, bd2.basicDataName as typeName, 
        CONCAT(h.createBy, "-", ui.`realName`) AS createName,
	    CONCAT(
	        ROUND(
	            IfNULL(spp.paidAmount, 0) / CONVERT(
	                REPLACE(h.subcontractAmount, ',', ''), DECIMAL (25, 2)
	            ) * 100, 2
	        ), "%"
	    ) AS paidRatio,IfNULL(spp.paidAmount, 0) AS paidAmount,
	    spp.customInfo AS extInfo
        <isEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> zra.zrApproverTime </isEqual>
        <isNotEqual prepend="," property="searchTimeType" compareValue="zrApproverTime"> h.zrApproveTime as zrApproverTime</isNotEqual>
    FROM
        pm_subcontract_project_header h 
        <include refid="sqlLeftJoinLatestPayment"/>
        LEFT JOIN fnd_department d 
            ON h.`officeCode` = d.`departmentNum` 
        LEFT JOIN fnd_department d1 
