-- L0608 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:68 | query_pm_task_list | fnd_basic_data, pm_project_header, pm_project_member, pm_project_state, pm_project_task, fnd_department
<![CDATA[
			SELECT  t0.`projectCode`, t0.`projectName` ,t4.`basicDataName` AS  projectStateName,t5.`basicDataName` AS taskName , t0.`projectId` ,
			 CASE WHEN t1.projectPlanState = 40 THEN  DATEDIFF(NOW() , t6.createTime) WHEN  t1.projectPlanState = 47 THEN  DATEDIFF(NOW() , t1.projectplanTime) ELSE  DATEDIFF( NOW() , t2.`eventPlanHappenDateENG`) END AS diff,
			 t2.`eventPlanHappenDateENG` , t6.`memberName` AS programManager , t8.departmentName AS officeName
			FROM 
			pm_project_header t0 
			LEFT JOIN pm_project_state t1  ON t0.`projectId` = t1.`projectId`
			LEFT JOIN fnd_basic_data t4 ON t1.`projectPlanState` = t4.`basicDataId` AND t4.`dataTypeCode` = '22'
			LEFT JOIN fnd_basic_data t3 ON t4.`basicDataName` = t3.`basicDataName`  AND t3.`dataTypeCode` = '09'
			LEFT JOIN pm_project_task t2 ON  t2.`taskTypeCode` = t3.`dataTypeCode` AND t2.`taskTypeId` = t3.`basicDataId` 
			AND t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL AND t2.`visibleFlag` = 1
			LEFT JOIN fnd_basic_data t5 ON t1.`projectPlanState` = t5.`basicDataId` AND t5.`dataTypeCode` = '23'
			LEFT JOIN pm_project_member t6 ON t6.`projectId` = t0.`projectId` AND t6.`memberRole` = '30' AND t6.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t7 ON t7.`projectId` = t0.`projectId` AND t7.`memberRole` = '20' AND t7.`effectiveTo` IS NULL
			LEFT JOIN fnd_department t8 ON t0.column001 = t8.departmentNum AND t8.`status` = 1
			WHERE t0.`projectState` IN ( 30 ,31,32) AND t0.`effectiveTo` IS NULL 
			AND ( t2.`eventPlanHappenDateENG` IS NULL OR ( DATEDIFF( t2.`eventPlanHappenDateENG` , NOW()) < 7))
			AND t1.`projectPlanState` != 48 AND t6.memberCode IS NOT NULL
		]]>
		<isNotEmpty prepend="and" property="taskQueryParam.projectName"><![CDATA[ t0.projectName like CONCAT('%', #taskQueryParam.projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="taskQueryParam.officeCode"><![CDATA[ t0.column001 = #taskQueryParam.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="taskQueryParam.programManager"><![CDATA[ t6.memberCode = #taskQueryParam.programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="taskQueryParam.serviceManager"><![CDATA[ (t7.memberCode = #taskQueryParam.serviceManager# or t6.memberCode = #taskQueryParam.serviceManager# )]]></isNotEmpty>
		<isNotEmpty property="displayParam.offset">
			limit #displayParam.offset#, #displayParam.pagesize# 
		</isNotEmpty>
;

-- L0609 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:97 | query_pm_task_count | fnd_basic_data, pm_project_header, pm_project_member, pm_project_state, pm_project_task
<![CDATA[
			SELECT  COUNT(1)
			FROM 
			pm_project_header t0 
			LEFT JOIN pm_project_state t1  ON t0.`projectId` = t1.`projectId`
			LEFT JOIN fnd_basic_data t4 ON t1.`projectPlanState` = t4.`basicDataId` AND t4.`dataTypeCode` = '22'
			LEFT JOIN fnd_basic_data t3 ON t4.`basicDataName` = t3.`basicDataName`  AND t3.`dataTypeCode` = '09'
			LEFT JOIN pm_project_task t2 ON  t2.`taskTypeCode` = t3.`dataTypeCode` AND t2.`taskTypeId` = t3.`basicDataId` 
			AND t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL AND t2.`visibleFlag` = 1
			LEFT JOIN fnd_basic_data t5 ON t1.`projectPlanState` = t5.`basicDataId` AND t5.`dataTypeCode` = '23'
			LEFT JOIN pm_project_member t6 ON t6.`projectId` = t0.`projectId` AND t6.`memberRole` = '30' AND t6.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t7 ON t7.`projectId` = t0.`projectId` AND t7.`memberRole` = '20' AND t7.`effectiveTo` IS NULL
			WHERE t0.`projectState` IN ( 30 ,31,32) AND t0.`effectiveTo` IS NULL 
			AND ( t2.`eventPlanHappenDateENG` IS NULL OR ( DATEDIFF( t2.`eventPlanHappenDateENG` , NOW()) < 7))
			AND t1.`projectPlanState` != 48 AND t6.memberCode IS NOT NULL
		]]>
		<isNotEmpty prepend="and" property="projectName"><![CDATA[ t0.projectName like CONCAT('%', #projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="officeCode"><![CDATA[ t0.column001 = #officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="programManager"><![CDATA[ t6.memberCode = #programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="serviceManager"><![CDATA[ (t7.memberCode = #serviceManager# or t6.memberCode = #serviceManager#)]]></isNotEmpty>
;

-- L0610 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:120 | query_notify_count | pm_project_header, pm_project_member, pm_project_notification, fnd_department
<![CDATA[
			SELECT COUNT(*)
			FROM pm_project_notification t1 
			LEFT JOIN pm_project_header t2 ON t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t3 ON t2.`projectId` = t3.`projectId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t2.`projectId` = t4.`projectId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_department t5 ON t2.`column001` = t5.`departmentNum` AND t5.`status` = 1 where 1 = 1 and t2.projectId is not null
		]]>
		<isNotEmpty prepend="and" property="projectName"><![CDATA[ t2.projectName like CONCAT('%', #projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="officeCode"><![CDATA[ t2.column001 = #officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="programManager"><![CDATA[ t4.memberCode = #programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="serviceManager"><![CDATA[ (t3.memberCode = #serviceManager# or t4.memberCode = #serviceManager#)]]></isNotEmpty>
;

-- L0611 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:143 | query_notify_list | pm_project_header, pm_project_member, pm_project_notification, fnd_department, fnd_user_info
<![CDATA[
			SELECT t1.`projectId`,t2.`projectName` , t5.`departmentName` , t1.`notifyContent`, t1.`createTime` ,
				CONCAT( t1.`createBy` ,'-' ,t6.`realName`) as createBy, t4.`memberName` AS programManager , t3.`memberName` AS serviceManager FROM pm_project_notification t1 
			LEFT JOIN pm_project_header t2 ON t1.`projectId` = t2.`projectId` AND t2.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t3 ON t2.`projectId` = t3.`projectId` AND t3.`memberRole` = '20' AND t3.`effectiveTo` IS NULL
			LEFT JOIN pm_project_member t4 ON t2.`projectId` = t4.`projectId` AND t4.`memberRole` = '30' AND t4.`effectiveTo` IS NULL
			LEFT JOIN fnd_user_info t6 ON t6.`username` = t1.`createBy`
			LEFT JOIN fnd_department t5 ON t2.`column001` = t5.`departmentNum` AND t5.`status` = 1
			WHERE 1 = 1 and t2.projectId is not null
		]]>
		<isNotEmpty prepend="and" property="notifyQueryParam.projectName"><![CDATA[ t2.projectName like CONCAT('%', #notifyQueryParam.projectName#, '%')]]></isNotEmpty>
		<isNotEmpty prepend="and" property="notifyQueryParam.officeCode"><![CDATA[ t2.column001 = #notifyQueryParam.officeCode#]]></isNotEmpty>
		<isNotEmpty prepend="and" property="notifyQueryParam.programManager"><![CDATA[ t4.memberCode = #notifyQueryParam.programManager#]]> </isNotEmpty>
		<isNotEmpty prepend="and" property="notifyQueryParam.serviceManager"><![CDATA[( t3.memberCode = #notifyQueryParam.serviceManager# or t4.memberCode = #notifyQueryParam.serviceManager# )]]></isNotEmpty>
		<![CDATA[
			ORDER BY t1.`createTime` DESC
		]]>
		<isNotEmpty property="notifyDisplayParam.offset">
			limit #notifyDisplayParam.offset#, #notifyDisplayParam.pagesize# 
		</isNotEmpty>
;

-- L0612 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:240 | query_call_back_task | pm_cl_callback, pm_project_header, pm_project_member, fnd_department, fnd_user_info
<![CDATA[
			SELECT t3.`projectCode` , t3.`projectName` , t4.`departmentName` AS officeName,t5.`memberName`  as programManager, t1.`NAME_`  as taskName,t3.`projectId` ,
			CASE WHEN t6.`realName` IS NULL THEN '回访人员' ELSE CONCAT(t6.username,'-' , t6.realName) END AS ASSIGNEE_ 
			,t1.id_ , t2.applyTime ,t7.KEY_ ,t7.NAME_ as procTypeDesc , mm.memberName ,
		    CASE
		        WHEN t3.column012 IS NULL 
		        AND t3.columno12_readonly = - 1 
		        THEN t3.column012 
		        WHEN t3.column012 IS NOT NULL 
		        THEN t3.column012 
		        ELSE t3.columno12_readonly 
    		END AS implType, mm.memberName 
			FROM act_ru_task t1 
			JOIN pm_cl_callback t2 ON t1.`PROC_INST_ID_` = t2.instId AND t2.`instId` IS NOT NULL AND t2.`effectiveTo` IS NULL
			LEFT JOIN act_re_procdef t7 ON t1.PROC_DEF_ID_ = t7.ID_
			LEFT JOIN pm_project_header t3 ON t2.`projectId` = t3.`projectId`
			LEFT JOIN fnd_department t4 ON t3.`column001` = t4.`departmentNum` AND t4.`status`  = 1
			LEFT JOIN pm_project_member t5 ON t3.`projectId` = t5.`projectId` AND t5.`memberRole` = '30' AND t5.`effectiveTo` IS NULL
			LEFT JOIN 
		        (SELECT 
		            m.projectId, GROUP_CONCAT(m.memberName) AS memberName 
		        FROM
		            pm_project_member m 
		        WHERE m.effectiveTo IS NULL 
		            AND m.memberRole = '60' 
		        GROUP BY m.projectId) mm 
		        ON mm.projectId = t3.projectId 
			LEFT JOIN fnd_user_info t6 ON t1.`ASSIGNEE_` = t6.`username` AND t6.`status` = 1
			WHERE t3.projectState != 20 
		]]>
		<isEqual compareValue="1" property="callbackRole" prepend="and"><![CDATA[ 
			(
			ASSIGNEE_ = 'callbackRole' 
			or ASSIGNEE_ = #assignee#
			)]]>
		</isEqual>
		<isEqual compareValue="0" property="callbackRole" prepend="and">
			<![CDATA[ ASSIGNEE_ = #assignee#]]>
		</isEqual>
;

-- L0613 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:330 | query_callback_his_list | fnd_act_hi_comment, pm_cl_callback, pm_project_header, fnd_user_info
<![CDATA[
			SELECT t3.`projectCode` ,t3.`projectName` ,t4.`NAME_` ,'项目人员回访' AS taskName,t1.`applyBy` , 
				t5.`realName`  AS applyName, t6.`realName`  AS assigneeName,t2.`assigneeTime` , t2.`result` ,t1.`projectId`
				, null AS projectCustomer, null AS projectCustomerTel
			FROM pm_cl_callback t1  LEFT JOIN fnd_act_hi_comment t2 ON t1.`instId` = t2.`instId`
			LEFT JOIN pm_project_header t3 ON t1.`projectId` = t3.`projectId`
			LEFT JOIN act_re_procdef t4 ON t2.`procdefKey` = t4.`KEY_` 
			LEFT JOIN fnd_user_info t5 ON t1.`applyBy` = t5.`username` AND t5.`effectiveTo` IS NULL 
			LEFT JOIN fnd_user_info t6 ON t2.`assignee` = t6.`username` AND t6.`effectiveTo` IS NULL
			WHERE t2.`assignee` = #username# and t2.procdefKey = 'CallBack'
		]]>
;

-- L0614 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:403 | query_probTask_list | fnd_basic_data, fnd_department, fnd_user_info
SELECT 
			m.id AS probId, m.probNum, m.theme, m.createTime, m.status, t1.`basicDataName` AS watchName, t2.`basicDataName` AS statusName, t3.basicDataName AS priorityName, t4.username as trackingUser, CONCAT(t4.username, '-', t4.realName) AS trackingUsername, d.`departmentName` AS officeName
			, m.customInfo 
		FROM
		    `prob_main` m 
		    LEFT JOIN `prob_restore` r 
			ON m.`id` = r.`probId`
		    LEFT JOIN `prob_restore_process` rp 
			ON r.`processId` = rp.`id` 
		    LEFT JOIN fnd_department d 
			ON r.`officeCode` = d.`departmentNum` 
		    LEFT JOIN fnd_basic_data t1 
			ON m.`watch` = t1.`basicDataId` 
			AND t1.`dataTypeCode` = '30' 
			AND t1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t2 
			ON m.`status` = t2.basicDataId 
			AND t2.dataTypeCode = '31' 
			AND t1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_basic_data t3 
			ON m.`priority` = t3.`basicDataId` 
			AND t3.`dataTypeCode` = '32' 
			AND t1.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_user_info t4 
			ON m.trackingUser = t4.username 
		<dynamic prepend="where">
			<isEqual property="isProbAdmin" compareValue="0">
					(
						<isNotEmpty prepend="and" property="assignee">
							(<![CDATA[
								( r.assignee = #assignee# 
							]]>	
							<isNotEmpty prepend="OR" property="areapower">
								<![CDATA[ 
									r.officeCode IN ($areapower$)
								]]>	
							</isNotEmpty>
								)  AND rp.`restoreStatus` = '10'
							)
						</isNotEmpty>
						OR m.watch = 15
					)
				<![CDATA[ 
					AND (
					m.`status` <> '10' 
					AND m.`status` <> '6' 
					AND m.`status` <> '8'
					AND m.`status` <> '1'
				) 
				]]>
			</isEqual>
			<isEqual property="isProbAdmin" compareValue="1">
				<![CDATA[ 
					 (
					m.`status` <> '10' 
					AND m.`status` <> '6'
				) 
				]]>
			</isEqual>
			<isEqual property="isProbAdmin" compareValue="2">
				<![CDATA[ 
					 (
					m.`status` = '4' 
					OR m.`status` = '5'
				) 
				]]>
			</isEqual>
			<isEqual property="isProbAdmin" compareValue="3">
				<![CDATA[ 
					 (
					m.`status` = '6' and m.`trackingUser` = #assignee#
				) 
				]]>
			</isEqual>
			<![CDATA[ and m.effectiveTo is null]]>
		</dynamic>
		GROUP BY m.`id` 
		ORDER BY m.`watch` ASC, m.`priority` DESC, m.`id` DESC
;

-- L0615 | D:/EclipseWorkspace/Parctice/PMS/PMS-struts/config-ibaits/sql-map-work-config.xml:484 | queryProjectSupervisionTask | pm_project_member, pm_project_supervision, fnd_department
SELECT 
		    ps.`projectId` AS applyNum , ps.`projectCode`, ps.`projectName`, 
		    d.`departmentName` AS officeName, pm.`memberName` AS realName, 
		    '工程人员' AS assigneeName, ps.`createTime`, 
		    "ProjectSupervision" AS procTypeName, "项目督查" AS procTypeDesc, "填写督查问卷" AS name 
		FROM
		    `pm_project_supervision` ps 
		    LEFT JOIN pm_project_member pm 
		        ON ps.`projectId` = pm.`projectId` 
		        AND pm.`memberRole` = '30' 
		        AND pm.`effectiveTo` IS NULL 
		    LEFT JOIN fnd_department d 
		        ON ps.`officeCode` = d.`departmentNum` 
		WHERE isdelete = FALSE 
		    AND state = FALSE
;

