-- L0619 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/DispatchProjectMapper.xml:978 | selectDispatchProjectVOList | fnd_basic_data, fnd_department, t_user, t_user_info
select 
	    h.*, d.`departmentName` as officeName, d1.`departmentName` as profitDepName, bd.`basicDataName` as stateName, bd1.`basicDataName` as callbackStateName, bd2.basicDataName as typeName, concat(h.createBy, "-", ui.`realName`) as createName 
	from
	    `pm_dispatch_project_header` h 
	    left join fnd_department d 
	        on h.`officeCode` = d.`departmentNum` 
	    left join fnd_department d1 
	        on h.`profitDepCode` = d1.`departmentNum` 
	    left join `fnd_basic_data` bd 
	        on h.`state` = bd.`basicDataId` 
	        and bd.`dataTypeCode` = 'dispatchState' 
	    left join `fnd_basic_data` bd1 
	        on h.`callbackState` = bd1.`basicDataId` 
	        and bd1.`dataTypeCode` = 'dispatchCbState' 
	    left join `fnd_basic_data` bd2 
	        on h.`type` = bd2.`basicDataId` 
	        and bd2.`dataTypeCode` = 'dispatchType' 
	    left join t_user u 
	        on u.`user_name` = h.`createBy` 
	    left join t_user_info ui 
	        on ui.`user_id` = u.`user_id` 
	        <if test="orgId != null">
				and ui.compID = #{orgId, jdbcType=INTEGER}
			</if>
	<include refid="baseWhereSql" />
;

-- L0620 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/DispatchSettlementMapper.xml:944 | selectSettlementWidthDispatchPageableOld | fnd_basic_data, fnd_department, sms_ofst_contract_head_sap
select 
	    h.id as `dispatch.id`, h.`dispatchName` as `dispatch.dispatchName`, h.`dispatchNo` as `dispatch.dispatchNo`, 
	    h.`dispatchSeq` as `dispatch.dispatchSeq`, h.`contractNos` as `dispatch.contractNos`, 
	    h.`projectIds` as `dispatch.projectIds`, h.`type` as `dispatch.type`, h.`state` as `dispatch.state`, 
	    h.`customInfo` as `dispatch.customInfo`, h.id as `dispatchId`, h.dispatchSeq as `dispatchSeq`, 
	    ds.settledAmount, h.dispatchAmount as `dispatch.dispatchAmount`,
	    sum(sc.`collected_money_amount`) as collectedAmount, 
        sum(sc.`delivered_money_amount`) as deliveredAmount, 
        sum(sc.`contract_money_amount`) as contractAmount,
	    <!-- ROUND(ds.settledAmount / h.dispatchAmount, 4) as settledRatio, 
	    ROUND(h.collectedAmount / h.deliveredAmount, 4) as collectedRatio,  -->
	    ROUND(ds.settledAmount / h.dispatchAmount, 4) as settledRatio, 
    	<!-- ROUND(sum(sc.`collected_money_amount`) / sum(sc.`delivered_money_amount`), 4) as collectedRatio,  -->
    	ROUND(sum(sc.`collected_money_amount`) / sum(sc.`contract_money_amount`), 4) as collectedRatio, 
	    s.* 
	from
	    <!-- (select 
	        h.*, 
	        sum(sc.`collected_money_amount`) as collectedAmount, 
	        sum(sc.`delivered_money_amount`) as deliveredAmount, 
	        sum(sc.`contract_money_amount`) as contractAmount 
	    from
	        pm_dispatch_project_header h 
	        left join `sms_ofst_contract_head_sap` sc 
	            on FIND_IN_SET(
	                sc.`contract_num`, h.`contractNos`
	            ) 
	    <where>
			<if test="model != null and model.dispatched != null"> h.`dispatched` = #{model.dispatched} </if>
	    </where>
	    group by h.id) h  -->
	    pm_dispatch_project_header h 
	    left join `pm_dispatch_project_settlement` s 
	        on h.`id` = s.`dispatchId` 
	        and s.`disabled` = false 
        left join `sms_ofst_contract_head_sap` sc 
            on FIND_IN_SET(sc.`contract_num`, h.`contractNos`) 
	    left join 
	        (select 
	            dispatchId, sum(replace(ds.`amount`, ",", "")) as settledAmount 
	        from
	            `pm_dispatch_project_settlement` ds 
	        where ds.`disabled` = false 
	        group by ds.`dispatchId`) ds 
	        on ds.`dispatchId` = h.`id` 
	    left join fnd_department d 
	        on h.`officeCode` = d.`departmentNum` 
	    left join `fnd_basic_data` bd 
	        on s.`state` = bd.`basicDataId` 
	        and bd.`dataTypeCode` = 'settlementState' 
	    left join `fnd_basic_data` bd1 
	        on h.`state` = bd1.`basicDataId` 
	        and bd1.`dataTypeCode` = 'dispatchState' 
	    left join `fnd_basic_data` bd2 
	        on h.`type` = bd2.`basicDataId` 
	        and bd2.`dataTypeCode` = 'dispatchType' 
	<where>
		<trim prefixOverrides="and | or" suffixOverrides="and | or">
			h.disabled = false AND
			<if test="model != null">
				<if test="model.dispatched != null"> h.`dispatched` = #{model.dispatched} AND </if>
				<if test="model.dispatch != null">
					<if test="model.dispatch.dispatchNo != null and '' != model.dispatch.dispatchNo">
						h.dispatchNo like concat("%", #{model.dispatch.dispatchNo, jdbcType=VARCHAR}, "%") AND
					</if>
					<if test="model.dispatch.dispatchSeq != null and '' != model.dispatch.dispatchSeq">
						h.dispatchSeq like concat("%", #{model.dispatch.dispatchSeq, jdbcType=VARCHAR}, "%") AND
					</if>
					<if test="model.dispatch.dispatchName != null and '' != model.dispatch.dispatchName">
						h.dispatchName like concat("%", #{model.dispatch.dispatchName, jdbcType=VARCHAR}, "%") AND
					</if>
					<if test="model.dispatch.smsProjectCode != null and '' != model.dispatch.smsProjectCode">
						h.smsProjectCode like concat("%", #{model.dispatch.smsProjectCode, jdbcType=VARCHAR}, "%") AND
					</if>
					<if test="model.dispatch.contractNos != null and '' != model.dispatch.contractNos">
						h.contractNos like concat("%", #{model.dispatch.contractNos, jdbcType=VARCHAR}, "%") AND
					</if>
					<if test="model.dispatch.type != null and '' != model.dispatch.type">
						h.type like concat("%", #{model.dispatch.type, jdbcType=VARCHAR}, "%") AND
					</if>
				</if>
			</if>
			<include refid="sql_model_where"></include>
			<if test="fuzzySearch == true and fuzzy != ''">
				(
					s.settleSeq like CONCAT("%", #{fuzzy}, "%") or
					s.dispatchSeq like CONCAT("%", #{fuzzy}, "%") or
					s.progressDesc like CONCAT("%", #{fuzzy}, "%") or
					s.acceptanceDesc like CONCAT("%", #{fuzzy}, "%") or
					s.acceptanceRatio like CONCAT("%", #{fuzzy}, "%") or
					s.ratio like CONCAT("%", #{fuzzy}, "%") or
					s.amount like CONCAT("%", #{fuzzy}, "%") or
					s.memo like CONCAT("%", #{fuzzy}, "%") or
					s.remark like CONCAT("%", #{fuzzy}, "%") or
					s.customInfo like CONCAT("%", #{fuzzy}, "%") or
					s.createBy like CONCAT("%", #{fuzzy}, "%") or
					s.updateBy like CONCAT("%", #{fuzzy}, "%") or
					h.dispatchNo like CONCAT("%", #{fuzzy}, "%") or
					h.dispatchSeq like CONCAT("%", #{fuzzy}, "%") or
					h.dispatchName like CONCAT("%", #{fuzzy}, "%") or
					h.contractNos like CONCAT("%", #{fuzzy}, "%")
				)
			</if>
		</trim>
	</where>
	group by h.id, s.`id`
	<if test="orderBy != null">
        order by ${orderBy}
    </if>
    <if test="orderBy == null">
		order by settledRatio, s.`id` desc
    </if>
    <if test="start != null and pageSize != -1">
        limit #{start}, #{pageSize}
    </if>
;

-- L0621 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/DispatchSettlementMapper.xml:1121 | selectSettlementWidthDispatchPageable | fnd_basic_data, fnd_department, pm_project, sms_ofst_contract_head_sap
SELECT h.id AS `dispatch.id`, h.`dispatchName` AS `dispatch.dispatchName`, h.`dispatchNo` AS `dispatch.dispatchNo`, h.`dispatchSeq` AS `dispatch.dispatchSeq`, h.`contractNos` AS `dispatch.contractNos`
	    , h.facilitatorId AS `dispatch.facilitatorId`, h.facilitatorCode AS `dispatch.facilitatorCode`, h.facilitatorName AS `dispatch.facilitatorName`
	    , h.`projectIds` AS `dispatch.projectIds`, h.`type` AS `dispatch.type`, h.`state` AS `dispatch.state`, h.`reason` AS `dispatch.reason`, h.`remark` AS `dispatch.remark`
	    <!-- , h.`customInfo` AS `dispatch.customInfo` -->
	    , h.`dispatch.customInfo`
	    , h.id AS `dispatchId`
	    , h.dispatchSeq AS `dispatchSeq`, h.smsProjectCode AS `dispatch.smsProjectCode`, h.customInfo ->> '$.smsOrderExecNumber' AS `smsOrderExecNumber`
	    , h.contractAmount, h.deliveredAmount, h.collectedAmount
	    , h.dispatchAmount AS `dispatch.dispatchAmount`, ds.settledAmount
	    , ROUND(IFNULL(ds.settledAmount / h.dispatchAmount, 0), 4) AS settledRatio
	    , IFNULL(h.collectedRatio, 0) AS collectedRatio
	    , IFNULL(CONCAT(h.projectProgress, '%'), s.progressDesc) AS progressDesc
	    , IFNULL(h.projectStateName, s.acceptanceDesc) AS acceptanceDesc
	    , s.*
	FROM (
		    SELECT h.*
		        , SUM(sc.`collected_money_amount`) AS collectedAmount
		        , SUM(sc.`delivered_money_amount`) AS deliveredAmount
		        , SUM(sc.`contract_money_amount`) AS contractAmount
		        , ROUND(SUM(sc.`collected_money_amount`) / SUM(sc.`contract_money_amount`), 4) AS collectedRatio
		        , ph.customInfo ->> "$.projectProgress" AS projectProgress
		        , phsd.`basicDataName` AS projectStateName
		        , JSON_SET(h.customInfo, '$.projectProgress', IFNULL(ph.customInfo ->> "$.projectProgress", 0), '$.projectStateName', IFNULL(phsd.`basicDataName`, "")) AS `dispatch.customInfo`
		    FROM (
		        SELECT h.*
		            , SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(h.`contractNos`, ',', h.`contractNos`), ',', fih.id + 1), ',', -1) AS contractNo
		        FROM pm_dispatch_project_header h
		            JOIN <![CDATA[ find_in_set_help fih ON fih.`id` < LENGTH(h.`contractNos`) - LENGTH(REPLACE(h.contractNos, ',', '')) + 1 ]]>
		        <where>
                    <trim prefixOverrides="and | or" suffixOverrides="and | or">
	                   <include refid="sql_model_dispatch_where"></include>
                    </trim>
                </where>
		        GROUP BY h.id, contractNo
		        ORDER BY NULL
		    ) h
		        LEFT JOIN sms_ofst_contract_head_sap sc ON sc.contract_num = contractNo
		        LEFT JOIN pm_project ph ON ph.projectId = h.projectIds
		        LEFT JOIN fnd_basic_data phsd 
		            ON phsd.`dataTypeCode` = concat(ph.`projectType`, "_projectState") 
		            AND phsd.`basicDataId` = ph.`projectState` 
		    GROUP BY h.id
		    ORDER BY NULL
		) h
	    LEFT JOIN `pm_dispatch_project_settlement` s
	    ON h.`id` = s.`dispatchId`
	        AND s.`disabled` = FALSE
	    LEFT JOIN (
	        SELECT dispatchId, SUM(REPLACE(ds.`amount`, ',', '')) AS settledAmount
	        FROM `pm_dispatch_project_settlement` ds
	        WHERE ds.`disabled` = FALSE
	        GROUP BY ds.`dispatchId`
	    ) ds
	    ON ds.`dispatchId` = h.`id`
	    LEFT JOIN fnd_department d ON h.`officeCode` = d.`departmentNum`
	    LEFT JOIN `fnd_basic_data` bd
	    ON s.`state` = bd.`basicDataId`
	        AND bd.`dataTypeCode` = 'settlementState'
	    LEFT JOIN `fnd_basic_data` bd1
	    ON h.`state` = bd1.`basicDataId`
	        AND bd1.`dataTypeCode` = 'dispatchState'
	    LEFT JOIN `fnd_basic_data` bd2
	    ON h.`type` = bd2.`basicDataId`
	        AND bd2.`dataTypeCode` = 'dispatchType'
	<where>
        <trim prefixOverrides="and | or" suffixOverrides="and | or">
            <include refid="sql_model_dispatch_where"></include>
            <include refid="sql_model_where"></include>
            <if test="fuzzySearch == true and fuzzy != ''">
                (
                    s.settleSeq like CONCAT("%", #{fuzzy}, "%") or
                    s.dispatchSeq like CONCAT("%", #{fuzzy}, "%") or
                    s.progressDesc like CONCAT("%", #{fuzzy}, "%") or
                    s.acceptanceDesc like CONCAT("%", #{fuzzy}, "%") or
                    s.acceptanceRatio like CONCAT("%", #{fuzzy}, "%") or
                    s.ratio like CONCAT("%", #{fuzzy}, "%") or
                    s.amount like CONCAT("%", #{fuzzy}, "%") or
                    s.memo like CONCAT("%", #{fuzzy}, "%") or
                    s.remark like CONCAT("%", #{fuzzy}, "%") or
                    s.customInfo like CONCAT("%", #{fuzzy}, "%") or
                    s.createBy like CONCAT("%", #{fuzzy}, "%") or
                    s.updateBy like CONCAT("%", #{fuzzy}, "%") or
                    h.dispatchNo like CONCAT("%", #{fuzzy}, "%") or
                    h.dispatchSeq like CONCAT("%", #{fuzzy}, "%") or
                    h.dispatchName like CONCAT("%", #{fuzzy}, "%") or
                    h.contractNos like CONCAT("%", #{fuzzy}, "%") or
                    h.facilitatorName like CONCAT("%", #{fuzzy}, "%")
                )
            </if>
        </trim>
    </where>
    group by h.id, s.`id`
    <if test="model != null">
        <if test="model.checkCollectAndSettle != null"> 
            <if test="model.checkCollectAndSettle == 1">
                having collectedRatio > settledRatio
            </if>
            <if test="model.checkCollectAndSettle == 0">
                having collectedRatio = settledRatio
            </if>
            <if test="model.checkCollectAndSettle == -1">
                having settledRatio > collectedRatio
            </if>
        </if>
    </if>
    <if test="orderBy != null">
        order by ${orderBy}
    </if>
    <if test="orderBy == null">
        order by settledRatio, s.`id` desc
    </if>
    <if test="start != null and pageSize != -1">
        limit #{start}, #{pageSize}
    </if>
;

-- L0622 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/DispatchSettlementMapper.xml:1238 | countSettlementWidthDispatchPageable | sms_ofst_contract_head_sap
select 
        count(*) 
    from (
        select h.id AS dispatchId, s.`id` AS settleId
            , IFNULL(h.collectedRatio, 0) AS collectedRatio
            , ROUND(IFNULL(ds.settledAmount / h.dispatchAmount, 0), 4) AS settledRatio
        from
            (
	            SELECT h.*
	                , SUM(sc.`collected_money_amount`) AS collectedAmount
	                , SUM(sc.`delivered_money_amount`) AS deliveredAmount
	                , SUM(sc.`contract_money_amount`) AS contractAmount
	                , ROUND(SUM(sc.`collected_money_amount`) / SUM(sc.`contract_money_amount`), 4) AS collectedRatio
	            FROM (
	                SELECT h.*
	                    , SUBSTRING_INDEX(SUBSTRING_INDEX(CONCAT(h.`contractNos`, ',', h.`contractNos`), ',', fih.id + 1), ',', -1) AS contractNo
	                FROM pm_dispatch_project_header h
	                    JOIN <![CDATA[ find_in_set_help fih ON fih.`id` < LENGTH(h.`contractNos`) - LENGTH(REPLACE(h.contractNos, ',', '')) + 1 ]]>
	                <where>
	                    <trim prefixOverrides="and | or" suffixOverrides="and | or">
	                       <include refid="sql_model_dispatch_where"></include>
	                    </trim>
	                </where>
	                GROUP BY h.id, contractNo
	                ORDER BY NULL
	            ) h
	                LEFT JOIN sms_ofst_contract_head_sap sc ON sc.contract_num = contractNo
	            GROUP BY h.id
	            ORDER BY NULL
	        ) h
	        LEFT JOIN `pm_dispatch_project_settlement` s
	        ON h.`id` = s.`dispatchId`
	            AND s.`disabled` = FALSE
	        LEFT JOIN (
	            SELECT dispatchId, SUM(REPLACE(ds.`amount`, ',', '')) AS settledAmount
	            FROM `pm_dispatch_project_settlement` ds
	            WHERE ds.`disabled` = FALSE
	            GROUP BY ds.`dispatchId`
	        ) ds
	        ON ds.`dispatchId` = h.`id`
        <where>
            <trim prefixOverrides="and | or" suffixOverrides="and | or">
                <include refid="sql_model_dispatch_where"></include>
                <include refid="sql_model_where"></include>
                <if test="fuzzySearch == true and fuzzy != ''">
                    (
                        s.settleSeq like CONCAT("%", #{fuzzy}, "%") or
                        s.dispatchSeq like CONCAT("%", #{fuzzy}, "%") or
                        s.progressDesc like CONCAT("%", #{fuzzy}, "%") or
                        s.acceptanceDesc like CONCAT("%", #{fuzzy}, "%") or
                        s.acceptanceRatio like CONCAT("%", #{fuzzy}, "%") or
                        s.ratio like CONCAT("%", #{fuzzy}, "%") or
                        s.amount like CONCAT("%", #{fuzzy}, "%") or
                        s.memo like CONCAT("%", #{fuzzy}, "%") or
                        s.remark like CONCAT("%", #{fuzzy}, "%") or
                        s.customInfo like CONCAT("%", #{fuzzy}, "%") or
                        s.createBy like CONCAT("%", #{fuzzy}, "%") or
                        s.updateBy like CONCAT("%", #{fuzzy}, "%") or
	                    h.dispatchNo like CONCAT("%", #{fuzzy}, "%") or
	                    h.dispatchSeq like CONCAT("%", #{fuzzy}, "%") or
	                    h.dispatchName like CONCAT("%", #{fuzzy}, "%") or
	                    h.contractNos like CONCAT("%", #{fuzzy}, "%") or
	                    h.facilitatorName like CONCAT("%", #{fuzzy}, "%")
                    )
                </if>
            </trim>
        </where>
        group by h.id, s.`id`
        <if test="model != null">
	        <if test="model.checkCollectAndSettle != null"> 
	            <if test="model.checkCollectAndSettle == 1">
	                having collectedRatio > settledRatio
	            </if>
	            <if test="model.checkCollectAndSettle == 0">
	                having collectedRatio = settledRatio
	            </if>
	            <if test="model.checkCollectAndSettle == -1">
	                having settledRatio > collectedRatio
	            </if>
	        </if>
	    </if>
    ) t
;

