	                ON pw.`procInstId` = RES.`PROC_INST_ID_` 
	        WHERE RES.END_TIME_ IS NOT NULL 
	            AND (
	                RES.ASSIGNEE_ = #{model.assignee, jdbcType=VARCHAR} 
			        OR (
