-- L0629 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1507 | checkPermission | pm_project_member, pm_project, t_user_info
<![CDATA[
	  	select 
		    count(IF(pm.`memberRole` in ('20', '30', '40'), pm.id, null)) > 0 
		    	and count(ui.id) > 0 as `all`, 
		    count(IF(pm.`memberRole` in ('20', '30', '40'), pm.id, null)) > 0 as edit, 
		    count(IFNULL(pm.id, ui.id)) > 0 view,
		    group_concat(distinct ph.projectType) as projectTypes,
		    max(ph.projectState) as maxState,
		    group_concat(distinct pm.memberRole) memberRoles, 
		    #{permissionTypes} as permissionTypes,
		    #{user.userInfoId} as userInfoId,
		    count(ui.id) > 0 hasPower,
		    ph.disabled as disabled
		from
		    pm_project ph 
		    left join pm_project_member pm 
		        on ph.projectId = pm.projectId 
		        and pm.effectiveFrom <= now() 
		        and (
		            pm.effectiveTo > now() 
		            or pm.effectiveTo is null
		        ) 
		        and pm.memberCode = #{user.userName}
	]]>
		    left join t_user_info ui 
		        on ui.`id` = #{user.userInfoId}
		        <if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
			        and find_in_set(ph.`column001`, ui.`custom5`) 
				</if>
		        and find_in_set(ph.projectType, ui.custom4)
		<!-- where (
		        pm.memberCode = #{user.userName}
		        or ui.id = #{user.userInfoId}
		    ) -->
	<where>
		<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
			<if test="model != null">
				<if test="model.projectId != null">
					AND ph.projectId = #{model.projectId}
				</if>
				<if test="model.projectIds != null">
					AND FIND_IN_SET(ph.projectId, #{model.projectIds})
				</if>
				AND (
					(
					<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
						1 = 1
						<if test="model.projectTypes != null">
							AND FIND_IN_SET(ph.`projectType`, #{model.projectTypes})
						</if>
						<if test="model.officeCodes != null">
							AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
						</if>
					</trim>
					)
					<if test="model.memberCode != null and model.memberCode != ''">
						OR pm.memberCode like concat("%", #{model.memberCode}, "%")
					</if>
				) 
				<if test="model.customInfo != null and model.customInfo.hasDispatched == 'true'">
                    AND #{model.customInfo.hasDispatched} = ph.customInfo -> '$.hasDispatched'
                </if>
				<!-- <if test="model.projectTypes != null">
					AND FIND_IN_SET(ph.`projectType`, #{model.projectTypes})
				</if>
				<if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
				</if> -->
			</if>
		</trim>
	</where>
;

-- L0630 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1582 | selectPermissionByMemberRole | fnd_basic_data, t_role, t_user_info, t_user_role
SELECT 
	    p.`permission_name` 
	FROM
	    `t_permission` p 
	    LEFT JOIN `t_role_permission` rp 
	        ON rp.permission_id = p.permission_id 
	    LEFT JOIN `t_role` r
	        ON rp.role_id = r.role_id 
	    LEFT JOIN `fnd_basic_data` db 
	        ON db.dataTypeCode = 'afProjectMember' 
	        AND r.role_name = db.basicDataAttri1 
        <if test="memberRoles != null and memberRoles != ''">
	        AND FIND_IN_SET(db.basicDataId, #{memberRoles}) 
        </if>
        <if test="memberRoles == null or memberRoles == ''">
        	AND p.permission_name REGEXP ":detail|:list"
        LEFT JOIN t_user_role ur ON ur.`role_id` = r.`role_id`
	    LEFT JOIN t_user_info ui
            ON ui.`user_id` = ur.`user_id`
	        AND ur.`comp_id` = ui.`compID`
	        AND ui.id = #{userInfoId}
        </if>
	where (r.role_name = db.basicDataAttri1
	    <if test="memberRoles == null or memberRoles == ''">
	        OR ui.id = #{userInfoId}
	    </if>
	)
	<if test="permissionTypes != null">
	    and p.permission_name regexp #{permissionTypes}
	</if>
;

-- L0631 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1616 | selectRoleByMemberRole | fnd_basic_data, t_role, t_user_info, t_user_role
select 
	    r.`role_name` 
	from
	    t_user_info ui 
	    inner join t_user_role ur 
	        on ui.`user_id` = ur.`user_id` 
	        and ur.`comp_id` = ui.`compID` 
	    inner join `t_role` r 
	        on ur.`role_id` = r.`role_id` 
	    left join `fnd_basic_data` db 
	        on db.dataTypeCode = 'afProjectMember' 
        <if test="memberRoles != null and memberRoles != ''">
	        and find_in_set(db.basicDataId, #{memberRoles}) 
        </if>
	        and r.role_name = db.basicDataAttri1 
	where ui.id = #{userInfoId}
		and (
	        r.role_name = db.basicDataAttri1 
	        or r.`role_name` in ("admin", "projectAdmin") 
			<if test="hasPower == true">
		        or r.`role_name` in ("projectSubAdmin", "projectAreaManager", "dispatchSettleStaff")
			</if>
	    )
;

-- L0632 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectHeaderMapper.xml:1955 | selectAllProjectRelateInfos | pm_project
select 
	    *, concat(
            "insert into ", tableName, "(", columns, ") select * from ( select ", 
                replace(selectColumns, concat(tableAlias, ".customInfo"), concat("JSON_MERGE_PRESERVE(IFNULL(", tableAlias, ".customInfo, '{}'), ", transferValues, ") as customInfo")),
	        " from ", tableName, " as ", tableAlias, 
	        IF(locate("nph.", selectColumns), 
                " left join pm_project nph on nph.projectId = '$newProjectId$' and nph.projectType = '$newProjectType$' ", 
                ""
            ),
	        " where ", whereColumns
			, " ) ", tableAlias
	    ) as `insertSql`, IF(
	        queryColumns = "projectIds", concat(
                "update ", tableName, " as ", tableAlias, " set ", tableAlias, ".projectIds = concat(projectIds, ',$newProjectId$') where FIND_IN_SET('$oldProjectId$', ", queryColumnsWithAlias, ") AND !FIND_IN_SET('$newProjectId$', ", queryColumnsWithAlias, ")"
	        ), null
	    ) as `updateSql`, 
	    IF(hasCustomInfo <!-- or hasEffectiveTo or hasDisabled or hasDeleted  -->
			, concat(
			    "update ", tableName, " as ", tableAlias, 
			    " set ", 
				concat_ws(",",
					IF(hasCustomInfo, concat(tableAlias, ".customInfo = JSON_MERGE_PATCH(JSON_MERGE_PRESERVE(IFNULL(", tableAlias, ".customInfo, '{}'), ", transferValues, "), JSON_OBJECT('transferProjectFlag', 1))"), null)
					<!-- ,IF(hasEffectiveTo, concat(tableAlias, ".effectiveTo = now()"), null)
 					,IF(hasDisabled, concat(tableAlias, ".disabled = true"), null)
 					,IF(hasDeleted, concat(tableAlias, ".deleted = true"), null) -->
				),
			    " where ", whereColumns
			), null
	    ) as transferFlagSql
<![CDATA[
		, concat(
            "MD5(concat_ws('&', IFNULL(", REPLACE(
                md5Columns, ",", ",'NULL'),IFNULL("
            ), ",'NULL')", ")", ")"
        ) md5Sql 
]]>
	from
	(select *, 
		replace(
            replace(
                replace(
                    replace(
                        replace(
                            replace(
                                replace(
                                    replace(
                                        columnsWithAlias, concat(tableAlias, ".projectId,"), "'$newProjectId$' as projectId,"
                                    ), concat(tableAlias, ".projectType,"), "'$newProjectType$' as projectType,"
                                ), concat(tableAlias, ".objId,"), "'$newObjId$' as objId,"
                            ), concat(tableAlias, ".objType,"), "$newObjType$ as objType,"
                        ), concat(tableAlias, ".projectCode,"), concat("IFNULL(nph.projectCode, ", tableAlias, ".projectCode) projectCode,")
                    ), concat(tableAlias, ".projectName,"), concat("IFNULL(nph.projectName, ", tableAlias, ".projectName) projectName,")
                ), concat(tableAlias, ".contractNo,"), concat("IFNULL(nph.customInfo ->> '$.contractNo', ", tableAlias, ".contractNo) contractNo,")
            ), concat(tableAlias, ".officeCode,"), concat("IFNULL(nph.column001, ", tableAlias, ".officeCode) officeCode,")
        ) as selectColumns, 
        replace(
		    replace(
				replace(
				    replace(
						replace(
						    replace(
								concat(queryColumnsWithAlias, ",$"), "projectId,", "projectId='$oldProjectId$' AND "
						    ), "projectType,", "projectType='$oldProjectType$' AND "
						), "objType,", "objType in ($oldObjType$) AND "
		    	<!-- ), "objId,", "objId='$oldObjId$' AND " -->
				    ), concat(tableAlias, ".objId,"), concat("'$oldObjId$' = IF(", tableAlias, ".objType = 'project', ", tableAlias, ".objId, JSON_UNQUOTE(JSON_EXTRACT(", tableAlias, ".`customInfo`, concat('$.', LOWER(REPLACE(", tableAlias, ".objType, 'project', '')), '.projectId')))) AND ")
                ), concat(tableAlias, ".projectIds,"), concat("FIND_IN_SET('$oldProjectId$', ", tableAlias, ".projectIds) AND ")
		    ), " AND $", ""
		) as whereColumns,
		replace(
            replace(
                replace(
                    replace(
                        replace(
                            replace(
                                concat(queryColumnsWithAlias, ",$"), "projectId,", "projectId='$oldProjectId$' AND "
                            ), "projectType,", "projectType='$oldProjectType$' AND "
                        ), "objType,", "objType in ($oldObjType$) AND "
                    ), "objId,", "objId='$oldObjId$' AND "
                ), concat(tableAlias, ".projectIds,"), concat("FIND_IN_SET('$oldProjectId$', ", tableAlias, ".projectIds) AND ")
            ), " AND $", ""
        ) as newWhereColumns,
        replace(replace(replace(
        replace(replace(replace(
        replace(replace(replace(
        replace(replace(replace(
            replace(concat(columnsWithAlias, ",$"), concat(tableAlias, ".projectId,"), ''), 
                concat(tableAlias, ".projectType,"), ''),
                concat(tableAlias, ".projectCode,"), ''),
                concat(tableAlias, ".projectName,"), ''),
                concat(tableAlias, ".contractNo,"), ''),
                concat(tableAlias, ".officeCode,"), ''),
                concat(tableAlias, ".updateBy,"), ''),
                concat(tableAlias, ".updateTime,"), ''),
                concat(tableAlias, ".effectiveTo,"), ''),
                concat(tableAlias, ".customInfo,"), ''),
                concat(tableAlias, ".disabled,"), ''),
                concat(tableAlias, ".deleted,"), ''),
            ",$", ""
        ) AS md5Columns,
<![CDATA[
        concat("concat_ws('&', IFNULL(", REPLACE(primaryKeysWithAlias, ",", ",'NULL'),IFNULL("), ",'NULL')", ")") as oldPrimaryValues,
        concat("JSON_OBJECT('transferToProjectId', $newProjectId$, 'transferFromProjectId', $oldProjectId$, 'oldPrimaryKeys', '", primaryKeys, "', 'oldPrimaryValues', ", concat("concat_ws('&', IFNULL(", REPLACE(primaryKeysWithAlias, ",", ",'NULL'),IFNULL("), ",'NULL')", ")"), ")") as transferValues
]]>
	from 
	    (select 
	        t.`TABLE_NAME` as tableName, t.tableAlias, 
	        group_concat(distinct pc.column_name order by pc.`ORDINAL_POSITION`) primaryKeys, 
        	group_concat(distinct c.column_name order by c.`column_name`) queryColumns,
			concat(group_concat(distinct c.column_name order by c.`column_name`), ",", group_concat(distinct ac.column_name order by ac.`ORDINAL_POSITION`)) columns, 
			concat(group_concat(distinct concat(t.tableAlias, ".", c.column_name) order by c.`column_name`), ",", group_concat(distinct concat(t.tableAlias, ".", ac.column_name) order by ac.`ORDINAL_POSITION`)) columnsWithAlias, 
			group_concat(distinct concat(t.tableAlias, ".", c.column_name) order by c.`column_name`) queryColumnsWithAlias,
            group_concat(distinct concat(t.tableAlias, ".", pc.column_name) order by pc.`ORDINAL_POSITION`) primaryKeysWithAlias, 
			max(ac.`COLUMN_NAME` = 'customInfo') as hasCustomInfo,
			max(ac.`COLUMN_NAME` = 'effectiveTo') as hasEffectiveTo,
	        max(ac.`COLUMN_NAME` = 'disabled') as hasDisabled,
	        max(ac.`COLUMN_NAME` = 'deleted') as hasDeleted
	    from
	        (select 
	            t.*, GROUP_CONCAT(
	                SUBSTRING(
	                    SUBSTRING_INDEX(
	                        SUBSTRING_INDEX(t.TABLE_NAME, '_', sh.id + 1), '_', - 1
	                    ), 1, 1
	                ) separator ""
	            ) as tableAlias 
	        from
	            information_schema.tables t 
	            left join find_in_set_help sh 
<![CDATA[    		on sh.id < (LENGTH(t.TABLE_NAME) - LENGTH(REPLACE(t.TABLE_NAME, '_', '')) + 1) ]]>
	        where t.TABLE_SCHEMA = database() 
	            and t.TABLE_TYPE = 'BASE TABLE' 
	        group by t.TABLE_NAME) t 
	        left join information_schema.columns ac 
	            on t.`TABLE_CATALOG` = ac.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = ac.`TABLE_NAME` 
	            and ac.`COLUMN_KEY` != "PRI" 
	            and ac.COLUMN_NAME not in (
	                'projectId', 'projectType', 'projectIds', 'objType', 'objId'
	            ) 
	        left join information_schema.columns c 
	            on t.`TABLE_CATALOG` = c.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = c.`TABLE_NAME` 
	            and c.COLUMN_NAME in (
	                'projectId', 'projectType', 'projectIds', 'objType', 'objId'
	            ) 
	        left join information_schema.columns pc 
	            on t.`TABLE_CATALOG` = pc.`TABLE_CATALOG` 
	            and t.`TABLE_NAME` = pc.`TABLE_NAME` 
	            and pc.`COLUMN_KEY` = "PRI" 
	    where t.TABLE_SCHEMA = database() 
	        and c.TABLE_SCHEMA = database() 
	        and pc.TABLE_SCHEMA = database() 
	        and ac.TABLE_SCHEMA = database() 
	        and t.TABLE_TYPE = 'BASE TABLE' 
	    group by tableName) t ) t
	where queryColumns in (
	        "projectId", "projectIds", "projectId,projectType", "objId,objType"
	    ) 
	    and tableName not in ('pm_project')
;

-- L0633 | D:/EclipseWorkspace/Parctice/PMS/PMS-springmvc/src/main/java/com/dp/plat/pms/springmvc/mapping/ProjectTaskMapper.xml:673 | checkPermission | pm_project_member, pm_project_task, pm_project, t_user_info
<![CDATA[
	  	select 
		    count(IF(pm.`memberRole` in ('20', '30', '40'), pm.id, null)) > 0 
		    	and count(ui.id) > 0 as `all`, 
		    count(IF(pm.`memberRole` in ('20', '30', '40'), pm.id, null)) > 0 as edit, 
		    count(IFNULL(pm.id, ui.id)) > 0 view, 
		    max(ph.projectState) as maxState,
		    group_concat(distinct pm.memberRole) memberRoles, 
		    #{permissionTypes} as permissionTypes,
		    #{user.userInfoId} as userInfoId,
		    count(ui.id) > 0 hasPower,
		    ph.disabled as disabled
		from
		    pm_project ph 
		    left join pm_project_task pt 
		        on pt.projectId = ph.projectId 
		        and pt.projectType = ph.projectType 
		    left join pm_project_member pm 
		        on ph.projectId = pm.projectId 
		        and pm.effectiveFrom <= now() 
		        and (
		            pm.effectiveTo > now() 
		            or pm.effectiveTo is null
		        ) 
		        and pm.memberCode = #{user.userName}
  	]]>
		    left join t_user_info ui 
		        on ui.`id` = #{user.userInfoId}
		        <if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
			        and find_in_set(ph.`column001`, ui.`custom5`) 
				</if>
		        and find_in_set(ph.projectType, ui.custom4) 
		where <!-- (
		        pm.memberCode = #{user.userName}
		        or ui.id = #{user.userInfoId}
		    )  -->
		(
			(
			<trim prefixOverrides=" and | or " suffixOverrides=" and | or ">
				1 = 1
				<if test="model.projectTypes != null">
					AND FIND_IN_SET(ph.`projectType`, #{model.projectTypes})
				</if>
				<if test="model.officeCodes != null">
					AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
				</if>
			</trim>
			)
			or pm.memberCode = #{user.userName}
	        or ui.id = #{user.userInfoId}
		) 
	<if test="model != null">
		<if test="model.taskId != null">
			AND pt.taskId = #{model.taskId}
		</if>
		<if test="model.projectId != null">
			AND ph.projectId = #{model.projectId}
		</if>
		<if test="model.projectIds != null">
			AND FIND_IN_SET(ph.projectId, #{model.projectIds})
		</if>
		<if test="model.customInfo != null and model.customInfo.hasDispatched == 'true'">
            AND #{model.customInfo.hasDispatched} = ph.customInfo -> '$.hasDispatched'
        </if>
		<!-- <if test="model.projectType != null">
			AND FIND_IN_SET(ph.projectType, #{model.projectType})
		</if>
		<if test="model.officeCodes != null">
			AND FIND_IN_SET(ph.`column001`, #{model.officeCodes})
		</if> -->
	</if>
;

-- L0634 | D:/EclipseWorkspace/Parctice/PMS/core/src/main/java/com/dp/plat/core/mapping/DataExportMapper.xml:23 | exportUserDetail | t_role, t_user, t_user_info, t_user_role
SELECT 
	    u.*, ui.id AS userInfoId, ui.realName, ui.mobile, ui.telphone, ui.avatar, ui.birthday, ui.email, ui.sex, GROUP_CONCAT(r.`role_name_zn`) AS roles 
	FROM
	    t_user u 
	    LEFT JOIN t_user_info ui 
	        ON u.user_id = ui.user_id 
	    LEFT JOIN t_user_role ur 
	        ON u.user_id = ur.`user_id` 
	    LEFT JOIN t_role r 
	        ON ur.`role_id` = r.`role_id` 
  	<where>
  		<if test="model !=null">
        	<if test="model.userName != null">
        		u.user_name like CONCAT("%", #{model.userName}, "%")
       		</if>
       		<if test="model.email != null">
        		and ui.email like CONCAT("%", #{model.email}, "%")
       		</if>
       		<if test="model.realName != null">
        		and ui.realName like CONCAT("%", #{model.realName}, "%")
       		</if>
       		<if test="model.sex != null">
        		and ui.sex = #{model.sex}
       		</if>
       		<if test="model.roleId != null">
        		and ur.role_id = #{model.roleId}
       		</if>
       		<if test="model.status != null">
        		and u.status = #{model.status}
       		</if>
      	</if>
      	<if test="fuzzySearch == true and fuzzy != ''">
      		and (
      			u.user_name like CONCAT("%", #{fuzzy}, "%") or
    			ui.email like CONCAT("%", #{fuzzy}, "%") or
      			ui.realName like CONCAT("%", #{fuzzy}, "%") or
      			r.role_name like CONCAT("%", #{fuzzy}, "%") or
      			r.role_name_zn like CONCAT("%", #{fuzzy}, "%")
      		)
      	</if>
  	</where>
	GROUP BY u.user_id 
  	<if test="orderBy != null">
   		order by ${orderBy}
    </if>
;
